#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO pin connected to the MCP3008 chip enable (CE0)
#define MCP3008_CE 8

// Define the SPI channel (CE0)
#define SPI_CHANNEL 0

// Define the SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Global variable to store the SPI handle
int spi_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the moisture level from the MCP3008 ADC
int read_moisture_level() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // Construct the SPI message to read from channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended mode, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer the SPI message
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure the CE pin as an output
    gpioSetMode(MCP3008_CE, PI_OUTPUT);
    gpioWrite(MCP3008_CE, 1); // Ensure CE is initially high

    // Open the SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and log moisture levels
    while (1) {
        // Read the moisture level
        int moisture_level = read_moisture_level();

        if (moisture_level >= 0) {
            // Get the current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the timestamp and moisture level to the console
            printf("%s - Moisture Level: %d\n", timestamp, moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

