#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int pga_gain;
    int data_rate;
} ads1115_config_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to initialize the ADS1115
int init_ads1115(int i2c_handle, ads1115_config_t config) {
    uint16_t config_value = 0;

    // Construct the configuration value
    config_value |= CONFIG_OS_SINGLE;
    config_value |= CONFIG_MUX_SINGLE_0;
    config_value |= CONFIG_MODE_SINGLE;

    // Set data rate
    switch (config.data_rate) {
        case 128:
            config_value |= CONFIG_DR_128SPS;
            break;
        case 64:
            config_value |= 0x0080;
            break;
        case 32:
            config_value |= 0x00A0;
            break;
        case 16:
            config_value |= 0x00C0;
            break;
        case 8:
            config_value |= 0x00E0;
            break;
        case 4:
            config_value |= 0x0100;
            break;
        case 2:
            config_value |= 0x0120;
            break;
        case 1:
            config_value |= 0x0140;
            break;
        default:
            fprintf(stderr, "Invalid data rate. Using default (128 SPS).\n");
            config_value |= CONFIG_DR_128SPS;
            break;
    }

    // Set PGA gain
    switch (config.pga_gain) {
        case 4096:
            config_value |= CONFIG_PGA_4_096V;
            break;
        case 2048:
            config_value |= 0x0200;
            break;
        case 1024:
            config_value |= 0x0400;
            break;
        case 512:
            config_value |= 0x0600;
            break;
        case 256:
            config_value |= 0x0800;
            break;
        default:
            fprintf(stderr, "Invalid PGA gain. Using default (+/-4.096V).\n");
            config_value |= CONFIG_PGA_4_096V;
            break;
    }

    config_value |= CONFIG_COMP_MODE_TRAD;
    config_value |= CONFIG_COMP_POL_LOW;
    config_value |= CONFIG_COMP_LAT_NON;
    config_value |= CONFIG_COMP_QUE_DISABLE;

    // Write the configuration value to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_CONFIG, buf + 1, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read the current from the ADS1115
float read_current(int i2c_handle) {
    char buf[2];
    int16_t raw_value;

    // Read the conversion register
    int result = i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERT, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1.0;
    }

    // Combine the two bytes to form the 16-bit raw value
    raw_value = (buf[0] << 8) | buf[1];

    // Convert the raw value to current (40mV/A, 2.5V offset)
    float current = (raw_value * 4.096 / 32768.0 - 2.5) / 0.04;

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115 configuration
    ads1115_config_t config = {
        .i2c_address = ADS1115_ADDR,
        .pga_gain = 4096,
        .data_rate = 128
    };

    if (init_ads1115(i2c_handle, config) != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read current from ADS1115
        float current = read_current(i2c_handle);

        if (current >= 0) {
            // Log the current to the console
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        // Wait for 500ms
        gpioDelay(500000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

