#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_GAIN_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0060
#define TEMP_MIN 20.0
#define TEMP_MAX 80.0
#define TEMP_ADC_MIN 0.0
#define TEMP_ADC_MAX 3.3
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_TIME_MS 50
#define BUZZER_DURATION_MS 2000

// Global variables
int i2c_handle;
FILE *log_file;
volatile int running = 1;
volatile unsigned long last_flame_time = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int initialize_ads1115();
int read_flame_sensor();
float read_temperature();
void log_event(const char *message);
void activate_buzzer();
void deactivate_buzzer();
void flame_detected_isr(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Function to initialize ADS1115
int initialize_ads1115() {
    // Configure ADS1115 for single-shot mode, gain +/-4.096V, 128 SPS
    unsigned short config = ADS1115_GAIN_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to read flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read temperature from ADS1115
float read_temperature() {
    char buf[1];
    char read_buf[2];
    int16_t raw_value;
    float voltage, temperature;

    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return -1000.0; // Indicate error
    }

    gpioDelay(9); // Wait for conversion (at least 8ms for 128 SPS)

    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register for read\n");
        return -1000.0; // Indicate error
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1000.0; // Indicate error
    }

    raw_value = (read_buf[0] << 8) | read_buf[1];

    // Convert raw value to voltage (assuming gain of +/-4.096V)
    voltage = (float)raw_value * 4.096 / 32768.0;

    // Convert voltage to temperature (linear mapping)
    temperature = TEMP_MIN + (voltage - TEMP_ADC_MIN) * (TEMP_MAX - TEMP_MIN) / (TEMP_ADC_MAX - TEMP_ADC_MIN);

    return temperature;
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0);
}

// Interrupt service routine for flame sensor
void flame_detected_isr(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 0) { // Falling edge detected (flame detected)
        unsigned long current_time = gpioTick();
        if (current_time - last_flame_time > DEBOUNCE_TIME_MS * 1000) {
            last_flame_time = current_time;
            float temperature = read_temperature();

            if (temperature > TEMP_THRESHOLD) {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Fire detected! Temperature: %.2f°C", temperature);
                log_event(log_message);
                activate_buzzer();
                gpioDelay(BUZZER_DURATION_MS);
                deactivate_buzzer();
            } else if (temperature > 0) {
                char log_message[50];
                snprintf(log_message, sizeof(log_message), "Flame detected! Temperature: %.2f°C", temperature);
                log_event(log_message);
            } else {
                log_event("Flame detected!");
            }
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c()) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115()) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler for flame sensor
    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_detected_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read temperature (for logging purposes)
        float temperature = read_temperature();
        if (temperature > 0 && temperature < TEMP_THRESHOLD) {
            char log_message[50];
            snprintf(log_message, sizeof(log_message), "Temperature: %.2f°C", temperature);
            log_event(log_message);
        } else if (temperature > TEMP_THRESHOLD) {
            char log_message[50];
            snprintf(log_message, sizeof(log_message), "Temperature: %.2f°C (Above threshold)", temperature);
            log_event(log_message);
        } else if (temperature < 0) {
            log_event("Error reading temperature.");
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

