#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define CO_CHANNEL 0 // ADS1115 channel connected to CO sensor
#define NO2_CHANNEL 1 // ADS1115 channel connected to NO2 sensor
#define CO_SENSITIVITY 0.1 // Example sensitivity (adjust based on datasheet)
#define CO_OFFSET 100.0    // Example offset (adjust based on datasheet)
#define NO2_SENSITIVITY 0.2 // Example sensitivity (adjust based on datasheet)
#define NO2_OFFSET 50.0    // Example offset (adjust based on datasheet)
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
int ads1115_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int read_ads1115(int channel);
float convert_to_ppm(int raw_value, float sensitivity, float offset);
int log_data(float co_ppm, float no2_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize ADS1115 ADC
int initialize_ads1115() {
    ads1115_handle = i2cOpen(I2C_BUS, ADS1115_ADDRESS, 0);
    if (ads1115_handle < 0) {
        fprintf(stderr, "Failed to open ADS1115 device: %d\n", ads1115_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115 for single-ended mode, 4.096V range, and 128 SPS
    // 0b01000001 00000000 (Single-ended A0, +/-4.096V, 128 SPS)
    char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x41; // Single-ended A0
    config[2] = 0x83; // 128 SPS, +/-4.096V, Continuous conversion

    if (i2cWriteDevice(ads1115_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        i2cClose(ads1115_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int channel) {
    char config[3];
    char data[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended mode, 4.096V range, and 128 SPS
    // 0b01000001 00000000 (Single-ended A0, +/-4.096V, 128 SPS)
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x41 | (channel << 1); // Single-ended A0/A1, +/-4.096V, 128 SPS
    config[2] = 0x83; // 128 SPS, +/-4.096V, Continuous conversion

    if (i2cWriteDevice(ads1115_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register for channel %d\n", channel);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    config[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(ads1115_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register for channel %d\n", channel);
        return -1;
    }

    if (i2cReadDevice(ads1115_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register for channel %d\n", channel);
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];

    return raw_value;
}

// Convert raw ADC value to PPM
float convert_to_ppm(int raw_value, float sensitivity, float offset) {
    // Assuming a logarithmic relationship: PPM = sensitivity * log10(raw_value + offset)
    // This is a simplified example; refer to the MICS-4514 datasheet for the correct formula.
    float ppm = sensitivity * log10(raw_value + offset);
    return ppm;
}

// Log data to file
int log_data(float co_ppm, float no2_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f PPM, NO2: %.2f PPM\n", timestamp, co_ppm, no2_ppm);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (ads1115_handle >= 0) {
        i2cClose(ads1115_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC values from CO and NO2 channels
        int co_raw = read_ads1115(CO_CHANNEL);
        int no2_raw = read_ads1115(NO2_CHANNEL);

        if (co_raw < 0 || no2_raw < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert raw values to PPM
        float co_ppm = convert_to_ppm(co_raw, CO_SENSITIVITY, CO_OFFSET);
        float no2_ppm = convert_to_ppm(no2_raw, NO2_SENSITIVITY, NO2_OFFSET);

        // Log data
        if (log_data(co_ppm, no2_ppm) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("CO: %.2f PPM, NO2: %.2f PPM\n", co_ppm, no2_ppm);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

