#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MICS_4514_ADDR 0x48
#define CO_REG 0x00 // Example register address for CO
#define NO2_REG 0x02 // Example register address for NO2
#define CO_PPM_SCALE_FACTOR 0.1 // Example scaling factor for CO
#define NO2_PPM_SCALE_FACTOR 0.2 // Example scaling factor for NO2
#define ALERT_THRESHOLD 25.0
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *co_adc, uint16_t *no2_adc);
float calculate_co_ppm(uint16_t co_adc);
float calculate_no2_ppm(uint16_t no2_adc);
void log_co_ppm(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS_4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *co_adc, uint16_t *no2_adc) {
    char buf[4];
    int result;

    // Read CO data
    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read CO data: %d\n", result);
        return -1;
    }
    *co_adc = (buf[0] << 8) | buf[1];

    // Read NO2 data
    result = i2cReadI2CBlockData(i2c_handle, NO2_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read NO2 data: %d\n", result);
        return -1;
    }
    *no2_adc = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to calculate CO PPM
float calculate_co_ppm(uint16_t co_adc) {
    return (float)co_adc * CO_PPM_SCALE_FACTOR;
}

// Function to calculate NO2 PPM
float calculate_no2_ppm(uint16_t no2_adc) {
    return (float)no2_adc * NO2_PPM_SCALE_FACTOR;
}

// Function to log CO PPM to file
void log_co_ppm(float co_ppm) {
    FILE *fp = fopen("co_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open co_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f PPM\n", s, co_ppm);
    fclose(fp);
}

// Function to log alert to file
void log_alert(float co_ppm) {
    FILE *fp = fopen("alert_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open alert_log.txt\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n", s, co_ppm, ALERT_THRESHOLD);
    fclose(fp);
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t co_adc, no2_adc;

        // Read sensor data
        if (read_sensor_data(&co_adc, &no2_adc) == 0) {
            // Calculate PPM values
            float co_ppm = calculate_co_ppm(co_adc);
            float no2_ppm = calculate_no2_ppm(no2_adc);

            // Log CO PPM
            log_co_ppm(co_ppm);

            // Check for alert
            if (co_ppm > ALERT_THRESHOLD) {
                log_alert(co_ppm);
            }

            printf("CO: %.2f PPM, NO2: %.2f PPM\n", co_ppm, no2_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpio uses microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

