#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define MIC_REG 0x00
#define SAMPLE_RATE 100 // milliseconds
#define MIC_SENSITIVITY -38.0 // dBV/Pa
#define REFERENCE_PRESSURE 20e-6 // Pa
#define ERROR_VALUE -999.0
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int mic1_address;
    int mic2_address;
    int mic_register;
    int sample_rate;
    double mic_sensitivity;
    double reference_pressure;
    char *log_file;
} Config;

// Function prototypes
int initialize_i2c(int bus, int address);
int read_microphone_data(int handle);
double convert_to_db(int16_t raw_data);
double calculate_average_db(double db1, double db2);
int log_data(double average_db);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C connection
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", address, handle);
        return -1;
    }
    return handle;
}

// Read microphone data
int read_microphone_data(int handle) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(handle, MIC_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading microphone data: %d\n", bytes_read);
        return -1;
    }
    return (buf[0] << 8) | buf[1]; // Combine the two bytes into a 16-bit signed integer
}

// Convert raw data to dB
double convert_to_db(int16_t raw_data) {
    double pressure = (double)raw_data / 32768.0 * REFERENCE_PRESSURE; // Assuming 16-bit ADC
    return 20.0 * log10(pressure / REFERENCE_PRESSURE) + MIC_SENSITIVITY;
}

// Calculate average dB
double calculate_average_db(double db1, double db2) {
    return (db1 + db2) / 2.0;
}

// Log data to file
int log_data(double average_db) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f dB\n", timestamp, average_db);
    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, MIC1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, MIC2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_data1 = read_microphone_data(i2c_handle1);
        int raw_data2 = read_microphone_data(i2c_handle2);

        double db1, db2, average_db;

        if (raw_data1 == -1) {
            db1 = ERROR_VALUE;
        } else {
            db1 = convert_to_db((int16_t)raw_data1);
        }

        if (raw_data2 == -1) {
            db2 = ERROR_VALUE;
        } else {
            db2 = convert_to_db((int16_t)raw_data2);
        }

        average_db = calculate_average_db(db1, db2);

        if (log_data(average_db) != 0) {
