#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_MS 1
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_MS)
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float calculate_rms(int *samples, int num_samples);
void control_led(int state);
void log_data(float rms1, float rms2);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int led_gpio;
    float rms_threshold;
    int sample_window_ms;
    int sample_interval_ms;
    int num_samples;
    int adc_channel_1;
    int adc_channel_2;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    LED_GPIO,
    RMS_THRESHOLD,
    SAMPLE_WINDOW_MS,
    SAMPLE_INTERVAL_MS,
    NUM_SAMPLES,
    ADC_CHANNEL_1,
    ADC_CHANNEL_2
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (!terminate) {
        // Sample audio from microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_adc(config.adc_channel_1);
            mic2_samples[i] = read_adc(config.adc_channel_2);
            gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
        }

        // Calculate RMS values
        float rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
        float rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Check if RMS exceeds threshold
        if (rms1 > config.rms_threshold || rms2 > config.rms_threshold) {
            control_led(1); // Turn on LED
            gpioDelay(500000); // Delay for 500 ms
            control_led(0); // Turn off LED
        }

        // Log data
        log_data(rms1, rms2);

        // Calculate elapsed time
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Delay to achieve desired sampling rate
        if (elapsed_time < (config.sample_window_ms / 1000.0)) {
            gpioDelay((config.sample_window_ms / 1000.0 - elapsed_time) * 1000000); // Delay in microseconds
        }
        clock_gettime(CLOCK_REALTIME, &start_time);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Calculate RMS value
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Control LED state
void control_led(int state) {
    gpioWrite(config.led_gpio, state);
}

// Log data to CSV file
void log_data(float rms1, float rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, rms1, rms2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

