#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    float overcurrent_threshold;
    int buffer_size;
    int sample_rate_hz;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .ads1115_address = ADS1115_ADDR,
    .led_pin = LED_GPIO,
    .overcurrent_threshold = OVERCURRENT_THRESHOLD,
    .buffer_size = BUFFER_SIZE,
    .sample_rate_hz = SAMPLE_RATE_HZ
};

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        float current;

        // Read sensor value
        if (read_ads1115(&raw_value) != 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying.\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert to current
        current = convert_to_current(raw_value);

        // Add to buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED
        if (average_current > config.overcurrent_threshold) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        // Print current reading
        printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion mode
    uint16_t config_value = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read raw value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return 1;
    }

    gpioDelay(1000); // Wait for conversion (at least 8ms for 128 SPS)

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return 1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // Assuming 5V supply and 0.5V to 4.5V output range
    // Current = (Voltage - 0.5V) / (4.5V - 0.5V) * 100A
    float voltage = (float)raw_value * 4.096 / 32768.0; // 4.096V range
    float current = (voltage - 0.5) / 4.0 * 100.0;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % config.buffer_size;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < config.buffer_size; i++) {
        sum += current_buffer[i];
    }
    return sum / config.buffer_size;
}

// Control LED state
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

