// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_CONTROL         0x0F
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A
#define TCS34725_ID              0x12

// Configuration values
#define TCS34725_INTEGRATIONTIME 0xFF  // 2.4ms
#define TCS34725_GAIN            0x01  // 4x

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    int status;
    uint8_t id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    id = (uint8_t)status;
    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Set integration time
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME);
    if (status < 0) {
        fprintf(stderr, "Error writing integration time: %d\n", status);
        return -1;
    }

    // Set gain
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN);
    if (status < 0) {
        fprintf(stderr, "Error writing gain: %d\n", status);
        return -1;
    }

    // Enable power and ADC
    status = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x01 | 0x02);
    if (status < 0) {
        fprintf(stderr, "Error enabling sensor: %d\n", status);
        return -1;
    }

    gpioDelay(3000); // Wait for power-on (3ms)

    return 0;
}

// Function to read color data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int status;

    status = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        data.clear = 0; // Set to 0 to avoid using uninitialized data
    } else {
        data.clear = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        data.red = 0;
    } else {
        data.red = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        data.green = 0;
    } else {
        data.green = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        data.blue = 0;
    } else {
        data.blue = (uint16_t)status;
    }

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int status;
    sensor_data_t sensor_data;
    int i2c_retries = 0;
    const int max_retries = 3;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    fflush(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data with retries
        i2c_retries = 0;
        do {
            sensor_data = read_sensor_data();
            if (sensor_data.clear != 0 || sensor_data.red != 0 || sensor_data.green != 0 || sensor_data.blue != 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i2c_retries + 1, max_retries);
                i2c_retries++;
                gpioDelay(10000); // Wait 10ms before retrying
            }
        } while (i2c_retries < max_retries);

        if (sensor_data.clear != 0 || sensor_data.red != 0 || sensor_data.green != 0 || sensor_data.blue != 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", max_retries);
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

