// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define SENSITIVITY 0.1 // V/A
#define OFFSET 0.05      // V
#define OVERCURRENT_THRESHOLD 10.0 // A
#define MOTOR_SHUTDOWN_PIN 17
#define LOG_FILE "current_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void overcurrent_shutdown();
void overcurrent_recovery();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    int retries = 0;
    while (retries < 3) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after 3 attempts.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to shut down the motor
void overcurrent_shutdown() {
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Set GPIO LOW
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,OVERCURRENT SHUTDOWN\n", timestamp);
    fflush(log_file);
    printf("Overcurrent detected! Motor shutdown.\n");
}

// Function to recover from overcurrent
void overcurrent_recovery() {
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Set GPIO HIGH
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,OVERCURRENT RECOVERY\n", timestamp);
    fflush(log_file);
    printf("Overcurrent recovered! Motor re-enabled.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Initially HIGH (motor enabled)

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Ensure motor is enabled on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_shutdown();
            gpioDelay(1000); // Wait 1 second
            overcurrent_recovery();
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

