#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    char *log_file_name;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_pressure(int handle, uint16_t *pressure);
float convert_to_kPa(uint16_t raw_pressure);
int log_pressure(FILE *fp, float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read pressure from the sensor
int read_pressure(int handle, uint16_t *pressure) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            *pressure = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading pressure (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw pressure to kPa
float convert_to_kPa(uint16_t raw_pressure) {
    return (float)raw_pressure / 65535.0 * 500.0;
}

// Function to log pressure data to a file
int log_pressure(FILE *fp, float pressure_kPa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function to close I2C and file handles
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX90817_ADDR,
        .log_file_name = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure;
        float pressure_kPa;

