#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 400.0
#define TEMPERATURE_MIN 0.0
#define TEMPERATURE_MAX 100.0
#define PRESSURE_THRESHOLD 105.0
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int channel, int *raw_value);
float convert_pressure(int raw_pressure);
float convert_temperature(int raw_temperature);
void display_data(float pressure, float temperature);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended readings
int configure_ads1115() {
    // Configuration register value: Single-ended AIN0, +/-6.144V, 128 SPS, Continuous conversion
    uint16_t config = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int channel, int *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw pressure value to kPa
float convert_pressure(int raw_pressure) {
    // Assuming 0V = 0 kPa, 5V = 400 kPa
    float voltage = (float)raw_pressure * 6.144 / 32768.0; // 2/3 gain, 16-bit ADC
    return voltage * 400.0;
}

// Convert raw temperature value to Celsius (simplified NTC approximation)
float convert_temperature(int raw_temperature) {
    // Assuming 1V = 0°C, 2V = 100°C
    float voltage = (float)raw_temperature * 6.144 / 32768.0; // 2/3 gain, 16-bit ADC
    return voltage * 100.0;
}

// Display pressure and temperature data
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read raw pressure and temperature values
        if (read_ads1115(0, &raw_pressure) == 0 && read_ads1115(1, &raw_temperature) == 0) {
            // Convert raw values to pressure and temperature
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);

            // Validate sensor readings
            if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX &&
                temperature >= TEMPERATURE_MIN && temperature <= TEMPERATURE_MAX) {
                // Display data
                display_data(pressure, temperature);

                // Control LED
                control_led(pressure);
            } else {
                fprintf(stderr, "Invalid sensor readings: Pressure=%.2f, Temperature=%.2f\n", pressure, temperature);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

