#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define SENSITIVITY 0.066 // 66 mV/A
#define OVERCURRENT_THRESHOLD 10.0 // 10 Amps
#define SHUTDOWN_GPIO 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    float sensitivity;
    float overcurrent_threshold;
    int shutdown_gpio;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    SENSITIVITY,
    OVERCURRENT_THRESHOLD,
    SHUTDOWN_GPIO,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        log_current(current);
        check_overcurrent(current);

        gpioDelay(100); // Sample every 100ms
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(config.shutdown_gpio, PI_OUTPUT);
    gpioWrite(config.shutdown_gpio, 0); // Initially LOW

    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    spiClose(spi_handle);
    gpioWrite(config.shutdown_gpio, 0); // Ensure shutdown is LOW
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Zero pad

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

float voltage_to_current(float voltage) {
    return (voltage - 1.65) / config.sensitivity;
}

void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

void check_overcurrent(float current) {
    if (current > config.overcurrent_threshold) {
        fprintf(stderr, "OVERCURRENT DETECTED: %.2f A\n", current);
        fprintf(log_file, "OVERCURRENT DETECTED: %.2f A\n", current);
        fflush(log_file);

        gpioWrite(config.shutdown_gpio, 1); // Set shutdown GPIO HIGH
        fprintf(stderr, "Motor shutdown triggered\n");
        fprintf(log_file, "Motor shutdown triggered\n");
        fflush(log_file);

        terminate = 1; // Stop the main loop
    }
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    fprintf(log_file, "Signal received (%d). Terminating...\n", signal);
    fflush(log_file);
    terminate = 1;
}

