#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // Reference voltage of ADS1115
#define SENSITIVITY 0.1 // kPa/V
#define OFFSET 0.5 // kPa
#define MIN_PRESSURE 0.0 // kPa
#define MAX_PRESSURE 100.0 // kPa
#define SAMPLE_INTERVAL_MS 1000 // 1 Hz

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float reference_voltage;
    float sensitivity;
    float offset;
    float min_pressure;
    float max_pressure;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_ads1115(int handle);
int16_t read_adc(int handle);
float convert_to_voltage(int16_t raw_value, float reference_voltage);
float convert_to_pressure(float voltage, float sensitivity, float offset);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
int configure_ads1115(int handle) {
    // Configuration register value: Single-ended AIN0, +/-4.096V, Continuous conversion
    uint16_t config = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc(int handle) {
    char buf[1];
    buf[0] = CONVERSION_REG;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from conversion register: %d\n", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value, float reference_voltage) {
    return (float)raw_value * reference_voltage / 32768.0;
}

// Convert voltage to pressure using linear transfer function
float convert_to_pressure(float voltage, float sensitivity, float offset) {
    return (voltage - offset) / sensitivity;
}

// Log pressure reading to file with ISO-8601 timestamp
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

