#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define VREF 5.0 // Reference voltage for MCP3208
#define R0 10000.0 // Thermistor resistance at 25°C (10kΩ)
#define BETA 3950.0 // Thermistor beta parameter
#define HUMIDITY_THRESHOLD 80.0
#define ALERT_RECIPIENT "recipient@example.com" // Replace with your email
#define ALERT_SENDER "sender@example.com" // Replace with your email
#define ALERT_SUBJECT "Humidity Alert"
#define ALERT_BODY "Humidity exceeds 80%!"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
