    float beta;
    float humidity_threshold;
    char alert_recipient[100];
    char alert_sender[100];
    char alert_subject[100];
    char alert_body[100];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3208_CHANNEL_HUMIDITY,
    MCP3208_CHANNEL_THERMISTOR,
    VREF,
    R0,
    BETA,
    HUMIDITY_THRESHOLD,
    ALERT_RECIPIENT,
    ALERT_SENDER,
    ALERT_SUBJECT,
    ALERT_BODY
};

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("humidity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_humidity = read_mcp3208(config.mcp3208_humidity_channel);
        int adc_thermistor = read_mcp3208(config.mcp3208_thermistor_channel);

        if (adc_humidity == -1 || adc_thermistor == -1) {
            fprintf(stderr, "Failed to read ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_humidity);
        float temperature = calculate_temperature(adc_thermistor);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > config.humidity_threshold) {
            send_email_alert(humidity);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }
    return 0;
}

// Read data from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    float voltage = (adc_value / 1023.0) * config.vref;
    float humidity = (voltage - 0.824) / 0.0315;

    // Clamp humidity to 0-100%
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

// Calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * config.vref;
    float resistance = (config.vref / voltage) - 1.0;
    resistance = resistance * 10000.0; // Convert to ohms

    float temperature = (1.0 / ((log(resistance / config.r0) / config.beta) + (1.0 / 298.15))) - 273.15;

    return temperature;
}

// Log data to file
void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%.2f,%.2f\n", timestamp, humidity, temperature);
}

// Send email alert using ssmtp
void send_email_alert(float humidity) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Subject: %s\n\n%s\" | ssmtp %s", config.alert_subject, config.alert_body, config.alert_recipient);
    int result = system(command);
    if (result == 0) {
        printf("Email alert sent successfully.\n");
    } else {
        fprintf(stderr, "Failed to send email alert.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

