#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define VREF 3.3 // Reference voltage
#define SENSITIVITY 0.3 // 300mV/g
#define IMPACT_THRESHOLD 2.0 // 2g
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
accelerometer_data_t read_accelerometer_data();
float convert_to_g(int adc_value);
float calculate_magnitude(accelerometer_data_t data);
void log_data(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read accelerometer data from all channels
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    data.x = read_adc(0);
    data.y = read_adc(1);
    data.z = read_adc(2);
    return data;
}

// Function to convert ADC value to g
float convert_to_g(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate an error
    }
    float voltage = (float)adc_value * VREF / 1024.0;
    float g = (voltage - 1.65) / SENSITIVITY;
    return g;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(accelerometer_data_t data) {
    float x_g = convert_to_g(data.x);
    float y_g = convert_to_g(data.y);
    float z_g = convert_to_g(data.z);

    if (x_g < -1.0 || x_g > 1.0 || y_g < -1.0 || y_g > 1.0 || z_g < -1.0 || z_g > 1.0) {
        fprintf(stderr, "Error: Acceleration values out of range. Skipping magnitude calculation.\n");
        return -1.0; // Indicate an error
    }

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log data to file
void log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d", timestamp, data.x, data.y, data.z);

    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, ",IMPACT DETECTED\n");
    } else {
        fprintf(log_file, ",\n");
    }

    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close SPI and file
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude >= 0) {
            log_data(data, magnitude);
        } else {
            fprintf(stderr, "Error: Could not calculate magnitude. Skipping logging.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US); // Delay for 10ms (100Hz)
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

