#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define TEMPERATURE_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float compensate_voltage(float voltage, float temperature);
int read_temperature();
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
                retries++;
                gpioDelay(10); // Small delay before retry
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
            retries++;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Error: Failed to read ADC value after %d retries.\n", MAX_RETRIES);
    log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
    return -1; // Indicate failure
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to compensate voltage for temperature
float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to read temperature from file
int read_temperature() {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open temperature file. Using default temperature: 25.0\n");
        return 250; // Default temperature * 10
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Warning: Could not read temperature from file. Using default temperature: 25.0\n");
        fclose(fp);
        return 250; // Default temperature * 10
    }

    fclose(fp);

    char *endptr;
    long temp_celsius = strtol(line, &endptr, 10);

    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Warning: Invalid temperature format in file. Using default temperature: 25.0\n");
        return 250; // Default temperature * 10
    }

    if (temp_celsius < -40 || temp_celsius > 125) {
        fprintf(stderr, "Warning: Temperature out of range. Using default temperature: 25.0\n");
        return 250; // Default temperature * 10
    }

    return (int)(temp_celsius * 10); // Return temperature * 10
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.1f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature / 10.0, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    if (flame_detected) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer ON
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        int raw_temperature = read_temperature();
        float temperature = raw_temperature / 10.0;

        // Read ADC value
        int raw_adc = read_mcp3008(0);
        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Skipping iteration.\n");
            gpioDelay(500); // Wait 500ms before next iteration
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(raw_adc);

        // Compensate voltage for temperature
        float compensated_voltage = compensate_voltage(voltage, temperature);

        // Check for flame detection
        int flame_detected = (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, raw_temperature, flame_detected);

        // Control buzzer
        control_buzzer(flame_detected);

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    fclose(log_file);
    gpioTerminate();

    return 0;
}

