#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_water_level(float percentage);
void control_led(float percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        pigpio_error("Invalid MCP3008 channel");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        pigpio_error("SPI transfer failed");
        return -1;
    }

    // Parse ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log water level to JSON file
void log_water_level(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ldZ", timeinfo->tm_sec);

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage);
    fflush(json_file); // Ensure data is written to disk immediately
}

// Function to control LED based on water level
void control_led(float percentage) {
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED ON
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        pigpio_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED OFF

    // Open JSON file
    json_file = fopen(JSON_FILE, "a");
    if (json_file == NULL) {
        perror("Failed to open JSON file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write JSON array start if the file is newly created
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If the file already contains data, go back one character and overwrite the closing bracket
        fseek(json_file, -1, SEEK_END);
        char last_char;
        fread(&last_char, 1, 1, json_file);
        if (last_char == ']') {
            fseek(json_file, -1, SEEK_END);
            fprintf(json_file, ",");
        } else {
            fprintf(stderr, "JSON file is in an invalid state.  Appending to the end.\n");
        }
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close JSON file
    fprintf(json_file, "]\n");
    fclose(json_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in 5 seconds...\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert to percentage
        float percentage = convert_to_percentage(adc_value);

        // Log water level
        log_water_level(percentage);

        // Control LED
        control_led(percentage);

        printf("Water level: %.2f%%\n", percentage);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    printf("Water level monitoring stopped.\n");
    return 0;
}

