#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define AWM7300V_MIN_VOLTAGE 0.0 // Volts
#define AWM7300V_MAX_VOLTAGE 5.0 // Volts
#define AWM7300V_MIN_FLOW_RATE 0.0 // LPM
#define AWM7300V_MAX_FLOW_RATE 20.0 // LPM
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float convert_to_lpm(float voltage);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float awm7300v_min_voltage;
    float awm7300v_max_voltage;
    float awm7300v_min_flow_rate;
    float awm7300v_max_flow_rate;
    int sample_interval_ms;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    AWM7300V_MIN_VOLTAGE,
    AWM7300V_MAX_VOLTAGE,
    AWM7300V_MIN_FLOW_RATE,
    AWM7300V_MAX_FLOW_RATE,
    SAMPLE_INTERVAL_MS,
    LOG_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (LPM)\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d ms.\n", config.sample_interval_ms);
            gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Convert voltage to flow rate
        float flow_rate = convert_to_lpm(voltage);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Failed to log data. Retrying in %d ms.\n", config.sample_interval_ms);
        }

        // Delay
        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.awm7300v_max_voltage;
}

// Convert voltage to flow rate (LPM)
float convert_to_lpm(float voltage) {
    return (voltage - config.awm7300v_min_voltage) / (config.awm7300v_max_voltage - config.awm7300v_min_voltage) * (config.awm7300v_max_flow_rate - config.awm7300v_min_flow_rate) + config.awm7300v_min_flow_rate;
}

// Log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to log file
    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }

    // Flush the buffer to ensure data is written immediately
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
