#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define PRESSURE_MIN 0.1
#define PRESSURE_MAX 1.5
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define ADC_MIN 0
#define ADC_MAX 1023
#define SLEEP_INTERVAL 1 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float pressure_min;
    float pressure_max;
    float voltage_min;
    float voltage_max;
    int adc_min;
    int adc_max;
    int sleep_interval;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_adc(int channel);
float convert_adc_to_voltage(int adc_value);
float map_voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to voltage
float convert_adc_to_voltage(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return ((float)adc_value / ADC_MAX) * VREF;
}

// Map voltage to pressure (kPa)
float map_voltage_to_pressure(float voltage) {
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
        return -1.0; // Indicate error
    }
    return PRESSURE_MIN + ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * (PRESSURE_MAX - PRESSURE_MIN);
}

// Log pressure reading with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure sensor reading started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying in %d seconds...\n", SLEEP_INTERVAL);
            sleep(SLEEP_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Failed to convert ADC to voltage, retrying in %d seconds...\n", SLEEP_INTERVAL);
            sleep(SLEEP_INTERVAL);
            continue;
        }

        // Map voltage to pressure
        float pressure = map_voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Failed to map voltage to pressure, retrying in %d seconds...\n", SLEEP_INTERVAL);
            sleep(SLEEP_INTERVAL);
            continue;
        }

        // Log pressure reading
        log_pressure(pressure);

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

