#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define BUFFER_CAPACITY 20
#define SAMPLE_INTERVAL 5 // seconds

// Data structure for logging
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_CAPACITY];
int buffer_index = 0;
int buffer_count = 0;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_CAPACITY;
    if (buffer_count < BUFFER_CAPACITY) {
        buffer_count++;
    }
}

// Function to print the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_CAPACITY) % BUFFER_CAPACITY;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize pump to OFF state
    control_pump(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = OFF, 1 = ON
    int moisture_level;

    // Main loop
    while (!terminate) {
        // Read moisture level from MCP3008
        moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            // Optionally add retry logic here
        } else {
            // Control pump based on moisture level
            if (moisture_level < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                control_pump(1);
                pump_state = 1;
                printf("Moisture level: %d, Pump ON\n", moisture_level);
            } else if (moisture_level > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                control_pump(0);
                pump_state = 0;
                printf("Moisture level: %d, Pump OFF\n", moisture_level);
            } else {
                printf("Moisture level: %d, Pump %s\n", moisture_level, pump_state ? "ON" : "OFF");
            }

            // Log data
            log_data(moisture_level, pump_state);

            // Print log buffer
            print_log_buffer();
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpio uses microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

