#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
void log_data(int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    int num_channels;
    int retry_count;
    int retry_delay_ms;
    int log_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    VREF,
    NUM_CHANNELS,
    RETRY_COUNT,
    RETRY_DELAY_MS,
    LOG_INTERVAL_MS
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (result == 0) {
            // Extract ADC value
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ + null terminator

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, 1MHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("analog_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    rewind(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Analog data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < config.num_channels; ++channel) {
            int adc_value = read_mcp3008(channel);
            if (adc_value >= 0) {
                float voltage = calculate_voltage(adc_value);
                log_data(channel, voltage);
                printf("Channel %d: Voltage = %.3f V\n", channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        gpioDelay(config.log_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

