    while (!terminate) {
        // Read ADC value from MQ-2 sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate gas concentration
        float gas_concentration = calculate_gas_concentration(adc_value);

        // Control buzzer based on gas concentration
        if (gas_concentration < LOW_THRESHOLD) {
            control_buzzer(0); // Turn buzzer OFF
        } else {
            control_buzzer(1); // Turn buzzer ON
        }

