        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Reset GPIO states
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer OFF

    // Terminate pigpio library
    gpioTerminate();

    printf("Gas sensor monitoring stopped.\n");

    return 0;
}

