#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_RELAY 17
#define GPIO_REED_SENSOR 27
#define LOG_FILE "/var/log/door_events.log"
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_INTERVAL_MS 50
#define THRESHOLD_MULTIPLIER 0.8
#define POLL_INTERVAL_MS 200
#define RELAY_DURATION_S 3
#define RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *value);
float calibrate_threshold(int16_t *baseline_samples, int num_samples);
int control_relay(int state);
int read_reed_sensor();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int gpio_relay;
    int gpio_reed_sensor;
    char log_file[256];
    int num_baseline_samples;
    int baseline_sample_interval_ms;
    float threshold_multiplier;
    int poll_interval_ms;
    int relay_duration_s;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int16_t *value) {
    uint8_t config[3];
    uint8_t buffer[2];
    int retries = RETRY_COUNT;

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, +/- 6.144V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    while (retries > 0) {
        if (write(i2c_fd, config, 3) == 3) {
            break;
        } else {
            perror("Error writing to ADS1115");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    if (retries == 0) {
        log_event("Failed to write to ADS1115 after multiple retries.");
        return -1;
    }

    usleep(100000); // Wait for conversion (at least 8ms for 128 SPS)

    retries = RETRY_COUNT;
    while (retries > 0) {
        if (write(i2c_fd, &ADS1115_REG_CONVERT, 1) == 1) {
            if (read(i2c_fd, buffer, 2) == 2) {
                *value = (buffer[0] << 8) | buffer[1];
                return 0;
            } else {
                perror("Error reading from ADS1115");
                retries--;
                usleep(10000); // 10ms delay
            }
        } else {
            perror("Error writing to ADS1115 for read");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    log_event("Failed to read from ADS1115 after multiple retries.");
    return -1;
}

// Calibrate the threshold based on baseline samples
float calibrate_threshold(int16_t *baseline_samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += baseline_samples[i];
    }
    float average = (float)(sum / num_samples);
    return average * THRESHOLD_MULTIPLIER;
}

// Control the relay (1 = ON, 0 = OFF)
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Read the reed sensor (0 = door open, 1 = door closed)
int read_reed_sensor() {
    return gpioRead(GPIO_REED_SENSOR);
}

// Log an event to the log file
void log_event(const char *message) {
    if (log_fp != NULL) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_fp, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, message);
        fflush(log_fp);
    } else {
        perror("Error opening log file");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");
    control_relay(0); // De-energize relay

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_REED_SENSOR, PI_INPUT);
    gpioSetPullUpDown(GPIO_REED_SENSOR, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    log_event("Door lock system started");

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Calibrate threshold
    int16_t baseline_samples[NUM_BASELINE_SAMPLES];
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_ads1115(&baseline_samples[i]) != 0) {
            log_event("Failed to read baseline sample, using default threshold");
            baseline_samples[i] = 1000; // Default value
        }
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }
    float threshold = calibrate_threshold(baseline_samples, NUM_BASELINE_SAMPLES);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Threshold calibrated to: %.2f", threshold);
    log_event(log_message);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t distance;
    int reed_state;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&distance) == 0) {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Distance: %d", distance);
            log_event(log_message);

            if (distance < threshold) {
                log_event("Distance below threshold, releasing door lock");
                control_relay(1); // Energize relay
                usleep(RELAY_DURATION_S * 1000000); // Wait for relay duration
                control_relay(0); // De-energize relay

                reed_state = read_reed_sensor();
                if (reed_state == 0) {
                    log_event("Door opened");
                } else {
                    log_event("Door not opened");
                }
            }
        } else {
            log_event("Failed to read distance");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    log_event("Door lock system stopped");
    return 0;
}

