    for (int i = 0; i < num_samples; i++) {
        sum += baseline_samples[i];
    }
    float average = (float)(sum / num_samples);
    return average * THRESHOLD_MULTIPLIER;
}

// Control the relay (1 = ON, 0 = OFF)
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Read the reed sensor (0 = door open, 1 = door closed)
int read_reed_sensor() {
    return gpioRead(GPIO_REED_SENSOR);
}

// Log an event to the log file
void log_event(const char *message) {
    if (log_fp != NULL) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_fp, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, message);
        fflush(log_fp);
    } else {
        perror("Error opening log file");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");
    control_relay(0); // De-energize relay

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_REED_SENSOR, PI_INPUT);
    gpioSetPullUpDown(GPIO_REED_SENSOR, PI_PUD_UP); // Enable pull-up resistor

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    log_event("Door lock system started");

    // Initialize I2C
    if (init_i2c() != 0) {
        log_event("I2C initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Calibrate threshold
    int16_t baseline_samples[NUM_BASELINE_SAMPLES];
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_ads1115(&baseline_samples[i]) != 0) {
            log_event("Failed to read baseline sample, using default threshold");
            baseline_samples[i] = 1000; // Default value
        }
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }
    float threshold = calibrate_threshold(baseline_samples, NUM_BASELINE_SAMPLES);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Threshold calibrated to: %.2f", threshold);
    log_event(log_message);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t distance;
    int reed_state;

    // Main loop
    while (!terminate) {
        if (read_ads1115(&distance) == 0) {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Distance: %d", distance);
            log_event(log_message);

            if (distance < threshold) {
                log_event("Distance below threshold, releasing door lock");
                control_relay(1); // Energize relay
                usleep(RELAY_DURATION_S * 1000000); // Wait for relay duration
                control_relay(0); // De-energize relay

                reed_state = read_reed_sensor();
                if (reed_state == 0) {
                    log_event("Door opened");
                } else {
                    log_event("Door not opened");
                }
            }
        } else {
            log_event("Failed to read distance");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    log_event("Door lock system stopped");
    return 0;
}

