#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define SPI mode
#define SPI_MODE SPI_MODE_0

// Define SPI speed (1 MHz)
#define SPI_SPEED 1000000

// Define MCP3008 command to read channel 0
#define MCP3008_COMMAND 0x01

// Define MCP3008 channel to read
#define MCP3008_CHANNEL 0

// Define log file name
#define LOG_FILE "soil_moisture_log.csv"

// Global variables for SPI file descriptor and GPIO chip
int spi_fd = -1;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t cs_pin, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(uint8_t cs_pin, uint8_t channel);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int gpio_init(void);
int gpio_request(int pin);
int gpio_set_value(int pin, int value);
int gpio_release(int pin);

// Structure to hold GPIO line information
struct gpiod_line *cs0_line = NULL;
struct gpiod_line *cs1_line = NULL;
struct gpiod_line *cs2_line = NULL;

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to perform SPI transfer
int spi_transfer(uint8_t cs_pin, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    // Assert chip select line
    if (gpio_set_value(cs_pin, 0) < 0) {
        fprintf(stderr, "Error setting CS pin %d low\n", cs_pin);
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error performing SPI transfer");
        // Deassert chip select line even on error
        gpio_set_value(cs_pin, 1);
        return -1;
    }

    // Deassert chip select line
    if (gpio_set_value(cs_pin, 1) < 0) {
        fprintf(stderr, "Error setting CS pin %d high\n", cs_pin);
        return -1;
    }

    return 0;
}

// Function to read data from MCP3008
int read_mcp3008(uint8_t cs_pin, uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = MCP3008_COMMAND;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    // Perform SPI transfer
    if (spi_transfer(cs_pin, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading from MCP3008 on CS pin %d\n", cs_pin);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int sensor1, int sensor2, int sensor3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Write data to file
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);

    // Close file
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO lines
    if (cs0_line) {
        gpio_release(CS0_PIN);
    }
    if (cs1_line) {
        gpio_release(CS1_PIN);
    }
    if (cs2_line) {
        gpio_release(CS2_PIN);
    }

    // Release GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to initialize GPIO chip
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    return 0;
}

// Function to request GPIO line
int gpio_request(int pin) {
    char line_name[32];
    snprintf(line_name, sizeof(line_name), "gpio%d", pin);

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, line_name);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(line, "soil_moisture", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set GPIO line value
int gpio_set_value(int pin, int value) {
    char line_name[32];
    snprintf(line_name, sizeof(line_name), "gpio%d", pin);

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, line_name);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to release GPIO line
int gpio_release(int pin) {
    char line_name[32];
    snprintf(line_name, sizeof(line_name), "gpio%d", pin);

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, line_name);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return 1;
    }

    // Request GPIO lines
    if (gpio_request(CS0_PIN) < 0 || gpio_request(CS1_PIN) < 0 || gpio_request(CS2_PIN) < 0) {
        gpio_release(CS0_PIN);
        gpio_release(CS1_PIN);
        gpio_release(CS2_PIN);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        gpio_release(CS0_PIN);
        gpio_release(CS1_PIN);
        gpio_release(CS2_PIN);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Check if the log file is empty and write the header if needed
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("Error creating log file");
            close(spi_fd);
            gpio_release(CS0_PIN);
            gpio_release(CS1_PIN);
            gpio_release(CS2_PIN);
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        fprintf(fp, "Timestamp,Sensor1,Sensor2,Sensor3\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1 = read_mcp3008(CS0_PIN, MCP3008_CHANNEL);
        int sensor2 = read_mcp3008(CS1_PIN, MCP3008_CHANNEL);
        int sensor3 = read_mcp3008(CS2_PIN, MCP3008_CHANNEL);

        // Log data
        if (log_data(sensor1, sensor2, sensor3) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

