#define MCP3008_CHANNEL 0
#define EMA_ALPHA 0.1
#define THRESHOLD_MULTIPLIER 1.2
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_ema(double new_value, double previous_ema);
int detect_peak(double raw_value, double ema);
int log_event(double raw_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate exponential moving average
double calculate_ema(double new_value, double previous_ema) {
    return EMA_ALPHA * new_value + (1 - EMA_ALPHA) * previous_ema;
}

// Function to detect peak
int detect_peak(double raw_value, double ema) {
    double threshold = ema * THRESHOLD_MULTIPLIER;
    return (raw_value > threshold) ? 1 : 0;
}

// Function to log event to file
int log_event(double raw_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, Raw Value: %d\n", timestamp, (int)raw_value);
    fclose(fp);
    return 0;
}

