#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the control byte for single-ended AIN0
#define CONTROL_BYTE 0x40 // 10000000

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to write a byte to the I2C device
int write_i2c_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from the I2C device
int read_i2c_byte(int fd) {
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return data;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (set_i2c_slave(i2c_fd, PCF8591_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print the ADC value
    while (1) {
        // Write the control byte to configure the ADC
        if (write_i2c_byte(i2c_fd, CONTROL_BYTE) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Read a dummy byte to clear the previous conversion
        if (read_i2c_byte(i2c_fd) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Read the ADC value
        int adc_value = read_i2c_byte(i2c_fd);
        if (adc_value < 0) {
            close(i2c_fd);
            return 1;
        }

        // Print the ADC value to stdout
        printf("AIN0: %d\n", adc_value);

        // Delay for 100 milliseconds
        usleep(100000); // 100 ms
    }

    // The program should never reach here due to the infinite loop
    close(i2c_fd);
    return 0;
}

