#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_SHUTDOWN 27
#define THRESHOLD 500.0 // Gauss
#define BUFFER_SIZE 10
#define SLEEP_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int16_t read_ads1115(int channel);
float convert_to_gauss(int16_t raw_value);
void add_to_buffer(float gauss);
float calculate_rolling_average();
void control_shutdown(float average_gauss);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Initially LOW
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int16_t read_ads1115(int channel) {
    // Configuration register value: Single-ended, 4.096V, 128 SPS, continuous conversion
    uint16_t config = 0x4003; // Default config, single-ended AIN0
    if (channel == 1) {
        config = 0x4103; // Single-ended AIN1
    } else if (channel == 2) {
        config = 0x4203; // Single-ended AIN2
    } else if (channel == 3) {
        config = 0x4303; // Single-ended AIN3
    }

    // Write configuration to ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read conversion register
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from ADS1115");
        return -1;
    }

    // Combine the two bytes to get the 16-bit result
    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

    return raw_value;
}

