float convert_to_gauss(int16_t raw_value) {
    // Assuming 3.3V reference, 16-bit resolution, and sensitivity of 1.4 mV/Gauss
    float voltage = (float)raw_value * 3.3 / 32768.0; // Convert to voltage
    float gauss = (voltage - 2.5) / 0.0014; // Convert to Gauss
    return gauss;
}

