void add_to_buffer(float gauss) {
    magnetic_field_buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the buffer
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

