    syslog(priority, "%s", log_entry);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, 0); // Ensure shutdown is LOW
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("honeywell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Honeywell monitor started");

    // Main loop
    while (!terminate) {
        // Read sensor values from all four channels
        int16_t raw_value0 = read_ads1115(0);
        int16_t raw_value1 = read_ads1115(1);
        int16_t raw_value2 = read_ads1115(2);
        int16_t raw_value3 = read_ads1115(3);

        // Convert raw values to Gauss
        float gauss0 = convert_to_gauss(raw_value0);
        float gauss1 = convert_to_gauss(raw_value1);
        float gauss2 = convert_to_gauss(raw_value2);
        float gauss3 = convert_to_gauss(raw_value3);

        // Log sensor readings
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Sensor 0: %.2f Gauss, Sensor 1: %.2f Gauss, Sensor 2: %.2f Gauss, Sensor 3: %.2f Gauss",
                 gauss0, gauss1, gauss2, gauss3);
