        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    gpioPWM(PWM_MOTOR, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure MCP3008 CE pin as output
    gpioSetMode(MCP3008_CE, PI_OUTPUT);
    gpioWrite(MCP3008_CE, 0); // Ensure CE is low initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
