#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SENSITIVITY 0.001 // 1 mV/Gauss = 0.001 V/Gauss
#define ZERO_GAUSS_OUTPUT 1.65 // 1.65V
#define VREF 4.096 // Reference voltage for ADS1115

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int16_t *raw_value);
double convert_to_gauss(int16_t raw_value);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double threshold;
} Config;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char data[2];

    // Configure ADS1115 for single-ended AIN0, 4.096V gain, continuous conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010: OS=1, MUX=010, PGA=111, MODE=1, DR=100, COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11
    config[2] = 0x83; // 0b10000011: COMP_TH_MSB=00, COMP_TH_LSB=00, COMP_TR=00, COMP_HYST=00

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write to conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    double voltage = (double)raw_value * VREF / 32768.0; // 2^15 = 32768
    double gauss = (voltage - ZERO_GAUSS_OUTPUT) / SENSITIVITY;
    return gauss;
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    double gauss;

    // Main loop
    while (!terminate) {
        // Read sensor value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss = convert_to_gauss(raw_value);

            // Print Gauss value
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            // Check threshold and blink LED
            if (gauss > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                for (int i = 0; i < 50; ++i) { // Blink for 1 second (50 * 10ms = 500ms)
                    control_led(1);
                    gpioDelay(50); // 50ms on
                    control_led(0);
                    gpioDelay(50); // 50ms off
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

