#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_TOPIC_PUMP_STATUS "pump_status"
#define MQTT_QOS 1
#define READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void publish_moisture(float moisture);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %d", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC range is 0-1023 and moisture range is 0-100%
    // This is a linear mapping.  Adjust as needed for your sensor.
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
    } else {
        syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
    }
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int result = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, MQTT_QOS, false);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture reading: %s", mosquitto_strerror(result));
    } else {
        syslog(LOG_INFO, "Published moisture reading: %.2f", moisture);
    }
}

// MQTT on_connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(result));
    }
}

// MQTT on_message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                control_pump(1);
                mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUMP_STATUS, 4, "ON", MQTT_QOS, false);
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                control_pump(0);
                mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUMP_STATUS, 3, "OFF", MQTT_QOS, false);
            } else {
                syslog(LOG_WARNING, "Invalid pump command: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(result));
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = off, 1 = on
    float last_moisture = -1.0; // Initialize to an invalid value

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);

        // Publish moisture reading
        publish_moisture(moisture);

        // Control pump based on hysteresis
        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_pump(1);
            pump_state = 1;
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_pump(0);
            pump_state = 0;
        }

        // Check for significant changes in moisture
        if (last_moisture != -1.0 && fabs(moisture - last_moisture) > 5.0) {
            syslog(LOG_WARNING, "Significant change in moisture: %.2f -> %.2f", last_moisture, moisture);
        }

        last_moisture = moisture;

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup
    control_pump(0); // Ensure pump is off on exit
    spiClose(spi_handle);
    gpioTerminate();
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

