    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Data logging started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from channels
        int adc_value0 = read_mcp3008(CHANNEL_0);
        int adc_value1 = read_mcp3008(CHANNEL_1);
        int adc_value2 = read_mcp3008(CHANNEL_2);

        // Check for errors during ADC readings
        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 5 seconds
            continue;
        }

        // Convert ADC values to voltages
        float voltage0 = adc_to_voltage(adc_value0, VREF);
        float voltage1 = adc_to_voltage(adc_value1, VREF);
