        if (voltage0 == -1.0 || voltage1 == -1.0 || voltage2 == -1.0) {
            fprintf(stderr, "Error: Failed to convert ADC values to voltages. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 5 seconds
            continue;
        }

        // Log data
        log_data(voltage0, voltage1, voltage2);

        // Delay for 5 seconds
        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

