#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI device and parameters
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define noise threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define log file path
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
void set_motor_pwm(int gpio, int duty_cycle);
void log_event(int adc_value);
void signal_handler(int signal);
void cleanup(void);

// Structure to hold configuration data
typedef struct {
    int motor1_gpio;
    int motor2_gpio;
    int spi_device;
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int noise_threshold;
    int pwm_frequency;
    char log_file[64];
} config_t;

config_t config = {
    MOTOR1_GPIO,
    MOTOR2_GPIO,
    SPI_DEVICE,
    SPI_MODE,
    SPI_BITS_PER_WORD,
    SPI_SPEED,
    NOISE_THRESHOLD,
    PWM_FREQUENCY,
    LOG_FILE
};

// SPI initialization function
int spi_init(void) {
    spi_fd = open(config.spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = config.spi_mode;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = config.spi_bits_per_word;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = config.spi_speed;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = config.spi_speed;
    transfer[0].bits_per_word = config.spi_bits_per_word;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to set PWM duty cycle for a motor
void set_motor_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log event to file
void log_event(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Noise detected: ADC Value = %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");
    // Stop motors
    set_motor_pwm(config.motor1_gpio, 0);
    set_motor_pwm(config.motor2_gpio, 0);

    // Close SPI device
    if (spi_fd > 0) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(config.motor1_gpio, PI_OUTPUT);
    gpioSetMode(config.motor2_gpio, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set PWM frequency for motors
    gpioSetPWMfrequency(config.motor1_gpio, config.pwm_frequency);
    gpioSetPWMfrequency(config.motor2_gpio, config.pwm_frequency);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;
        }

        // Check noise threshold
        if (adc_value > config.noise_threshold) {
            // Map ADC value to PWM duty cycle (0-255)
            int duty_cycle = (int)(((float)adc_value / 1023.0) * 255.0);

            // Set PWM duty cycle for both motors
            set_motor_pwm(config.motor1_gpio, duty_cycle);
            set_motor_pwm(config.motor2_gpio, duty_cycle);

            // Log the event
            log_event(adc_value);
        } else {
            // Turn off motors
            set_motor_pwm(config.motor1_gpio, 0);
            set_motor_pwm(config.motor2_gpio, 0);
        }

        // Delay for 10 ms
        gpioDelay(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

