    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        close(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
