int read_bh1750() {
    // Send start measurement command
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for measurement (at least 180 ms)
    gpioDelay(180000); // 180 ms

    // Read 2 bytes of data
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    // Convert data to lux
    int lux = (buffer[0] << 8) | buffer[1];
    return lux;
