    // Initialize resources
    if (initialize() != 0) {
        return 1;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        int light_level = read_bh1750();
        float sound_level = -1.0; // Initialize to an invalid value
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            error_code |= 1; // Set ADC error bit
        } else {
            sound_level = adc_to_db(adc_value);
        }

        if (light_level < 0) {
            fprintf(stderr, "Error reading light level\n");
            error_code |= 2; // Set light sensor error bit
        }

        log_data(sound_level, light_level, error_code);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

