#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            // Extract ADC value from response
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming 0 ADC value = 3V, 1023 ADC value = 0V
    float voltage = (float)adc_value / 1023.0 * 3.0;
    float moisture_percentage = 100.0 - (voltage / 3.0) * 100.0;

    // Clamp the percentage to the range 0-100
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    printf("Pump set to %s\n", state ? "ON" : "OFF");
}

// Function to log data with timestamp
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Calculate moisture percentage
            float moisture_percentage = calculate_moisture_percentage(adc_value);

            // Log data
            log_data(moisture_percentage);

            // Control pump based on moisture level
            if (moisture_percentage < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn pump ON
            } else {
                control_pump(0); // Turn pump OFF
            }
        }

        // Wait for 60 seconds
        gpioDelay(60000);
    }

    // Cleanup
    control_pump(0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

