#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define POLLING_INTERVAL 100 // ms
#define DEBOUNCE_DELAY 1000 // ms
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_distance(int adc_value);
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            log_event("SPI transfer failed");
            gpioDelay(10); // Small delay before retrying
            retries++;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries\n", MAX_RETRIES);
    log_event("SPI transfer failed after multiple retries");
    return -1; // Indicate failure
}

// Function to convert ADC value to distance (cm)
float adc_to_distance(int adc_value) {
    // GP2Y0A21YK0F: 10-80cm range, 1024 ADC units
    // Distance (cm) = 27.86 * (ADC_Value / 1023) ^ -1.15
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    float voltage = (adc_value / 1023.0) * 3.3; // Assuming 3.3V reference
    float distance = 27.86 * pow(voltage / 3.3, -1.15);

    return distance;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char event_message[50];
    snprintf(event_message, sizeof(event_message), "Relay set to %s", state ? "ON" : "OFF");
    log_event(event_message);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_event("Program terminated by signal");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Door monitoring started. Press Ctrl+C to exit.\n");
    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_event("Failed to read ADC value");
            gpioDelay(POLLING_INTERVAL);
            continue;
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to convert ADC value to distance\n");
            log_event("Failed to convert ADC value to distance");
            gpioDelay(POLLING_INTERVAL);
            continue;
        }

        char distance_message[50];
        snprintf(distance_message, sizeof(distance_message), "Distance: %.2f cm", distance);
        log_event(distance_message);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            printf("Proximity detected! Distance: %.2f cm\n", distance);
            log_event("Proximity detected");

            // Energize relay
            control_relay(1);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY);

            // De-energize relay
            control_relay(0);
        }

        // Polling interval
        gpioDelay(POLLING_INTERVAL);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

