// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 100

// Define log file path
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle0, spi_handle1;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float average_sensors(int sensor1, int sensor2, int sensor3);
int map_to_valve_position(float average);
void set_valve_position(int valve_position);
void log_data(int sensor1, int sensor2, int sensor3, float average, int valve_position);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI command (single-ended mode)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average sensor readings
float average_sensors(int sensor1, int sensor2, int sensor3) {
    float sum = 0.0;
    int count = 0;

    if (sensor1 >= 0) {
        sum += sensor1;
        count++;
    }
    if (sensor2 >= 0) {
        sum += sensor2;
        count++;
    }
    if (sensor3 >= 0) {
        sum += sensor3;
        count++;
    }

    if (count == 0) {
        return -1.0; // Indicate no valid readings
    }

    return sum / count;
}

// Function to map average sensor reading to valve position (0-100%)
int map_to_valve_position(float average) {
    if (average < 0) return 0; // Handle invalid average
    if (average > 1023) return 100; // Handle out-of-range average

    // Invert the mapping: dry soil (low ADC value) gives high opening, wet soil (high ADC value) gives low opening
    return 100 - (int)((average / 1023.0) * 100.0);
}

