    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channels
    spi_handle0 = spiOpen(SPI_CE0, SPI_SPEED, SPI_MODE);
    if (spi_handle0 < 0) {
        fprintf(stderr, "Error: SPI open failed (CE0): %d\n", spi_handle0);
        gpioTerminate();
        return 1;
    }

