    if (spi_handle1 < 0) {
        fprintf(stderr, "Error: SPI open failed (CE1): %d\n", spi_handle1);
        spiClose(spi_handle0);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PIN, PWM_RANGE);

