    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle0);
        spiClose(spi_handle1);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_0 = read_mcp3008(spi_handle0, 0);
        int sensor2_0 = read_mcp3008(spi_handle0, 1);
        int sensor3_0 = read_mcp3008(spi_handle0, 2);

        int sensor1_1 = read_mcp3008(spi_handle1, 0);
        int sensor2_1 = read_mcp3008(spi_handle1, 1);
        int sensor3_1 = read_mcp3008(spi_handle1, 2);

        // Average sensor readings
        float average0 = average_sensors(sensor1_0, sensor2_0, sensor3_0);
        float average1 = average_sensors(sensor1_1, sensor2_1, sensor3_1);

        // Map to valve position
        int valve_position0 = map_to_valve_position(average0);
        int valve_position1 = map_to_valve_position(average1);

        // Set valve position
        set_valve_position(valve_position0);

        // Log data
        log_data(sensor1_0, sensor2_0, sensor3_0, average0, valve_position0);
        log_data(sensor1_1, sensor2_1, sensor3_1, average1, valve_position1);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_valve_position(0); // Close the valve
    spiClose(spi_handle0);
    spiClose(spi_handle1);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");
