#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 5
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    char log_file[64];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    LOG_FILE
};

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

            // Validate ADC value
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
                return -1; // Indicate error
            }
        } else {
            fprintf(stderr, "SPI communication error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(10000 * (1 << retries)); // Exponential backoff (10ms, 20ms, 40ms, 80ms, 160ms)
            retries++;
        }
    }

    fprintf(stderr, "Error: SPI communication failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate persistent error
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    // Assuming 0 ADC value = 100% moisture, 1023 ADC value = 0% moisture
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", config.log_file);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value >= 0) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            log_data(moisture_percentage);
            printf("Moisture percentage: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

