    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_CHANNEL);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty_cycle file");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", duty_cycle);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to PWM duty_cycle file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Save calibration data to file
int save_calibration_data(const char *filename, const CalibrationData *calibration) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Failed to open calibration file for writing");
        return -1;
    }

    fprintf(fp, "ldr_min_adc=%.2f\n", calibration->ldr_min_adc);
    fprintf(fp, "ldr_max_adc=%.2f\n", calibration->ldr_max_adc);
    fprintf(fp, "ldr_min_voltage=%.2f\n", calibration->ldr_min_voltage);
    fprintf(fp, "ldr_max_voltage=%.2f\n", calibration->ldr_max_voltage);

    fclose(fp);
    return 0;
}

// Load calibration data from file
int load_calibration_data(const char *filename, CalibrationData *calibration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Failed to open calibration file for reading");
        return -1;
    }

    if (fscanf(fp, "ldr_min_adc=%f\n", &calibration->ldr_min_adc) != 1) {
        fprintf(stderr, "Error reading ldr_min_adc from file\n");
        fclose(fp);
        return -1;
    }
    if (fscanf(fp, "ldr_max_adc=%f\n", &calibration->ldr_max_adc) != 1) {
        fprintf(stderr, "Error reading ldr_max_adc from file\n");
        fclose(fp);
        return -1;
    }
    if (fscanf(fp, "ldr_min_voltage=%f\n", &calibration->ldr_min_voltage) != 1) {
        fprintf(stderr, "Error reading ldr_min_voltage from file\n");
        fclose(fp);
        return -1;
    }
    if (fscanf(fp, "ldr_max_voltage=%f\n", &calibration->ldr_max_voltage) != 1) {
        fprintf(stderr, "Error reading ldr_max_voltage from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("theremin.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Load calibration data
    if (load_calibration_data("theremin_config.txt", &calibration) != 0) {
        log_message("Failed to load calibration data, using default values.");
    }

    // Initialize hardware
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed.");
        fclose(log_file);
        return 1;
    }
    if (initialize_pwm() != 0) {
        log_message("PWM initialization failed.");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    if (initialize_spi() != 0) {
        log_message("SPI initialization failed.");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("Theremin started.");

    // Main loop
    while (running) {
        // Read sensor data
        float distance = read_distance();
        float ldr_value = read_ldr(spi_fd0);

        // Check for errors
        if (distance < 0) {
            log_message("Timeout reading distance.");
        }
        if (ldr_value < 0) {
            log_message("Error reading LDR.");
        }

        // Map data to frequency and volume
        float frequency = 0.0;
        float volume = 0.0;

        if (distance >= 0) {
            frequency = map_distance_to_frequency(distance);
        }
        if (ldr_value >= 0) {
            volume = map_ldr_to_volume(ldr_value);
        }

        // Set PWM frequency and duty cycle
        if (frequency > 0) {
            set_pwm_frequency((int)frequency);
        }
        if (volume >= 0) {
            int duty_cycle = (int)(volume * 1000000); // 0-1000000
            set_pwm_duty_cycle(duty_cycle);
        }

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Distance: %.2f cm, LDR: %.2f V, Frequency: %.2f Hz, Volume: %.2f",
                 distance, ldr_value, frequency, volume);
        log_message(log_buffer);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    log_message("Theremin exiting.");

    // Disable PWM
    set_pwm_duty_cycle(0);

    // Close SPI
    if (spi_fd0 >= 0) {
        close(spi_fd0);
    }
    if (spi_fd1 >= 0) {
        close(spi_fd1);
    }

    // Uninitialize pigpio
    gpioTerminate();

    // Save calibration data
    save_calibration_data("theremin_config.txt", &calibration);

    // Close log file
    fclose(log_file);

    return 0;
}

