// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_aqi(int adc_value);
void control_fan(float aqi);
void log_data(float aqi);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

// Read ADC value from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 0) {
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS);
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Convert ADC value to AQI (linear mapping)
float adc_to_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Linear mapping: 0-500 AQI corresponds to 0-1023 ADC
    return (float)adc_value * 500.0 / 1023.0;
}

// Control the ventilation fan based on AQI
void control_fan(float aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Log data to file
void log_data(float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float aqi = adc_to_aqi(adc_value);
            if (aqi >= 0) {
                printf("AQI: %.2f\n", aqi);
                control_fan(aqi);
                log_data(aqi);
            } else {
                fprintf(stderr, "Failed to convert ADC value to AQI\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    cleanup();
    return 0;
}

