#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define ALCOHOL_THRESHOLD_HIGH 50.0
#define ALCOHOL_THRESHOLD_LOW 20.0
#define LOG_FILE "alcohol_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm, const char *status);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
typedef struct {
    int fd;
    unsigned int speed;
    unsigned char mode;
    unsigned char bits_per_word;
} spi_config_t;

// SPI initialization function
int spi_init(void) {
    spi_config_t config = {
        .speed = SPI_SPEED,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    struct spi_ioc_transfer transfer[1];
    int adc_value = -1;
    int retries = 0;

    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode + channel number
    tx[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx;
    transfer[0].rx_buf = (unsigned long)rx;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;

    while (retries < MAX_RETRIES) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
            perror("Error during SPI transfer");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        break; // Exit retry loop on success
    }

    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return adc_value;
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to log data to file
void log_data(float ppm, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f PPM, %s\n", timestamp, ppm, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    int adc_value;
    float ppm;
    const char *status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping.\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to PPM
        ppm = adc_to_ppm(adc_value);

        // Determine status
        if (ppm > ALCOHOL_THRESHOLD_HIGH) {
            status = "Alcohol detected! Limit exceeded.";
        } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
            status = "Sobriety confirmed.";
        } else {
            status = "Alcohol level within acceptable range.";
        }

        // Log data
        log_data(ppm, status);

        printf("PPM: %.2f, Status: %s\n", ppm, status);

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

