            perror("Error during SPI transfer");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        break; // Exit retry loop on success
    }

    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return adc_value;
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to log data to file
void log_data(float ppm, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f PPM, %s\n", timestamp, ppm, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    int adc_value;
    float ppm;
    const char *status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping.\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to PPM
        ppm = adc_to_ppm(adc_value);

        // Determine status
        if (ppm > ALCOHOL_THRESHOLD_HIGH) {
            status = "Alcohol detected! Limit exceeded.";
        } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
            status = "Sobriety confirmed.";
        } else {
            status = "Alcohol level within acceptable range.";
        }

        // Log data
        log_data(ppm, status);

        printf("PPM: %.2f, Status: %s\n", ppm, status);

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

