#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCELERATION_TIME 2.0
#define CONSTANT_SPEED_TIME 2.0
#define DECELERATION_TIME 2.0
#define PAUSE_TIME 5.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_pot_to_speed(int pot_value);
void set_motor_speed(int enable_pin, int direction_pin, float speed);
void move_forward(float speed1, float speed2);
void move_backward(float speed1, float speed2);
void stop_motors();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to speed
float map_pot_to_speed(int pot_value) {
    // Logarithmic mapping
    float speed = MIN_SPEED + (float)(pot_value - 0) / (1023.0 - 0) * (MAX_SPEED - MIN_SPEED);
    return speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int enable_pin, int direction_pin, float speed) {
    if (speed < MIN_SPEED) {
        speed = MIN_SPEED;
    } else if (speed > MAX_SPEED) {
        speed = MAX_SPEED;
    }

    gpioPWM(enable_pin, (int)speed);
}

// Function to move forward
void move_forward(float speed1, float speed2) {
    gpioWrite(MOTOR1_DIRECTION, 1); // Forward
    gpioWrite(MOTOR2_DIRECTION, 0); // Backward
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);
}

// Function to move backward
void move_backward(float speed1, float speed2) {
    gpioWrite(MOTOR1_DIRECTION, 0); // Backward
    gpioWrite(MOTOR2_DIRECTION, 1); // Forward
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);
}

// Function to stop motors
void stop_motors() {
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Map potentiometer values to speeds
        float speed1 = map_pot_to_speed(pot1_value);
        float speed2 = map_pot_to_speed(pot2_value);

        // Motion profile: Forward
        printf("Moving forward...\n");
        for (float t = 0; t <= ACCELERATION_TIME && !terminate; t += 0.1) {
            float current_speed1 = MIN_SPEED + (speed1 - MIN_SPEED) * (t / ACCELERATION_TIME);
            float current_speed2 = MIN_SPEED + (speed2 - MIN_SPEED) * (t / ACCELERATION_TIME);
            move_forward(current_speed1, current_speed2);
            gpioDelay(100); // 100ms delay
        }
        move_forward(speed1, speed2);
        gpioDelay(CONSTANT_SPEED_TIME * 1000); // Constant speed for 2 seconds

        for (float t = 0; t <= DECELERATION_TIME && !terminate; t += 0.1) {
            float current_speed1 = speed1 - (speed1 - MIN_SPEED) * (t / DECELERATION_TIME);
            float current_speed2 = speed2 - (speed2 - MIN_SPEED) * (t / DECELERATION_TIME);
            move_forward(current_speed1, current_speed2);
            gpioDelay(100); // 100ms delay
        }
        stop_motors();
        gpioDelay(PAUSE_TIME * 1000); // Pause for 5 seconds

        // Motion profile: Backward
        printf("Moving backward...\n");
        for (float t = 0; t <= ACCELERATION_TIME && !terminate; t += 0.1) {
            float current_speed1 = MIN_SPEED + (speed1 - MIN_SPEED) * (t / ACCELERATION_TIME);
            float current_speed2 = MIN_SPEED + (speed2 - MIN_SPEED) * (t / ACCELERATION_TIME);
            move_backward(current_speed1, current_speed2);
            gpioDelay(100); // 100ms delay
        }
        move_backward(speed1, speed2);
        gpioDelay(CONSTANT_SPEED_TIME * 1000); // Constant speed for 2 seconds

        for (float t = 0; t <= DECELERATION_TIME && !terminate; t += 0.1) {
            float current_speed1 = speed1 - (speed1 - MIN_SPEED) * (t / DECELERATION_TIME);
            float current_speed2 = speed2 - (speed2 - MIN_SPEED) * (t / DECELERATION_TIME);
            move_backward(current_speed1, current_speed2);
            gpioDelay(100); // 100ms delay
        }
        stop_motors();
        gpioDelay(PAUSE_TIME * 1000); // Pause for 5 seconds
    }

    // Stop motors and terminate pigpio
    stop_motors();
    spiClose(spi_handle);
    gpioTerminate();

    printf("Motor control stopped.\n");
    return 0;
}

