#define CALIBRATION_TIME 5 // seconds
#define THRESHOLD_MULTIPLIER 1.1
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calibrate_noise_level();
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate the noise level
double calibrate_noise_level() {
    double sum = 0.0;
    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_TIME);
    for (int i = 0; i < CALIBRATION_TIME * 100; ++i) { // Sample every 10ms
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value during calibration.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        gpioDelay(10000); // 10 ms delay
    }
    return sum / (CALIBRATION_TIME * 100);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate noise level
    double noise_level = calibrate_noise_level();
    if (noise_level < 0) {
        fprintf(stderr, "Error: Noise level calibration failed. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Noise level: %.2f\n", noise_level);

    // Main loop
    int led_on = 0;
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value. Continuing...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Check if sound level exceeds threshold
        if (adc_value > noise_level * THRESHOLD_MULTIPLIER) {
            if (!led_on) {
                control_led(1); // Turn LED on
                led_on = 1;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            }
        } else {
            if (led_on) {
                control_led(0); // Turn LED off
                led_on = 0;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

