#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)
#define MCP3008_CHANNEL 0
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *cs_chip = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_close(void);
int gpio_init(void);
int gpio_set_output(void);
int gpio_set_low(void);
int gpio_set_high(void);
int gpio_close(void);
int log_data(uint32_t timestamp_ns, uint16_t raw_adc_value);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI close function
int spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    cs_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!cs_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(cs_chip);
        return -1;
    }

    return 0;
}

// GPIO set output function
int gpio_set_output(void) {
    if (gpiod_line_request_output(cs_line, "audio_sampler", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(cs_chip);
        return -1;
