#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define PPM_SCALE_FACTOR 1000.0
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_ppm(float voltage);
void log_data(float voltage, float ppm);
void print_data(float voltage, float ppm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    float ppm_scale_factor;
    char log_file[64];
} config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to PPM (placeholder linear relationship)
float voltage_to_ppm(float voltage) {
    return voltage * PPM_SCALE_FACTOR;
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f, %.3f\n", timestamp, voltage, ppm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print data to console
void print_data(float voltage, float ppm) {
    printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    printf("Propane Leak Detector started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float voltage = adc_to_voltage(adc_value);
            float ppm = voltage_to_ppm(voltage);

            log_data(voltage, ppm);
            print_data(voltage, ppm);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d ms...\n", RETRY_DELAY_MS);
            gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
            continue; // Skip the rest of the loop and retry
        }

        gpioDelay(1000000); // Wait 1 second (1000000 microseconds)
    }

    cleanup();
    return 0;
}

