#include <pigpio.h>
#include <math.h>

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.3 // 300mV/g
#define ADXL335_ZERO_G 1.5      // 1.5V

// Define MCP3008 SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS 8

// Define Kalman filter parameters
#define Q 0.01
#define R 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} KalmanState;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(float measurement, KalmanState *state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to convert voltage to acceleration
float voltage_to_acceleration(float voltage) {
    return (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
}

// Function to implement Kalman filter
float kalman_filter(float measurement, KalmanState *state) {
    // Prediction step
    float x = state->x;
    float P = state->P + Q;

    // Update step
    float K = P / (P + R);
    float y = measurement - x;
    x = x + K * y;
    P = (1 - K) * P;

    // Update state
    state->x = x;
    state->P = P;

    return x;
}

