#include <time.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the quiescent voltage (VCC / 2)
#define V_QUIESCENT 1.65

// Define the sensitivity (V/mT)
#define SENSITIVITY 0.025

// Define the magnetic field range (mT)
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Define the sampling interval (milliseconds)
#define SAMPLE_INTERVAL 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in mT
float calculate_magnetic_field(int sensor_value) {
    float voltage = (sensor_value == 1) ? 3.3 : 0.0;
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

// Function to log the magnetic field readings to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing!\n");
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Ensure data is written to the file immediately
    fclose(fp);
}

// Function to check if the magnetic field value is within the valid range
void check_range(float magnetic_field, int sensor_number) {
    if (magnetic_field < MIN_MAGNETIC_FIELD || magnetic_field > MAX_MAGNETIC_FIELD) {
        fprintf(stderr, "Warning: Sensor %d magnetic field value (%.2f mT) is out of range!\n", sensor_number, magnetic_field);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Calculate magnetic field strengths
        float sensor1_mT = (sensor1_value != -1) ? calculate_magnetic_field(sensor1_value) : 0.0;
        float sensor2_mT = (sensor2_value != -1) ? calculate_magnetic_field(sensor2_value) : 0.0;
        float sensor3_mT = (sensor3_value != -1) ? calculate_magnetic_field(sensor3_value) : 0.0;

        // Log the data
        log_data(sensor1_mT, sensor2_mT, sensor3_mT);

        // Check for out-of-range values
        check_range(sensor1_mT, 1);
        check_range(sensor2_mT, 2);
        check_range(sensor3_mT, 3);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

