#include <string.h>

// Constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
int log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump relay
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Error: Failed to write to pump GPIO.");
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off on startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (!terminate) {
        // Read soil moisture sensor
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            log_event("Error reading moisture level, retrying...");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Log moisture level
        char log_message[50];
        snprintf(log_message, sizeof(log_message), "Moisture level: %d", moisture_level);
        log_event(log_message);

        // Control pump based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD) {
            if (control_pump(1) == 0) {
                log_event("Pump turned ON.");
            }
        } else {
            if (control_pump(0) == 0) {
                log_event("Pump turned OFF.");
            }
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Clean up
    control_pump(0); // Ensure pump is off on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated.");

    return 0;
}

