#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signum);
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, int *led_state);
int set_led_state(int led_state);
void log_error(const char *message);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// MQTT connect callback
int mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("MQTT connected to %s:%d\n", MQTT_BROKER, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
    return result;
}

// MQTT disconnect callback
int mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        fprintf(stderr, "MQTT disconnected unexpectedly with code %d\n", rc);
    }
    return 0;
}

// MQTT message callback
int mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        int led_state;
        if (parse_json_payload((const char *)message->payload, &led_state) == 0) {
            if (set_led_state(led_state) != 0) {
                log_error("Failed to set LED state");
            }
        } else {
            log_error("Failed to parse JSON payload");
        }
    } else {
        log_error("Empty MQTT message received");
    }
    return 0;
}

// Parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        *led_state = cJSON_IsTrue(led_state_json);
    } else {
        log_error("Invalid 'led_state' value in JSON");
        cJSON_Delete(json);
        return -1;
    }

    cJSON_Delete(json);
    return 0;
}

// Set LED state
int set_led_state(int led_state) {
    if (gpioWrite(GPIO_PIN, led_state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Log error message with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Turn off LED initially
    gpioWrite(GPIO_PIN, 0);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    // Connect to MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int reconnect_delay = 1;
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 for blocking, 1 max messages processed
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error in mosquitto_loop: %s\n", mosquitto_strerror(rc));
            log_error("MQTT connection lost, attempting to reconnect...");
            mosquitto_reconnect(mosq);
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > MAX_RECONNECT_DELAY) {
                reconnect_delay = MAX_RECONNECT_DELAY;
            }
        }
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

