#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sound sensor
int read_sound_sensor() {
    int sound_level = gpioRead(SOUND_SENSOR_PIN);
    if (sound_level < 0) {
        fprintf(stderr, "Error reading sound sensor: %d\n", sound_level);
        return -1; // Indicate an error
    }
    return sound_level;
}

// Function to trigger the alarm LED
void trigger_alarm() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);            // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level == 0) {
            printf("Sound detected!\n");
            trigger_alarm();
        } else if (sound_level == 1) {
            printf("No sound detected.\n");
        } else {
            fprintf(stderr, "Error reading sound sensor, exiting.\n");
            break; // Exit loop on sensor read error
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

