#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LM35_SENSITIVITY 0.01 // 10mV/°C
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void update_circular_buffer(float temperature);
void log_to_file(const char *filename);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = voltage / LM35_SENSITIVITY;
    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to log the circular buffer to a file
void log_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", filename);
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error: Could not write all data to file %s\n", filename);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping this reading\n");
            sleep(5);
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Update circular buffer
        update_circular_buffer(temperature);

        // Log to file every 5 seconds
        log_to_file(LOG_FILE);

        // Print temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Wait 5 seconds
        sleep(5);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

