#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x62
#define DAC_RESOLUTION 4095.0
#define VREF 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define VOUT_MIN 0.0
#define VOUT_MAX 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int write_dac(int dac_value);
float map_temperature_to_voltage(float temperature);
void log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to write to MCP4725 DAC
int write_dac(int dac_value) {
    if (dac_value < 0 || dac_value > DAC_RESOLUTION) {
        fprintf(stderr, "Error: Invalid DAC value: %d\n", dac_value);
        return -1;
    }

    char tx_buffer[3];

    // Construct I2C message (EEPROM write mode)
    tx_buffer[0] = 0x40; // Write command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // MSB
    tx_buffer[2] = (dac_value << 4) & 0xF0; // LSB

    if (i2cWriteDevice(i2c_handle, tx_buffer, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    return 0;
}

// Function to map temperature to voltage
float map_temperature_to_voltage(float temperature) {
    return (temperature - TEMP_MIN) * (VOUT_MAX - VOUT_MIN) / (TEMP_MAX - TEMP_MIN) + VOUT_MIN;
}

// Function to log data to file
void log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, MCP4725_ADDRESS, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map temperature to voltage
        float voltage = map_temperature_to_voltage(temperature);

        // Convert voltage to DAC value
        int dac_value = (int)(voltage / VREF * DAC_RESOLUTION);

        // Write to DAC
        if (write_dac(dac_value) != 0) {
            fprintf(stderr, "Error writing to DAC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log data
        log_data(adc_value, temperature, voltage);

        // Wait 0.5 seconds
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

