#include <string.h>

// Define GPIO pins
#define MIC_PIN 26
#define LED_PIN 16

// Define constants
#define THRESHOLD 700
#define LED_ON_TIME 500 // milliseconds
#define DEBOUNCE_TIME 50 // milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned int last_trigger_time = 0;

// Function prototypes
int read_adc(int gpio_pin);
int is_clap_detected(int adc_value, int threshold);
void control_led(int gpio_pin, int state);
void log_clap_detection(void);
void signal_handler(int signal);

// Function to read ADC value using bit-banging
int read_adc(int gpio_pin) {
    int adc_value = 0;
    int i;

    gpioSetMode(gpio_pin, PI_INPUT); // Ensure pin is in input mode

    // Simulate ADC conversion (10-bit)
    for (i = 0; i < 10; i++) {
        gpioDelay(1); // Small delay for charging capacitor
        adc_value += gpioRead(gpio_pin);
    }

    return adc_value;
}

// Function to check if a clap is detected
int is_clap_detected(int adc_value, int threshold) {
    return (adc_value > threshold);
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log clap detection with timestamp
void log_clap_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Clap detected!\n", timestamp);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_led(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_adc(MIC_PIN);

        if (is_clap_detected(adc_value, THRESHOLD)) {
            unsigned int current_time = gpioTick();

            // Debounce logic
            if (current_time - last_trigger_time > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
                control_led(LED_PIN, 1); // Turn on LED
                log_clap_detection(); // Log detection
                gpioDelay(LED_ON_TIME * 1000); // Keep LED on for specified time
                control_led(LED_PIN, 0); // Turn off LED
                last_trigger_time = current_time; // Update last trigger time
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(LED_PIN, 0);
    gpioTerminate();

    return 0;
}

