#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_to_distance(int voltage);
void log_distance(float distance);
void check_feeder_status(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
    }
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Reads the value of the specified GPIO pin (0 or 1)
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Converts the digital GPIO reading (0 or 1) to a voltage (0V or 3.3V)
float voltage_to_distance(int voltage) {
    if (voltage == 0) {
        return 0.0;
    } else if (voltage == 1) {
        return 3.3;
    } else {
        fprintf(stderr, "Invalid voltage value: %d\n", voltage);
        return -1.0; // Indicate an error
    }
}

// Logs the distance reading to a file with a timestamp
void log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance);

    fclose(fp);
}

// Checks the distance and prints a message based on proximity
void check_feeder_status(float distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    int voltage;
    float distance;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Distance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read GPIO value
        voltage = gpio_read(GPIO_PIN);
        if (voltage < 0) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue; // Retry the loop
        }

        // Convert voltage to distance
        distance = voltage_to_distance(voltage);
        if (distance < 0) {
            fprintf(stderr, "Failed to convert voltage to distance. Retrying in 1 second.\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Log the distance
        log_distance(distance);

        // Check feeder status
        check_feeder_status(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d.\n", GPIO_PIN);
    }

    printf("Program finished.\n");
    return 0;
}

