FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float calculate_magnetic_field(float voltage);
int log_data(float magnetic_field);
void control_led(float magnetic_field);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int led_gpio;
    float field_threshold;
    float vcc;
    float sensitivity;
    float quiescent_output;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    LED_GPIO,
    FIELD_THRESHOLD,
    VCC,
    SENSITIVITY,
    QUIESCENT_OUTPUT
};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Calculate magnetic field strength
        float magnetic_field = calculate_magnetic_field(voltage);

        // Log data
        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        // Control LED
        control_led(magnetic_field);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (float)adc_value * config.vcc / 1023.0;
}

// Calculate magnetic field strength from voltage
float calculate_magnetic_field(float voltage) {
    return (voltage - config.quiescent_output) * 1000.0 / config.sensitivity;
}

// Log data to file
int log_data(float magnetic_field) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.3f mT\n", timestamp, magnetic_field) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control LED based on magnetic field strength
void control_led(float magnetic_field) {
    if (magnetic_field > config.field_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.led_gpio, 0); // Turn off LED
    gpioTerminate();
}

