#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define ZERO_CURRENT_VOLTAGE (VREF / 2.0)
#define FULL_SCALE_VOLTAGE VREF
#define FULL_SCALE_CURRENT 50.0
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_mcp3008(int channel);
float convert_to_voltage(int raw_code);
float convert_to_current(float voltage);
int log_current_data(float current);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float zero_current_voltage;
    float full_scale_voltage;
    float full_scale_current;
    char *log_file;
    int sample_interval_ms;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    VREF,
    ZERO_CURRENT_VOLTAGE,
    FULL_SCALE_VOLTAGE,
    FULL_SCALE_CURRENT,
    LOG_FILE,
    SAMPLE_INTERVAL_MS
};

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read MCP3008
        int raw_code = read_mcp3008(config.mcp3008_channel);
        if (raw_code < 0) {
            fprintf(stderr, "Failed to read MCP3008. Skipping.\n");
            gpioDelay(config.sample_interval_ms * 1000); // Delay for 100ms
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_code);

        // Convert to current
        float current = convert_to_current(voltage);

        // Log current data
        if (log_current_data(current) != 0) {
            fprintf(stderr, "Failed to log current data. Skipping.\n");
        }

        // Delay
        gpioDelay(config.sample_interval_ms * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract raw code
    int raw_code = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return raw_code;
}

// Convert to voltage
float convert_to_voltage(int raw_code) {
    return ((float)raw_code / 1023.0) * config.vref;
}

// Convert to current
float convert_to_current(float voltage) {
    if (voltage < 0.0 || voltage > config.vref) {
        fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
        return -1.0; // Indicate error
    }
    return (voltage - config.zero_current_voltage) * (config.full_scale_current / (config.full_scale_voltage - config.zero_current_voltage));
}

// Log current data
int log_current_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Append current data to log file
    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

