    return 0;
}

// Read MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract raw code
    int raw_code = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return raw_code;
}

// Convert to voltage
float convert_to_voltage(int raw_code) {
    return ((float)raw_code / 1023.0) * config.vref;
}

// Convert to current
float convert_to_current(float voltage) {
    if (voltage < 0.0 || voltage > config.vref) {
        fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
        return -1.0; // Indicate error
    }
    return (voltage - config.zero_current_voltage) * (config.full_scale_current / (config.full_scale_voltage - config.zero_current_voltage));
}

// Log current data
int log_current_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Append current data to log file
    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

