// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO lines
        if (sensor1_line) {
            if (gpiod_line_release(sensor1_line) < 0) {
                perror("Error releasing sensor 1 GPIO line");
            }
        }
        if (sensor2_line) {
