        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor value
int debounce_sensor(struct gpiod_line *line) {
    int low_count = 0;
    int high_count = 0;

    for (int i = 0; i < 5; i++) {
        int value = read_sensor(line);
        if (value < 0) {
            return -1; // Propagate error
        }
        if (value == 0) {
            low_count++;
        } else {
            high_count++;
        }
        usleep(2000); // 2 ms delay
    }

    if (low_count > high_count) {
        return 0; // Object present
    } else {
        return 1; // No object
    }
}

