    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for sensor 1 and sensor 2
    sensor1_line = gpiod_chip_get_line(gpio_chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        perror("Error getting sensor 1 GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(gpio_chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        perror("Error getting sensor 2 GPIO line");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines as input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Error requesting sensor 1 GPIO line as input");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Error requesting sensor 2 GPIO line as input");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_sensor(sensor1_line);
        int sensor2_state = debounce_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor data, exiting.\n");
            break; // Exit loop on error
        }

        log_sensor_data(sensor1_state, sensor2_state);

        sleep(1); // Wait for 1 second
    }

    // Release GPIO lines and close GPIO chip before exiting
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

