#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO initialised successfully");
    return 0;
}

int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

int debounce_sensor() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    return gpioRead(GPIO_PIN);
}

int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n --width %d --height %d --encoding jpeg --timeout 1000", filename, CAPTURE_WIDTH, CAPTURE_HEIGHT);

    syslog(LOG_INFO, "Executing command: %s", command);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        char *args[] = {"libcamera-still", "-o", (char*)filename, "-n", "--width", (char*)CAPTURE_WIDTH, "--height", (char*)CAPTURE_HEIGHT, "--encoding", "jpeg", "--timeout", "1000", NULL};
        execvp(args[0], args);
        syslog(LOG_ERR, "Failed to execute libcamera-still");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            int exit_status = WEXITSTATUS(status);
            if (exit_status == 0) {
                syslog(LOG_INFO, "Capture successful");
                return 0;
            } else {
                syslog(LOG_ERR, "Capture failed with exit status: %d", exit_status);
                return -1;
            }
        } else {
            syslog(LOG_ERR, "Capture process terminated abnormally");
            return -1;
        }
    } else {
        syslog(LOG_ERR, "Failed to fork process");
        return -1;
    }
}

int generate_filename(char *filename, size_t filename_size) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, filename_size, "%Y%m%d_%H%M%S", timeinfo);
    snprintf(filename + strlen(filename), filename_size - strlen(filename), "_%03ld.jpg", ts.tv_nsec / 1000000); // Add milliseconds

    return 0;
}

int main() {
