#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1

// Structure to hold camera parameters
typedef struct {
    char *device_name;
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer_start;
    size_t buffer_length;
    int image_count;
    int running;
} camera_t;

// Function prototypes
int camera_open(camera_t *camera);
int camera_init(camera_t *camera);
int camera_start_streaming(camera_t *camera);
int camera_capture_frame(camera_t *camera);
int camera_save_frame(camera_t *camera, const char *filename);
int camera_stop_streaming(camera_t *camera);
int camera_close(camera_t *camera);
void signal_handler(int signum);

// Global camera instance
camera_t camera;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping streaming...\n", signum);
        camera.running = 0;
    }
}

// Function to open the camera device
int camera_open(camera_t *camera) {
    camera->fd = open(camera->device_name, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd < 0) {
        perror("Error opening device");
        return -1;
    }
    printf("Device %s opened successfully.\n", camera->device_name);
    return 0;
}

// Function to initialize the camera
int camera_init(camera_t *camera) {
    // Check device capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &camera->cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", camera->device_name);
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", camera->device_name);
        return -1;
    }

    // Set image format
    camera->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->fmt.fmt.pix.width = IMAGE_WIDTH;
    camera->fmt.fmt.pix.height = IMAGE_HEIGHT;
    camera->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY; // 8-bit grayscale
    camera->fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &camera->fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    camera->req.count = NUM_BUFFERS;
    camera->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &camera->req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    // Map buffers
    for (int i = 0; i < camera->req.count; i++) {
        camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        camera->buf.memory = V4L2_MEMORY_MMAP;
        camera->buf.index = i;

        if (ioctl(camera->fd, VIDIOC_QUERYBUF, &camera->buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        camera->buffer_start = mmap(NULL, camera->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, camera->buf.m.offset);
        if (camera->buffer_start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }

        if (ioctl(camera->fd, VIDIOC_QBUF, &camera->buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int camera_start_streaming(camera_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int camera_capture_frame(camera_t *camera) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(camera->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error in select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
    }

    if (ioctl(camera->fd, VIDIOC_DQBUF, &camera->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to save a frame to a PGM file
int camera_save_frame(camera_t *camera, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(camera->buffer_start, 1, IMAGE_WIDTH * IMAGE_HEIGHT, fp);

    fclose(fp);
    return 0;
}

// Function to stop streaming
int camera_stop_streaming(camera_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
        return -1;
    }

    return 0;
}

// Function to close the camera device
int camera_close(camera_t *camera) {
    if (close(camera->fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    printf("Device closed.\n");
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize camera parameters
    camera.device_name = DEFAULT_DEVICE;
    camera.image_count = 0;
    camera.running = 1;

    // Parse command-line arguments
    if (argc > 1) {
        camera.device_name = argv[1];
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera
    if (camera_open(&camera) < 0) {
        return 1;
    }

    // Initialize the camera
    if (camera_init(&camera) < 0) {
        camera_close(&camera);
        return 1;
    }

    // Start streaming
    if (camera_start_streaming(&camera) < 0) {
        camera_close(&camera);
        return 1;
    }

    printf("Streaming started...\n");

    // Capture and save frames
    while (camera.running) {
        if (camera_capture_frame(&camera) == 0) {
            // Generate filename
            char filename[50];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", camera.image_count + 1);

            // Save frame
            if (camera_save_frame(&camera, filename) == 0) {
                printf("Saved frame to %s\n", filename);
                camera.image_count++;
            } else {
                fprintf(stderr, "Error saving frame.\n");
            }

            // Requeue buffer
            if (ioctl(camera.fd, VIDIOC_QBUF, &camera.buf) < 0) {
                perror("Error requeuing buffer");
                camera.running = 0; // Stop on error
            }
        } else {
            // Handle capture error (e.g., timeout)
            fprintf(stderr, "Error capturing frame, retrying...\n");
        }
    }

    // Stop streaming
    if (camera_stop_streaming(&camera) < 0) {
        fprintf(stderr, "Error stopping streaming during cleanup.\n");
    }

    // Close the camera
    if (camera_close(&camera) < 0) {
        fprintf(stderr, "Error closing camera during cleanup.\n");
    }

    printf("Exiting.\n");
    return 0;
}

