#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int              fd = -1;
static buffer          *buffers = NULL;
static unsigned int     n_buffers = 0;
static int              running = 1;

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_device(int fd);
int  close_device(int fd);
int  init_mmap(int fd);
int  capture_image(int fd, const char *filename);
void signal_handler(int signum);

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        running = 0;
    }
}

// Open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Initialize memory mapping
int init_mmap(int fd) {
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    // Map buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Start capturing
int start_capturing(int fd) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Uninitialize the device
int uninit_device(int fd) {
    unsigned int i;
    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    free(buffers);
    buffers = NULL;
    n_buffers = 0;
    return 0;
}

// Close the device
int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Capture an image and save to file
int capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    FILE *fp;
    int ret;

    // Dequeue a buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret == -1) {
        perror("Error dequeueing buffer");
        return -1;
    }

    // Verify data is available
    if (buf.bytesused == 0) {
        fprintf(stderr, "No data in buffer\n");
        return -1;
    }

    // Open the file for writing
    fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    // Write the raw data to the file
    if (fwrite(buffers[buf.index].start, buf.bytesused, 1, fp) != 1) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    // Close the file
    fclose(fp);

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error requeueing buffer");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing image... (Press Ctrl+C to stop)\n");

    // Capture and save the image
    if (capture_image(fd, IMAGE_FILE) == -1) {
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Image saved to %s\n", IMAGE_FILE);

    // Stop capturing
    if (stop_capturing(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Uninitialize the device
    if (uninit_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Close the device
    if (close_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Capture complete.\n");

    return EXIT_SUCCESS;
}

