    ret = gpiod_line_request_input(pan_left_button_line, "pan_left_button");
    if (ret < 0) {
        perror("Error requesting pan left button line for input");
        goto cleanup_pan_down_button_output;
    }

    ret = gpiod_line_request_input(pan_right_button_line, "pan_right_button");
    if (ret < 0) {
        perror("Error requesting pan right button line for input");
        goto cleanup_pan_left_button_output;
    }

    // Enable pull-up resistors
    ret = gpiod_line_set_value(tilt_up_button_line, 1);
    if (ret < 0) {
        perror("Error setting tilt up button pull-up");
        goto cleanup_pan_right_button_output;
    }

    ret = gpiod_line_set_value(tilt_down_button_line, 1);
    if (ret < 0) {
        perror("Error setting tilt down button pull-up");
        goto cleanup_pan_right_button_output;
    }

    ret = gpiod_line_set_value(pan_left_button_line, 1);
    if (ret < 0) {
        perror("Error setting pan left button pull-up");
        goto cleanup_pan_right_button_output;
    }

    ret = gpiod_line_set_value(pan_right_button_line, 1);
    if (ret < 0) {
        perror("Error setting pan right button pull-up");
        goto cleanup_pan_right_button_output;
    }

    return 0;

cleanup_pan_right_button_output:
    gpiod_line_release(pan_right_button_line);
cleanup_pan_left_button_output:
    gpiod_line_release(pan_left_button_line);
cleanup_pan_down_button_output:
    gpiod_line_release(pan_right_button_line);
cleanup_tilt_down_button_output:
    gpiod_line_release(tilt_down_button_line);
cleanup_tilt_up_button_output:
    gpiod_line_release(tilt_up_button_line);
cleanup_tilt_servo_output:
    gpiod_line_release(tilt_servo_line);
cleanup_pan_servo_output:
    gpiod_line_release(pan_servo_line);
cleanup_tilt_servo:
    gpiod_line_release(tilt_servo_line);
cleanup_pan_servo:
    gpiod_line_release(pan_servo_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Set servo pulse width
int set_servo_pulse_width(struct gpiod_line *line, int pulse_width) {
    int ret;
    struct gpiod_line_request_config config;

    memset(&config, 0, sizeof(config));
    config.consumer = "servo";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting line for PWM");
        return -1;
    }

    // Calculate the on-time and off-time
    uint64_t on_time = (uint64_t)pulse_width * PWM_PERIOD_NS / 1000000; // Convert us to ns
    uint64_t off_time = PWM_PERIOD_NS - on_time;

    // Set the value to 1 for the on-time, then 0 for the off-time
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting line high");
        gpiod_line_release(line);
        return -1;
    }
    struct timespec on_delay = {0, on_time};
    nanosleep(&on_delay, NULL);

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting line low");
        gpiod_line_release(line);
        return -1;
    }
    struct timespec off_delay = {0, off_time};
    nanosleep(&off_delay, NULL);

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing line");
        return -1;
    }

    return 0;
}

// Read button state
int read_button(struct gpiod_line *line) {
    int ret;
    int value;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error reading button value");
        return -1;
    }

    value = (ret == 0) ? 1 : 0; // Active low
    return value;
}

// Cleanup GPIO resources
void cleanup(void) {
    printf("Cleaning up GPIO resources...\n");

    if (pan_servo_line) {
        gpiod_line_release(pan_servo_line);
    }
    if (tilt_servo_line) {
        gpiod_line_release(tilt_servo_line);
    }
    if (tilt_up_button_line) {
        gpiod_line_release(tilt_up_button_line);
    }
    if (tilt_down_button_line) {
        gpiod_line_release(tilt_down_button_line);
    }
    if (pan_left_button_line) {
        gpiod_line_release(pan_left_button_line);
    }
    if (pan_right_button_line) {
        gpiod_line_release(pan_right_button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int pan_pulse_width = SERVO_MID_PULSE_WIDTH;
    int tilt_pulse_width = SERVO_MID_PULSE_WIDTH;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Pan-Tilt Camera Control Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read button states
        int tilt_up_pressed = read_button(tilt_up_button_line);
        int tilt_down_pressed = read_button(tilt_down_button_line);
        int pan_left_pressed = read_button(pan_left_button_line);
        int pan_right_pressed = read_button(pan_right_button_line);

        if (tilt_up_pressed < 0 || tilt_down_pressed < 0 || pan_left_pressed < 0 || pan_right_pressed < 0) {
            fprintf(stderr, "Error reading button states. Continuing.\n");
            continue;
        }

        // Update servo positions
        if (tilt_up_pressed) {
            tilt_pulse_width += SERVO_INCREMENT;
            if (tilt_pulse_width > SERVO_MAX_PULSE_WIDTH) {
                tilt_pulse_width = SERVO_MAX_PULSE_WIDTH;
            }
        } else if (tilt_down_pressed) {
            tilt_pulse_width -= SERVO_INCREMENT;
            if (tilt_pulse_width < SERVO_MIN_PULSE_WIDTH) {
                tilt_pulse_width = SERVO_MIN_PULSE_WIDTH;
            }
        }

        if (pan_left_pressed) {
            pan_pulse_width -= SERVO_INCREMENT;
            if (pan_pulse_width < SERVO_MIN_PULSE_WIDTH) {
                pan_pulse_width = SERVO_MIN_PULSE_WIDTH;
            }
        } else if (pan_right_pressed) {
            pan_pulse_width += SERVO_INCREMENT;
            if (pan_pulse_width > SERVO_MAX_PULSE_WIDTH) {
                pan_pulse_width = SERVO_MAX_PULSE_WIDTH;
            }
        }

        // Set servo pulse widths
        ret = set_servo_pulse_width(pan_servo_line, pan_pulse_width);
        if (ret < 0) {
            fprintf(stderr, "Error setting pan servo pulse width.\n");
        }

        ret = set_servo_pulse_width(tilt_servo_line, tilt_pulse_width);
        if (ret < 0) {
            fprintf(stderr, "Error setting tilt servo pulse width.\n");
        }

        // Delay
        struct timespec delay = {0, 50000000}; // 50 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

