#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int              fd = -1;
static buffer          *buffers = NULL;
static unsigned int     n_buffers = 0;
static unsigned int     current_buffer = 0;
static int              running = 1;

// Function prototypes
int  open_device(const char *device_name);
int  init_device(int fd);
int  start_capturing(int fd);
int  stop_capturing(int fd);
int  uninit_device(int fd);
int  close_device(int fd);
int  init_mmap(int fd);
int  uninit_mmap(int fd);
int  capture_frame(int fd, unsigned char **frame_buffer);
int  convert_yuyv_to_rgb24(unsigned char *yuyv_frame, unsigned char *rgb24_frame, int width, int height);
int  apply_box_blur(unsigned char *input_image, unsigned char *output_image, int width, int height, int radius);
int  save_jpeg(unsigned char *rgb24_image, int width, int height, int quality, const char *filename);
void signal_handler(int signum);

// Signal handler for clean exit
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set the video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    return 0;
}

// Initialize memory mapping
int init_mmap(int fd) {
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Uninitialize memory mapping
int uninit_mmap(int fd) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    free(buffers);
    buffers = NULL;
    n_buffers = 0;
    return 0;
}

// Start capturing
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    struct v4l2_buffer buf;

    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Uninitialize the device
int uninit_device(int fd) {
    if (buffers) {
        if (uninit_mmap(fd) < 0) {
            return -1;
        }
    }
    return 0;
}

// Close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Capture a single frame
int capture_frame(int fd, unsigned char **frame_buffer) {
    fd_set fds;
    struct timeval tv;
    int r;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_buffer = buffers[buf.index].start;
    current_buffer = buf.index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Convert YUYV to RGB24
int convert_yuyv_to_rgb24(unsigned char *yuyv_frame, unsigned char *rgb24_frame, int width, int height) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int y = yuyv_frame[2 * (i * width + j) + 0];
            int u = yuyv_frame[2 * (i * width + j) + 1] - 128;
            int v = yuyv_frame[2 * (i * width + j) + 3] - 128;

            int r = y + (1.370705 * v);
            int g = y - (0.698001 * v) - (0.336331 * u);
            int b = y + (1.732446 * u);

            // Clamp values to 0-255
            if (r < 0) r = 0;
            if (r > 255) r = 255;
            if (g < 0) g = 0;
            if (g > 255) g = 255;
            if (b < 0) b = 0;
            if (b > 255) b = 255;

            rgb24_frame[3 * (i * width + j) + 0] = (unsigned char)r;
            rgb24_frame[3 * (i * width + j) + 1] = (unsigned char)g;
            rgb24_frame[3 * (i * width + j) + 2] = (unsigned char)b;
        }
    }
    return 0;
}

// Apply box blur filter
int apply_box_blur(unsigned char *input_image, unsigned char *output_image, int width, int height, int radius) {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;

            for (int k = -radius; k <= radius; k++) {
                for (int l = -radius; l <= radius; l++) {
                    int x = j + k;
                    int y = i + l;

                    // Clamp coordinates to the image bounds
                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        r_sum += input_image[3 * (y * width + x) + 0];
                        g_sum += input_image[3 * (y * width + x) + 1];
                        b_sum += input_image[3 * (y * width + x) + 2];
                        count++;
                    }
                }
            }

            output_image[3 * (i * width + j) + 0] = (unsigned char)(r_sum / count);
            output_image[3 * (i * width + j) + 1] = (unsigned char)(g_sum / count);
            output_image[3 * (i * width + j) + 2] = (unsigned char)(b_sum / count);
        }
    }
    return 0;
}

// Save image as JPEG
int save_jpeg(unsigned char *rgb24_image, int width, int height, int quality, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        perror("Error opening output file");
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb24_image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    unsigned char *yuyv_frame = NULL;
    unsigned char *rgb24_frame = NULL;
    unsigned char *blurred_image = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(fd) < 0) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) < 0) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for YUYV frame
    yuyv_frame = calloc(WIDTH * HEIGHT * 2, 1);
    if (!yuyv_frame) {
        perror("Out of memory");
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for RGB24 frame
    rgb24_frame = calloc(WIDTH * HEIGHT * 3, 1);
    if (!rgb24_frame) {
        perror("Out of memory");
        free(yuyv_frame);
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for blurred image
    blurred_image = calloc(WIDTH * HEIGHT * 3, 1);
    if (!blurred_image) {
        perror("Out of memory");
        free(yuyv_frame);
        free(rgb24_frame);
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Capture a frame
    if (capture_frame(fd, &yuyv_frame) < 0) {
        free(yuyv_frame);
        free(rgb24_frame);
        free(blurred_image);
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Convert YUYV to RGB24
    convert_yuyv_to_rgb24(yuyv_frame, rgb24_frame, WIDTH, HEIGHT);

    // Apply box blur filter
    apply_box_blur(rgb24_frame, blurred_image, WIDTH, HEIGHT, BLUR_RADIUS);

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format filename
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    // Save JPEG image
    if (save_jpeg(blurred_image, WIDTH, HEIGHT, 75, filename) < 0) {
        free(yuyv_frame);
        free(rgb24_frame);
        free(blurred_image);
        stop_capturing(fd);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Image saved as %s\n", filename);

    // Clean up
    free(yuyv_frame);
    free(rgb24_frame);
    free(blurred_image);
    stop_capturing(fd);
    uninit_device(fd);
    close_device(fd);

    return EXIT_SUCCESS;
}

