#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_RESOLUTIONS 10
#define MAX_FRAME_RATES 10

// Structure to hold camera capabilities
typedef struct {
    char device_name[256];
    unsigned int capabilities;
    unsigned int focus_support;
    struct v4l2_frmsizeenum frame_sizes[MAX_RESOLUTIONS];
    struct v4l2_frmivalenum frame_intervals[MAX_FRAME_RATES];
    int num_frame_sizes;
    int num_frame_intervals;
} camera_info_t;

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Function to query camera capabilities
int query_capabilities(int fd, camera_info_t *camera_info) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    camera_info->capabilities = cap.capabilities;
    strncpy(camera_info->device_name, cap.card, sizeof(camera_info->device_name) - 1);
    camera_info->device_name[sizeof(camera_info->device_name) - 1] = '\0';

    return 0;
}

// Function to query autofocus support
int query_focus_support(int fd, camera_info_t *camera_info) {
    struct v4l2_queryctrl queryctrl;
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) < 0) {
        if (errno == EINVAL) {
            camera_info->focus_support = 0; // Not supported
            return 0;
        } else {
            perror("Error querying autofocus support");
            return -1;
        }
    }

    camera_info->focus_support = queryctrl.flags & V4L2_CTRL_FLAG_AUTO;
    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, camera_info_t *camera_info) {
    struct v4l2_frmsizeenum fsize;
    fsize.index = 0;
    fsize.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format

    camera_info->num_frame_sizes = 0;

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize) == 0) {
        if (camera_info->num_frame_sizes < MAX_RESOLUTIONS) {
            camera_info->frame_sizes[camera_info->num_frame_sizes] = fsize;
            camera_info->num_frame_sizes++;
        } else {
            fprintf(stderr, "Warning: Too many frame sizes, skipping.\n");
            break;
        }
        fsize.index++;
    }

    if (camera_info->num_frame_sizes == 0) {
        fprintf(stderr, "Error: No frame sizes enumerated.\n");
        return -1;
    }

    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, camera_info_t *camera_info) {
    struct v4l2_frmivalenum fival;
    fival.index = 0;
    fival.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format
    fival.width = camera_info->frame_sizes[0].discrete.width; // Use the first frame size
    fival.height = camera_info->frame_sizes[0].discrete.height;

    camera_info->num_frame_intervals = 0;

    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fival) == 0) {
        if (camera_info->num_frame_intervals < MAX_FRAME_RATES) {
            camera_info->frame_intervals[camera_info->num_frame_intervals] = fival;
            camera_info->num_frame_intervals++;
        } else {
            fprintf(stderr, "Warning: Too many frame intervals, skipping.\n");
            break;
        }
        fival.index++;
    }

    if (camera_info->num_frame_intervals == 0) {
        fprintf(stderr, "Error: No frame intervals enumerated.\n");
        return -1;
    }

    return 0;
}

// Function to print camera information
void print_camera_info(const camera_info_t *camera_info) {
    printf("Camera: %s\n", camera_info->device_name);
    printf("Capabilities: 0x%08x\n", camera_info->capabilities);

    if (camera_info->capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("  - Video capture supported\n");
    }
    if (camera_info->capabilities & V4L2_CAP_STREAMING) {
        printf("  - Streaming supported\n");
    }

    printf("Supported Resolutions:\n");
    for (int i = 0; i < camera_info->num_frame_sizes; i++) {
        printf("  - %dx%d\n", camera_info->frame_sizes[i].discrete.width, camera_info->frame_sizes[i].discrete.height);
    }

    printf("Supported Frame Rates:\n");
    for (int i = 0; i < camera_info->num_frame_intervals; i++) {
        double fps = (double)camera_info->frame_intervals[i].discrete.denominator / camera_info->frame_intervals[i].discrete.numerator;
        printf("  - %.2f fps\n", fps);
    }

    if (camera_info->focus_support) {
        printf("Autofocus Supported\n");
    } else {
        printf("Autofocus Not Supported\n");
    }
}

int main() {
    int fd;
    camera_info_t camera_info;

    // Open the camera device
    fd = open_camera(DEVICE_NAME);
    if (fd < 0) {
        fprintf(stderr, "Failed to open camera. Ensure it is connected and the device node is accessible.\n");
        return EXIT_FAILURE;
    }

    // Query camera capabilities
    if (query_capabilities(fd, &camera_info) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Query autofocus support
    if (query_focus_support(fd, &camera_info) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Enumerate frame sizes
    if (enumerate_frame_sizes(fd, &camera_info) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Enumerate frame intervals
    if (enumerate_frame_intervals(fd, &camera_info) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Print camera information
    print_camera_info(&camera_info);

    // Close the camera device
    close(fd);

    return EXIT_SUCCESS;
}

