// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo center position (1500 microseconds)
#define SERVO_CENTER 1500

// Define servo pulse width limits (1000-2000 microseconds)
#define SERVO_MIN 1000
#define SERVO_MAX 2000

// Define servo increment/decrement step (10 microseconds)
#define SERVO_STEP 10

// Global variables for servo positions
int pan_position = SERVO_CENTER;
int tilt_position = SERVO_CENTER;

// Function prototypes
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        switch (gpio) {
            case UP_BUTTON_PIN:
                tilt_position += SERVO_STEP;
                if (tilt_position > SERVO_MAX) {
                    tilt_position = SERVO_MAX;
                }
                break;
            case DOWN_BUTTON_PIN:
                tilt_position -= SERVO_STEP;
                if (tilt_position < SERVO_MIN) {
                    tilt_position = SERVO_MIN;
                }
                break;
            case LEFT_BUTTON_PIN:
                pan_position -= SERVO_STEP;
                if (pan_position < SERVO_MIN) {
                    pan_position = SERVO_MIN;
                }
                break;
            case RIGHT_BUTTON_PIN:
                pan_position += SERVO_STEP;
                if (pan_position > SERVO_MAX) {
                    pan_position = SERVO_MAX;
                }
                break;
            default:
                fprintf(stderr, "Error: Unknown button GPIO %d\n", gpio);
                break;
        }
        gpioServo(PAN_SERVO_PIN, pan_position);
        gpioServo(TILT_SERVO_PIN, tilt_position);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for buttons (input with pull-up resistors)
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set GPIO modes for servos (output)
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Initialize servos to center position
    gpioServo(PAN_SERVO_PIN, SERVO_CENTER);
    gpioServo(TILT_SERVO_PIN, SERVO_CENTER);

    // Set up callbacks for button presses
    gpioSetAlertFunc(UP_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(DOWN_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(LEFT_BUTTON_PIN, button_callback);
    gpioSetAlertFunc(RIGHT_BUTTON_PIN, button_callback);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Print startup message
    printf("Camera Pan-Tilt System\n");
    printf("Pan Servo GPIO: %d, Tilt Servo GPIO: %d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Up Button GPIO: %d, Down Button GPIO: %d, Left Button GPIO: %d, Right Button GPIO: %d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center Position: %d microseconds\n", SERVO_CENTER);

    // Main loop (keep the program running)
    while (1) {
        gpioDelay(50); // Delay for 50 milliseconds
    }

    return 0;
}

