#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LENGTH 256

// Structure to hold program configuration
typedef struct {
    char server_ip[20];
    int server_port;
} ProgramConfig;

// Global variables
static volatile int running = 1;
static time_t last_motion_time = 0;
static ProgramConfig config;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_snapshot(char *filename);
int send_data_to_server(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
void signal_handler(int signal);
void cleanup();
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture a snapshot using libcamera-still
int capture_snapshot(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n --width 640 --height 480 --quality 85", filename);

    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Error capturing snapshot: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to send data to the server using libcurl
int send_data_to_server(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    // Construct JSON payload
    snprintf(json_payload, sizeof(json_payload), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://%s:%d/upload", config.server_ip, config.server_port);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Set Content-Type header to application/json
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            printf("HTTP Response Code: %ld\n", response_code);
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers); // Free the header list
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }

    curl_global_cleanup();
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Function to perform cleanup
void cleanup() {
    gpioTerminate();
    printf("GPIO terminated.\n");
}

// Function to get ISO 8601 timestamp with microseconds
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%06ldZ", ts.tv_nsec / 1000);

    return timestamp_str;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    strncpy(config.server_ip, argv[1], sizeof(config.server_ip) - 1);
    config.server_ip[sizeof(config.server_ip) - 1] = '\0';
    config.server_port = atoi(argv[2]);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create the capture directory if it doesn't exist
    if (mkdir(CAPTURE_DIR, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory %s\n", CAPTURE_DIR);
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            time_t current_time = time(NULL);

            // Debounce the sensor
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                printf("Motion detected!\n");

                // Generate filename
                char filename[MAX_FILENAME_LENGTH];
                snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", CAPTURE_DIR, current_time);

                // Capture snapshot
                if (capture_snapshot(filename) == 0) {
                    printf("Snapshot captured: %s\n", filename);

                    // Get timestamp
                    char timestamp[32];
                    get_iso8601_timestamp(timestamp, sizeof(timestamp));

                    // Send data to server
                    if (send_data_to_server(filename, timestamp, motion_detected, GPIO_PIN) == 0) {
                        printf("Data sent to server.\n");
                    } else {
                        fprintf(stderr, "Failed to send data to server.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture snapshot.\n");
                }

                last_motion_time = current_time;
            }
        }

        gpioDelay(100); // Check every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

