#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define NUM_BUFFERS 1

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer_start;
    size_t buffer_length;
} camera_t;

// Global camera instance
camera_t camera;

// Signal handler flag
volatile sig_atomic_t stop_flag = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the camera
int init_camera(camera_t *cam) {
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cam->cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->fmt.fmt.pix.width = WIDTH;
    cam->fmt.fmt.pix.height = HEIGHT;
    cam->fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    cam->fmt.fmt.pix.field = FIELD;

    if (ioctl(fd, VIDIOC_S_FMT, &cam->fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    if (cam->fmt.fmt.pix.width != WIDTH || cam->fmt.fmt.pix.height != HEIGHT || cam->fmt.fmt.pix.pixelformat != PIXEL_FORMAT) {
        fprintf(stderr, "Format not supported by device\n");
        close(fd);
        return -1;
    }

    cam->req.count = NUM_BUFFERS;
    cam->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &cam->req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;

    for (int i = 0; i < NUM_BUFFERS; i++) {
        cam->buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &cam->buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        cam->buffer_start = mmap(NULL, cam->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, cam->buf.m.offset);
        if (cam->buffer_start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }

        if (ioctl(fd, VIDIOC_QBUF, &cam->buf) < 0) {
            perror("Error queuing buffer");
            munmap(cam->buffer_start, cam->buf.length);
            close(fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(cam->buffer_start, cam->buf.length);
        close(fd);
        return -1;
    }

    cam->fd = fd;
    cam->buffer_length = cam->buf.length;

    return 0;
}

// Function to capture a frame
int capture_frame(camera_t *cam, void **frame_data, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(cam->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Select interrupted by signal\n");
            return -1;
        }
        perror("Select error");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    if (ioctl(cam->fd, VIDIOC_DQBUF, &cam->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *frame_data = cam->buffer_start;
    *frame_size = cam->buf.bytesused;

    return 0;
}

// Function to crop the frame
int crop_frame(void *frame_data, size_t frame_size, int width, int height, int x, int y, int crop_width, int crop_height, void **cropped_data, size_t *cropped_size) {
    if (x < 0 || x + crop_width > width || y < 0 || y + crop_height > height) {
        fprintf(stderr, "Crop region out of bounds\n");
        return -1;
    }

    if (crop_width % 2 != 0 || crop_height % 2 != 0) {
        fprintf(stderr, "Crop width and height must be even\n");
        return -1;
    }

    size_t bytes_per_pixel = 2; // YUYV is 2 bytes per pixel
    size_t bytes_per_row = width * bytes_per_pixel;
    size_t bytes_per_cropped_row = crop_width * bytes_per_pixel;

    *cropped_size = crop_width * crop_height * bytes_per_pixel;
    *cropped_data = malloc(*cropped_size);
    if (*cropped_data == NULL) {
        perror("Error allocating memory for cropped frame");
        return -1;
    }

    for (int i = 0; i < crop_height; i++) {
        memcpy(
            (char *)*cropped_data + i * bytes_per_cropped_row,
            (char *)frame_data + (y + i) * bytes_per_row + x * bytes_per_pixel,
            bytes_per_cropped_row
        );
    }

    return 0;
}

// Function to save the cropped frame to a file
int save_frame(void *cropped_data, size_t cropped_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_data, 1, cropped_size, fp);
    if (bytes_written != cropped_size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to stop the camera
int stop_camera(camera_t *cam) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        cam->buf.index = i;
        if (ioctl(cam->fd, VIDIOC_QUERYBUF, &cam->buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }
        if (munmap(cam->buffer_start, cam->buf.length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    if (close(cam->fd) < 0) {
        perror("Error closing device");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("Camera initialized successfully\n");

    // Capture a frame
    void *frame_data;
    size_t frame_size;
    if (capture_frame(&camera, &frame_data, &frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame captured successfully\n");

    // Crop the frame
    void *cropped_data;
    size_t cropped_size;
    if (crop_frame(frame_data, frame_size, WIDTH, HEIGHT, 100, 50, 200, 150, &cropped_data, &cropped_size) < 0) {
        fprintf(stderr, "Frame cropping failed\n");
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame cropped successfully\n");

    // Save the cropped frame
    if (save_frame(cropped_data, cropped_size, "cropped.yuv") < 0) {
        fprintf(stderr, "Frame saving failed\n");
        free(cropped_data);
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame saved successfully\n");

    // Free allocated memory
    free(cropped_data);

    // Stop the camera
    if (stop_camera(&camera) < 0) {
        fprintf(stderr, "Camera stopping failed\n");
        return EXIT_FAILURE;
    }

    printf("Camera stopped successfully\n");

    return EXIT_SUCCESS;
}

