    if (x < 0 || x + crop_width > width || y < 0 || y + crop_height > height) {
        fprintf(stderr, "Crop region out of bounds\n");
        return -1;
    }

    if (crop_width % 2 != 0 || crop_height % 2 != 0) {
        fprintf(stderr, "Crop width and height must be even\n");
        return -1;
    }

    size_t bytes_per_pixel = 2; // YUYV is 2 bytes per pixel
    size_t bytes_per_row = width * bytes_per_pixel;
    size_t bytes_per_cropped_row = crop_width * bytes_per_pixel;

    *cropped_size = crop_width * crop_height * bytes_per_pixel;
    *cropped_data = malloc(*cropped_size);
    if (*cropped_data == NULL) {
        perror("Error allocating memory for cropped frame");
        return -1;
    }

    for (int i = 0; i < crop_height; i++) {
        memcpy(
            (char *)*cropped_data + i * bytes_per_cropped_row,
            (char *)frame_data + (y + i) * bytes_per_row + x * bytes_per_pixel,
            bytes_per_cropped_row
        );
    }

    return 0;
}

// Function to save the cropped frame to a file
int save_frame(void *cropped_data, size_t cropped_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_data, 1, cropped_size, fp);
    if (bytes_written != cropped_size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to stop the camera
int stop_camera(camera_t *cam) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        cam->buf.index = i;
        if (ioctl(cam->fd, VIDIOC_QUERYBUF, &cam->buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }
        if (munmap(cam->buffer_start, cam->buf.length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    if (close(cam->fd) < 0) {
        perror("Error closing device");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("Camera initialized successfully\n");

    // Capture a frame
    void *frame_data;
    size_t frame_size;
    if (capture_frame(&camera, &frame_data, &frame_size) < 0) {
        fprintf(stderr, "Frame capture failed\n");
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame captured successfully\n");

    // Crop the frame
    void *cropped_data;
    size_t cropped_size;
    if (crop_frame(frame_data, frame_size, WIDTH, HEIGHT, 100, 50, 200, 150, &cropped_data, &cropped_size) < 0) {
        fprintf(stderr, "Frame cropping failed\n");
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame cropped successfully\n");

    // Save the cropped frame
    if (save_frame(cropped_data, cropped_size, "cropped.yuv") < 0) {
        fprintf(stderr, "Frame saving failed\n");
        free(cropped_data);
        stop_camera(&camera);
        return EXIT_FAILURE;
    }

    printf("Frame saved successfully\n");

    // Free allocated memory
    free(cropped_data);

    // Stop the camera
    if (stop_camera(&camera) < 0) {
        fprintf(stderr, "Camera stopping failed\n");
        return EXIT_FAILURE;
    }

    printf("Camera stopped successfully\n");

    return EXIT_SUCCESS;
}

