#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define initial angle (degrees)
#define INITIAL_ANGLE 90

// Define angle increment (degrees)
#define ANGLE_INCREMENT 5

// Global variables for current angles
int pan_angle = INITIAL_ANGLE;
int tilt_angle = INITIAL_ANGLE;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int gpio, int angle);
int read_user_input(int *pan_angle, int *tilt_angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Setting servos to neutral position and exiting.\n");
        set_servo_angle(PAN_GPIO, INITIAL_ANGLE);
        set_servo_angle(TILT_GPIO, INITIAL_ANGLE);
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the angle of a servo motor
int set_servo_angle(int gpio, int angle) {
    // Validate angle
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d is out of range (%d-%d)\n", angle, MIN_ANGLE, MAX_ANGLE);
        return 1; // Indicate failure
    }

    // Calculate pulse width (linear mapping)
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    int duty_cycle = (int)(((float)pulse_width / 20000.0) * 255.0); // pigpio duty cycle is 0-255

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio);
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to read user input and update pan and tilt angles
int read_user_input(int *pan_angle, int *tilt_angle) {
    int input;

    input = getchar();

    if (input == EOF) {
        return 1; // Indicate end of input
    }

    switch (input) {
        case 'w': // Up
            *tilt_angle += ANGLE_INCREMENT;
            if (*tilt_angle > MAX_ANGLE) {
                *tilt_angle = MAX_ANGLE;
            }
            break;
        case 's': // Down
            *tilt_angle -= ANGLE_INCREMENT;
            if (*tilt_angle < MIN_ANGLE) {
                *tilt_angle = MIN_ANGLE;
            }
            break;
        case 'a': // Left
            *pan_angle -= ANGLE_INCREMENT;
            if (*pan_angle < MIN_ANGLE) {
                *pan_angle = MIN_ANGLE;
            }
            break;
        case 'd': // Right
            *pan_angle += ANGLE_INCREMENT;
            if (*pan_angle > MAX_ANGLE) {
                *pan_angle = MAX_ANGLE;
            }
            break;
        case 'q': // Quit
            return 1;
        default:
            fprintf(stderr, "Invalid input. Use w, a, s, d, or q.\n");
            // Consume the rest of the line to avoid unexpected behavior
            while (getchar() != '\n' && getchar() != EOF);
            return 0; // Indicate invalid input
    }

    return 0; // Indicate valid input
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pan-Tilt Camera Control\n");
    printf("Use arrow keys (w, a, s, d) to adjust pan and tilt. Press q to quit.\n");

    // Main loop
    while (1) {
        // Read user input
        if (read_user_input(&pan_angle, &tilt_angle) == 1) {
            break; // Exit loop if user enters 'q' or EOF
        }

        // Set servo angles
        if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
            fprintf(stderr, "Error setting pan angle. Continuing...\n");
        }
        if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt angle. Continuing...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

