        i++;
    }
}

// Read CPU usage
float read_cpu_usage() {
    cpu_stats_t prev_stats = read_cpu_stats();
    gpioDelay(1000); // Wait 1 second
    cpu_stats_t current_stats = read_cpu_stats();

    unsigned long long prev_idle = prev_stats.idle + prev_stats.iowait;
    unsigned long long current_idle = current_stats.idle + current_stats.iowait;

    unsigned long long prev_non_idle = prev_stats.user + prev_stats.nice + prev_stats.system + prev_stats.irq + prev_stats.softirq + prev_stats.steal;
    unsigned long long current_non_idle = current_stats.user + current_stats.nice + current_stats.system + current_stats.irq + current_stats.softirq + current_stats.steal;

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long current_total = current_idle + current_non_idle;

    unsigned long long totald = current_total - prev_total;
    unsigned long long idled = current_idle - prev_idle;

    float cpu_usage = (float)(totald - idled) / totald * 100.0;

    return cpu_usage;
}

// Read CPU stats from /proc/stat
cpu_stats_t read_cpu_stats() {
    cpu_stats_t stats;
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        stats.user = 0;
        stats.nice = 0;
        stats.system = 0;
        stats.idle = 0;
        stats.iowait = 0;
        stats.irq = 0;
        stats.softirq = 0;
        stats.steal = 0;
        stats.guest = 0;
        stats.guest_nice = 0;
        return stats;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                       &stats.user, &stats.nice, &stats.system, &stats.idle, &stats.iowait, &stats.irq, &stats.softirq, &stats.steal, &stats.guest, &stats.guest_nice) != 10) {
                fprintf(stderr, "Failed to parse CPU stats\n");
                fclose(fp);
                stats.user = 0;
                stats.nice = 0;
                stats.system = 0;
                stats.idle = 0;
                stats.iowait = 0;
                stats.irq = 0;
                stats.softirq = 0;
                stats.steal = 0;
                stats.guest = 0;
                stats.guest_nice = 0;
                return stats;
            }
            break;
        }
    }

    fclose(fp);
    return stats;
}

// Read temperature from /sys/class/thermal/thermal_zone0/temp
float read_temperature() {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature file\n");
        return -1.0;
    }

    int temp_milli_celsius;
    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Failed to read temperature\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Display data on the OLED
void display_data(float cpu_usage, float temperature) {
    char cpu_str[20];
    char temp_str[20];

    snprintf(cpu_str, sizeof(cpu_str), "CPU: %.2f%%", cpu_usage);
    snprintf(temp_str, sizeof(temp_str), "Temp: %.2fC", temperature);

    ssd1306_clear();
    ssd1306_draw_string(0, 0, cpu_str);
    ssd1306_draw_string(0, 16, temp_str);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize SSD1306
    if (init_ssd1306() != 0) {
        close_i2c();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float cpu_usage = read_cpu_usage();
        float temperature = read_temperature();

        if (cpu_usage >= 0 && temperature >= -273.15) {
            display_data(cpu_usage, temperature);
        } else {
            fprintf(stderr, "Failed to read CPU or temperature data\n");
        }

        gpioDelay(5000); // Update every 5 seconds
    }

    // Close I2C
    close_i2c();

    return 0;
}

