#include <time.h>
#include <string.h>

// Define GPIO pins for the water flow sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27

// Define the I2C bus and address for the LCD
#define I2C_BUS 1
#define LCD_ADDR 0x27

// Define the calibration factor for the YF-S201 sensor (pulses per liter)
#define CALIBRATION_FACTOR 450.0

// Define the number of pulses per liter
#define PULSES_PER_LITER 450.0

// Define the number of seconds to update the LCD
#define LCD_UPDATE_INTERVAL 10

// Global variables
volatile int pulse_count1 = 0;
volatile int pulse_count2 = 0;
volatile int pulse_count3 = 0;
double total_volume1 = 0.0;
double total_volume2 = 0.0;
double total_volume3 = 0.0;
int i2c_handle;

// Function prototypes
void pulse_counter1(int gpio, int level, uint32_t tick);
void pulse_counter2(int gpio, int level, uint32_t tick);
void pulse_counter3(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulse_count);
void update_lcd(double flow_rate1, double flow_rate2, double flow_rate3, double total_volume1, double total_volume2, double total_volume3);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    exit(0);
}

// Interrupt handler for sensor 1
void pulse_counter1(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count1++;
    }
}

// Interrupt handler for sensor 2
void pulse_counter2(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count2++;
    }
}

// Interrupt handler for sensor 3
void pulse_counter3(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count3++;
    }
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to update the LCD display
void update_lcd(double flow_rate1, double flow_rate2, double flow_rate3, double total_volume1, double total_volume2, double total_volume3) {
    char buffer[20];

    lcd_clear();
    lcd_set_cursor(0, 0);
    snprintf(buffer, sizeof(buffer), "S1: %.2f LPM", flow_rate1);
    lcd_print(buffer);

    lcd_set_cursor(1, 0);
    snprintf(buffer, sizeof(buffer), "S2: %.2f LPM", flow_rate2);
    lcd_print(buffer);

    lcd_set_cursor(0, 10);
    snprintf(buffer, sizeof(buffer), "S3: %.2f LPM", flow_rate3);
    lcd_print(buffer);

    lcd_set_cursor(1, 10);
    snprintf(buffer, sizeof(buffer), "V: %.2f L", total_volume1 + total_volume2 + total_volume3);
    lcd_print(buffer);
}

// LCD initialization function
int lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD (4-bit mode)
    gpioDelay(50); // Wait for more than 4.1ms after VCC rises to 2.7V
    i2cWriteByteData(i2c_handle, 0x00, 0x33); // Initialize
    gpioDelay(5);  // Wait for more than 4.1ms
    i2cWriteByteData(i2c_handle, 0x00, 0x32); // Initialize
    gpioDelay(1);  // Wait for more than 100us
    i2cWriteByteData(i2c_handle, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    i2cWriteByteData(i2c_handle, 0x00, 0x0C); // Display on, cursor off, blink off
    i2cWriteByteData(i2c_handle, 0x00, 0x06); // Increment cursor, no shift
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2);  // Wait for more than 1.53ms

    return 0;
}

// LCD clear function
void lcd_clear() {
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2);  // Wait for more than 1.53ms
}

// LCD set cursor function
void lcd_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = 0x80 + col;
    } else {
        address = 0xC0 + col;
    }
    i2cWriteByteData(i2c_handle, 0x00, address);
}

// LCD print function
void lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        i2cWriteByteData(i2c_handle, 0x40, str[i]); // Send data
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    // Set interrupt handlers for rising edges
    gpioSetAlertFuncEx(SENSOR1_GPIO, pulse_counter1, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, pulse_counter2, NULL);
    gpioSetAlertFuncEx(SENSOR3_GPIO, pulse_counter3, NULL);

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_lcd_update = time(NULL);

    // Main loop
    while (1) {
        // Calculate flow rates
        double flow_rate1 = calculate_flow_rate(pulse_count1);
        double flow_rate2 = calculate_flow_rate(pulse_count2);
        double flow_rate3 = calculate_flow_rate(pulse_count3);

        // Update total volumes
        total_volume1 += (double)pulse_count1 / PULSES_PER_LITER;
        total_volume2 += (double)pulse_count2 / PULSES_PER_LITER;
        total_volume3 += (double)pulse_count3 / PULSES_PER_LITER;

        // Reset pulse counts
        pulse_count1 = 0;
        pulse_count2 = 0;
        pulse_count3 = 0;

        // Print flow rates and total volume to the console
        printf("Sensor 1: %.2f LPM, Total Volume: %.2f L\n", flow_rate1, total_volume1);
        printf("Sensor 2: %.2f LPM, Total Volume: %.2f L\n", flow_rate2, total_volume2);
        printf("Sensor 3: %.2f LPM, Total Volume: %.2f L\n", flow_rate3, total_volume3);
        printf("Total Volume: %.2f L\n", total_volume1 + total_volume2 + total_volume3);

        // Update LCD every 10 seconds
        time_t current_time = time(NULL);
        if (difftime(current_time, last_lcd_update) >= LCD_UPDATE_INTERVAL) {
            update_lcd(flow_rate1, flow_rate2, flow_rate3, total_volume1, total_volume2, total_volume3);
            last_lcd_update = current_time;
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    return 0;
}

