#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define SAMPLE_INTERVAL_MS 500
#define PULSES_PER_ROTATION 1.0 // Adjust based on your anemometer
#define ADC_MIN 10
#define ADC_MAX 990

// Global variables
static volatile int pulse_count = 0;
static int spi_handle = -1;
static int i2c_handle = -1;
static int socket_desc = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulses);
int read_wind_vane();
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void send_data(float wind_speed, int wind_direction);
void signal_handler(int signal);
void cleanup();

// Anemometer interrupt handler
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    if (level == RISING_EDGE)
    {
        pulse_count++;
    }
}

// Calculate wind speed
float calculate_wind_speed(int pulses)
{
    return (float)pulses * 0.5 * PULSES_PER_ROTATION;
}

// Read wind vane from MCP3008
int read_wind_vane()
{
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 command: start bit, single-ended mode, channel 0, don't care
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (MCP3008_CHANNEL << 4)); // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0)
    {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Validate ADC value
    if (adc_value < ADC_MIN || adc_value > ADC_MAX)
    {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// LCD functions (PCF8574 backpack)
void lcd_init()
{
    // Initialize LCD (4-bit mode)
    gpioDelay(50); // Wait for LCD to power up
    gpioWrite(i2c_handle, 0x33); // Initialize
    gpioDelay(5);
    gpioWrite(i2c_handle, 0x32); // Initialize
    gpioDelay(5);
    gpioWrite(i2c_handle, 0x28); // 4-bit mode, 2 lines, 5x8 font
    gpioDelay(5);
    gpioWrite(i2c_handle, 0x0C); // Display on, cursor off, blink off
    gpioDelay(5);
    gpioWrite(i2c_handle, 0x06); // Increment cursor, no shift
    gpioDelay(5);
    gpioWrite(i2c_handle, 0x01); // Clear display
    gpioDelay(5);
}

void lcd_clear()
{
    gpioWrite(i2c_handle, 0x01); // Clear display
    gpioDelay(5);
}

void lcd_set_cursor(int row, int col)
{
    int addr;
    if (row == 0)
    {
        addr = 0x80 + col;
    }
    else
    {
        addr = 0xC0 + col;
    }
    gpioWrite(i2c_handle, addr);
    gpioDelay(5);
}

void lcd_print(const char *str)
{
    for (int i = 0; str[i] != '\0'; i++)
    {
        gpioWrite(i2c_handle, 0x09); // Set RS bit for data
        gpioWrite(i2c_handle, str[i]);
        gpioDelay(5);
    }
}

// Send data to server
void send_data(float wind_speed, int wind_direction)
{
    struct sockaddr_in server_addr;
    char buffer[256];

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc < 0)
    {
        fprintf(stderr, "Error: Could not create socket\n");
        return;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0)
    {
        fprintf(stderr, "Error: Invalid address/ Address not supported\n");
        close(socket_desc);
        socket_desc = -1;
        return;
    }

    // Connect to server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0)
    {
        fprintf(stderr, "Error: Connection failed\n");
        close(socket_desc);
        socket_desc = -1;
        return;
    }

    // Prepare data
    snprintf(buffer, sizeof(buffer), "Wind Speed: %.2f m/s, Direction: %d degrees", wind_speed, wind_direction);

    // Send data
    if (send(socket_desc, buffer, strlen(buffer), 0) < 0)
    {
        fprintf(stderr, "Error: Send failed\n");
    }

    // Close socket
