#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 7.5
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1 // Mode - Sending data
#define LCD_CMD 0 // Mode - Sending command

// Global variables
static volatile int pulse_count = 0;
static int lcd_fd;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses, float time_interval);
void display_flow_rate(float flow_rate);
void log_flow_rate(float flow_rate);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void signal_handler(int signal);

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Calculate flow rate function
float calculate_flow_rate(int pulses, float time_interval) {
    return (float)pulses / PULSES_PER_LITER / time_interval * 60.0;
}

// Display flow rate on LCD function
void display_flow_rate(float flow_rate) {
    char buffer[20];

    lcd_clear();
    lcd_string("Flow Rate:");

    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_byte(0xC0, LCD_CMD); // Move cursor to the beginning of the second line
    lcd_string(buffer);
}

// Log flow rate to file function
void log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f L/min\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// LCD initialization function
void lcd_init() {
    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // 0x0F = Display on, Cursor on, Blink on. 0x0C = Display on,Cursor off, Blink off.
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(500);           // Delay for clear display
}

// LCD byte send function
void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high;
    int bits_low;

    // Use the upper nibble
    bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWrite(lcd_fd, bits_high);
    wiringPiI2CWrite(lcd_fd, bits_high | LCD_EN);
    gpioDelay(1); // Enable pulse must be > 450ns
    wiringPiI2CWrite(lcd_fd, bits_high & ~LCD_EN);
    gpioDelay(50);

    // Low bits
    wiringPiI2CWrite(lcd_fd, bits_low);
    wiringPiI2CWrite(lcd_fd, bits_low | LCD_EN);
    gpioDelay(1); // Enable pulse must be > 450ns
    wiringPiI2CWrite(lcd_fd, bits_low & ~LCD_EN);
    gpioDelay(50);
}

// LCD string send function
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// LCD clear function
void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(500);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int pulses;
    float flow_rate;
    time_t start_time, current_time;
    double time_interval;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up alert function for pulse counting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL);

    // Initialize LCD
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "LCD initialisation failed\n");
        gpioTerminate();
        return 1;
    }
    lcd_init();

    // Open log file
    log_file = fopen("flow_rate.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    time(&start_time);

    while (!terminate) {
        time(&current_time);
        time_interval = difftime(current_time, start_time);

        if (time_interval >= 1.0) {
            pulses = pulse_count;
            pulse_count = 0; // Reset pulse count

            flow_rate = calculate_flow_rate(pulses, time_interval);

            display_flow_rate(flow_rate);
            log_flow_rate(flow_rate);

            time(&start_time);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    lcd_clear();
    lcd_string("Exiting...");
    fclose(log_file);
    gpioTerminate();

    printf("Water flow monitoring stopped.\n");

    return 0;
}

