#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"

// Row pins (anodes)
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};

// Column pins (cathodes)
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};

// Number of rows and columns
const int num_rows = 8;
const int num_cols = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *row_lines[num_rows];
struct gpiod_line *col_lines[num_cols];

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request row lines as output
    for (int i = 0; i < num_rows; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 1) < 0) {
            perror("Error requesting row line as output");
            goto cleanup;
        }
    }

    // Request column lines as output
    for (int i = 0; i < num_cols; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            perror("Error requesting column line as output");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    // Release already allocated lines
    for (int j = 0; j < i; j++) {
        if (row_lines[j]) {
            gpiod_line_release(row_lines[j]);
        }
        if (col_lines[j]) {
            gpiod_line_release(col_lines[j]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return -1;
}

// Function to clear the LED matrix
void clear_matrix()
{
    // Set all column cathodes HIGH
    for (int i = 0; i < num_cols; i++) {
        if (gpiod_line_set_value(col_lines[i], 1) < 0) {
            perror("Error setting column HIGH");
        }
    }

    // Set all row anodes LOW
    for (int i = 0; i < num_rows; i++) {
        if (gpiod_line_set_value(row_lines[i], 0) < 0) {
            perror("Error setting row LOW");
        }
    }
}

// Function to display a column
void display_column(int col)
{
    // Set the column cathode LOW
    if (gpiod_line_set_value(col_lines[col], 0) < 0) {
        perror("Error setting column LOW");
    }

    // Set all row anodes HIGH
    for (int i = 0; i < num_rows; i++) {
        if (gpiod_line_set_value(row_lines[i], 1) < 0) {
            perror("Error setting row HIGH");
        }
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("LED matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        for (int col = 0; col < num_cols; col++) {
            clear_matrix();
            display_column(col);
            usleep(150000); // 150 ms
        }
    }

    return 0;
}

