            // Attempt to re-open I2C connection
            i2cClose(i2c_handle);
            if (open_i2c_connection() != 0) {
                fprintf(stderr, "Failed to re-open I2C connection\n");
                terminate = 1; // Exit loop if re-opening fails
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

