#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24
#define REG_COMMAND 0x18
#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04

// I2C handle
int i2c_handle;

// Log file pointer
FILE *log_file;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int sample_rate_ms;
} sensor_config_t;

// Global configuration
sensor_config_t config = {1, SI1145_ADDR, 500};

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Log the data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(config.sample_rate_ms * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int part_id;

    // Read the PART ID register
    part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART ID: %d\n", part_id);
        return -1;
    }

    // Verify the PART ID
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the device (optional, but recommended)
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Failed to reset device\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_IRQ_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Failed to write IRQ_ENABLE\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE1, 0x00) < 0) {
        fprintf(stderr, "Failed to write IRQ_MODE1\n");
        return -1;
    }

    // Enable ALS and PS1 measurements
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x07) < 0) {
        fprintf(stderr, "Failed to enable measurements\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int als_vis_data0, ps1_data0;

    // Read ALS data
    als_vis_data0 = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (als_vis_data0 < 0) {
        fprintf(stderr, "Failed to read ALS data: %d\n", als_vis_data0);
        return -1;
    }

    // Read PS1 data
    ps1_data0 = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    if (ps1_data0 < 0) {
        fprintf(stderr, "Failed to read PS1 data: %d\n", ps1_data0);
        return -1;
    }

    // Combine the two bytes to form the 16-bit values
    *ambient_light = als_vis_data0;
    *proximity = ps1_data0;

    return 0;
}

// Function to log the sensor data to a file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO-8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to log file
    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Flush and close log file
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

