#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define BLINK_DURATION_MS 100
#define POLLING_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_led(int state);
void log_event(const char *message);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", buf, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to blink the LED
void blink_led() {
    control_led(1); // Turn LED on
    gpioDelay(BLINK_DURATION_MS * 1000); // Delay for blink duration
    control_led(0); // Turn LED off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_sensor_state = 1; // Initialize to HIGH (no object detected)

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        // Detect falling edge (object detected)
        if (sensor_value == 0 && last_sensor_state == 1) {
            log_event("Object detected");
            blink_led();
        }

        last_sensor_state = sensor_value;
        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

