#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CH_LIST 0x4F
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x18
#define REG_COMMAND 0x30

// Si1145 commands
#define ALS_FORCE 0x06
#define PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    int status;

    // Check PART_ID
    status = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", status);
        return -1;
    }
    printf("Si1145 PART_ID: 0x%02X\n", status);

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Configure CH_LIST (enable PS1 and ALS_VIS)
    status = i2cWriteByteData(i2c_handle, REG_CH_LIST, 0x77); // Enable all channels
    if (status < 0) {
        fprintf(stderr, "Error writing CH_LIST: %d\n", status);
        return -1;
    }

    // Set measurement rates (example values, adjust as needed)
    // These are just examples, refer to the Si1145 datasheet for proper configuration
    status = i2cWriteByteData(i2c_handle, 0x08, 0x07); // PS_RATE
    if (status < 0) {
        fprintf(stderr, "Error writing PS_RATE: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x09, 0x07); // ALS_RATE
    if (status < 0) {
        fprintf(stderr, "Error writing ALS_RATE: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    int status;
    uint8_t data[4];

    // Trigger ALS measurement
    status = i2cWriteByteData(i2c_handle, REG_COMMAND, ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error triggering ALS measurement: %d\n", status);
        return -1;
    }

    // Trigger PS measurement
    status = i2cWriteByteData(i2c_handle, REG_COMMAND, PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error triggering PS measurement: %d\n", status);
        return -1;
    }

    // Read ALS_VIS data
    status = i2cReadI2CBlockData(i2c_handle, REG_ALS_VIS_DATA0, (char *)data, 4);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }

    // Read PS1 data
    status = i2cReadI2CBlockData(i2c_handle, REG_PS1_DATA0, (char *)data, 4);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }

    // Combine the two bytes to form the 16-bit values
    *ambient_light = (uint16_t)((data[1] << 8) | data[0]);
    *proximity = (uint16_t)((data[3] << 8) | data[2]);

    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[25]; // Static to persist across calls

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the data to a CSV file
int log_data(const char *timestamp, uint16_t proximity, uint16_t ambient_light) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    uint16_t proximity, ambient_light;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,proximity,ambient_light\n");
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

