#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_data(double distance, const char *message);
void check_distance_and_log_reminder(double distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Indicate that echo has started
        } else if (level == 0) {
            echo_end_tick = tick;
        }
    }
}

// Calculate distance in centimeters
double calculate_distance(int pulse_width_us) {
    return (pulse_width_us * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and by 2 for one-way distance
}

// Log data to file
void log_data(double distance, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Distance: %.2f cm, %s\n", timestamp, distance, message);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check distance and log reminder if necessary
void check_distance_and_log_reminder(double distance) {
    if (distance < 15.0) {
        log_data(distance, "Time to water the plant!");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioTerminate();           // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0; // Reset echo received flag
        echo_start_tick = 0;
        echo_end_tick = 0;

        trigger_sensor();

        // Wait for echo or timeout
        int timeout_counter = 0;
        while (!echo_received && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_counter++;
        }

        if (!echo_received) {
            log_data(-1.0, "Timeout waiting for echo start");
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        timeout_counter = 0;
        while (echo_end_tick == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_counter++;
        }

        if (echo_end_tick == 0) {
            log_data(-1.0, "Timeout waiting for echo end");
            gpioDelay(60000); // Wait 60 seconds
            continue;
        }

        // Calculate pulse width in microseconds
        int pulse_width_us = echo_end_tick - echo_start_tick;

        // Calculate distance
        double distance = calculate_distance(pulse_width_us);

        // Validate distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            char message[50];
            snprintf(message, sizeof(message), "Invalid distance: %.2f cm", distance);
            log_data(distance, message);
        } else {
            char message[50];
            snprintf(message, sizeof(message), "Distance: %.2f cm", distance);
            log_data(distance, message);
            check_distance_and_log_reminder(distance);
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    cleanup();
    return 0;
}

