#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint8_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    int status;

    // Verify sensor ID
    status = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (status != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", status);
        return -1;
    }
    printf("Sensor ID verified: 0x%02X\n", status);

    // Enable power and ALS (Ambient Light Sensing)
    status = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Set ATIME (Integration time)
    status = i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB);
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set WTIME (Wait time)
    status = i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6);
    if (status < 0) {
        fprintf(stderr, "Error writing to WTIME register: %d\n", status);
        return -1;
    }

    // Set PPULSE (Proximity pulse length)
    status = i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87);
    if (status < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %d\n", status);
        return -1;
    }

    // Set CONTROL (Proximity gain)
    status = i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", status);
        return -1;
    }

    // Set CONFIG2 (Proximity and ALS configuration)
    status = i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %d\n", status);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int status;
    uint8_t buffer[8];

    // Read RGBC data (6 bytes) and proximity data (1 byte)
    status = i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, (char *)buffer, 8);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes for each color channel
    data->clear = (buffer[1] << 8) | buffer[0];
    data->red = (buffer[3] << 8) | buffer[2];
    data->green = (buffer[5] << 8) | buffer[4];
    data->blue = (buffer[7] << 8) | buffer[6];
    data->proximity = buffer[8];

    return 0;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to CSV file
    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.red, data.green, data.blue, data.proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

