#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x5A

// Define register addresses
#define REG_PART_ID 0x00
#define REG_MEAS_RATE0 0x08
#define REG_COMMAND 0x47
#define REG_PS_DATA0 0x24
#define REG_PS_DATA1 0x25

// Define commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Define proximity threshold for BPM calculation
#define PROXIMITY_THRESHOLD 500

// Define BPM calculation parameters
#define BPM_SCALE 0.1
#define BPM_OFFSET 60.0

// Global variables
int i2c_fd;
FILE *csv_file;
volatile sig_atomic_t running = true;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int si1182_init(int fd);
int read_proximity(int fd);
float calculate_bpm(int proximity);
int log_data(FILE *fp, float bpm);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    // Reset the device
    if (i2c_write_reg(fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1182\n");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Configure measurement rate (adjust as needed)
    if (i2c_write_reg(fd, REG_MEAS_RATE0, 0x0A) < 0) { // Example: 10 Hz
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }

    // Start continuous proximity measurement
    if (i2c_write_reg(fd, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error starting proximity measurement\n");
        return -1;
    }

    return 0;
}

// Read proximity data function
int read_proximity(int fd) {
    int low = i2c_read_reg(fd, REG_PS_DATA0);
    int high = i2c_read_reg(fd, REG_PS_DATA1);

    if (low < 0 || high < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    return (high << 8) | low;
}

// Calculate BPM from proximity data function
float calculate_bpm(int proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        return BPM_SCALE * proximity + BPM_OFFSET;
    } else {
        return 0.0;
    }
}

// Log data to CSV file function
int log_data(FILE *fp, float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    running = false;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify Si1182 part ID
    int part_id = i2c_read_reg(i2c_fd, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID\n");
        close(i2c_fd);
        return 1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x82)\n", part_id);
        close(i2c_fd);
        return 1;
    }

    printf("Si1182 part ID verified: 0x%02X\n", part_id);

    // Initialize Si1182 sensor
    if (si1182_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen("heartrate.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        int proximity = read_proximity(i2c_fd);
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity data, skipping sample\n");
            usleep(100000); // Wait 100ms before next attempt
            continue;
        }

        // Calculate BPM
        float bpm = calculate_bpm(proximity);

        // Log data
        if (log_data(csv_file, bpm) < 0) {
            fprintf(stderr, "Error logging data, skipping sample\n");
        }

        // Wait 100ms
        usleep(100000);
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    printf("Program finished.\n");
    return 0;
}

