#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// GPIO pin for interrupt (BCM numbering)
#define INTERRUPT_PIN 17

// I2C bus number
#define I2C_BUS 1

// File to log distance measurements
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l0x_init();
int vl53l0x_read_distance(int *distance);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// VL53L0X register addresses (Example - refer to datasheet for complete list)
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L0X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L0X_REG_SYSRANGE_START 0x000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x000B

// Function to write a byte to a VL53L0X register
int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L0X sensor
int vl53l0x_init() {
    // Check sensor presence
    uint8_t model_id;
    if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "VL53L0X not found (model ID: 0x%02X)\n", model_id);
        return -1;
    }

    // Recommended settings (example - adjust as needed)
    if (vl53l0x_write_byte(i2c_handle, 0x88, 0x00) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0x80, 0x01) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0xFF, 0x01) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0x00, 0x00) != 0) return -1;

    if (vl53l0x_write_byte(i2c_handle, 0x91, 0x3C) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0x00, 0x01) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0xFF, 0x00) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, 0x80, 0x00) != 0) return -1;

    if (vl53l0x_write_byte(i2c_handle, VL53L0X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x14) != 0) return -1;
    if (vl53l0x_write_byte(i2c_handle, VL53L0X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x14) != 0) return -1;

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int vl53l0x_read_distance(int *distance) {
    uint8_t range_status;
    uint8_t data[14];
    int16_t distance_mm;
    int timeout_count = 0;

    // Start a single measurement
    if (vl53l0x_write_byte(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for measurement to complete (with timeout)
    while (1) {
        if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &range_status) != 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (range_status & 0x01) {
            break; // Measurement complete
        }
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the range status
    if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read the distance data
    if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    distance_mm = (int16_t)((data[10] << 8) | data[11]);

    // Clear interrupt
    if (vl53l0x_write_byte(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    *distance = distance_mm;
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused

    int distance;
    if (vl53l0x_read_distance(&distance) == 0) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error reading distance in interrupt handler\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    terminate = 1;
    printf("Received signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (vl53l0x_init() != 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge detection
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop (wait for termination signal)
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("VL53L0X distance measurement stopped.\n");

    return 0;
}

