int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ch101_address;
    char *log_file_name;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int addr);
int trigger_measurement(int handle);
int read_distance(int handle, unsigned short *distance);
char* get_timestamp();
int log_distance(const char *timestamp, unsigned short distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Trigger a measurement
int trigger_measurement(int handle) {
    int result = i2cWriteByteData(handle, MEASURE_CMD, 0x00); // No data to write, just the command
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int handle, unsigned short *distance) {
    char buffer[2];
    int result = i2cReadI2CBlockData(handle, DISTANCE_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

