int log_distance(const char *timestamp, unsigned short distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

