void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .i2c_bus = I2C_BUS,
        .ch101_address = CH101_ADDR,
        .log_file_name = LOG_FILE,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(config.i2c_bus, config.ch101_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        unsigned short distance;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        gpioDelay(50); // 50 ms

        // Read distance
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log distance
        if (log_distance(timestamp, distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        // Print distance to stdout
        printf("%s, %u\n", timestamp, distance);

        // Wait before next sample
        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

