#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define RETRY_COUNT 3
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient_light);
int log_data(FILE *log_file, uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient_light) {
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, PROXIMITY_REG);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REG);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    if (retries == RETRY_COUNT) {
