#define WHO_AM_I_REG 0x00
#define DISTANCE_REG 0x01 // Example register, adjust based on datasheet
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

// Global variables
int i2c_handle;
int distance_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_distance(int *distance);
int log_data(int distance);
void control_led(int distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int led_pin;
    int distance_threshold;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID (WHO_AM_I register)
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Replace 0xXX with the expected WHO_AM_I value for ICU-20201
    if (who_am_i != 0xXX) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    printf("I2C initialized successfully.\n");
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    printf("GPIO initialized successfully.\n");
    return 0;
}

// Function to read distance from the sensor
int read_distance(int *distance) {
    int raw_distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (raw_distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", raw_distance);
        return -1;
    }

    // Convert raw data to millimeters (adjust based on sensor datasheet)
    *distance = raw_distance / 10; // Example conversion

    return 0;
}

