int log_data(int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to control the LED based on distance
void control_led(int distance) {
    if (distance < distance_threshold) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Distance threshold set to: %d mm\n", distance_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

