        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(const uint8_t *command, int command_length) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, command_length);
    if (result != command_length) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read a response from the sensor
int read_response(uint8_t *response, int response_length) {
    int result = i2cReadDevice(i2c_handle, (char *)response, response_length);
    if (result != response_length) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate the response frame
int validate_response(const uint8_t *response, int response_length) {
    if (response_length != RESPONSE_FRAME_LENGTH) {
        fprintf(stderr, "Invalid response length: %d\n", response_length);
        return -1;
    }

    if (response[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X\n", response[0]);
        return -1;
    }

    return 0;
}

// Extract the distance from the response frame
uint16_t extract_distance(const uint8_t *response) {
    uint16_t distance = (response[11] << 8) | response[12];
    return distance;
}

// Calculate the average distance
float calculate_average_distance(const uint16_t *distances, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)(sum / num_samples);
}

// Log an intrusion event
int log_intrusion(float average_distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t response[RESPONSE_FRAME_LENGTH];
    uint16_t distances[10];
    int num_samples = 10;

    // Main loop
    while (!terminate) {
        // Sample the sensor multiple times
        for (int i = 0; i < num_samples; i++) {
            // Send the command
            if (send_command(command_frame, COMMAND_FRAME_LENGTH) != 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                gpioDelay(100000); // Wait 100ms before retrying
                i--; // Retry the current sample
                continue;
            }

            // Wait for a short period
            gpioDelay(10000); // 10 ms

            // Read the response
            if (read_response(response, RESPONSE_FRAME_LENGTH) != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                gpioDelay(100000); // Wait 100ms before retrying
                i--; // Retry the current sample
                continue;
            }

            // Validate the response
            if (validate_response(response, RESPONSE_FRAME_LENGTH) != 0) {
                fprintf(stderr, "Error validating response, retrying...\n");
                gpioDelay(100000); // Wait 100ms before retrying
                i--; // Retry the current sample
                continue;
            }

            // Extract the distance
            distances[i] = extract_distance(response);
        }

        // Calculate the average distance
        float average_distance = calculate_average_distance(distances, num_samples);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        }

        // Delay before the next sample
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

