#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x4C

// Define the distance register address
#define DISTANCE_REGISTER 0x00

// Define the millimeters per count conversion factor
#define MM_PER_COUNT 0.125

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read distance data from the MLX75030 sensor
int read_distance(int fd) {
    uint8_t buffer[2];
    int16_t distance;

    // Read two bytes from the distance register
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading distance data");
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    distance = (buffer[1] << 8) | buffer[0];

    return distance;
}

// Function to convert raw distance data to millimeters
float convert_to_mm(int16_t raw_distance) {
    return (float)raw_distance * MM_PER_COUNT;
}

// Function to log the distance data with a timestamp
void log_distance(float distance) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s.%06ld Distance: %.2f mm\n", timestamp, tv.tv_usec, distance);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop to read and log distance data
    while (1) {
        int16_t raw_distance;
        float distance_mm;

        // Read the distance from the sensor
        raw_distance = read_distance(i2c_fd);
        if (raw_distance < 0) {
            fprintf(stderr, "Failed to read distance. Retrying in 500 ms.\n");
            struct timespec sleep_time = {0, 500000000}; // 500 ms
            nanosleep(&sleep_time, NULL);
            continue; // Retry the loop
        }

        // Convert the raw distance to millimeters
        distance_mm = convert_to_mm(raw_distance);

        // Log the distance data
        log_distance(distance_mm);

        // Wait for 500 milliseconds
        struct timespec sleep_time = {0, 500000000}; // 500 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

