#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MAX_DISTANCE 400.0   // cm
#define TIMEOUT_US 200000     // 200ms timeout in microseconds

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        echo_end_tick = tick;
        if (echo_start_tick != 0) {
            int pulse_width_us = echo_end_tick - echo_start_tick;
            if (pulse_width_us > 0 && pulse_width_us < TIMEOUT_US) {
                echo_valid = 1; // Set validity flag
            } else {
                echo_valid = 0; // Invalid pulse width
                echo_start_tick = 0; // Reset start tick
                echo_end_tick = 0; // Reset end tick
            }
        }
    }
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width_us) {
    if (pulse_width_us <= 0) {
        return -1.0; // Indicate error
    }
    double distance = (pulse_width_us * SPEED_OF_SOUND) / 2.0;
    if (distance > MAX_DISTANCE) {
        return -1.0; // Indicate out-of-range
    }
    return distance;
}

// Function to log distance with timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance >= 0) {
        printf("%s Distance: %.2f cm\n", timestamp, distance);
    } else {
        printf("%s Error: Invalid distance reading\n", timestamp);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor();
        gpioDelay(1000000); // Wait 1 second

        if (echo_valid) {
            int pulse_width_us = echo_end_tick - echo_start_tick;
            double distance = calculate_distance(pulse_width_us);
            log_distance(distance);
        } else {
            log_distance(-1.0); // Log error
        }

        echo_start_tick = 0;
        echo_end_tick = 0;
        echo_valid = 0;
    }

    // This point will not be reached unless there's an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

