#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0 // meters
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (8 + 128) // 8 bytes header + 128 bytes data
#define MAGIC_WORD_SIZE 8

// Magic Word
const unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for radar data
typedef struct {
    unsigned char header[MAGIC_WORD_SIZE];
    short range_profile[NUM_RANGE_BINS];
} radar_data_t;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_radar_data(int fd, radar_data_t *data);
float calculate_distance(const short *range_profile, int num_bins, float range_resolution);
int detect_intrusion(float distance, float threshold);
void trigger_alert(int gpio_pin, int duration_ms);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Function to initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read radar data
int read_radar_data(int fd, radar_data_t *data) {
    ssize_t bytes_read = read(fd, data, DATA_FRAME_SIZE);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != DATA_FRAME_SIZE) {
        fprintf(stderr, "Incomplete data frame received (%zd bytes)\n", bytes_read);
        return -1;
    }

    // Validate magic word
    if (memcmp(data->header, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Invalid magic word received\n");
        return -1;
    }

    return 0;
}

// Function to calculate distance from range profile
float calculate_distance(const short *range_profile, int num_bins, float range_resolution) {
    // Find the minimum range bin
    int min_index = 0;
    for (int i = 1; i < num_bins; i++) {
        if (range_profile[i] < range_profile[min_index]) {
            min_index = i;
        }
    }

    // Calculate the distance
    float distance = (float)min_index * range_resolution;
    return distance;
}

// Function to detect intrusion
int detect_intrusion(float distance, float threshold) {
    return (distance <= threshold) ? 1 : 0;
}

// Function to trigger alert (LED)
void trigger_alert(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Function to log intrusion
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (m)\n");
    }

    radar_data_t radar_data;

    fprintf(stderr, "Intrusion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read radar data
        if (read_radar_data(uart_fd, &radar_data) == 0) {
            // Calculate distance
            float distance = calculate_distance(radar_data.range_profile, NUM_RANGE_BINS, RANGE_RESOLUTION);

            // Detect intrusion
            if (detect_intrusion(distance, RANGE_THRESHOLD)) {
                fprintf(stderr, "Intrusion detected! Distance: %.3f meters\n", distance);

                // Trigger alert
                trigger_alert(GPIO_LED, 2000); // 2 seconds

                // Log intrusion
                log_intrusion(distance);
            }
        } else {
            fprintf(stderr, "Error reading radar data. Retrying...\n");
            // Attempt to re-initialize UART
            close(uart_fd);
            uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
            if (uart_fd == -1) {
                fprintf(stderr, "Failed to re-initialize UART. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

