                deactivate_buzzer();
                log_event("Obstacle removed");
                last_state = 1;
            }
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    deactivate_buzzer();
    fclose(log_file);
    gpioTerminate();

    return 0;
