int read_distance(int *distance) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

