#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_distance(int *distance);
float map_distance_to_frequency(int distance);
void blink_led(float frequency);
void log_data(int distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int led_gpio;
    int distance_register;
} sensor_config_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit distance value
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Map distance to blink frequency
float map_distance_to_frequency(int distance) {
    if (distance < 50) {
        return 10.0; // 50 mm maps to 10 Hz
    } else if (distance > 500) {
        return 1.0; // 500 mm maps to 1 Hz
    } else {
        // Linear mapping between 50 and 500 mm
        return 10.0 - (float)(distance - 50) / 450.0 * 9.0; // 500 - 50 = 450
    }
}

// Blink the LED
void blink_led(float frequency) {
    if (frequency <= 0) {
        gpioWrite(LED_GPIO, 0); // Turn off LED
        return;
    }

    // Calculate the half-period in microseconds
    int half_period_us = (int)(1000000.0 / frequency / 2.0);

    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(half_period_us); // Delay for half the period
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(half_period_us); // Delay for half the period
}

// Log data to stdout
void log_data(int distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int distance;
    float frequency;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Map distance to frequency
            frequency = map_distance_to_frequency(distance);

            // Blink LED
            blink_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay for the sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

