#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define POLLING_INTERVAL_MS 10

// Structure to hold sensor state
typedef struct {
    int gpio;
    int last_state;
    int debounce_count;
} sensor_t;

// Global variables
FILE *log_file = NULL;
sensor_t sensor1, sensor2;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_event(int sensor_id, const char *event_type);
void debounce(sensor_t *sensor);
void signal_handler(int signal);
