// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    sensor1.gpio = SENSOR_1_GPIO;
    sensor1.last_state = gpioRead(SENSOR_1_GPIO);
    sensor1.debounce_count = 0;

    sensor2.gpio = SENSOR_2_GPIO;
    sensor2.last_state = gpioRead(SENSOR_2_GPIO);
    sensor2.debounce_count = 0;

    return 0;
}

// Read sensor value with debouncing
void debounce(sensor_t *sensor) {
    int current_state = gpioRead(sensor->gpio);

    if (current_state != sensor->last_state) {
        sensor->debounce_count++;
        if (sensor->debounce_count >= (DEBOUNCE_DELAY_MS / POLLING_INTERVAL_MS)) {
            sensor->last_state = current_state;
            sensor->debounce_count = 0;

            if (sensor->gpio == SENSOR_1_GPIO) {
                if (current_state == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
            } else {
                if (current_state == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
            }
        }
    } else {
        sensor->debounce_count = 0;
    }
}

