// Define sensor-specific constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define DATA_READY_BIT 0x01
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int meas_trigger_reg;
    int meas_status_reg;
    int dist_high_reg;
    int dist_low_reg;
    int data_ready_bit;
    int max_retries;
    int retry_delay_ms;
} sensor_config_t;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int trigger_measurement(int fd);
int read_distance(int fd, uint16_t *distance);
int log_data(FILE *fp, uint16_t distance);
void signal_handler(int signal);
int initialize_sensor(int fd);

// Helper function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Function to read a single byte from an I2C register
int i2c_read_register(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %s (errno: %d). Retry %d/%d\n", reg, strerror(errno), errno, retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s (errno: %d). Retry %d/%d\n", reg, value, strerror(errno), errno, retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }
    fprintf(stderr, "Failed to write register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to trigger a single range measurement
int trigger_measurement(int fd) {
    return i2c_write_register(fd, MEAS_TRIGGER_REG, 0x01);
}

// Function to read the distance from the sensor
int read_distance(int fd, uint16_t *distance) {
    int high_byte, low_byte;

    high_byte = i2c_read_register(fd, DIST_HIGH_REG);
    if (high_byte < 0) return -1;

    low_byte = i2c_read_register(fd, DIST_LOW_REG);
    if (low_byte < 0) return -1;

    *distance = (uint16_t)((high_byte << 8) | low_byte);
    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, uint16_t distance) {
    char *timestamp = get_iso8601_timestamp();
    if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(int fd) {
    // Add any initialization steps specific to the CH-101 here
    // For example, setting configuration registers or resetting the sensor
    // This is a placeholder, replace with actual initialization code
    printf("Initializing sensor...\n");
    return 0; // Indicate success
}

int main() {
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = I2C_ADDRESS,
        .meas_trigger_reg = MEAS_TRIGGER_REG,
        .meas_status_reg = MEAS_STATUS_REG,
        .dist_high_reg = DIST_HIGH_REG,
        .dist_low_reg = DIST_LOW_REG,
        .data_ready_bit = DATA_READY_BIT,
        .max_retries = MAX_RETRIES,
        .retry_delay_ms = RETRY_DELAY_MS
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(config.i2c_bus, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s (errno: %d)\n", strerror(errno), errno);
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, config.i2c_address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        uint16_t distance;
        int status;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue; // Skip to the next iteration
        }

        // Wait for data ready
        int timeout_ms = 50;
        while (timeout_ms > 0) {
            status = i2c_read_register(i2c_fd, config.meas_status_reg);
            if (status < 0) {
                fprintf(stderr, "Failed to read measurement status.\n");
                break; // Exit the inner loop on error
            }

            if (status & config.data_ready_bit) {
                break; // Data is ready
            }

            usleep(1000); // Wait 1 ms
            timeout_ms--;
        }

        if (timeout_ms == 0) {
            fprintf(stderr, "Timeout waiting for data ready.\n");
            continue; // Skip to the next iteration
        }

        // Read distance
        if (read_distance(i2c_fd, &distance) != 0) {
            fprintf(stderr, "Failed to read distance.\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(log_file, distance) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait 500 ms
        usleep(500000); // Convert ms to microseconds
    }

    // Clean up
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

