        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REGISTER, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit distance value
            int distance = (buf[0] << 8) | buf[1];
            return distance;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
