#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// I2C bus number
#define I2C_BUS 1

// File descriptor for I2C communication
int i2c_fd;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the VL53L4CX sensor
int init_vl53l4cx() {
    // Soft reset
    if (i2cWriteByteData(i2c_fd, 0x7FFF, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Start ranging
    if (i2cWriteByteData(i2c_fd, 0x0009, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

// Function to read distance data from the VL53L4CX sensor
int read_distance(int *distance) {
    // Poll interrupt status register
    int status = i2cReadByteData(i2c_fd, 0x0046);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    // Check if new data is available (bit 0 is set)
    if (status & 0x01) {
        // Read distance data (high byte and low byte)
        int high_byte = i2cReadByteData(i2c_fd, 0x0096);
        int low_byte = i2cReadByteData(i2c_fd, 0x0097);

        if (high_byte < 0 || low_byte < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
            return -1;
        }

        // Combine high and low bytes to get the distance
        *distance = (high_byte << 8) | low_byte;

        return 0; // Success
    } else {
        return -2; // No new data available
    }
}

// Function to log the distance data with a timestamp
void log_distance(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Format the timestamp
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    // Print the timestamp and distance
    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L4CX sensor
    if (init_vl53l4cx() < 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        // Read distance data
        int result = read_distance(&distance);

        if (result == 0) {
            // Log the distance data
            log_distance(distance);
        } else if (result == -2) {
            // No new data available, skip logging
        } else {
