    if (i2cWriteByteData(i2c_fd, 0x7FFF, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Start ranging
    if (i2cWriteByteData(i2c_fd, 0x0009, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

// Function to read distance data from the VL53L4CX sensor
int read_distance(int *distance) {
    // Poll interrupt status register
    int status = i2cReadByteData(i2c_fd, 0x0046);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    // Check if new data is available (bit 0 is set)
    if (status & 0x01) {
        // Read distance data (high byte and low byte)
        int high_byte = i2cReadByteData(i2c_fd, 0x0096);
        int low_byte = i2cReadByteData(i2c_fd, 0x0097);

        if (high_byte < 0 || low_byte < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
            return -1;
        }

        // Combine high and low bytes to get the distance
        *distance = (high_byte << 8) | low_byte;

        return 0; // Success
    } else {
        return -2; // No new data available
    }
}

