#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define RANGE_STATUS_OK 0

// VL53L1X register addresses
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, SOFT_RESET, 0x01);
    if (status != 0) {
        fprintf(stderr, "Error: Soft reset failed (0x%02X)\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Set I2C address (optional, but good practice)
    status = i2cWriteByteData(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR);
    if (status != 0) {
        fprintf(stderr, "Error: Failed to set I2C address (0x%02X)\n", status);
        return -1;
    }

    // Start continuous ranging mode
    status = i2cWriteByteData(i2c_handle, SYSTEM__MODE_START, 0x07); // Continuous ranging mode
    if (status != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging (0x%02X)\n", status);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    int status;
    uint8_t data[2];

    // Read distance data (2 bytes)
    status = i2cReadI2CBlockData(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, (char *)data, 2);
    if (status != 2) {
        fprintf(stderr, "Error: Failed to read distance data (0x%02X)\n", status);
        return -1;
    }

    // Combine the two bytes to form the distance
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main() {
    int distance;
    int status;
    time_t last_i2c_error_time = 0;
    const int i2c_error_threshold = 5; // seconds

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (0x%02X)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("VL53L1X sensor initialized. Monitoring distance...\n");

    // Main loop
    while (!terminate) {
        // Read distance
        status = read_distance(&distance);
        if (status == 0) {
            // Check for valid range status
            if (distance < 0 || distance > 8191) {
                fprintf(stderr, "Error: Invalid distance reading: %d\n", distance);
                continue; // Skip to the next iteration
            }

            // Control buzzer based on distance
            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Activate buzzer
            } else {
                control_buzzer(0); // Deactivate buzzer
            }

            // Print distance
            printf("Distance: %d mm\n", distance);

            last_i2c_error_time = 0; // Reset error counter
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
            time_t current_time = time(NULL);
            if (difftime(current_time, last_i2c_error_time) >= i2c_error_threshold) {
                fprintf(stderr, "Error: I2C error threshold reached. Re-initializing sensor...\n");
                i2cClose(i2c_handle);
                gpioDelay(100000); // Wait 100ms before re-opening
                i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Could not re-open I2C bus (0x%02X)\n", i2c_handle);
                    terminate = 1; // Exit loop if re-initialization fails
                } else {
                    if (init_vl53l1x() != 0) {
                        fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
                        terminate = 1; // Exit loop if re-initialization fails
                    } else {
                        last_i2c_error_time = 0; // Reset error counter after successful re-initialization
                    }
                }
            } else {
                last_i2c_error_time = current_time;
            }
        }

        gpioDelay(500000); // Wait 500ms
    }

    // Clean up
    control_buzzer(0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

