#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50 ms)
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_PULSE_WIDTH 1000  // Minimum pulse width for servo (us)
#define MAX_PULSE_WIDTH 2000  // Maximum pulse width for servo (us)
#define LOG_INTERVAL_MS 200   // Logging interval in milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long get_pulse_width();
float calculate_distance(long long pulse_width);
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void log_data(float distance, int angle);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float distance;
    int angle;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioWrite(SERVO_PIN, 0);    // Ensure servo is stopped initially

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long long get_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }

    float time_taken = (float)pulse_width / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to map the distance to a servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_PULSE_WIDTH;
    } else if (distance > MAX_DISTANCE) {
        return MAX_PULSE_WIDTH;
    } else {
        // Linear mapping
        float angle_range = MAX_PULSE_WIDTH - MIN_PULSE_WIDTH;
        float distance_range = MAX_DISTANCE - MIN_DISTANCE;
        float angle = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (angle_range / distance_range);
        return (int)angle;
    }
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

// Function to log the data to a file
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d us\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_servo_angle(0); // Stop the servo
    gpioTerminate();     // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long long pulse_width = get_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance > 0) {
            int angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(LOG_INTERVAL_MS); // Delay for logging interval
    }

    // Cleanup and exit
    cleanup();
    printf("Parking assist system stopped.\n");
    return 0;
}

