float calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }

    float time_taken = (float)pulse_width / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to map the distance to a servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_PULSE_WIDTH;
    } else if (distance > MAX_DISTANCE) {
        return MAX_PULSE_WIDTH;
    } else {
        // Linear mapping
        float angle_range = MAX_PULSE_WIDTH - MIN_PULSE_WIDTH;
        float distance_range = MAX_DISTANCE - MIN_DISTANCE;
        float angle = MIN_PULSE_WIDTH + (distance - MIN_DISTANCE) * (angle_range / distance_range);
        return (int)angle;
    }
}

// Function to set the servo angle
void set_servo_angle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

// Function to log the data to a file
void log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d us\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_servo_angle(0); // Stop the servo
    gpioTerminate();     // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long long pulse_width = get_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance > 0) {
            int angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(LOG_INTERVAL_MS); // Delay for logging interval
    }

    // Cleanup and exit
    cleanup();
    printf("Parking assist system stopped.\n");
    return 0;
}

