#define DISTANCE_REG_LOW 0x0097
#define MODEL_ID_REG 0x010F
#define MODEL_ID_EXPECTED 0xEA
#define RESET_REG 0x0000
#define START_RANGING_REG 0x0080

// Message queue structure
typedef struct {
    long mtype;
    int distance;
} message_t;

// Global variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

