    terminate = 1;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;
    uint8_t model_id;

    // Check sensor presence by reading model ID
    status = i2cReadI2CBlockData(i2c_handle, MODEL_ID_REG, (char *)&model_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }

    if (model_id != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X)\n", model_id, MODEL_ID_EXPECTED);
        return -1;
    }

    printf("VL53L1X sensor found with model ID: 0x%02X\n", model_id);

    // Software reset
    status = i2cWriteByteData(i2c_handle, RESET_REG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command (0x00): %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    status = i2cWriteByteData(i2c_handle, RESET_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command (0x01): %d\n", status);
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    // Configure timing budget
    uint8_t timing_budget = (uint8_t)(TIMING_BUDGET_MS * 1000 / 1000); // Convert ms to us
    status = i2cWriteByteData(i2c_handle, 0x0081, timing_budget); // Example register, adjust as needed
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int status;
    uint8_t data_ready;
    uint8_t distance_high, distance_low;
    int distance;

    // Check data ready bit
    status = i2cReadI2CBlockData(i2c_handle, DATA_READY_REG, (char *)&data_ready, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading data ready bit: %d\n", status);
        return -1;
    }

    if (!(data_ready & 0x01)) {
        // Data not ready yet
        return -1;
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_HIGH, (char *)&distance_high, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", status);
        return -1;
    }

    status = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG_LOW, (char *)&distance_low, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", status);
        return -1;
    }

    distance = (distance_high << 8) | distance_low;

    return distance;
}

