    status = i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        msgctl(msg_queue_id, IPC_RMID, NULL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

