#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile int timeout = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
float calculateDistance(uint32_t pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger HIGH
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger LOW
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo has started
        timeout = 0; // Reset timeout flag
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate that echo has ended
    }
}

// Function to calculate distance from pulse width
float calculateDistance(uint32_t pulse_width) {
    // Handle tick wraparound
    if (end_tick < start_tick) {
        pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
    } else {
        pulse_width = end_tick - start_tick;
    }

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000 for microseconds, then by 2 for one-way distance

    return distance;
}

// Function to control the buzzer based on distance
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer ON
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer OFF
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        triggerSensor(); // Trigger the sensor

        // Wait for echo or timeout
        int count = 0;
        while (!echo_received && !timeout && count < 100) {
            gpioDelay(1000); // Check every 1 ms
            count++;
            if (count >= 100) {
                timeout = 1;
            }
        }

        if (timeout) {
            fprintf(stderr, "Timeout: No echo received within %d us\n", TIMEOUT_US);
        } else {
            // Calculate distance
            float distance = calculateDistance(end_tick - start_tick);

            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);

                // Control buzzer
                controlBuzzer(distance);
            } else {
                fprintf(stderr, "Invalid reading: Distance out of range (%.2f cm)\n", distance);
            }
        }

        gpioDelay(100000); // Wait 100 ms
    }

    return 0;
}

