#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 60000       // 60 ms
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000

// Global variables
static volatile int rising_edge_tick = 0;
static volatile int falling_edge_tick = 0;
static volatile int pulse_width = 0;
static volatile int valid_reading = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
void log_data(float distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int rising_edge;
    int falling_edge;
    int pulse_width;
    int valid_reading;
} sensor_data_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_edge_tick = tick;
    } else if (level == 0) {
        falling_edge_tick = tick;
        pulse_width = falling_edge_tick - rising_edge_tick;

        // Handle tick wraparound
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Add 2^32 to get the correct pulse width
        }

        valid_reading = 1;
    }
}

// Calculate distance in centimeters
float calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Log data to file
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(stdout, "%s, Distance: %.2f cm\n", timestamp, distance);
    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set alert function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        // Wait for valid reading or timeout
        int timeout_counter = 0;
        while (!valid_reading && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_counter++;
        }

        if (valid_reading) {
            // Validate pulse width
            if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
                fprintf(stderr, "Warning: Invalid pulse width: %d us\n", pulse_width);
                fprintf(log_file, "Warning: Invalid pulse width: %d us\n", pulse_width);
                fflush(log_file);
            } else {
                float distance = calculate_distance(pulse_width);
                log_data(distance);
            }
        } else {
            fprintf(stderr, "Warning: Timeout waiting for echo\n");
            fprintf(log_file, "Warning: Timeout waiting for echo\n");
            fflush(log_file);
        }

        valid_reading = 0; // Reset for next measurement
        gpioDelay(200);    // Wait 200 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

