        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%04X\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Initialize the sensor (send initialization sequence)
    for (int i = 0; i < sizeof(init_sequence); i++) {
        int result = i2cWriteByteData(i2c_handle, init_sequence[i], init_sequence[i+1]);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C during initialization: %d\n", result);
            i2cClose(i2c_handle);
            return -1;
        }
        i++; // Increment i to skip the data byte
    }

    // Start continuous ranging
    int start_ranging = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01);
    if (start_ranging < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", start_ranging);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

