int vl53l1x_read_distance(int *distance) {
    int range;

    // Read range data from the sensor
    range = i2cReadWordData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA);
    if (range < 0) {
        fprintf(stderr, "Error reading range data: %d\n", range);
