// VL53L1X initialization function
int init_vl53l1x() {
    int retries = 0;
    int status;

    // Soft reset
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01);
        if (status == 0) {
            gpioDelay(1000); // Wait 1 ms
            break;
        } else {
            log_message("Soft reset failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Soft reset failed after multiple retries.");
        return -1;
    }

    // Set I2C address (optional, but good practice)
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR);
        if (status == 0) {
            break;
        } else {
            log_message("Setting I2C address failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Setting I2C address failed after multiple retries.");
        return -1;
    }

    // Configure sensor (example configuration - adjust as needed)
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05);
        if (status == 0) {
            break;
        } else {
            log_message("Pre-range config failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Pre-range config failed after multiple retries.");
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x05);
        if (status == 0) {
            break;
        } else {
            log_message("Final range config failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Final range config failed after multiple retries.");
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01);
        if (status == 0) {
            break;
        } else {
            log_message("System sequence config failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("System sequence config failed after multiple retries.");
        return -1;
    }

    log_message("VL53L1X initialized successfully.");
    return 0;
}

// Distance reading function
int read_distance() {
    int retries = 0;
    int status;
    uint8_t data[2];
    int distance = -1; // Default to error value

    // Start measurement
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP_CONTROL, 0x01);
        if (status == 0) {
            break;
        } else {
            log_message("Start measurement failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Start measurement failed after multiple retries.");
        return -1;
    }

    // Poll for data ready
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status >= 0) {
            if (status & 0x01) {
                break; // Data ready
            } else {
                gpioDelay(10); // Wait 10 ms
                retries++;
            }
        } else {
            log_message("Polling for data ready failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Polling for data ready failed after multiple retries.");
        return -1;
    }

    // Read distance
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
        if (status == 2) {
            distance = (data[0] << 8) | data[1];
            break;
        } else {
            log_message("Reading distance failed, retrying...");
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries));
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        log_message("Reading distance failed after multiple retries.");
        return -1;
    }

    return distance;
}

// Motor control function
void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        gpioWrite(GPIO_FORWARD, 1);
        gpioWrite(GPIO_BACKWARD, 0);
        log_message("Motor: Forward");
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 1);
        log_message("Motor: Backward");
    } else {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 0);
        log_message("Motor: Stop");
    }
}

// Trigger ISR function
void trigger_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        int distance = read_distance();
        if (distance >= 0) {
            char message[64];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);
            control_motor(distance);
        } else {
            log_message("Failed to read distance.");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_message("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    // Set ISR for GPIO24
    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        log_message("Failed to set ISR for GPIO24.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_message("Program started.");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100 ms
    }

    // Cleanup
    gpioWrite(GPIO_FORWARD, 0);
    gpioWrite(GPIO_BACKWARD, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    log_message("Program terminated.");

    return 0;
}

