#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {17, 18, 27, 22}
#define NUM_ELECTRODES 12
#define POLLING_INTERVAL_MS 50

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELE0_TH 0x41
#define MPR121_ELE0_TL 0x42
#define MPR121_ELE1_TH 0x43
#define MPR121_ELE1_TL 0x44
#define MPR121_ELE2_TH 0x45
#define MPR121_ELE2_TL 0x46
#define MPR121_ELE3_TH 0x47
#define MPR121_ELE3_TL 0x48
#define MPR121_ELE4_TH 0x49
#define MPR121_ELE4_TL 0x4A
#define MPR121_ELE5_TH 0x4B
#define MPR121_ELE5_TL 0x4C
#define MPR121_ELE6_TH 0x4D
#define MPR121_ELE6_TL 0x4E
#define MPR121_ELE7_TH 0x4F
#define MPR121_ELE7_TL 0x50
#define MPR121_ELE8_TH 0x51
#define MPR121_ELE8_TL 0x52
#define MPR121_ELE9_TH 0x53
#define MPR121_ELE9_TL 0x54
#define MPR121_ELE10_TH 0x55
#define MPR121_ELE10_TL 0x56
#define MPR121_ELE11_TH 0x57
#define MPR121_ELE11_TL 0x58
#define MPR121_SOFTRESET 0x80

// Global Variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_lines[4] = {NULL, NULL, NULL, NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mpr121_init(int fd);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
void log_event(int electrode);
void signal_handler(int sig);

// I2C Read Register Function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// I2C Write Register Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// MPR121 Initialization Function
int mpr121_init(int fd) {
    // Soft Reset
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error resetting MPR121\n");
        return -1;
    }
    usleep(100000); // Wait for reset to complete

    // Verify sensor presence (read a register)
    int sensor_id = i2c_read_reg(fd, 0x00);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (sensor_id != 0x5A) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Stop Mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x00) < 0) {
        fprintf(stderr, "Error setting MPR121 to stop mode\n");
        return -1;
    }

    // Baseline Filtering
    if (i2c_write_reg(fd, MPR121_MHDR, 0x01) < 0 ||
        i2c_write_reg(fd, MPR121_NHDR, 0x01) < 0 ||
        i2c_write_reg(fd, MPR121_NCLR, 0x0E) < 0 ||
        i2c_write_reg(fd, MPR121_FDLR, 0x00) < 0) {
        fprintf(stderr, "Error setting baseline filtering\n");
        return -1;
    }

    // Auto-Configuration Thresholds
    if (i2c_write_reg(fd, MPR121_ELE0_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE0_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE1_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE1_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE2_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE2_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE3_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE3_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE4_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE4_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE5_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE5_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE6_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE6_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE7_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE7_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE8_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE8_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE9_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE9_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE10_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE10_TL, 0x05) < 0 ||
        i2c_write_reg(fd, MPR121_ELE11_TH, 0x0B) < 0 ||
        i2c_write_reg(fd, MPR121_ELE11_TL, 0x05) < 0) {
        fprintf(stderr, "Error setting auto-configuration thresholds\n");
        return -1;
    }

    // Enable all 12 electrodes in run mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x0C) < 0) {
        fprintf(stderr, "Error enabling electrodes\n");
        return -1;
    }

    return 0;
}

// GPIO Export Function
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO Unexport Function
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO Set Direction Function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO Write Function
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) != 1) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Log Event Function
void log_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Electrode %d touched\n", timestamp, electrode);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

int main() {
    int pins[] = GPIO_PINS;
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int touch_status_l, touch_status_h;
    int electrode;
    int i;

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Export GPIO pins and set direction to output
    for (i = 0; i < num_pins; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, pins[i]);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            // Unexport already exported pins before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }

        if (gpiod_line_request_output(gpio_lines[i], "mpr121", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", pins[i], strerror(errno));
            // Release already requested lines before exiting
            for (int j = 0; j <= i; j++) {
                if (gpio_lines[j]) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }
    }

    // Open log file
    log_file = fopen("mpr121_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Release GPIO lines before exiting
        for (i = 0; i < num_pins; i++) {
            if (gpio_lines[i]) {
                gpiod_line_release(gpio_lines[i]);
            }
        }
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "MPR121 Proximity Sensor Interface started\n");

    // Main loop
    while (!terminate) {
        // Read touch status from MPR121
        touch_status_l = i2c_read_reg(i2c_fd, MPR121_TOUCHSTATUS_L);
        touch_status_h = i2c_read_reg(i2c_fd, MPR121_TOUCHSTATUS_H);

        if (touch_status_l < 0 || touch_status_h < 0) {
            fprintf(stderr, "Error reading touch status\n");
            break; // Exit loop on error
        }

        // Check each electrode for touch
        for (electrode = 0; electrode < NUM_ELECTRODES; electrode++) {
            if ((touch_status_l >> electrode) & 1) {
                // Electrode is touched
                log_event(electrode);

                // Set GPIO output based on electrode number
                for (i = 0; i < num_pins; i++) {
                    if (electrode == pins[i]) {
                        if (gpio_write(pins[i], 1) < 0) {
                            fprintf(stderr, "Error writing to GPIO %d\n", pins[i]);
                            break; // Exit loop on error
                        }
                    } else {
                        if (gpio_write(pins[i], 0) < 0) {
                            fprintf(stderr, "Error writing to GPIO %d\n", pins[i]);
                            break; // Exit loop on error
                        }
                    }
                }
            } else {
                // Electrode is not touched
                for (i = 0; i < num_pins; i++) {
                    if (gpio_write(pins[i], 0) < 0) {
                        fprintf(stderr, "Error writing to GPIO %d\n", pins[i]);
                        break; // Exit loop on error
                    }
                }
            }
        }

        usleep(POLLING_INTERVAL_US); // Poll every 100ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");

    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Release GPIO lines
    for (i = 0; i < num_pins; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
        }
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "MPR121 Proximity Sensor Interface stopped\n");

    return 0;
}

