#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FFI_CONFIG 0x5B
#define MPR121_SFI_CONFIG 0x5C
#define MPR121_ESI_CONFIG 0x5D
#define MPR121_AFE_CONFIG 0x5D
#define MPR121_BASELINE_FILTER_CONFIG 0x5F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status();
void control_led(int state);
void log_event();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    // Check device ID
    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("MPR121 device ID: 0x%02X\n", device_id);

    // Configure electrode 0 for proximity detection
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to ELECTRODE_CONFIG register\n");
        return -1;
    }

    // Set touch and release thresholds for electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0, TOUCH_THRESHOLD) < 0) {
        fprintf(stderr, "Error writing to TOUCHTH_0 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Error writing to RELEASETH_0 register\n");
        return -1;
    }

    // Configure FFI, SFI, ESI, AFE, and baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_FFI_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to FFI_CONFIG register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_SFI_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to SFI_CONFIG register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ESI_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ESI_CONFIG register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_AFE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to AFE_CONFIG register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_FILTER_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to BASELINE_FILTER_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Read the touch status from the MPR121
int read_touch_status() {
    int touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    int touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Log the proximity event to a file
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Proximity detected on electrode 0\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            printf("Proximity detected on electrode 0\n");
            control_led(1); // Turn on LED
            log_event();    // Log the event
            gpioDelay(1000); // Wait for 1 second
            control_led(0); // Turn off LED
        }

        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

