#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define TIMEOUT_US 30000       // Timeout in microseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long long getEchoPulseWidth();
double calculateDistance(long long pulse_width);
void logDistance(double distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(5);              // Wait 5 microseconds
    gpioWrite(TRIGGER_PIN, 1); // Send a 10 microsecond pulse
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
}

// Function to measure the echo pulse width
long long getEchoPulseWidth() {
    long long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high with a timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low with a timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculateDistance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate an error
    }

    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to get cm

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
        return -1.0; // Indicate an error
    }

    return distance;
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        triggerSensor();
        long long pulse_width = getEchoPulseWidth();
        double distance = calculateDistance(pulse_width);

        if (distance > 0) {
            logDistance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

