#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define CONTINUOUS_MODE 0x00
#define NO_TIMEOUT 0x00
#define START_RANGING 0x01
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int configure_sensor();
int read_distance(int *distance);
int read_status(int *status);
void log_data(int distance, int status);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1); // Enable sensor
    gpioDelay(100); // Wait for sensor to stabilise

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the VL53L1X sensor
int configure_sensor() {
    // Continuous mode
    if (i2cWriteByteData(i2c_handle, 0x0018, CONTINUOUS_MODE) < 0) {
        syslog(LOG_ERR, "Failed to write continuous mode");
        return -1;
    }

