#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define RANGE_MODE_SHORT 0x00
#define RANGE_START 0x01
#define MODEL_ID_REG 0x010F
#define SHORT_RANGE_REG 0x0021
#define RANGE_START_REG 0x0015
#define DISTANCE_REG_HIGH 0x0089
#define DISTANCE_REG_LOW 0x008A

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance();
void control_gate(int open);
void log_data(int distance, int gate_state, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    int status;
    uint8_t model_id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, MODEL_ID_REG);
    if (status < 0) {
        log_data(-1, -1, "Error reading model ID");
        return -1;
    }
    model_id = (uint8_t)status;
    if (model_id != 0xEA) {
        log_data(-1, -1, "Incorrect model ID");
        return -1;
    }

    // Set short range mode
    status = i2cWriteByteData(i2c_handle, SHORT_RANGE_REG, RANGE_MODE_SHORT);
    if (status < 0) {
        log_data(-1, -1, "Error setting short range mode");
        return -1;
    }

    // Start ranging
    status = i2cWriteByteData(i2c_handle, RANGE_START_REG, RANGE_START);
    if (status < 0) {
        log_data(-1, -1, "Error starting ranging");
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    int status;
    uint16_t distance_raw;
    int distance_cm;

    // Read distance registers
    status = i2cReadWordData(i2c_handle, DISTANCE_REG_HIGH);
    if (status < 0) {
        log_data(-1, -1, "Error reading distance high byte");
        return -1;
    }
    distance_raw = (uint16_t)status;

    // Convert mm to cm
    distance_cm = distance_raw / 10;

    return distance_cm;
}

// Control the gate actuator
void control_gate(int open) {
    gpioWrite(GATE_GPIO, open);
}

// Log data to file
void log_data(int distance, int gate_state, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Distance: %d cm, Gate: %s, Message: %s\n",
            timestamp, distance, gate_state ? "Open" : "Closed", message);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int distance;
    int gate_state = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_data(-1, -1, "Error opening I2C connection");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        log_data(-1, -1, "Sensor initialisation failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initially close the gate

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();
        if (distance >= 0) {
            if (distance < DISTANCE_THRESHOLD && gate_state == 0) {
                control_gate(1);
                gate_state = 1;
                log_data(distance, gate_state, "Gate opened");
            } else if (distance >= DISTANCE_THRESHOLD && gate_state == 1) {
                control_gate(0);
                gate_state = 0;
                log_data(distance, gate_state, "Gate closed");
            } else {
                log_data(distance, gate_state, "Distance within threshold");
            }
        } else {
            log_data(-1, -1, "Error reading distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

