#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout
#define NUM_SAMPLES 5
#define DEFAULT_ANGLE 90.0

// Global variables
static volatile int pulse_width = 0;
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_valid = 0;
static volatile sig_atomic_t terminate = 0;

// Moving average filter
static float distance_buffer[NUM_SAMPLES];
static int buffer_index = 0;
static float distance_sum = 0.0;

// File pointer for logging
static FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
float calculateDistance(int pulse_width);
float applyMovingAverage(float new_distance);
float mapDistanceToAngle(float distance);
int setServoAngle(float angle);
void logData(float distance, float angle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        pulse_valid = 0; // Reset validity flag on rising edge
    } else if (level == 0) {
        pulse_end = tick;

        // Check for wrap-around
        if (pulse_end < pulse_start) {
            pulse_width = pulse_end + (0xFFFFFFFF - pulse_start) + 1; // Calculate pulse width with wrap-around
        } else {
            pulse_width = pulse_end - pulse_start;
        }

        pulse_valid = 1; // Set validity flag on falling edge
    }
}

// Function to calculate distance from pulse width
float calculateDistance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Invalid pulse width
    }

    float time_taken = (float)pulse_width / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Out of range
    }

    return distance;
}

// Function to apply a moving average filter
float applyMovingAverage(float new_distance) {
    distance_sum -= distance_buffer[buffer_index];
    distance_buffer[buffer_index] = new_distance;
    distance_sum += new_distance;
    buffer_index = (buffer_index + 1) % NUM_SAMPLES;

    return distance_sum / NUM_SAMPLES;
}

// Function to map distance to servo angle (logarithmic mapping)
float mapDistanceToAngle(float distance) {
    // Logarithmic mapping: angle = k * log(distance) + offset
    // Adjust k and offset to fit the desired range (0-180 degrees)
    float k = 100.0;  // Adjust this value
    float offset = -20.0; // Adjust this value

    // Ensure distance is within the valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    float angle = k * log10(distance) + offset;

    // Clamp the angle to the valid range
    if (angle < 0.0) {
        angle = 0.0;
    } else if (angle > 180.0) {
        angle = 180.0;
    }

    return angle;
}

// Function to set the servo angle
int setServoAngle(float angle) {
    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(500.0 + (angle / 180.0) * 2000.0);

    // Set the servo pulse width
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to a CSV file
void logData(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Open the log file
    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");

    // Initialize moving average filter
    for (int i = 0; i < NUM_SAMPLES; i++) {
        distance_buffer[i] = 0.0;
    }

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    printf("Ultrasonic distance measurement and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Wait for the echo pulse with a timeout
        int timeout_counter = 0;
        while (!pulse_valid && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every 1 us
            timeout_counter++;
        }

        if (!pulse_valid) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            logData(-1.0, DEFAULT_ANGLE);
            setServoAngle(DEFAULT_ANGLE);
        } else {
            // Calculate the distance
            float distance = calculateDistance(pulse_width);

            if (distance < 0) {
                fprintf(stderr, "Invalid distance reading\n");
                logData(-1.0, DEFAULT_ANGLE);
