// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer distance_buffer;

// Function prototypes
int init_vl53l1x();
int read_distance();
void add_to_buffer(CircularBuffer *cb, int value);
int get_latest_distance(CircularBuffer *cb);
void control_led(int state);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get latest distance from circular buffer
int get_latest_distance(CircularBuffer *cb) {
    if (cb->count == 0) {
        return -1; // Indicate empty buffer
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Get index of last element
    return cb->buffer[index];
}

