#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Si1102 Register Addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x08
#define REG_ALS_VIS_DATA1 0x09
#define REG_PS1_DATA0 0x0A
#define REG_PS1_DATA1 0x0B
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_PS_LED21_SELECT 0x0F
#define REG_PS_ENCODING 0x10
#define REG_PS1_ADCMUX 0x11
#define REG_PS_ADC_GAIN 0x12
#define REG_PS_ADC_MISC 0x13
#define REG_PS_LED21_DRIVE 0x14
#define REG_PS_LED3_DRIVE 0x15
#define REG_PS_LED2_DRIVE 0x16
#define REG_PS_LED1_DRIVE 0x17
#define REG_PS_LED_CURRENT 0x18
#define REG_PS_FORCE 0x19
#define REG_PS_CONFIG 0x1A
#define REG_PS_ALSVIS_CONFIG 0x1B
#define REG_PS_ALSIR_CONFIG 0x1C
#define REG_PS_ALSVIS_DATA0 0x1D
#define REG_PS_ALSVIS_DATA1 0x1E
#define REG_PS_ALSIR_DATA0 0x1F
#define REG_PS_ALSIR_DATA1 0x20
#define REG_PS_ALSIR_DATA2 0x21
#define REG_PS_ALSIR_DATA3 0x22
#define REG_PS_ALSVIS_DATA2 0x23
#define REG_PS_ALSVIS_DATA3 0x24
#define REG_PS_PARAM_WR 0x25
#define REG_COMMAND 0x30
#define REG_HW_KEY 0x31

// Global Variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;
static volatile int running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
int initialize_i2c();
int initialize_sensor();
int read_proximity();
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1102 sensor
int initialize_sensor() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_PS_LED21_SELECT, 0x03) < 0) return -1; // LED current
    if (i2cWriteByteData(i2c_handle, REG_PS_ENCODING, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_PS1_ADCMUX, 0x03) < 0) return -1; // ADC Mux
    if (i2cWriteByteData(i2c_handle, REG_PS_ADC_GAIN, 0x40) < 0) return -1; // ADC Gain
    if (i2cWriteByteData(i2c_handle, REG_PS_ADC_MISC, 0x20) < 0) return -1; // ADC Misc
    if (i2cWriteByteData(i2c_handle, REG_PS_LED21_DRIVE, 0x7F) < 0) return -1; // LED Drive
    if (i2cWriteByteData(i2c_handle, REG_PS_LED3_DRIVE, 0x7F) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_PS_LED2_DRIVE, 0x7F) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_PS_LED1_DRIVE, 0x7F) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_PS_LED_CURRENT, 0x0F) < 0) return -1; // LED Current
    if (i2cWriteByteData(i2c_handle, REG_PS_CONFIG, 0x01) < 0) return -1; // PS Config
    if (i2cWriteByteData(i2c_handle, REG_PS_ALSVIS_CONFIG, 0x00) < 0) return -1; // ALS Vis Config
    if (i2cWriteByteData(i2c_handle, REG_PS_ALSIR_CONFIG, 0x00) < 0) return -1; // ALS IR Config

    // Start measurements
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x07) < 0) {
        fprintf(stderr, "Error starting measurements\n");
        return -1;
    }

    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity() {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte\n");
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, REG_PS1_DATA1);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte\n");
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity = read_proximity();
    if (proximity >= 0) {
        const char *status = (proximity <= threshold) ? "SAFE" : "ALERT";
        log_data(proximity, status);
    }
}

// Function to log data to a file
void log_data(int proximity, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

