#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define SPEAKER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms timeout in microseconds

// Global variables
volatile sig_atomic_t terminate = 0;
double previous_distance = 0.0;

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double map_distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to measure distance using HC-SR04
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return previous_distance; // Return previous distance
    }
    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return previous_distance; // Return previous distance
    }
    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
