long getPulseWidth();
float calculateDistance(long pulseWidth);
float calculateFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM output
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10); // Wait 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        startTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo high\n");
        return -1; // Indicate timeout error
    }

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        endTime = gpioTick();
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo low\n");
        return -1; // Indicate timeout error
    }

    return endTime - startTime; // Return pulse width in microseconds
}

// Function to calculate distance from pulse width
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }

    // Speed of sound in air (approx. 343 m/s)
    // Distance = (Time * Speed of Sound) / 2
    // Distance in cm = (pulseWidth * 0.0343) / 2
    return (pulseWidth * 0.0343) / 2.0;
}

