float calculateFrequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0.0; // Return 0 frequency for out-of-range distances
    }

    // Linear mapping: frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST)
    return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(float frequency) {
    // Calculate PWM duty cycle (50% for square wave)
    int dutyCycle = 128; // 128 out of 255

    // Set PWM frequency and duty cycle
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, dutyCycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Get the pulse width
        long pulseWidth = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Calculate the frequency
        float frequency = calculateFrequency(distance);

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Print the distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Stop PWM output and terminate pigpio (should not reach here if signal handler works)
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

