#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"

// Define sensor registers
#define REG_MEASURE 0x00
#define REG_RANGE 0x02
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    uint8_t range;
    uint8_t measurement_mode;
} sensor_config_t;

// Function to write a register
int write_register(uint8_t reg, uint8_t value) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = reg | 0x80; // Set MSB for write
    tx_buffer[1] = value;

    gpioWrite(CS_PIN, 0); // Select the sensor
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }

    return 0;
}

// Function to read a register
int read_register(uint8_t reg, uint8_t *value) {
    char tx_buffer[2];
    char rx_buffer[2];

    tx_buffer[0] = reg & 0x7F; // Clear MSB for read
    tx_buffer[1] = 0x00; // Dummy byte for reading

    gpioWrite(CS_PIN, 0); // Select the sensor
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }

    *value = rx_buffer[1];
    return 0;
}

// Function to initialize the sensor
int initialize_sensor() {
    // Configure the sensor (example configuration)
    if (write_register(REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "Error configuring range register.\n");
        return -1;
    }

    if (write_register(REG_MEASURE, 0x01) != 0) {
        fprintf(stderr, "Error configuring measurement register.\n");
        return -1;
    }

    return 0;
}

