#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VIS_LOW_REG 0x22
#define ALS_VIS_HIGH_REG 0x23
#define LOG_FILE "proximity_log.csv"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t size);
int log_data(const char* timestamp, uint16_t als_visible);
void signal_handler(int sig);
int initialize_sensor(int fd);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int result, retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        }
        perror("I2C read failed");
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result, retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        perror("I2C write failed");
        retries--;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to read ALS Visible data
uint16_t read_als_visible(int fd) {
    int low, high;

    low = i2c_read_reg(fd, ALS_VIS_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading ALS Visible Low register.\n");
        return 0; // Return 0 on error
    }

    high = i2c_read_reg(fd, ALS_VIS_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading ALS Visible High register.\n");
        return 0; // Return 0 on error
    }

    return (uint16_t)((high << 8) | low);
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(timestamp_str, size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_str;
}

// Function to log data to CSV file
int log_data(const char* timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the Si1175 sensor
int initialize_sensor(int fd) {
    // Example initialization sequence (refer to Si1175 datasheet)
    if (i2c_write_reg(fd, 0x18, 0x0F) < 0) return -1; // Reset
    usleep(10000); // Wait for reset
    if (i2c_write_reg(fd, 0x02, 0x01) < 0) return -1; // Enable ALS
    if (i2c_write_reg(fd, 0x03, 0x00) < 0) return -1; // ALS Integration Time
    if (i2c_write_reg(fd, 0x04, 0x00) < 0) return -1; // ALS Gain
    if (i2c_write_reg(fd, 0x17, 0x00) < 0) return -1; // PS LED Drive Strength
    if (i2c_write_reg(fd, 0x18, 0x00) < 0) return -1; // PS1 Integration Time
    if (i2c_write_reg(fd, 0x19, 0x00) < 0) return -1; // PS1 Gain
    if (i2c_write_reg(fd, 0x1A, 0x00) < 0) return -1; // PS2 Integration Time
    if (i2c_write_reg(fd, 0x1B, 0x00) < 0) return -1; // PS2 Gain
    if (i2c_write_reg(fd, 0x1C, 0x00) < 0) return -1; // PS3 Integration Time
    if (i2c_write_reg(fd, 0x1D, 0x00) < 0) return -1; // PS3 Gain
    if (i2c_write_reg(fd, 0x01, 0x07) < 0) return -1; // Enable PS1
    return 0;
}

int main() {
    char timestamp[32];
    uint16_t als_visible;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read ALS Visible data
        als_visible = read_als_visible(i2c_fd);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

