#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_RESET 0x30

// Si1120 Part ID value
#define SI1120_PART_ID 0x41

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1120 sensor
int initialize_sensor() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01);
        if (result == 0) {
            break;
        } else {
            fprintf(stderr, "Error resetting sensor (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10); // Wait 10 ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset sensor after multiple retries.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (result >= 0) {
            if (result == SI1120_PART_ID) {
                printf("Si1120 Part ID verified: 0x%02X\n", result);
