#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24
#define LUX_SCALE 0.1
#define LOG_FILE "biometric_log.txt"
#define SLEEP_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float lux;
    int proximity;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int verify_sensor(int fd);
int configure_sensor(int fd);
sensor_data_t read_sensor_data(int fd);
float convert_lux(uint16_t raw_lux);
void log_data(FILE *fp, sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single byte from a register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return value;
}

// Write a single byte to a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Verify the sensor by reading the Part ID register
int verify_sensor(int fd) {
    int part_id = read_register(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        return -1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Si1182-A-GM sensor verified (Part ID: 0x%02X)\n", part_id);
    return 0;
}

// Configure the sensor (e.g., set measurement rate)
int configure_sensor(int fd) {
    if (write_register(fd, MEAS_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error configuring measurement rate\n");
        return -1;
    }

    printf("Measurement rate configured to 0x07\n");
    return 0;
}

// Read ambient light and proximity data from the sensor
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    uint8_t buffer[4];

    // Read ambient light data (2 bytes)
    if (write(fd, &AMBIENT_LIGHT_REG, 1) != 1) {
        perror("Error writing ambient light register address");
        data.lux = -1.0; // Indicate error
        data.proximity = -1;
        return data;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading ambient light data");
        data.lux = -1.0; // Indicate error
        data.proximity = -1;
        return data;
    }
    uint16_t raw_lux = (buffer[1] << 8) | buffer[0];
    data.lux = convert_lux(raw_lux);

    // Read proximity data (2 bytes)
    if (write(fd, &PROXIMITY_REG, 1) != 1) {
        perror("Error writing proximity register address");
        data.lux = -1.0; // Indicate error
        data.proximity = -1;
        return data;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading proximity data");
        data.lux = -1.0; // Indicate error
        data.proximity = -1;
        return data;
    }
    data.proximity = (buffer[1] << 8) | buffer[0];

    return data;
}

// Convert raw ambient light data to lux
float convert_lux(uint16_t raw_lux) {
    return raw_lux * LUX_SCALE;
}

// Log data to file
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long milliseconds = rawtime % 1000;
    snprintf(timestamp + strlen(timestamp), 4, ".%03ld", milliseconds);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, data.lux, data.proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Print data to stdout
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long milliseconds = rawtime % 1000;
    snprintf(timestamp + strlen(timestamp), 4, ".%03ld", milliseconds);

    printf("%s,%.2f,%d\n", timestamp, data.lux, data.proximity);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI1182_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data(i2c_fd);

        if (data.lux != -1.0 && data.proximity != -1) {
            log_data(log_file, data);
            print_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        usleep(SLEEP_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

