// Function to read proximity data from the Si1145 sensor
int read_proximity() {
    int retries = 0;
    int result;
    uint8_t low_byte, high_byte;
    uint16_t proximity;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (result >= 0) {
            low_byte = (uint8_t)result;
            break;
        }
        fprintf(log_file, "%s - Error reading REG_PS1_DATA0 (attempt %d): %d\n", get_timestamp(), retries + 1, result);
        fflush(log_file);
        gpioDelay(1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(log_file, "%s - Failed to read REG_PS1_DATA0 after %d retries.\n", get_timestamp(), MAX_RETRIES);
        fflush(log_file);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, REG_PS1_DATA1);
        if (result >= 0) {
            high_byte = (uint8_t)result;
            break;
        }
        fprintf(log_file, "%s - Error reading REG_PS1_DATA1 (attempt %d): %d\n", get_timestamp(), retries + 1, result);
        fflush(log_file);
        gpioDelay(1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(log_file, "%s - Failed to read REG_PS1_DATA1 after %d retries.\n", get_timestamp(), MAX_RETRIES);
        fflush(log_file);
        return -1;
    }

    proximity = (high_byte << 8) | low_byte;
    return proximity;
}

// Function to log data to a file
void log_data(int proximity) {
    char* timestamp = get_timestamp();
    fprintf(log_file, "%s - Proximity: %d\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            log_data(proximity);
        } else {
            fprintf(log_file, "%s - Failed to read proximity data\n", get_timestamp());
            fflush(log_file);
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

