#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile unsigned int rising_edge_tick = 0;
volatile unsigned int falling_edge_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) { // Rising edge
        rising_edge_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received) { // Falling edge
        falling_edge_tick = tick;
        echo_received = 0; // Reset the flag
    }
}

// Function to calculate distance from pulse width
float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer based on distance
void control_buzzer(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_sensor(); // Trigger the sensor

        // Wait for a short period to allow the echo to be received
        gpioDelay(50000); // 50 ms

        // Calculate pulse width and distance
        unsigned int pulse_width = falling_edge_tick - rising_edge_tick;
        float distance = calculate_distance(pulse_width);

        // Control the buzzer
        control_buzzer(distance);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

