#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_DISTANCE 20.0     // Minimum measurable distance in cm
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum pulse width for servo (us)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width for servo (us)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
float getDistance();
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    setServoAngle(90); // Set servo to a safe position
    gpioTerminate();    // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for echo to start (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%.2f cm)\n", distance);
        return -1.0; // Indicate invalid distance
    }

    return distance;
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    // Linear mapping: 200 cm -> 0 degrees, 110 cm -> 90 degrees, 20 cm -> 180 degrees
    int angle = (int)(((distance - 20.0) / (110.0 - 20.0)) * 180.0);

    // Clamp the angle to the valid range
    if (angle < 0) {
        angle = 0;
    } else if (angle > 180) {
        angle = 180;
    }

    return angle;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Get distance
        float distance = getDistance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to get distance\n");
        } else {
            // Map distance to angle
            int angle = mapDistanceToAngle(distance);

            // Set servo angle
            setServoAngle(angle);

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        // Wait 100 milliseconds
        gpioDelay(100000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    setServoAngle(90); // Set servo to a safe position
    gpioTerminate();    // Terminate pigpio

    return 0;
}

