#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_ANGLE 0.0         // Minimum servo angle in degrees
#define MAX_ANGLE 180.0       // Maximum servo angle in degrees
#define MIN_PULSE_WIDTH 500   // Minimum servo pulse width in us
#define MAX_PULSE_WIDTH 2500  // Maximum servo pulse width in us

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;

// Function prototypes
void triggerSensor();
double measureDistance();
double mapDistanceToAngle(double distance);
void setServoAngle(double angle);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCtrl+C pressed. Stopping servo and exiting...\n");
    setServoAngle(0.0); // Stop the servo
    gpioTerminate();     // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 us
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the distance using the ultrasonic sensor
double measureDistance() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_valid = 0;

    triggerSensor();

    // Wait for echo to start (rising edge)
    int start_time = gpioTick();
    while (echo_start_tick == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (echo_start_tick == 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Timeout
    }

    // Wait for echo to end (falling edge)
    start_time = gpioTick();
    while (echo_end_tick == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (echo_end_tick == 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Timeout
    }

    // Calculate pulse duration in microseconds
    int pulse_duration_us = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_duration_us * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and then by 2

    return distance;
}

// Function to map distance to servo angle
double mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle
void setServoAngle(double angle) {
    // Map angle to pulse width
    int pulse_width = MIN_PULSE_WIDTH + (int)((angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE));

    gpioServo(SERVO_PIN, pulse_width);
}

// Callback function for echo pin rising edge
void echoRisingEdge(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    }
}

// Callback function for echo pin falling edge
void echoFallingEdge(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        echo_end_tick = tick;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Set up callback functions for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoRisingEdge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echoFallingEdge, NULL);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Measure distance
        double distance = measureDistance();

        if (distance > 0) {
            // Map distance to angle
            double angle = mapDistanceToAngle(distance);

            // Set servo angle
            setServoAngle(angle);

            // Print distance and angle
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    gpioTerminate();
    return 0;
}

