#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_config_register(int handle);
int read_sensor_data(int handle, uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to the configuration register
int write_config_register(int handle) {
    int result = i2cWriteByteData(handle, CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    return 0;
}

// Read temperature and humidity data
int read_sensor_data(int handle, uint16_t *temperature, uint16_t *humidity) {
    int result;

    // Read temperature
    result = i2cWriteByte(handle, TEMP_CMD);
    if (result < 0) {
        fprintf(stderr, "Failed to write temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    result = i2cReadWordData(handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    *temperature = (uint16_t)result;

    // Read humidity
    result = i2cWriteByte(handle, HUMID_CMD);
    if (result < 0) {
        fprintf(stderr, "Failed to write humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms
    result = i2cReadWordData(handle, HUMID_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }
    *humidity = (uint16_t)result;

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return (175.72 * raw_temp) / 65536.0 - 46.85;
}

// Convert raw humidity to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (125.0 * raw_humidity) / 65536.0 - 6.0;
}

// Log temperature and humidity data
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Write to configuration register
    if (write_config_register(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
            // Convert data
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = open_i2c_bus();
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (write_config_register(i2c_handle) != 0) {
                    fprintf(stderr, "Failed to re-write config register. Exiting.\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

