#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len, uint8_t crc);
sensor_data_t convert_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to SHT40
int send_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SHT40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadI2CBlockData(handle, 0, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == crc);
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t result;
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    result.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    result.humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (result.humidity < 0.0) {
        result.humidity = 0.0;
    } else if (result.humidity > 100.0) {
        result.humidity = 100.0;
    }

    return result;
}

// Log data to console
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Open I2C bus
        i2c_handle = open_i2c_bus();
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus, retrying in %d seconds...\n", RETRY_DELAY_MS / 1000);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_HIGH_REP) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Wait for measurement (at least 10 ms)
        gpioDelay(10000); // 10 ms

        // Read data
        uint8_t data[6];
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, 2, data[2]) || !validate_crc8(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Close I2C bus
        i2cClose(i2c_handle);
        i2c_handle = -1;

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

