void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Open I2C bus
        i2c_handle = open_i2c_bus();
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus, retrying in %d seconds...\n", RETRY_DELAY_MS / 1000);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_HIGH_REP) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Wait for measurement (at least 10 ms)
        gpioDelay(10000); // 10 ms

        // Read data
        uint8_t data[6];
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, 2, data[2]) || !validate_crc8(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            continue;
        }

        // Convert data
        sensor_data_t sensor_data = convert_data(data);

        // Log data
        log_data(sensor_data);

        // Close I2C bus
        i2cClose(i2c_handle);
        i2c_handle = -1;

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

