#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define SAMPLE_INTERVAL 5 // seconds
#define ERROR_LOG_FILE "error_log.txt"
#define TEMP_LOG_FILE "enclosure_temp_log.txt"

// Global variables
int i2c_handle;
FILE *temp_log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read temperature from STS30-DIS sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int32_t raw_temperature = (buffer[0] << 8) | buffer[1];
    *temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (temp_log_file == NULL) {
        temp_log_file = fopen(TEMP_LOG_FILE, "a");
        if (temp_log_file == NULL) {
            log_error("Failed to open temperature log file");
            return -1;
        }
    }

    fprintf(temp_log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(temp_log_file); // Ensure data is written to disk immediately

    return 0;
}

// Log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file == NULL) {
        error_log_file = fopen(ERROR_LOG_FILE, "a");
        if (error_log_file == NULL) {
            perror("Failed to open error log file");
            return -1; // Cannot log error if error log file cannot be opened
        }
    }

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (temp_log_file != NULL) {
        fclose(temp_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        result = read_temperature(&temperature);
        if (result == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            log_error("Failed to read temperature");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

