#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD_1 0x36
#define CONTINUOUS_MEASUREMENT_CMD_2 0x08
#define DATA_FRAME_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIALIZATION 0xFF
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t command1, uint8_t command2);
int read_data(int handle, uint8_t *data, int count);
int validate_crc(const uint8_t *data, int length);
sensor_data_t convert_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INITIALIZATION;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint8_t command1, uint8_t command2) {
    char buf[2] = {command1, command2};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int length) {
    if (length < 2) return -1; // Need at least 2 bytes for CRC

    uint8_t crc = crc8(data, length - 1);
    if (crc != data[length - 1]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor = (data[6] << 8) | data[7];

    // Apply scaling factors (from SDP810 datasheet)
    sensor_data.pressure = (float)raw_pressure / scale_factor; // Pa
    sensor_data.temperature = (float)raw_temperature / scale_factor; // °C

    return sensor_data;
}

// Log data to a CSV file
int log_data(const sensor_data_t *data) {
