// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INITIALIZATION;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

