int read_sensor_data(sensor_data_t *data) {
    uint8_t write_data[1] = {MEASURE_HIGH_REPEATABILITY};
    uint8_t read_data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)write_data, 1) != 0) {
