        if (bytes_read == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, bytes_read);
            gpioDelay(1000 * (1 << (RETRY_COUNT - retries))); // Exponential backoff
            retries--;
