int init_pigpio();
int open_i2c_bus();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(i2c_handle));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd, buf[2];
    int result;
    uint16_t raw_temp, raw_humidity;

    // Read temperature
    cmd = TEMP_CMD;
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature command: %s\n", strerror(result));
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet specifies up to 20ms)

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(result));
        return -1;
    }
    raw_temp = (buf[0] << 8) | buf[1];
    data->temperature = convert_temperature(raw_temp);

    // Read humidity
    cmd = HUMID_CMD;
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write humidity command: %s\n", strerror(result));
        return -1;
    }
    gpioDelay(20); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %s\n", strerror(result));
        return -1;
    }
    raw_humidity = (buf[0] << 8) | buf[1];
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

