    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Print data to console
void print_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", data.temperature, data.humidity);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int retries;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < RETRY_COUNT) {
            if (read_sensor_data(&sensor_data) == 0) {
                log_data(sensor_data);
                print_data(sensor_data);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Retrying sensor read (%d/%d)...\n", retries + 1, RETRY_COUNT);
                retries++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Skipping.\n", RETRY_COUNT);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

