int validate_crc(const uint8_t *data, int length);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(TRIGGER_MEASUREMENT_CMD >> 8) & 0xFF, TRIGGER_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return -1;
    }

    gpioDelay(45000); // Wait 45 ms

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int length) {
    for (int i = 0; i < length; i += CRC_LENGTH) {
        uint8_t crc = crc8(data + i, CRC_LENGTH - 1);
        if (crc != data[i + CRC_LENGTH - 1]) {
            fprintf(stderr, "CRC validation failed at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Scale factor is a float, but we only need the integer part for this example
    float scale_factor = (float)raw_scale_factor;

    sensor_data.pressure = (float)raw_pressure / scale_factor;
    sensor_data.temperature = (float)raw_temperature / 200.0 - 45.0;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    uint8_t sensor_data[DATA_LENGTH];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, DATA_LENGTH) == 0) {
                // Convert data
                converted_data = convert_data(sensor_data);

                // Log data
                log_data(converted_data);
            } else {
                fprintf(stderr, "CRC validation failed, skipping data logging\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping data logging\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

