#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for storing sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *temperature, float *humidity) {
    uint8_t cmd_temp = 0xE3;
    uint8_t cmd_humidity = 0xE5;
    uint8_t buf[2];
    int result;
    int retries;

    // Read temperature
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, cmd_temp);
        if (result == 0) {
            gpioDelay(10); // Wait 10 ms
            result = i2cReadDevice(i2c_handle, (char *)buf, 2);
            if (result == 2) {
                uint16_t raw_temp = (buf[0] << 8) | buf[1];
                *temperature = convert_temperature(raw_temp);
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error reading temperature (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Wait before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Read humidity
    retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, cmd_humidity);
        if (result == 0) {
            gpioDelay(10); // Wait 10 ms
            result = i2cReadDevice(i2c_handle, (char *)buf, 2);
            if (result == 2) {
                uint16_t raw_humidity = (buf[0] << 8) | buf[1];
                *humidity = convert_humidity(raw_humidity);
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error reading humidity (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing humidity command (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Wait before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read humidity after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Function to control the fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_ON) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_OFF) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to the circular buffer
void log_data(float temperature, float humidity) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, buffer[index].temperature, buffer[index].humidity);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            control_fan(temperature);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 2 seconds.\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

