        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data (CO2, temperature, humidity)
int read_sensor_data(sensor_data_t *data) {
    uint8_t raw_data[9];

    if (read_data(raw_data, 9) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Validate CRC for each 2-byte word
    if (!validate_crc(raw_data, 2) || !validate_crc(raw_data + 3, 2) || !validate_crc(raw_data + 6, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    data->co2 = (raw_data[0] << 8) | raw_data[1];
    data->temperature = (raw_data[3] << 8) | raw_data[4];
    data->humidity = (raw_data[6] << 8) | raw_data[7];

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t *data, int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
