    float temperature = convert_temperature(data.temperature);
    float humidity = convert_humidity(data.humidity);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, data.co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
        return -1;
    }
    return 0;
}

