    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 1 second
    gpioDelay(1000); // 1000 ms = 1 second

    sensor_data_t sensor_data;
    uint8_t data_ready_buf[2];
    uint16_t data_ready_command = CMD_DATA_READY;
    char data_ready_buf_char[2];
    data_ready_buf_char[0] = data_ready_command >> 8;
    data_ready_buf_char[1] = data_ready_command & 0xFF;

    // Main loop
    while (!terminate) {
        // Check data ready flag
        if (i2cWriteDevice(i2c_handle, data_ready_buf_char, 2) != 0) {
            fprintf(stderr, "Failed to write data ready command\n");
            break;
        }
        gpioDelay(1); // Small delay after writing the command

        if (i2cReadDevice(i2c_handle, (char *)data_ready_buf, 2) != 2) {
            fprintf(stderr, "Failed to read data ready flag\n");
            break;
        }

        uint16_t data_ready_flag = (data_ready_buf[0] << 8) | data_ready_buf[1];

        if (data_ready_flag == 0x0000) {
            // Data not ready yet, wait 500ms and retry
            gpioDelay(500);
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to stop periodic measurement during shutdown\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

