#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5 // seconds

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Data Structure for Sensor Readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_reading_t;

// Circular Buffer Structure
typedef struct {
    sensor_reading_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global Variables
int i2c_handle;
circular_buffer_t reading_buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_pigpio();
int init_i2c();
int init_led();
int init_circular_buffer(circular_buffer_t *cb);
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int start_periodic_measurement(int handle);
int stop_periodic_measurement(int handle);
int read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity);
int get_data_ready_status(int handle);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint16_t data, uint8_t crc);
int add_reading(circular_buffer_t *cb, uint16_t co2, float temperature, float humidity);
int get_reading(circular_buffer_t *cb, int index, sensor_reading_t *reading);
void print_reading(sensor_reading_t reading);
void control_led(int gpio, int state);
void signal_handler(int signal);
void cleanup();

// CRC-8 Checksum Calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 Checksum
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = data >> 8;
    data_bytes[1] = data & 0xFF;
    return crc8(data_bytes, 2) == crc;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
