int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read Data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Start Periodic Measurement
int start_periodic_measurement(int handle) {
    return write_command(handle, CMD_START_PERIODIC_MEASUREMENT);
}

// Stop Periodic Measurement
int stop_periodic_measurement(int handle) {
    return write_command(handle, CMD_STOP_PERIODIC_MEASUREMENT);
}

// Read Measurement
int read_measurement(int handle, uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    if (read_data(handle, data, 9) != 0) {
        return -1;
    }

