    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint8_t co2_crc = data[2];
    uint16_t temperature_raw = (data[3] << 8) | data[4];
    uint8_t temperature_crc = data[5];
    uint16_t humidity_raw = (data[6] << 8) | data[7];
    uint8_t humidity_crc = data[8];

    // Validate CRC
    if (!validate_crc(co2_raw, co2_crc) || !validate_crc(temperature_raw, temperature_crc) || !validate_crc(humidity_raw, humidity_crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    *co2 = co2_raw;
    *temperature = -45 + 175 * (float)temperature_raw / 65535.0;
    *humidity = 100 * (float)humidity_raw / 65535.0;

    return 0;
}

