int add_reading(circular_buffer_t *cb, uint16_t co2, float temperature, float humidity) {
    time(&cb->buffer[cb->head].timestamp);
    cb->buffer[cb->head].co2 = co2;
    cb->buffer[cb->head].temperature = temperature;
    cb->buffer[cb->head].humidity = humidity;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    return 0;
}

// Get Reading from Circular Buffer
int get_reading(circular_buffer_t *cb, int index, sensor_reading_t *reading) {
    if (index < 0 || index >= cb->count) {
        return -1; // Invalid index
    }
    int actual_index = (cb->tail + index) % BUFFER_SIZE;
    *reading = cb->buffer[actual_index];
    return 0;
}

