#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define VALID_TEMP_MIN -40.0
#define VALID_TEMP_MAX 150.0
#define MAX_CONSECUTIVE_FAILURES 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int consecutive_failures = 0;

// Structure to hold temperature data
typedef struct {
    double temperature;
    int valid;
} TemperatureData;

// Function prototypes
int initialize_gpio();
TemperatureData read_temperature();
double convert_to_celsius(double th, double tl);
int log_temperature(double temperature, int valid);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Read temperature from the TMP05 sensor
TemperatureData read_temperature() {
    TemperatureData data = {0.0, 0};
    int high_start = 0, high_end = 0, low_start = 0, low_end = 0;
    int timeout_us = 50000; // 50 ms timeout
    int start_tick, end_tick;

    // Wait for the signal to go high
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > timeout_us) {
            fprintf(stderr, "Timeout waiting for high signal\n");
            return data; // Timeout
        }
    }
    high_start = gpioTick();

    // Wait for the signal to go low
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > timeout_us) {
            fprintf(stderr, "Timeout waiting for low signal\n");
            return data; // Timeout
        }
    }
    high_end = gpioTick();

    // Wait for the signal to go high again
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > timeout_us) {
            fprintf(stderr, "Timeout waiting for high signal (2nd)\n");
            return data; // Timeout
        }
    }
    low_start = gpioTick();

    // Wait for the signal to go low again
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > timeout_us) {
            fprintf(stderr, "Timeout waiting for low signal (2nd)\n");
            return data; // Timeout
        }
    }
    low_end = gpioTick();

    // Calculate pulse widths
    double th = (double)(high_end - high_start);
    double tl = (double)(low_end - low_start);

    // Convert to Celsius
    data.temperature = convert_to_celsius(th, tl);

    // Validate temperature
    if (data.temperature >= VALID_TEMP_MIN && data.temperature <= VALID_TEMP_MAX) {
        data.valid = 1;
    } else {
        fprintf(stderr, "Temperature out of range: %.2f\n", data.temperature);
    }

    return data;
}

// Convert TH and TL to Celsius
double convert_to_celsius(double th, double tl) {
    if (tl == 0.0) {
        fprintf(stderr, "Division by zero error\n");
        return 0.0; // Or some other error value
    }
    return 4215.0 - (2143.0 * th / tl);
}

// Log temperature to file
int log_temperature(double temperature, int valid) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        if (valid) {
            fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
            fflush(log_file); // Ensure data is written to disk immediately
            consecutive_failures = 0; // Reset failure count on success
        } else {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
            fprintf(log_file, "%s, ERROR: Invalid temperature reading: %.2f\n", timestamp, temperature);
            fflush(log_file);
            consecutive_failures++;
        }
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    if (consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
        fprintf(log_file, "%s, SENSOR MALFUNCTION\n", timestamp);
        fflush(log_file);
        consecutive_failures = 0; // Reset after logging malfunction
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        TemperatureData temperature_data = read_temperature();
        log_temperature(temperature_data.temperature, temperature_data.valid);
        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

