#define MEASUREMENT_COMMAND 0x2400
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define SINUSOIDAL_PERIOD_SEC (3600.0) // 1 hour
#define SINUSOIDAL_AMPLITUDE_TEMP 2.0
#define SINUSOIDAL_AMPLITUDE_HUMIDITY 5.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
void apply_sinusoidal_offset(sensor_data_t *data, time_t current_time);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(sensor_data_t *data) {
    uint8_t write_data[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    uint8_t read_data[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        // Send measurement command
        if (i2cWriteDevice(i2c_handle, (char *)write_data, 2) != 2) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(15000); // Wait 15 ms for measurement

        // Read 6 bytes of data
        if (i2cReadDevice(i2c_handle, (char *)read_data, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(read_data, 2, read_data[2])) {
            fprintf(stderr, "Temperature CRC check failed (attempt %d)\n", retries + 1);
            retries++;
            continue;
        }

        // Validate CRC for humidity
        if (!validate_crc(read_data + 3, 2, read_data[5])) {
            fprintf(stderr, "Humidity CRC check failed (attempt %d)\n", retries + 1);
            retries++;
            continue;
        }

        // Convert raw data
        uint16_t raw_temperature = (read_data[0] << 8) | read_data[1];
        uint16_t raw_humidity = (read_data[3] << 8) | read_data[4];

        data->temperature = convert_temperature(raw_temperature);
        data->humidity = convert_humidity(raw_humidity);

        return 0; // Success
    }

    // All retries failed
    data->temperature = NAN;
    data->humidity = NAN;
    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
