float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Convert raw humidity to %RH
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Calculate CRC checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
