    double time_offset = (double)current_time / SINUSOIDAL_PERIOD_SEC * 2.0 * M_PI;
    data->temperature += SINUSOIDAL_AMPLITUDE_TEMP * sin(time_offset);
    data->humidity += SINUSOIDAL_AMPLITUDE_HUMIDITY * sin(time_offset);
}

