    time_t current_time;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Apply sinusoidal offset
            current_time = time(NULL);
            apply_sinusoidal_offset(&sensor_data, current_time);

