#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CSV_FILE "airflow.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int len);
sensor_data_t convert_data(const char *raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC checksum
int validate_crc(const char *data, int len) {
    if (len < 2) return -1; // Need at least 2 bytes for CRC

    uint8_t crc = crc8(data, len - 1);
    if (crc != (uint8_t)data[len - 1]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const char *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    // Scaling factors from the datasheet
    data.pressure = (float)raw_pressure / 240.0; // Pa
    data.temperature = (float)raw_temperature / 200.0; // °C

    return data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    while (!terminate) {
        char raw_data[9];
        int retry = 0;

        // Retry loop for reading data
        while (retry < RETRY_COUNT) {
            // Send continuous measurement command
            if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
                fprintf(stderr, "Failed to send command, retry %d\n", retry + 1);
                retry++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            gpioDelay(50); // Wait for conversion (adjust as needed)

            // Read data
            if (read_data(i2c_handle, raw_data, 9) != 0) {
                fprintf(stderr, "Failed to read data, retry %d\n", retry + 1);
                retry++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // Validate CRC
            if (validate_crc(raw_data, 3) != 0 || validate_crc(raw_data + 3, 3) != 0) {
                fprintf(stderr, "Failed to validate CRC, retry %d\n", retry + 1);
                retry++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // Convert data
            sensor_data_t data = convert_data(raw_data);

            // Log data
            log_data(data);

            break; // Exit retry loop on success
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

