#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"
#define POLL_INTERVAL_MS 5000
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor_data(int fd, uint8_t command, uint8_t *data);
int verify_crc(const uint8_t *data, size_t len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int sig);
int reset_sensor(int fd);

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data with retry mechanism
int read_sensor_data(int fd, uint8_t command, uint8_t *data) {
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        if (write(fd, &command, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Wait for data to be ready (adjust as needed)
        usleep(10000); // Wait 10ms

        // Read 3 bytes of data
        bytes_read = read(fd, data, 3);
        if (bytes_read == 3) {
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Verify CRC-8 checksum
int verify_crc(const uint8_t *data, size_t len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Reset the sensor
int reset_sensor(int fd) {
    uint8_t reset_cmd = RESET_CMD;
    if (write(fd, &reset_cmd, 1) != 1) {
        perror("Error resetting sensor");
        return -1;
    }
    usleep(100000); // Wait for reset to complete (100ms)
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }

    // Main loop
    while (!terminate) {
        uint8_t temp_data[3];
        uint8_t humid_data[3];
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(i2c_fd, TEMP_CMD, temp_data) == 0) {
            if (verify_crc(temp_data, 3)) {
                uint16_t raw_temp = (temp_data[0] << 8) | temp_data[1];
                temperature = convert_temperature(raw_temp);
            } else {
                fprintf(stderr, "Temperature CRC check failed.\n");
                temperature = -999.0; // Indicate error
                log_data(log_file, temperature, -999.0);
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            temperature = -999.0; // Indicate error
            log_data(log_file, temperature, -999.0);
        }

        // Read humidity
        if (read_sensor_data(i2c_fd, HUMID_CMD, humid_data) == 0) {
