        }

        // Read humidity
        if (read_sensor_data(i2c_fd, HUMID_CMD, humid_data) == 0) {
            if (verify_crc(humid_data, 3)) {
                uint16_t raw_humidity = (humid_data[0] << 8) | humid_data[1];
