#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONVERSION_TIME_US 50000 // 50ms
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_OFFSET -1000.0
#define TEMPERATURE_OFFSET -45.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int count);
sensor_data_t convert_data(const char *raw_data);
int log_data(FILE *file, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int count) {
    uint8_t crc = crc8(data, count);
    return (crc == 0);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const char *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure = (float)raw_pressure / PRESSURE_SCALE_FACTOR + PRESSURE_OFFSET;
    data.temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;

    return data;
}

// Log data to file
int log_data(FILE *file, sensor_data_t data) {
    size_t elements_written = fwrite(&data, sizeof(sensor_data_t), 1, file);
    if (elements_written != 1) {
        fprintf(stderr, "Failed to write data to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open data file in binary append mode
    data_file = fopen("airflow.dat", "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Write measurement command
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to write measurement command, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Wait for conversion
        gpioDelay(CONVERSION_TIME_US);

        // Read data
        char raw_data[9];
        if (read_data(i2c_handle, raw_data, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(raw_data, 2) || !validate_crc(raw_data + 3, 2)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_data);

        // Log data
        if (log_data(data_file, data) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", data.pressure, data.temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

