#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define MIN_FLOW_RATE 0.0   // SLPM
#define MAX_FLOW_RATE 10.0  // SLPM
#define MIN_RAW_VALUE 1638
#define MAX_RAW_VALUE 14745
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *raw_data);
float convert_to_flow_rate(uint16_t raw_data);
int set_fan_speed(float flow_rate);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    uint16_t raw_data;
    float flow_rate;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *raw_data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw data to flow rate
float convert_to_flow_rate(uint16_t raw_data) {
    // Mask off status bits (2 MSBs)
    raw_data = raw_data >> 2;

    // Scale to SLPM
    return MIN_FLOW_RATE + (float)(raw_data - MIN_RAW_VALUE) * (MAX_FLOW_RATE - MIN_FLOW_RATE) / (MAX_RAW_VALUE - MIN_RAW_VALUE);
}

// Function to set fan speed using PWM
int set_fan_speed(float flow_rate) {
    // Clamp flow rate to valid range
    if (flow_rate < MIN_FLOW_RATE) {
        flow_rate = MIN_FLOW_RATE;
    } else if (flow_rate > MAX_FLOW_RATE) {
        flow_rate = MAX_FLOW_RATE;
    }

    // Map flow rate to PWM duty cycle (0-255)
    int duty_cycle = (int)((flow_rate / MAX_FLOW_RATE) * 255.0);

    gpioPWM(FAN_GPIO, duty_cycle);
    return 0;
}

// Function to log data to file
int log_data(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Configure fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    uint16_t raw_data;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow_rate(raw_data);

            // Set fan speed
            set_fan_speed(flow_rate);

            // Log data
            log_data(flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

