} sensor_data_t;

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    int who_am_i;

    // Check WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0xB1\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (ODR = 10 Hz, BDU = enabled, Active mode)
    int result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0);
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read pressure data from the LPS33HW
int read_pressure(int32_t *pressure) {
    char buffer[3];
    int result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | ((uint32_t)buffer[0]));
    *pressure = *pressure >> 8; // Align to 24 bits

    return 0;
}

// Function to read temperature data from the LPS33HW
int read_temperature(int16_t *temperature) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    *temperature = (int16_t)((((uint16_t)buffer[1]) << 8) | ((uint16_t)buffer[0]));

    return 0;
}

// Function to log data to a file
void log_data(int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, timeinfo);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, (float)pressure / 4096.0, 42.5 + (float)temperature / 480.0);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() < 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t pressure;
    int16_t temperature;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            // Log the data
            log_data(pressure, temperature);
        } else {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime_r(&rawtime, timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the error to both stderr and the log file
            fprintf(stderr, "%s, Error reading sensor data\n", timestamp);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

