// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stlm75_address;
    int led_pin;
    int buffer_size;
    float temperature_threshold;
} Config;

Config config = {
    .i2c_bus = I2C_BUS,
    .stlm75_address = STLM75_ADDR,
    .led_pin = LED_GPIO,
    .buffer_size = BUFFER_SIZE,
    .temperature_threshold = TEMP_THRESHOLD
};

int main() {
    float temperature;
    float average_temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Add temperature to buffer
            add_to_buffer(temperature);

            // Calculate average temperature
            average_temperature = calculate_average();

            // Control LED
            control_led(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(config.i2c_bus, config.stlm75_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from STLM75 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int16_t raw_temp;

    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", bytes_read);
        return 1;
    }

    // Swap bytes (pigpio returns little-endian)
    raw_temp = (buf[1] << 8) | buf[0];

    // Extract temperature (9-bit resolution)
    raw_temp = raw_temp >> 7;

    // Convert to Celsius
    *temperature = (float)raw_temp * 0.5;

    return 0;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % config.buffer_size;
    if (buffer_count < config.buffer_size) {
        buffer_count++;
    }
}

// Calculate average temperature from circular buffer
float calculate_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    return sum / buffer_count;
}

// Control LED based on average temperature
void control_led(float average_temperature) {
    if (average_temperature > config.temperature_threshold) {
        gpioWrite(config.led_pin, 1); // Turn LED on
    } else {
        gpioWrite(config.led_pin, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(config.led_pin, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

