int start_periodic_measurement();
int stop_periodic_measurement();
int get_data_ready_status();
int get_serial_number(uint8_t *serial_number);
int perform_self_test();
VentilationState control_ventilation(float co2);
int log_data(float co2, float temperature, float humidity, VentilationState ventilation_state);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation
int validate_crc(uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD30
int send_command(uint16_t command) {
    uint8_t data[2];
    data[0] = command >> 8;
    data[1] = command & 0xFF;

    if (write_data(data, 2) != 0) {
        fprintf(stderr, "Failed to send command 0x%04X\n", command);
        return -1;
    }
    return 0;
}

// Read data from SCD30
int read_data(uint8_t *data, int count) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, count);
    if (bytes_read != count) {
        fprintf(stderr, "Failed to read %d bytes, read %d\n", count, bytes_read);
        return -1;
    }
    return 0;
}

// Write data to SCD30
int write_data(uint8_t *data, int count) {
    int bytes_written = i2cWriteDevice(i2c_handle, (char *)data, count);
    if (bytes_written != count) {
        fprintf(stderr, "Failed to write %d bytes, wrote %d\n", count, bytes_written);
        return -1;
    }
    return 0;
}

// Read SCD30 data
int read_scd30_data(float *co2, float *temperature, float *humidity) {
    uint8_t data[18];

    // Read measurement data (0x0300)
    if (send_command(0x0300) != 0) {
        return -1;
    }

    // Wait for data to be ready (0x0202)
    int ready = 0;
    for (int i = 0; i < 10; i++) {
        if (get_data_ready_status() == 1) {
            ready = 1;
            break;
        }
        gpioDelay(100); // Wait 100ms
    }

    if (!ready) {
        fprintf(stderr, "Data not ready after 1000ms\n");
        return -1;
    }

    if (read_data(data, 18) != 0) {
        return -1;
    }

    // Validate CRC for each value
    if (!validate_crc(data, 4) || !validate_crc(data + 4, 4) || !validate_crc(data + 8, 4)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to float
    *co2 = *((float *)data);
    *temperature = *((float *)(data + 4));
    *humidity = *((float *)(data + 8));

    return 0;
}

// Set measurement interval
int set_measurement_interval(int interval) {
    uint8_t data[3];
    data[0] = 0x46;
    data[1] = interval;
    data[2] = interval >> 8;

    if (send_command(0x4600) != 0) {
        return -1;
    }

    if (write_data(data, 3) != 0) {
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    if (send_command(0x0010) != 0) {
        return -1;
    }
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    if (send_command(0x0104) != 0) {
        return -1;
    }
    return 0;
}

// Get data ready status
int get_data_ready_status() {
    uint8_t data[3];
    if (send_command(0x0202) != 0) {
        return -1;
    }

    if (read_data(data, 3) != 0) {
        return -1;
    }

    return data[0];
}

// Get serial number
int get_serial_number(uint8_t *serial_number) {
    if (send_command(0x3682) != 0) {
        return -1;
    }

    if (read_data(serial_number, 16) != 0) {
        return -1;
    }

    return 0;
}

// Perform self-test
int perform_self_test() {
    uint8_t data[2];
    if (send_command(0x3646) != 0) {
        return -1;
    }

    if (read_data(data, 2) != 0) {
        return -1;
    }

    if (data[0] != 0x00 || data[1] != 0x00) {
        fprintf(stderr, "Self-test failed\n");
        return -1;
    }

    return 0;
}

// Control ventilation system
VentilationState control_ventilation(float co2) {
    if (co2 < 800) {
        return OFF;
    } else if (co2 < 1200) {
        return LOW;
    } else {
        return HIGH;
    }
}

// Log data to file
int log_data(float co2, float temperature, float humidity, VentilationState ventilation_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, co2, temperature, humidity, ventilation_state);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Perform self-test
    if (perform_self_test() != 0) {
        fprintf(stderr, "Self-test failed, exiting\n");
        cleanup();
        return 1;
    }

    // Set measurement interval
    if (set_measurement_interval(MEASUREMENT_INTERVAL) != 0) {
        fprintf(stderr, "Failed to set measurement interval, exiting\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Failed to start periodic measurement, exiting\n");
        cleanup();
        return 1;
    }

    float co2, temperature, humidity;
    VentilationState ventilation_state;

    // Main loop
    while (!terminate) {
        // Read SCD30 data
        if (read_scd30_data(&co2, &temperature, &humidity) == 0) {
            // Control ventilation system
            ventilation_state = control_ventilation(co2);

            // Log data
            log_data(co2, temperature, humidity, ventilation_state);

            printf("CO2: %.2f ppm, Temperature: %.2f °C, Humidity: %.2f %%, Ventilation: %d\n", co2, temperature, humidity, ventilation_state);
        } else {
            fprintf(stderr, "Failed to read SCD30 data\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Wait for the measurement interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

