#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3615
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int count);
int read_sensor_data(int handle, sensor_data_t *data);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int count) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int count) {
    uint8_t crc = crc8(data, count);
    if (crc != data[count]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, data[count]);
        return -1;
    }
    return 0;
}

// Read sensor data and convert to physical units
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    int16_t raw_pressure, raw_temperature;
    float scale_factor_pressure, scale_factor_temperature;

    // Send measurement command
    if (send_command(handle, MEASURE_CMD) != 0) {
        return -1;
    }

    // Wait for conversion (at least 45 ms)
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    // Validate CRC for pressure data
    if (validate_crc(buffer, 3) != 0) {
        return -1;
    }

    // Validate CRC for temperature data
    if (validate_crc(buffer + 3, 3) != 0) {
        return -1;
    }

    // Validate CRC for scale factor pressure data
    if (validate_crc(buffer + 6, 3) != 0) {
        return -1;
    }

    // Extract raw values
    raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    scale_factor_pressure = (float)((buffer[6] << 8) | buffer[7]);
    scale_factor_temperature = (float)((buffer[8] << 8) | 0x00); //Scale factor is only 16 bits

    // Convert raw values to physical units
    data->pressure = (float)raw_pressure / scale_factor_pressure;
    data->temperature = (float)raw_temperature / 200.0;

    return 0;
}

// Log sensor data to stdout
void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    printf("%s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, data->pressure, data->temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log data
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

