#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000(int fd) {
    uint16_t config_value = 0x0000; // Default configuration: Temperature and Humidity, 14-bit resolution
    uint8_t config_data[3];

    // Write the configuration register address
    config_data[0] = CONFIG_REG;
    config_data[1] = (config_value >> 8) & 0xFF; // MSB
    config_data[2] = config_value & 0xFF;      // LSB

    if (write(fd, config_data, 3) != 3) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint8_t data[4];
    uint16_t raw_temperature, raw_humidity;

    // Write the temperature register address
    if (write(fd, &TEMP_REG, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (at least 20 ms)
    usleep(20000); // 20 ms

    // Read 4 bytes of data (temperature and humidity)
    if (read(fd, data, 4) != 4) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes to form the raw temperature and humidity values
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[2] << 8) | data[3];

    // Convert the raw values to temperature and humidity
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device file
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address for the HDC1000
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing HDC1000 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and log temperature and humidity data
    while (1) {
        // Read temperature and humidity from the sensor
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the temperature and humidity data to the console
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            // Log an error message to stderr
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    return 0;
}

