// ICP-10101 I2C address
#define ICP10101_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Commands
#define CMD_READ_OTP 0x50
#define CMD_MEASURE_HP 0x40

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
uint16_t c0, c1, c00, c10, c01, c11, c20, c21, c30;

// Function prototypes
int read_calibration_coefficients();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double temperature);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Structure to hold calibration data
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
    uint16_t c01;
    uint16_t c11;
    uint16_t c20;
    uint16_t c21;
    uint16_t c30;
} calibration_data_t;

calibration_data_t calibration;

// Function to read calibration coefficients from OTP memory
int read_calibration_coefficients() {
    char buf[16];
    int result;

    result = i2cWriteByte(i2c_handle, CMD_READ_OTP);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for OTP to be ready

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 16);
    if (result != 16) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration.c0 = (buf[0] << 8) | buf[1];
    calibration.c1 = (buf[2] << 8) | buf[3];
    calibration.c00 = (buf[4] << 8) | buf[5];
    calibration.c10 = (buf[6] << 8) | buf[7];
    calibration.c01 = (buf[8] << 8) | buf[9];
    calibration.c11 = (buf[10] << 8) | buf[11];
    calibration.c20 = (buf[12] << 8) | buf[13];
    calibration.c21 = (buf[14] << 8) | buf[15];

    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char buf[6];
    int result;

    result = i2cWriteByte(i2c_handle, CMD_MEASURE_HP);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(7); // Wait for measurement to complete

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *pressure = (buf[2] << 24) | (buf[3] << 16) | (buf[4] << 8) | buf[5];

    return 0;
}

