double compensate_temperature(int32_t raw_temperature) {
    double temp;
    temp = (double)raw_temperature;
    return temp;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, double temperature) {
    double pressure;
    pressure = (double)raw_pressure;
    return pressure;
}

// Function to log data with timestamp
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int result;
    int32_t raw_temperature, raw_pressure;
