    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Log data
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

