#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60

// Define the pressure registers
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB

// Define the scaling factor
#define SCALING_FACTOR 0.1

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read pressure from the MLX90819 sensor
int read_pressure(int fd, float *pressure) {
    uint8_t msb, lsb;
    int16_t raw_pressure;

    // Trigger a measurement (replace with actual trigger command if needed)
    // For MLX90819, a simple read from a register might suffice.
    // If a trigger command is needed, add it here.
    // For example, writing to a register to start a measurement:
    // uint8_t trigger_cmd = 0x01; // Example trigger command
    // if (write(fd, &trigger_cmd, 1) != 1) {
    //     fprintf(stderr, "Error writing trigger command: %s\n", strerror(errno));
    //     return -1;
    // }
    // usleep(10000); // Wait for the measurement to complete (adjust as needed)

    // Read the MSB
    if (write(fd, &PRESSURE_MSB_REG, 1) != 1) {
        fprintf(stderr, "Error writing to MSB register: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB: %s\n", strerror(errno));
        return -1;
    }

    // Read the LSB
    if (write(fd, &PRESSURE_LSB_REG, 1) != 1) {
        fprintf(stderr, "Error writing to LSB register: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB: %s\n", strerror(errno));
        return -1;
    }

    // Combine the MSB and LSB to form the raw pressure value
    raw_pressure = (msb << 8) | lsb;

    // Convert the raw pressure value to kPa
    *pressure = (float)raw_pressure * SCALING_FACTOR;

    return 0;
}

int main() {
    time_t current_time;
    struct tm *time_info;
    float pressure;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
