            time_info = localtime(&current_time);

            // Print the timestamp and pressure value to stdout
            printf("%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f kPa\n",
                   time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                   time_info->tm_hour, time_info->tm_min, time_info->tm_sec, pressure);
        } else {
            // Get the current time
            current_time = time(NULL);
            time_info = localtime(&current_time);

            // Print an error message to stderr
            fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d, Error reading pressure\n",
                    time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                    time_info->tm_hour, time_info->tm_min, time_info->tm_sec);
        }

        // Wait for 1 second
        sleep(1);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(i2c_fd);
    return 0;
}

