#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_CMD 0x00
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_sensor_data(const uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from HIH6130
int read_sensor_data(uint8_t *data) {
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 40 ms)
    gpioDelay(40000); // 40 ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate sensor data (check status bits)
int validate_sensor_data(const uint8_t *data) {
    // Check status bits (bits 6 and 7 of the first byte)
    if ((data[0] & 0xC0) != 0) {
        fprintf(stderr, "Error: Invalid sensor data (status bits set)\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    uint16_t raw_temperature = ((uint16_t)data[0] << 6) | (data[1] >> 2);
    uint16_t raw_humidity = ((uint16_t)data[2] << 6) | (data[3] >> 2);

    sensor_data.temperature = raw_temperature * 165.0 / 16383.0 - 40.0;
    sensor_data.humidity = raw_humidity * 100.0 / 16383.0;

    return sensor_data;
}

// Log data to file with ISO-8601 timestamp
int log_data(sensor_data_t data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check file size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Truncate the file
        if (fp == NULL) {
            fprintf(stderr, "Error truncating log file: %s\n", LOG_FILE);
            return -1;
        }
    } else {
        rewind(fp);
    }

    // Write data to log file
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    uint8_t sensor_data[4];
    sensor_data_t processed_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("HIH6130 sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate sensor data
            if (validate_sensor_data(sensor_data) == 0) {
                // Convert data
                processed_data = convert_data(sensor_data);

                // Log data
                if (log_data(processed_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error validating sensor data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

