#include <string.h>

// Define GPIO pin for SENT data
#define SENT_GPIO 4

// Define SENT parameters
#define SYNC_PULSE_WIDTH 56
#define MIN_NIBBLE_PULSE_WIDTH 12
#define MAX_NIBBLE_PULSE_WIDTH 271
#define TIMEOUT_US 100000 // 100ms timeout

// Define pressure conversion parameters
#define PRESSURE_SCALE 0.1
#define PRESSURE_OFFSET 0.0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned char status;
    unsigned char data1;
    unsigned char data2;
    unsigned char data3;
    unsigned char checksum;
} SENT_Data;

// Function prototypes
int initialize_gpio();
int read_sent_data(SENT_Data *data);
int validate_checksum(const SENT_Data *data);
float convert_to_pressure(unsigned int raw_value);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Read SENT data from the sensor
int read_sent_data(SENT_Data *data) {
    int i, j;
    int level, last_level;
    int pulse_width;
    unsigned int tick;
    unsigned int start_tick;

    // Wait for the start of the synchronization pulse
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for start of sync pulse\n");
            return -1; // Timeout
        }
    }

    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
