#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define EXPECTED_DEVICE_ID 0x0117
#define TEMP_SCALE 0.0078125
#define SAMPLE_INTERVAL 60 // seconds
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    const char *filename;
    int sample_interval;
} config_t;

// Function prototypes
int init_pigpio();
int init_i2c(int bus, int addr);
int read_temperature(int handle, float *temperature);
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read temperature from TMP117 sensor
int read_temperature(int handle, float *temperature) {
    char buf[2];
    int16_t raw_temp;

    if (i2cReadI2CBlockData(handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * TEMP_SCALE;

    return 0;
}

// Write temperature to file
int write_temperature_to_file(float temperature) {
    uint32_t temp_uint32 = *((uint32_t *)&temperature);

    if (fwrite(&temp_uint32, sizeof(uint32_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .tmp117_address = TMP117_ADDR,
        .filename = FILENAME,
        .sample_interval = SAMPLE_INTERVAL
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.tmp117_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2) != 2) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint16_t device_id = (buf[0] << 8) | buf[1];
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }
    printf("Device ID verified: 0x%04X\n", device_id);

    // Open file for writing
    fp = fopen(config.filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.4f °C\n", temperature);
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to file, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, but continuing...\n");
        }

        sleep(config.sample_interval);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

