#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define TEMPERATURE_MIN -45.0
#define TEMPERATURE_MAX 125.0
#define HUMIDITY_MIN -6.0
#define HUMIDITY_MAX 125.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_i2c_data(int handle, uint8_t data);
int read_i2c_data(int handle, char *buffer, int count);
uint8_t calculate_crc8(const char *data, int len);
int validate_crc8(const char *data, int len, uint8_t crc);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write data to I2C bus
int write_i2c_data(int handle, uint8_t data) {
    int result = i2cWriteByteData(handle, 0, data);
    if (result < 0) {
        fprintf(stderr, "Failed to write data to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from I2C bus
int read_i2c_data(int handle, char *buffer, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data from I2C: %d\n", result);
        return -1;
    }
    return result;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const char *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
