#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for temperature data
typedef struct {
    float temperature;
    time_t timestamp;
} temperature_data_t;

// Circular buffer
temperature_data_t temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (big-endian)
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Apply temperature conversion formula
    *temperature = raw_temp * 0.0078125;

    return 0;
}

// Add temperature reading to circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Flush circular buffer to file
void flush_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(temperature_data_t), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write all data to log file\n");
    }

    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    flush_buffer_to_file();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            add_to_buffer(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

