int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void convert_data(int raw_mag, int raw_temp, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the Si7202
int read_sensor_data(sensor_data_t *data) {
    int raw_mag, raw_temp;

    // Read magnetic field data
    raw_mag = i2cReadWordData(i2c_handle, MAG_REG);
    if (raw_mag < 0) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", raw_mag);
        return -1;
    }

    // Read temperature data
    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temp);
        return -1;
    }

    convert_data(raw_mag, raw_temp, data);
    return 0;
}

// Convert raw data to Gauss and Celsius
void convert_data(int raw_mag, int raw_temp, sensor_data_t *data) {
    data->magnetic_field = raw_mag * 0.1;
    data->temperature = raw_temp * 0.01 - 25.0;
