                fflush(log_file);
                fclose(log_file);
            } else {
                fprintf(stderr, "Error opening log file for NaN logging\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

