volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp117_address;
    char *log_file_name;
    int max_retries;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_temperature(int handle, float *temperature);
