    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read temperature from TMP117 sensor
int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to Celsius
    *temperature = raw_temp * 0.0078125;

    return 0;
}

// Log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
