#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_SCALE_FACTOR 0.8
#define FLOW_OFFSET 0.1
#define TEMP_SCALE_FACTOR 0.8
#define TEMP_OFFSET 0.1
#define TEMP_OFFSET_C -40.0
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *raw_flow, uint16_t *raw_temp);
sensor_data_t convert_data(uint16_t raw_flow, uint16_t raw_temp);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(uint16_t *raw_flow, uint16_t *raw_temp) {
    char buffer[4];
    int result = i2cReadDevice(i2c_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *raw_temp = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Convert raw sensor data to SLPM and Celsius
sensor_data_t convert_data(uint16_t raw_flow, uint16_t raw_temp) {
    sensor_data_t data;

    // Apply scaling and offset
    data.flow_rate = ((float)raw_flow / 16384.0 - FLOW_OFFSET) / FLOW_SCALE_FACTOR * 25.0;
    data.temperature = ((float)raw_temp / 4096.0 - TEMP_OFFSET) / TEMP_SCALE_FACTOR * 80.0 + TEMP_OFFSET_C;

    return data;
}

// Log sensor data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data.flow_rate, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    uint16_t raw_flow, raw_temp;
    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&raw_flow, &raw_temp) == 0) {
                sensor_data = convert_data(raw_flow, raw_temp);
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed. Retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "I2C read failed after %d retries. Skipping logging.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

