#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.log"

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

// Function prototypes
int read_dht11(DHT11Data *data);
int validate_checksum(const unsigned char *data);
void log_data(const DHT11Data *data);
void log_error(const char *message, int status_code);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read DHT11 data
int read_dht11(DHT11Data *data) {
    int i, j;
    unsigned char dht11_data[5] = {0, 0, 0, 0, 0};
    unsigned int pulse_lengths[85]; // Increased size to accommodate all pulses
    int pulse_count = 0;
    int status = 0;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed", 1);
        return 1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18 ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20 us

    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for the sensor to pull the line low
    int timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            log_error("Timeout waiting for DHT11 start signal (low)", 2);
            status = 2;
            goto cleanup;
        }
    }

    // Wait for the sensor to pull the line high
    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            log_error("Timeout waiting for DHT11 start signal (high)", 3);
            status = 3;
            goto cleanup;
        }
    }

    // Read the 40 data bits
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("Timeout waiting for DHT11 data bit (low)", 4);
                status = 4;
                goto cleanup;
            }
        }

        // Measure the high pulse duration
        long start_tick = gpioTick();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1); // Wait 1 us
            timeout++;
            if (timeout > 100) {
                log_error("Timeout waiting for DHT11 data bit (high)", 5);
                status = 5;
                goto cleanup;
            }
        }
        long end_tick = gpioTick();
        long pulse_length = end_tick - start_tick;

        // Determine the bit value based on the pulse length
        if (pulse_length > 40) {
            dht11_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate the checksum
    if (validate_checksum(dht11_data) != 0) {
        log_error("Checksum validation failed", 6);
        status = 6;
        goto cleanup;
    }

    // Convert data to temperature and humidity
    data->humidity = dht11_data[0];
    data->temperature = dht11_data[2];

    // Log the data
    log_data(data);

cleanup:
    gpioTerminate();
    return status;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4];
}

// Function to log the data to a file
void log_data(const DHT11Data *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Temperature: %d, Humidity: %d\n", timestamp, data->temperature, data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to log errors to a file
void log_error(const char *message, int status_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(error_log_file, "%s, Error: %s, Status Code: %d\n", timestamp, message, status_code);
    fflush(error_log_file); // Ensure data is written to disk immediately
}

int main() {
    DHT11Data data;
    int status;

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT11 sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        status = read_dht11(&data);
        if (status != 0) {
            log_error("DHT11 read failed", status);
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    fclose(log_file);
    fclose(error_log_file);

    return 0;
}

