        }
        long end_tick = gpioTick();
        long pulse_length = end_tick - start_tick;

        // Determine the bit value based on the pulse length
        if (pulse_length > 40) {
            dht11_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate the checksum
    if (validate_checksum(dht11_data) != 0) {
        log_error("Checksum validation failed", 6);
        status = 6;
        goto cleanup;
    }

    // Convert data to temperature and humidity
    data->humidity = dht11_data[0];
    data->temperature = dht11_data[2];

    // Log the data
    log_data(data);

cleanup:
    gpioTerminate();
    return status;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    return (data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4];
}

