#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "sht31d_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c_data(int handle, uint16_t data);
int read_i2c_data(int handle, char *buf, int count);
uint8_t crc8(const char *data, int len);
int validate_crc(const char *data, int len);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len) {
    if (len < 2) return 0; // Need at least 2 bytes for CRC
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Data conversion function
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Data logging function
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// I2C write function with retry
int write_i2c_data(int handle, uint16_t data) {
    char buf[2];
    buf[0] = (data >> 8) & 0xFF;
    buf[1] = data & 0xFF;

    for (int i = 0; i < RETRY_COUNT; i++) {
        int result = i2cWriteDevice(handle, buf, 2);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to I2C (attempt %d): %d\n", i + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    return -1; // Failure after retries
}

// I2C read function with retry
int read_i2c_data(int handle, char *buf, int count) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        int result = i2cReadDevice(handle, buf, count);
        if (result == count) {
            return 0; // Success
        }
        fprintf(stderr, "Error reading from I2C (attempt %d): %d\n", i + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }
    return -1; // Failure after retries
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (write_i2c_data(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error: Failed to send measurement command\n");
            log_data(-999.0, -999.0); // Log error
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read data
        char buf[6];
        if (read_i2c_data(i2c_handle, buf, 6) != 0) {
            fprintf(stderr, "Error: Failed to read data\n");
            log_data(-999.0, -999.0); // Log error
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(buf, 2) || !validate_crc(buf + 3, 2)) {
            fprintf(stderr, "Error: CRC validation failed\n");
            log_data(-999.0, -999.0); // Log error
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[3] << 8) | buf[4];
        sensor_data_t data = convert_data(raw_temperature, raw_humidity);

        // Log data
        if (log_data(data.temperature, data.humidity) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

