#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Define register addresses
#define DEVICE_ID_REG 0x00
#define RED_DATA_REG 0x64
#define GREEN_DATA_REG 0x66
#define BLUE_DATA_REG 0x68

// Define McCamy coefficients
#define A 3.1847
#define B -0.0031416
#define C 0.000000144

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
float calculate_cct(sensor_data_t data);
float calculate_average_cct(float cct1, float cct2);
int log_cct_data(float average_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    int device_id;

    // Read device ID
    device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    // Verify device ID
    if (device_id != 0x2A) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buffer[6];
    int result;

    // Read red, green, and blue data in one go
    result = i2cReadI2CBlockData(i2c_handle, RED_DATA_REG, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Convert data to little-endian
    data->red = (buffer[1] << 8) | buffer[0];
    data->green = (buffer[3] << 8) | buffer[2];
    data->blue = (buffer[5] << 8) | buffer[4];

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(sensor_data_t data) {
    float x, y, n;

    // Calculate x and y
    x = (float)data.red / ((float)data.red + (float)data.green + (float)data.blue);
    y = (float)data.green / ((float)data.red + (float)data.green + (float)data.blue);

    // Calculate n
    n = (x - 0.3320) / (0.1858 - y);

    // Calculate CCT
    float cct = (449.0 * powf(n, 3)) + (3525.0 * powf(n, 2)) + (6823.3 * n) + 5520.33;

    return cct;
}

// Function to calculate the average CCT
float calculate_average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log CCT data to a CSV file
int log_cct_data(float average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open log file in append mode
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    // Close log file
    fclose(log_file);

    return 0;
}

int main() {
    sensor_data_t sensor1_data, sensor2_data;
    float cct1, cct2, average_cct;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus for sensor 1
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus for sensor 2
    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C bus for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (initialize_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Failed to initialize sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Failed to initialize sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &sensor1_data) == 0) {
            // Calculate CCT for sensor 1
            cct1 = calculate_cct(sensor1_data);
        } else {
            cct1 = -1.0; // Indicate error
        }

        if (read_sensor_data(i2c_handle2, &sensor2_data) == 0) {
            // Calculate CCT for sensor 2
            cct2 = calculate_cct(sensor2_data);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT
        if (cct1 >= 0 && cct2 >= 0) {
            average_cct = calculate_average_cct(cct1, cct2);
        } else {
            average_cct = -1.0; // Indicate error
        }

        // Log CCT data
        if (average_cct >= 0) {
            if (log_cct_data(average_cct) != 0) {
                fprintf(stderr, "Failed to log CCT data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, skipping log entry\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C bus
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

