#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 800.0
#define OUTPUT_MIN 0.0
#define OUTPUT_MAX 32768.0
#define TEMP_OFFSET -40.0
#define TEMP_SCALE 0.01
#define LOG_FILE "pressure_log.txt"
#define SLEEP_DURATION 2 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_sensor_data(int handle, uint16_t *pressure, uint16_t *temperature);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from registers
int read_sensor_data(int handle, uint16_t *pressure, uint16_t *temperature) {
    char buf[4];
    int result;

    // Read pressure data
    result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }
    *pressure = (buf[0] << 8) | buf[1];

    // Read temperature data
    result = i2cReadI2CBlockData(handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - OUTPUT_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (OUTPUT_MAX - OUTPUT_MIN);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * TEMP_SCALE + TEMP_OFFSET;
}

// Log data to file
int log_data(float pressure_kPa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa, %.2f C\n", timestamp, pressure_kPa, temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_pressure, raw_temperature;
    float pressure_kPa, temperature_C;

    printf("Starting pressure monitoring...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_pressure, &raw_temperature) == 0) {
            // Convert data
            pressure_kPa = convert_pressure(raw_pressure);
            temperature_C = convert_temperature(raw_temperature);

            // Log data
            if (log_data(pressure_kPa, temperature_C) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 2 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

