#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);
void initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize pigpio and I2C
void initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        exit(1);
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        exit(1);
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off
}

// Cleanup resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            raw_temp = raw_temp >> 7; // Shift right by 7 bits
            return raw_temp * 0.5;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1000.0; // Indicate error
}

// Calculate running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control fan based on temperature
void control_fan(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD_ON) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temperature < TEMP_THRESHOLD_OFF) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    initialize();

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            float average_temperature = calculate_average();
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
            control_fan(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping fan control\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

