int validate_crc(const char *data, int count) {
    for (int i = 0; i < count; i += 3) {
        uint8_t crc = crc8(data + i, 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC mismatch at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

