    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)raw_pressure / PRESSURE_SCALE_FACTOR;
    sensor_data.temperature = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;

