            // Validate CRC
            if (validate_crc(buffer, 9) == 0) {
                // Convert data
                sensor_data = convert_data(buffer);

                // Log data
                log_data(sensor_data);

                // Check pressure threshold
                if (sensor_data.pressure > PRESSURE_THRESHOLD) {
                    fprintf(stderr, "Warning: Pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", sensor_data.pressure, PRESSURE_THRESHOLD);
                }
