#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
gpioPulse_t led_pulse[2];

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int stts2004_address;
    int led_pin;
    float temp_high;
    float temp_low;
} config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_led(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from STTS2004 sensor
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            // Combine MSB and LSB, right-shift by 4 bits
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            raw_temp >>= 4;

            // Convert to Celsius
            *temperature = raw_temp * 0.0625;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the LED using pigpio
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    float temperature;
    int led_state = 0; // 0 = off, 1 = on
    int init_result;

    // Initialize pigpio
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            // Control LED based on temperature
            if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
                control_led(LED_GPIO, 1);
                led_state = 1;
            } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
                control_led(LED_GPIO, 0);
                led_state = 0;
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(1);
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

