#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SCALE_FACTOR_OFFSET 6
#define SCALE_FACTOR_LENGTH 2
#define PRESSURE_OFFSET 0
#define TEMPERATURE_OFFSET 3
#define CRC_LENGTH 1
#define DATA_LENGTH 9
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int length);
int16_t extract_scale_factor(const char *data);
sensor_data_t convert_data(const char *data, int16_t scale_factor);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int length) {
    uint8_t crc = crc8(data, length - CRC_LENGTH);
    return (crc == (uint8_t)data[length - CRC_LENGTH]);
}

// Extract scale factor from the data
int16_t extract_scale_factor(const char *data) {
    return (int16_t)((data[SCALE_FACTOR_OFFSET] << 8) | data[SCALE_FACTOR_OFFSET + 1]);
}

// Convert raw data to differential pressure and temperature
sensor_data_t convert_data(const char *data, int16_t scale_factor) {
    sensor_data_t sensor_data;
    int32_t raw_pressure = (int32_t)((data[PRESSURE_OFFSET] << 8) | data[PRESSURE_OFFSET + 1]);
    int32_t raw_temperature = (int32_t)((data[TEMPERATURE_OFFSET] << 8) | data[TEMPERATURE_OFFSET + 1]);

    sensor_data.differential_pressure = (float)raw_pressure / scale_factor;
    sensor_data.temperature = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa, %.2f °C\n", timestamp, data.differential_pressure, data.temperature);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    char data[DATA_LENGTH];
    int16_t scale_factor;
    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < RETRY_COUNT) {
            // Send measurement command
            if (send_command(i2c_handle, MEASURE_CMD) != 0) {
                fprintf(stderr, "Failed to send measurement command, retry %d\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Wait for measurement (at least 45 ms)
            gpioDelay(45000); // 45 ms

            // Read data
            if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
                fprintf(stderr, "Failed to read data, retry %d\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Validate CRC
            if (!validate_crc(data, PRESSURE_OFFSET + CRC_LENGTH) || !validate_crc(data + PRESSURE_OFFSET + CRC_LENGTH, TEMPERATURE_OFFSET + CRC_LENGTH)) {
                fprintf(stderr, "CRC validation failed, retry %d\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            // Extract scale factor
            scale_factor = extract_scale_factor(data);

            // Convert data
            sensor_data = convert_data(data, scale_factor);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data, retry %d\n", retries + 1);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                continue;
            }

            break; // Exit retry loop if successful
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        // Wait before next measurement
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

