#define MEASURE_TEMP_CMD 0xF3
#define MEASURE_HUMID_CMD 0xF5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd;
    uint8_t buf[2];
    int result;
    int retries;

    // Measure Temperature
    cmd = MEASURE_TEMP_CMD;
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(20); // Wait for measurement
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                uint16_t raw_temp = (buf[0] << 8) | buf[1];
                data->temperature = convert_temperature(raw_temp);
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
        }
        gpioDelay(RETRY_DELAY_MS);
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Measure Humidity
    cmd = MEASURE_HUMID_CMD;
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            gpioDelay(20); // Wait for measurement
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                uint16_t raw_humidity = (buf[0] << 8) | buf[1];
                data->humidity = convert_humidity(raw_humidity);
                break; // Success, exit retry loop
            } else {
