            }
        } else {
            fprintf(stderr, "Error writing humidity command (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
        }
        gpioDelay(RETRY_DELAY_MS);
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

