#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int configure_hdc1080();
int read_hdc1080(sensor_data_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure HDC1080
int configure_hdc1080() {
    // Configure for 14-bit temperature and humidity resolution
    uint16_t config_value = 0x0000; // Default configuration
    int result = i2cWriteWordData(i2c_handle, CONFIGURATION_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(sensor_data_t *data) {
    uint8_t buffer[4];
    int result;

    // Trigger measurement by writing to temperature register
    result = i2cWriteByte(i2c_handle, TEMPERATURE_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes of data (temperature MSB, temperature LSB, humidity MSB, humidity LSB)
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)buffer, 4);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB for temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[2] << 8) | buffer[3];

    // Convert raw values to temperature and humidity
    data->temperature = convert_temperature(raw_temperature);
    data->humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((float)raw_temp / 65536.0) * 165.0 - 40.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return ((float)raw_humidity / 65536.0) * 100.0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);

    // Close log file
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

