#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2CE0
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int write_i2c(int fd, uint16_t command);
int read_i2c(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
float convert_ticks_to_celsius(uint16_t ticks);
int log_temperature(float temperature);
void signal_handler(int sig);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int write_i2c(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read function
int read_i2c(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Temperature conversion function
float convert_ticks_to_celsius(uint16_t ticks) {
    return -45.0 + 175.0 * (float)ticks / 65535.0;
}

// Logging function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, STS40_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        uint16_t raw_temperature;
        float temperature_celsius;

        // Send measurement command
        if (write_i2c(i2c_fd, MEASURE_CMD_HIGH_REP) < 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion (10 ms)
        usleep(10000);

        // Read temperature data
        if (read_i2c(i2c_fd, data, 3) < 0) {
            fprintf(stderr, "Error reading temperature data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // CRC check
        if (crc8(data, 2) != data[2]) {
            fprintf(stderr, "CRC check failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature
        raw_temperature = (data[0] << 8) | data[1];
        temperature_celsius = convert_ticks_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature_celsius) < 0) {
            fprintf(stderr, "Error logging temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        printf("Temperature: %.2f °C\n", temperature_celsius);

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

