#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc8(const uint8_t *data, int count);
int validate_crc(uint8_t crc, uint8_t calculated_crc);
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature, int16_t raw_scale_factor);
int log_data(FILE *fp, float pressure_Pa, float temperature_C);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send a command to the SDP810
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Read data from the SDP810
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int count) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t crc, uint8_t calculated_crc) {
    return crc == calculated_crc;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temperature, int16_t raw_scale_factor) {
    sensor_data_t data;
    data.pressure_Pa = (float)raw_pressure / (float)raw_scale_factor;
    data.temperature_C = (float)raw_temperature / 200.0;
    return data;
}

// Log data to file
int log_data(FILE *fp, float pressure_Pa, float temperature_C) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    int result = fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    if (result < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature, raw_scale_factor;
        uint8_t pressure_crc, temperature_crc, scale_factor_crc;
        sensor_data_t sensor_data;

        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            log_data(log_file, -999.0, -999.0); // Log error
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(50); // Wait 50 ms

        // Read data
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            log_data(log_file, -999.0, -999.0); // Log error
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Extract raw data and CRC values
        raw_pressure = (int16_t)((data[0] << 8) | data[1]);
        pressure_crc = data[2];
        raw_temperature = (int16_t)((data[3] << 8) | data[4]);
        temperature_crc = data[5];
        raw_scale_factor = (int16_t)((data[6] << 8) | data[7]);
        scale_factor_crc = data[8];

        // Calculate CRC values
        uint8_t calculated_pressure_crc = calculate_crc8(data, 2);
        uint8_t calculated_temperature_crc = calculate_crc8(data + 3, 2);
        uint8_t calculated_scale_factor_crc = calculate_crc8(data + 6, 2);

        // Validate CRC values
        if (!validate_crc(pressure_crc, calculated_pressure_crc) ||
            !validate_crc(temperature_crc, calculated_temperature_crc) ||
            !validate_crc(scale_factor_crc, calculated_scale_factor_crc)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            log_data(log_file, -999.0, -999.0); // Log error
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        sensor_data = convert_data(raw_pressure, raw_temperature, raw_scale_factor);

        // Log data
        if (log_data(log_file, sensor_data.pressure_Pa, sensor_data.temperature_C) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_data.pressure_Pa, sensor_data.temperature_C);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

