#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_MEASUREMENT 0xE000
#define BUFFER_CAPACITY 100
#define LOGGING_INTERVAL 60
#define RETRY_COUNT 3

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t data_buffer;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
int validate_crc(uint8_t data[], int count);
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void *logging_thread(void *arg);
void signal_handler(int signal);
void log_error(const char *message);
void log_data(const char *message);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int count) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < count; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
