            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0xFF);
}

// Read CO2, temperature, and humidity data from the SCD40
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (send_command(READ_MEASUREMENT) != 0) {
            log_error("Failed to send read measurement command");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(1); // Small delay after sending command

        if (read_data(data, 9) != 0) {
            log_error("Failed to read measurement data");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate CRC checksums
        if (!validate_crc(data, 2) || !validate_crc(data + 3, 2) || !validate_crc(data + 6, 2)) {
