        }

        // Extract data
        *co2 = (data[0] << 8) | data[1];
        uint16_t raw_temperature = (data[3] << 8) | data[4];
        uint16_t raw_humidity = (data[6] << 8) | data[7];

        // Convert data
        *temperature = -45 + 175 * (float)raw_temperature / 65535;
        *humidity = 100 * (float)raw_humidity / 65535;

        return 0; // Success
    }

    log_error("Failed to read SCD40 data after multiple retries");
    return -1; // Failure after retries
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from the circular buffer
sensor_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    sensor_data_t data = buffer->buffer[(buffer->tail + index) % BUFFER_CAPACITY];
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

// Logging thread function
void *logging_thread(void *arg) {
    time_t current_time;
    char filename[100];
    FILE *fp;
    sensor_data_t data;

    while (running) {
        sleep(LOGGING_INTERVAL);

        current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        strftime(filename, sizeof(filename), "/var/log/scd40_data/scd40_data_%Y%m%d_%H%M%S.csv", time_info);

        // Create directory if it doesn't exist
        struct stat st = {0};
        if (stat("/var/log/scd40_data", &st) == -1) {
            mkdir("/var/log/scd40_data", 0777);
        }

        fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open log file for writing");
            continue;
        }

        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

        pthread_mutex_lock(&data_buffer.mutex);
        for (int i = 0; i < data_buffer.count; i++) {
            data = get_from_buffer(&data_buffer, i);
            fprintf(fp, "%ld,%u,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
        }
        pthread_mutex_unlock(&data_buffer.mutex);

        fclose(fp);
        log_data(filename);
    }

    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Log error messages to file
void log_error(const char *message) {
    FILE *fp = fopen("/var/log/scd40_error.log", "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Log data messages to file
void log_data(const char *message) {
    FILE *fp = fopen("/var/log/scd40_data.log", "a");
    if (fp == NULL) {
        perror("Failed to open data log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] DATA: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    pthread_t logging_thread_id;
    uint16_t co2;
    float temperature, humidity;
    sensor_data_t data;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Start periodic measurement
    if (send_command(START_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create logging thread
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        send_command(STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        sleep(5);

        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            // Get current timestamp
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;

            // Add data to buffer
            add_to_buffer(&data_buffer, data);

            char log_message[200];
            snprintf(log_message, sizeof(log_message), "CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%RH", co2, temperature, humidity);
            log_data(log_message);
        } else {
            log_error("Failed to read sensor data");
        }
    }

    // Stop periodic measurement
    if (send_command(STOP_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush remaining data to file
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char filename[100];
    strftime(filename, sizeof(filename), "/var/log/scd40_data/scd40_data_%Y%m%d_%H%M%S.csv", time_info);

    // Create directory if it doesn't exist
    struct stat st = {0};
    if (stat("/var/log/scd40_data", &st) == -1) {
        mkdir("/var/log/scd40_data", 0777);
    }

    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        log_error("Failed to open log file for writing");
    } else {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
        pthread_mutex_lock(&data_buffer.mutex);
        for (int i = 0; i < data_buffer.count; i++) {
            data = get_from_buffer(&data_buffer, i);
            fprintf(fp, "%ld,%u,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
        }
        pthread_mutex_unlock(&data_buffer.mutex);
        fclose(fp);
        log_data(filename);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    pthread_mutex_destroy(&data_buffer.mutex);

    return 0;
}

