#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SCALE_FACTOR 1000.0
#define TEMP_OFFSET -45.0
#define TEMP_SCALE 175.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t crc8(const char *data, int len);
int validate_crc(uint8_t crc, uint8_t calculated_crc);
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temp, uint16_t raw_scale);
int log_data(FILE *fp, float pressure_Pa, float temperature_C);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint8_t crc, uint8_t calculated_crc) {
    return crc == calculated_crc;
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the SDP810
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the SDP810
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(int16_t raw_pressure, int16_t raw_temp, uint16_t raw_scale) {
    sensor_data_t data;
    data.pressure_Pa = (float)raw_pressure * (float)raw_scale / SCALE_FACTOR;
    data.temperature_C = TEMP_OFFSET + (float)raw_temp * TEMP_SCALE / 65535.0;
    return data;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure_Pa, float temperature_C) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    int result = fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
    if (result < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for measurement (at least 45 ms)
        gpioDelay(50);

        // Read data
        char buffer[9];
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract raw data
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint8_t pressure_crc = buffer[2];
        int16_t raw_temp = (buffer[3] << 8) | buffer[4];
        uint8_t temp_crc = buffer[5];
        uint16_t raw_scale = (buffer[6] << 8) | buffer[7];
        uint8_t scale_crc = buffer[8];

        // CRC validation
        if (!validate_crc(pressure_crc, crc8(buffer, 2)) ||
            !validate_crc(temp_crc, crc8(buffer + 3, 2)) ||
            !validate_crc(scale_crc, crc8(buffer + 6, 2))) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_pressure, raw_temp, raw_scale);

        // Log data
        if (log_data(log_file, data.pressure_Pa, data.temperature_C) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

