#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10110 I2C address
#define ICP10110_ADDR 0x63

// ICP-10110 register addresses
#define WHO_AM_I_REG 0x08
#define PRESSURE_MSB_REG 0x00
#define TEMP_MSB_REG 0x03
#define CALIB_START_REG 0x05

// Calibration coefficients
int16_t c0, c1, c00, c10, c01, c11, c20, c21;

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the ICP-10110 sensor
int init_icp10110() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor identity
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    printf("WHO_AM_I: 0x%02X (Correct)\n", who_am_i);

    // Read calibration coefficients
    char calib_data[16];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, CALIB_START_REG, calib_data, 16);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", bytes_read);
        i2cClose(i2c_handle);
        return -1;
    }

    c0 = (calib_data[0] << 8) | calib_data[1];
    c1 = (calib_data[2] << 8) | calib_data[3];
    c00 = (calib_data[4] << 8) | calib_data[5];
    c10 = (calib_data[6] << 8) | calib_data[7];
    c01 = (calib_data[8] << 8) | calib_data[9];
    c11 = (calib_data[10] << 8) | calib_data[11];
    c20 = (calib_data[12] << 8) | calib_data[13];
    c21 = (calib_data[14] << 8) | calib_data[15];

    printf("Calibration coefficients read successfully.\n");

    return 0;
}

// Function to read raw pressure and temperature data from the sensor
int read_raw_data(int32_t *pressure, int32_t *temperature) {
    char data[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB_REG, data, 6);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", bytes_read);
        return -1;
    }

    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    *temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    return 0;
}

// Function to convert raw data to hPa and Celsius
sensor_data_t convert_data(int32_t raw_pressure, int32_t raw_temperature) {
    sensor_data_t data;

    // Conversion formulas from ICP-10110 datasheet
    float p_scaled = (float)raw_pressure / 4096.0;
    float t_scaled = (float)raw_temperature / 4096.0;

    data.pressure = c00 + p_scaled * (c10 + p_scaled * c20) + t_scaled * (c01 + p_scaled * c11 + t_scaled * c21);
    data.temperature = c0 + t_scaled * c1 + p_scaled * (c00 + t_scaled * c10);

    return data;
}

// Function to get the current timestamp in ISO-8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to log data to a file
int log_data(const char *timestamp, float pressure, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f hPa, %.2f C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (init_icp10110() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;
        sensor_data_t sensor_data;
        char timestamp[21];

        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue; // Skip to the next iteration
        }
        gpioDelay(10); // Wait for measurement to complete

        // Read raw data
        if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert data
            sensor_data = convert_data(raw_pressure, raw_temperature);

            // Get timestamp
            get_timestamp(timestamp);

            // Log data
            if (log_data(timestamp, sensor_data.pressure, sensor_data.temperature) != 0) {
