#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define LED_GPIO 17
#define HIGH_ALTITUDE_THRESHOLD 95000.0
#define MEASUREMENT_COMMAND 0x4011
#define OTP_CALIBRATION_ADDR 0x66
#define OTP_CALIBRATION_LENGTH 4
#define DATA_LENGTH 6
#define CRC_LENGTH 2
#define POLLING_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
