int set_led_state(struct gpiod_line *line, int state);
int blink_led(struct gpiod_line *line, int frequency);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, (char *)data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s. Retrying...\n", reg, len, strerror(errno));
            retries--;
            usleep(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d).\n", reg, len);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_word(int fd, uint8_t reg, uint16_t data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_word_data(fd, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%04X): %s. Retrying...\n", reg, data, strerror(errno));
            retries--;
            usleep(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%04X).\n", reg, data);
    return -1; // Failure
}

// Function to read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
    uint8_t data[OTP_CALIBRATION_LENGTH];

    if (i2c_read_bytes(fd, OTP_CALIBRATION_ADDR, data, OTP_CALIBRATION_LENGTH) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        return -1;
    }

    c0 = (int32_t)((data[0] << 8) | data[1]);
    c1 = (int32_t)((data[2] << 8) | data[3]);

    // Placeholder for reading c00 and c10 from OTP.  These are not used in the simplified example.
    c00 = 0; // Example value
    c10 = 0; // Example value

    printf("Calibration coefficients: c0 = %d, c1 = %d, c00 = %d, c10 = %d\n", c0, c1, c00, c10);
    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_word(fd, 0x00, MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, DATA_LENGTH) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }
    return 0;
}

// Function to verify CRC
int verify_crc(uint8_t *data, int len) {
    uint16_t crc_calculated = 0xFFFF;
    uint16_t crc_received = (data[len] << 8) | data[len + 1];

    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x8000) {
                crc_calculated = (crc_calculated << 1) ^ 0x1021;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC check failed! Calculated: 0x%04X, Received: 0x%04X\n", crc_calculated, crc_received);
        return -1;
    }

    return 0;
}

