    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    uint8_t sensor_data[DATA_LENGTH + CRC_LENGTH];
    int32_t raw_pressure, raw_temperature;
    double pressure, temperature;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request LED line as output
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (adjust as needed)
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Verify CRC
        if (verify_crc(sensor_data, DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC check failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract raw pressure and temperature
        raw_pressure = (int32_t)((sensor_data[0] << 8) | sensor_data[1]);
        raw_temperature = (int32_t)((sensor_data[2] << 8) | sensor_data[3]);

        // Convert to Pascals and Celsius
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Print pressure and temperature
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < HIGH_ALTITUDE_THRESHOLD) {
            // High altitude warning
            printf("High altitude warning!\n");
            if (blink_led(led_line, 5) != 0) {
                fprintf(stderr, "Failed to blink LED in high altitude mode.\n");
            }
        } else {
            // Normal operation
            if (blink_led(led_line, 1) != 0) {
                fprintf(stderr, "Failed to blink LED in normal mode.\n");
            }
        }

        // Wait before next measurement
        sleep(POLLING_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_led_state(led_line, 0); // Turn off LED
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

