#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_sensor_data(sensor_data_t *data);
float convert_raw_to_celsius(uint16_t raw_temp);
void control_fan(float object_temp);
void log_temperature(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MLX90614
int read_sensor_data(sensor_data_t *data) {
    uint16_t raw_ambient_temp, raw_object_temp;
    int retries = 0;

    // Read ambient temperature
    while (retries < MAX_RETRIES) {
        raw_ambient_temp = i2cReadWordData(i2c_handle, AMBIENT_TEMP_REG);
        if (raw_ambient_temp >= 0) break; // Success
        fprintf(stderr, "Failed to read ambient temp (attempt %d): %d\n", retries + 1, raw_ambient_temp);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ambient temperature after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Read object temperature
    retries = 0;
    while (retries < MAX_RETRIES) {
        raw_object_temp = i2cReadWordData(i2c_handle, OBJECT_TEMP_REG);
        if (raw_object_temp >= 0) break; // Success
        fprintf(stderr, "Failed to read object temp (attempt %d): %d\n", retries + 1, raw_object_temp);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read object temperature after %d retries\n", MAX_RETRIES);
        return -1;
    }

    // Convert raw values to Celsius
    data->ambient_temp = convert_raw_to_celsius(raw_ambient_temp);
    data->object_temp = convert_raw_to_celsius(raw_object_temp);

    return 0;
}

// Convert raw temperature data to Celsius
float convert_raw_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan based on object temperature
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f °C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f °C)\n", object_temp);
    }
}

// Log temperature data to file
void log_temperature(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, data.ambient_temp, data.object_temp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate sensor readings
            if (sensor_data.ambient_temp > -50.0 && sensor_data.ambient_temp < 150.0 &&
                sensor_data.object_temp > -50.0 && sensor_data.object_temp < 150.0) {
                // Log temperature data
                log_temperature(sensor_data);

                // Control the fan
                control_fan(sensor_data.object_temp);
            } else {
                fprintf(stderr, "Invalid sensor readings: Ambient = %.2f, Object = %.2f\n", sensor_data.ambient_temp, sensor_data.object_temp);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

