#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 10 ms)

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C device: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned short raw_temperature = (buf[0] << 8) | buf[1];
        unsigned short raw_humidity = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
        *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to format temperature and humidity data into an HTML string
char *format_html(float temperature, float humidity) {
    char *html_string = (char *)malloc(256 * sizeof(char));
    if (html_string == NULL) {
        perror("Failed to allocate memory for HTML string");
        return NULL;
    }
    snprintf(html_string, 256, 
             "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>",
             temperature, humidity);
    return html_string;
}

// Function to handle HTTP requests
void handle_http_request(int client_socket) {
    float temperature, humidity;
    char *html_string;
    char buffer[1024];
    ssize_t bytes_received;

    // Read the request (basically ignore it for this example)
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }
    buffer[bytes_received] = '\0';

    // Read sensor data
    if (read_sht40(&temperature, &humidity) == 0) {
        // Format HTML
        html_string = format_html(temperature, humidity);
        if (html_string != NULL) {
            // Send HTTP response
            char response[512];
            snprintf(response, sizeof(response), 
                     "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: %ld\r\n\r\n%s",
                     strlen(html_string), html_string);
            send(client_socket, response, strlen(response), 0);
            free(html_string);
        } else {
            fprintf(stderr, "Failed to format HTML\n");
            const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nContent-Length: 21\r\n\r\nInternal Server Error";
            send(client_socket, error_response, strlen(error_response), 0);
        }
    } else {
        // Send error response
        const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nContent-Length: 21\r\n\r\nInternal Server Error";
        send(client_socket, error_response, strlen(error_response), 0);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;
    float temperature, humidity;
    char *html_string;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        // Handle HTTP request
        handle_http_request(new_socket);
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

