        return -1;
    }
    return handle;
}

// Read temperature from TMP102 sensor
int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 12-bit value
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);

    // Convert to Celsius
    *temperature = raw_temp * 0.0625;

    return 0;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, TMP102_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

