#define HUMIDITY_REG 0x02
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for heater disabled and 14-bit resolution
    uint8_t config_value = 0x00; // Default value, heater disabled, 14-bit resolution
    int result = i2cWriteByteData(i2c_handle, CONFIG_REG, config_value);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement() {
    uint8_t measurement_config = 0x01; // One-shot measurement
    int result = i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, measurement_config);
    if (result != 0) {
        fprintf(stderr, "Error writing to measurement config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[4];
    int result;

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[2] << 8) | buffer[3];

    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log sensor data with timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete (at least 7ms)
        gpioDelay(10);

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

