#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the continuous measurement command
#define MEASURE_COMMAND 0x362F

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send the continuous measurement command
int send_measurement_command() {
    char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    // Extract raw pressure and temperature values
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to log the sensor data
void log_sensor_data(sensor_data_t data) {
    printf("Pressure: %d, Temperature: %d\n", data.pressure, data.temperature);
}

// Function to close the I2C bus and terminate the pigpio library
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register the signal handler for Ctrl+C
