#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MAX_TEMP 200.0
#define MIN_TEMP 0.0
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
FILE *profile_file;
double integral = 0.0;
double previous_error = 0.0;

// Structure for temperature profile
typedef struct {
    double time;
    double temperature;
} TemperatureProfile;

// Function Prototypes
int read_max6675(int spi_handle);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double kp, double ki, double kd);
void set_relay_duty_cycle(int gpio_pin, double duty_cycle);
void log_data(FILE *log_file, double time, double setpoint, double actual_temperature, double duty_cycle);
int load_profile(const char *filename, TemperatureProfile **profile, int *profile_size);
void free_profile(TemperatureProfile *profile, int profile_size);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle) {
    char buffer[2];
    int result = spiRead(spi_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1; // Indicate error
    }

    // Check for open circuit
    if (buffer[1] & 0x04) {
        fprintf(stderr, "MAX6675 open circuit!\n");
        return -1; // Indicate error
    }

    // Extract temperature data
    int raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    return raw_temp;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error, double kp, double ki, double kd) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;

    // Clamp the output to the range [0, 1]
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(int gpio_pin, double duty_cycle) {
    int pulse_width = (int)(duty_cycle * 1000000); // Convert duty cycle to microseconds
    gpioPWM(gpio_pin, pulse_width);
}

// Function to log data to a file
void log_data(FILE *log_file, double time, double setpoint, double actual_temperature, double duty_cycle) {
    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f\n", time, setpoint, actual_temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load the temperature profile from a file
int load_profile(const char *filename, TemperatureProfile **profile, int *profile_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        return -1;
    }

    // Determine the number of lines in the file
    *profile_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        (*profile_size)++;
    }

    // Allocate memory for the profile
    *profile = (TemperatureProfile *)malloc(sizeof(TemperatureProfile) * (*profile_size));
    if (*profile == NULL) {
        fprintf(stderr, "Error allocating memory for profile\n");
        fclose(fp);
        return -1;
    }

    // Reset the file pointer to the beginning
    rewind(fp);

    // Read the profile data
    for (int i = 0; i < *profile_size; i++) {
        if (fgets(line, sizeof(line), fp) == NULL) {
            fprintf(stderr, "Error reading line %d from profile file\n", i + 1);
            free(*profile);
            fclose(fp);
            return -1;
        }

        if (sscanf(line, "%lf,%lf", &((*profile)[i].time), &((*profile)[i].temperature)) != 2) {
            fprintf(stderr, "Error parsing line %d from profile file\n", i + 1);
            free(*profile);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to free the allocated memory for the profile
void free_profile(TemperatureProfile *profile, int profile_size) {
    if (profile != NULL) {
        free(profile);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_relay_duty_cycle(RELAY_GPIO, 0.0); // Turn off the relay
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (profile_file != NULL) {
        fclose(profile_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    TemperatureProfile *profile = NULL;
    int profile_size = 0;
    if (load_profile(PROFILE_FILE, &profile, &profile_size) != 0) {
        fprintf(stderr, "Error loading temperature profile\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int current_profile_index = 0;
    time_t start_time = time(NULL);
    while (current_profile_index < profile_size) {
        // Read temperature from MAX6675
        int raw_temp = read_max6675(spi_handle);
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading temperature, using previous value\n");
            // Optionally, you could use a default temperature here or skip the current iteration
            continue;
        }

        double actual_temperature = (double)raw_temp * 0.25; // Convert to Celsius

        // Calculate PID output
        double duty_cycle = calculate_pid(profile[current_profile_index].temperature, actual_temperature, &integral, &previous_error, KP, KI, KD);

        // Set relay duty cycle
        set_relay_duty_cycle(RELAY_GPIO, duty_cycle);

        // Log data
        time_t current_time = time(NULL);
        double elapsed_time = difftime(current_time, start_time);
        log_data(log_file, elapsed_time, profile[current_profile_index].temperature, actual_temperature, duty_cycle);

        // Check if the current time exceeds the next profile point
        if (elapsed_time >= profile[current_profile_index].time) {
            current_profile_index++;
            if (current_profile_index >= profile_size) {
                printf("Profile complete!\n");
                break;
            }
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up
    set_relay_duty_cycle(RELAY_GPIO, 0.0); // Turn off the relay
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    free_profile(profile, profile_size);

    return 0;
}

