#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define MAX_SENSORS 4
#define LOG_FILE "greenhouse.log"
#define SLEEP_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int num_sensors = 0;
static char sensor_ids[MAX_SENSORS][32];
static float setpoint = 25.0; // Default setpoint
static float Kp = 1.0;       // Default Kp
static float Ki = 0.1;       // Default Ki
static float Kd = 0.01;      // Default Kd
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
int read_temperature(const char *sensor_id, float *temperature);
int validate_crc(const char *data);
float calculate_average_temperature();
float calculate_pid(float setpoint, float actual_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float average_temperature, float setpoint, float pid_output, int duty_cycle);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
int discover_sensors();

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from a DS18B20 sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[128];
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading from %s\n", filepath);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Validate CRC
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

// Function to validate CRC8 checksum
int validate_crc(const char *data) {
    unsigned char crc = crc8((unsigned char *)data, 8);
    return (crc == 0);
}

// Function to calculate the average temperature from all sensors
float calculate_average_temperature() {
    float sum = 0.0;
    int valid_sensors = 0;

    for (int i = 0; i < num_sensors; i++) {
        float temperature;
        if (read_temperature(sensor_ids[i], &temperature) == 0) {
            sum += temperature;
            valid_sensors++;
        }
    }

    if (valid_sensors > 0) {
        return sum / valid_sensors;
    } else {
        return -1000.0; // Indicate error
    }
}

// Function to calculate the PID output
float calculate_pid(float setpoint, float actual_temperature) {
    float error = setpoint - actual_temperature;
    integral += error * SLEEP_INTERVAL;
    float derivative = (error - previous_error) / SLEEP_INTERVAL;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the PWM range
    if (output < 0) {
        output = 0;
    } else if (output > PWM_RANGE) {
