// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from a DS18B20 sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[128];
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading from %s\n", filepath);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Validate CRC
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

