#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_INTERVAL 5 // seconds
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_aht20(float *humidity, float *temperature);
void control_dehumidifier(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Structure to hold AHT20 calibration data (example, adjust as needed)
typedef struct {
    uint8_t calibration_data[7];
} aht20_calibration_t;

aht20_calibration_t calibration;

// Function to initialize the AHT20 sensor
int init_aht20() {
    char init_cmd[] = {0xBE, 0x08, 0x00};
    int result;

    result = i2cWriteDevice(i2c_handle, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait for initialization to complete

    return 0;
}

// Function to read humidity and temperature from the AHT20 sensor
int read_aht20(float *humidity, float *temperature) {
    char trigger_cmd[] = {0xAC, 0x33, 0x00};
    char data[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result != 0) {
            fprintf(stderr, "Error triggering measurement: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(80000); // Wait 80 ms

        result = i2cReadDevice(i2c_handle, data, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading data: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Check status byte (bit 7 should be 0 for calibrated and not busy)
        if ((data[0] & 0x80) != 0) {
            fprintf(stderr, "Sensor busy or not calibrated, retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert data to humidity and temperature (example conversion, adjust as needed)
        uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
        uint32_t temperature_raw = ((uint32_t)data[3] & 0x0F) << 16 | ((uint32_t)data[4] << 8) | (uint32_t)data[5];

        *humidity = ((float)humidity_raw / 0x100000) * 100;
        *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Function to log data to the console
void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%, Temperature: %.2f°C\n", timestamp, humidity, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float humidity, temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("AHT20 dehumidifier control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read humidity and temperature
        result = read_aht20(&humidity, &temperature);
        if (result == 0) {
            // Log data
            log_data(humidity, temperature);

            // Control dehumidifier
            control_dehumidifier(humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next measurement
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("AHT20 dehumidifier control stopped.\n");

    return 0;
}

