#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define READ_INTERVAL 60 // seconds
#define MAX_RETRIES 3
#define RETRY_DELAY_BASE 1 // seconds

// Global variables
int i2c_fd = -1;
bool running = true;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char data);
float read_humidity(int fd);
int post_data(const char *url, const char *data);
void signal_handler(int sig);
void log_message(int priority, const char *message);

// I2C read function with retry
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            log_message(LOG_ERR, "I2C write failed");
            retries++;
            sleep(RETRY_DELAY_BASE * retries);
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            log_message(LOG_ERR, "I2C read failed");
            retries++;
            sleep(RETRY_DELAY_BASE * retries);
        }
    }

    log_message(LOG_ERR, "I2C read failed after multiple retries");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, unsigned char reg, unsigned char data) {
    int retries = 0;
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = data;

    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            log_message(LOG_ERR, "I2C write failed");
            retries++;
            sleep(RETRY_DELAY_BASE * retries);
        }
    }

    log_message(LOG_ERR, "I2C write failed after multiple retries");
    return -1; // Failure
}

// Function to read humidity from HTU21D
float read_humidity(int fd) {
    unsigned char data[3];
    unsigned int raw_humidity;
    float humidity;

    // Trigger measurement (no hold master)
    if (i2c_write_byte(fd, 0xE5, 0x00) != 0) {
        log_message(LOG_ERR, "Failed to trigger humidity measurement");
        return -1.0;
    }

    // Wait for measurement (at least 50ms)
    usleep(50000);

    // Read 3 bytes of data
    if (i2c_read_bytes(fd, 0x00, data, 3) != 0) {
        log_message(LOG_ERR, "Failed to read humidity data");
        return -1.0;
    }

    // Convert data to humidity
    raw_humidity = (data[0] << 8) | data[1];
    raw_humidity &= 0xFFFC; // Clear status bits

    humidity = -6.0 + 125.0 * (float)raw_humidity / 65536.0;

    return humidity;
}

// Function to post data to HTTP endpoint
int post_data(const char *url, const char *data) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char buffer[1024];
    ssize_t bytes_received;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Parse URL (very basic parsing for demonstration)
    char *host = strdup(url); // Duplicate the string
    char *path = strchr(host, '/');
    if (path == NULL) {
        log_message(LOG_ERR, "Invalid URL format");
        free(host);
        close(sockfd);
        return -1;
    }
    *path = '\0'; // Split host and path
    path++;

    // Resolve DNS (basic implementation, use getaddrinfo for robustness)
    struct hostent *server = gethostbyname(host);
    if (server == NULL) {
        log_message(LOG_ERR, "DNS resolution failed");
        free(host);
        close(sockfd);
        return -1;
    }

    // Configure server address
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);
    serv_addr.sin_port = htons(80); // Default HTTP port

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_message(LOG_ERR, "Connection failed");
        free(host);
        close(sockfd);
        return -1;
    }

    // Construct HTTP request
    snprintf(buffer, sizeof(buffer), "POST /%s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             path, host, strlen(data), data);

    // Send HTTP request
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        log_message(LOG_ERR, "Failed to send HTTP request");
        free(host);
        close(sockfd);
        return -1;
    }

    // Receive HTTP response (very basic implementation)
    memset(buffer, 0, sizeof(buffer));
    bytes_received = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "Failed to receive HTTP response");
        free(host);
        close(sockfd);
        return -1;
    }

    // Check HTTP status code (very basic check)
    if (strncmp(buffer, "HTTP/1.1 200 OK", 15) != 0) {
        log_message(LOG_ERR, "HTTP request failed with status code");
        free(host);
        close(sockfd);
        return -1;
    }

    free(host);
    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

int main() {
