    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        log_message(LOG_ERR, "Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_message(LOG_INFO, "Humidity monitor started");

    while (running) {
        // Read humidity
        humidity = read_humidity(i2c_fd);

        if (humidity >= 0.0) {
            // Format data as JSON
            time(&now);
            timeinfo = localtime(&now);
            strftime(json_data, sizeof(json_data), "{\"timestamp\": \"%Y-%m-%d %H:%M:%S\", \"humidity\": %.2f}", timeinfo, humidity);

            // Post data to API endpoint
            if (post_data(API_ENDPOINT, json_data) == 0) {
