            } else {
                log_message(LOG_ERR, "Failed to post data");
            }
        } else {
            log_message(LOG_ERR, "Failed to read humidity");
        }

        // Wait for the next interval
        sleep(READ_INTERVAL);
    }

    // Close I2C bus
    close(i2c_fd);

    log_message(LOG_INFO, "Humidity monitor stopped");

    return 0;
}

