#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_FILE_PREFIX "sensor_log_"
#define LOG_FILE_SUFFIX ".csv"
#define MAX_SENSORS 2
#define MAX_RETRIES 3
#define BACKOFF_MS 10

// Global variables
static volatile int running = 1;
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static FILE *log_file = NULL;
static char log_filename[256];
static time_t last_log_change = 0;

// Function prototypes
int init_tmp117();
int init_aht20();
int read_tmp117(float *temperature);
int read_aht20(float *temperature, float *humidity);
int read_pir_sensor();
void log_data(float temperature1, float humidity1, float temperature2, float humidity2, int motion_detected);
void signal_handler(int signal);
void cleanup();
void check_sensor_presence();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the TMP117 sensor
int init_tmp117() {
    i2c_handle_tmp117 = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Error opening I2C device for TMP117: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the AHT20 sensor
int init_aht20() {
    i2c_handle_aht20 = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Error opening I2C device for AHT20: %s\n", strerror(errno));
        return -1;
    }

    // Initialize AHT20 (High Accuracy Mode)
    char init_cmd[] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle_aht20, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %s\n", strerror(errno));
        i2cClose(i2c_handle_aht20);
        i2c_handle_aht20 = -1;
        return -1;
    }
    gpioDelay(10); // Wait for initialization to complete

    return 0;
}

// Function to read temperature from the TMP117 sensor
int read_tmp117(float *temperature) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int result = i2cReadDevice(i2c_handle_tmp117, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (big-endian)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read temperature and humidity from the AHT20 sensor
int read_aht20(float *temperature, float *humidity) {
    char measure_cmd[] = {0xAC, 0x33, 0x00};
    char buf[7];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Trigger measurement
        int result = i2cWriteDevice(i2c_handle_aht20, measure_cmd, 3);
        if (result != 0) {
            fprintf(stderr, "Error triggering AHT20 measurement: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
            continue;
        }

        gpioDelay(80); // Wait for measurement to complete (at least 75ms)

        // Read 7 bytes of data
        result = i2cReadDevice(i2c_handle_aht20, buf, 7);
        if (result == 7) {
            // Check busy bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy\n");
                gpioDelay(BACKOFF_MS);
                retries++;
                continue;
            }

            // Convert raw data to humidity and temperature
            uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
            uint32_t temperature_raw = ((uint32_t)buf[3] & 0x0F) << 16 | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

            *humidity = ((float)humidity_raw / 0x100000) * 100;
            *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading AHT20 data: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

// Function to log data to a CSV file
void log_data(float temperature1, float humidity1, float temperature2, float humidity2, int motion_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the log file needs to be rotated
    time_t current_day = time(NULL);
    struct tm *current_tm = localtime(&current_day);
    char current_date[16];
    strftime(current_date, sizeof(current_date), "%Y-%m-%d", current_tm);

    char log_date[16];
    strftime(log_date, sizeof(log_date), "%Y-%m-%d", localtime(&last_log_change));

    if (strcmp(current_date, log_date) != 0) {
        // Close the current log file
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }

        // Generate the new log filename
        snprintf(log_filename, sizeof(log_filename), "%s%s%s", LOG_FILE_PREFIX, current_date, LOG_FILE_SUFFIX);

        // Open the new log file
        log_file = fopen(log_filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }

        // Write the CSV header
        fprintf(log_file, "Timestamp,Temperature1(C),Humidity1(%%),Temperature2(C),Humidity2(%%),MotionDetected\n");
        last_log_change = current_day;
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%d\n", timestamp, temperature1, humidity1, temperature2, humidity2, motion_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to check sensor presence
void check_sensor_presence() {
    int tmp117_present = (i2c_handle_tmp117 >= 0);
    int aht20_present = (i2c_handle_aht20 >= 0);

    if (!tmp117_present) {
        fprintf(stderr, "Warning: TMP117 sensor not found.\n");
    }
    if (!aht20_present) {
        fprintf(stderr, "Warning: AHT20 sensor not found.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize sensors
    if (init_tmp117() != 0) {
        fprintf(stderr, "TMP117 initialization failed. Continuing without it.\n");
    }
    if (init_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed. Continuing without it.\n");
    }

    // Check sensor presence
    check_sensor_presence();

    // Generate initial log filename
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char current_date[16];
    strftime(current_date, sizeof(current_date), "%Y-%m-%d", t);
    snprintf(log_filename, sizeof(log_filename), "%s%s%s", LOG_FILE_PREFIX, current_date, LOG_FILE_SUFFIX);
    last_log_change = now;

    // Open the log file
    log_file = fopen(log_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write the CSV header
    fprintf(log_file, "Timestamp,Temperature1(C),Humidity1(%%),Temperature2(C),Humidity2(%%),MotionDetected\n");
    fflush(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float temperature1 = -999.0; // Default value for error
        float humidity1 = -999.0;    // Default value for error
        float temperature2 = -999.0; // Default value for error
        float humidity2 = -999.0;    // Default value for error

        // Read sensor data
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(&temperature1) != 0) {
                fprintf(stderr, "Failed to read TMP117 data.\n");
            }
        }
        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(&temperature2, &humidity2) != 0) {
                fprintf(stderr, "Failed to read AHT20 data.\n");
            }
        }

        int motion_detected = read_pir_sensor();

        // Log the data
        log_data(temperature1, humidity1, temperature2, humidity2, motion_detected);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

