// Function to initialize the TMP117 sensor
int init_tmp117() {
    i2c_handle_tmp117 = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Error opening I2C device for TMP117: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the AHT20 sensor
int init_aht20() {
    i2c_handle_aht20 = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Error opening I2C device for AHT20: %s\n", strerror(errno));
        return -1;
    }

    // Initialize AHT20 (High Accuracy Mode)
    char init_cmd[] = {0xBE, 0x08, 0x00};
    int result = i2cWriteDevice(i2c_handle_aht20, init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error initializing AHT20: %s\n", strerror(errno));
        i2cClose(i2c_handle_aht20);
        i2c_handle_aht20 = -1;
        return -1;
    }
    gpioDelay(10); // Wait for initialization to complete

    return 0;
}

// Function to read temperature from the TMP117 sensor
int read_tmp117(float *temperature) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int result = i2cReadDevice(i2c_handle_tmp117, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (big-endian)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read temperature and humidity from the AHT20 sensor
int read_aht20(float *temperature, float *humidity) {
    char measure_cmd[] = {0xAC, 0x33, 0x00};
    char buf[7];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Trigger measurement
        int result = i2cWriteDevice(i2c_handle_aht20, measure_cmd, 3);
        if (result != 0) {
            fprintf(stderr, "Error triggering AHT20 measurement: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
            continue;
        }

        gpioDelay(80); // Wait for measurement to complete (at least 75ms)

        // Read 7 bytes of data
        result = i2cReadDevice(i2c_handle_aht20, buf, 7);
        if (result == 7) {
            // Check busy bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy\n");
                gpioDelay(BACKOFF_MS);
                retries++;
                continue;
            }

            // Convert raw data to humidity and temperature
            uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
            uint32_t temperature_raw = ((uint32_t)buf[3] & 0x0F) << 16 | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

            *humidity = ((float)humidity_raw / 0x100000) * 100;
            *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading AHT20 data: %s (attempt %d)\n", strerror(errno), retries + 1);
            gpioDelay(BACKOFF_MS);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

