    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the log file needs to be rotated
    time_t current_day = time(NULL);
    struct tm *current_tm = localtime(&current_day);
    char current_date[16];
    strftime(current_date, sizeof(current_date), "%Y-%m-%d", current_tm);

    char log_date[16];
    strftime(log_date, sizeof(log_date), "%Y-%m-%d", localtime(&last_log_change));

    if (strcmp(current_date, log_date) != 0) {
        // Close the current log file
        if (log_file != NULL) {
            fclose(log_file);
            log_file = NULL;
        }

        // Generate the new log filename
        snprintf(log_filename, sizeof(log_filename), "%s%s%s", LOG_FILE_PREFIX, current_date, LOG_FILE_SUFFIX);

        // Open the new log file
        log_file = fopen(log_filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }

        // Write the CSV header
        fprintf(log_file, "Timestamp,Temperature1(C),Humidity1(%%),Temperature2(C),Humidity2(%%),MotionDetected\n");
        last_log_change = current_day;
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%d\n", timestamp, temperature1, humidity1, temperature2, humidity2, motion_detected);
