#define MOTOR_IN2_PIN 24

// Define I2C address for DHT22 sensor
#define DHT22_I2C_ADDR 0x22

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
