    if (i2cWriteByte(fd, 0x00) < 0) {
        perror("i2cWriteByte (address)");
        return -1;
    }
    gpioDelay(1); // Wait 1ms

    // Read 5 bytes of data
    if (i2cReadDevice(fd, (char *)data, 5) != 5) {
        perror("i2cReadDevice");
        return -1;
    }

    // Verify checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

// Function to control the L298N motor driver
void motor_forward(int ena_pin, int in1_pin, int in2_pin, int duration_sec) {
    // Enable the motor
    if (gpio_write(ena_pin, 1) < 0) {
        fprintf(stderr, "Error enabling motor\n");
        return;
    }

    // Set direction to forward
    if (gpio_write(in1_pin, 1) < 0) {
        fprintf(stderr, "Error setting IN1 pin\n");
        gpio_write(ena_pin, 0); // Disable motor on error
        return;
    }
    if (gpio_write(in2_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN2 pin\n");
        gpio_write(ena_pin, 0); // Disable motor on error
        return;
    }

    // Run the motor for the specified duration
    gpioDelay(duration_sec * 1000000); // Delay in microseconds

    // Stop the motor
    motor_stop(ena_pin, in1_pin, in2_pin);
}

// Function to stop the L298N motor driver
void motor_stop(int ena_pin, int in1_pin, int in2_pin) {
    // Disable the motor
    if (gpio_write(ena_pin, 0) < 0) {
        fprintf(stderr, "Error disabling motor\n");
    }

    // Set both direction pins low
    if (gpio_write(in1_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN1 pin low\n");
    }
    if (gpio_write(in2_pin, 0) < 0) {
        fprintf(stderr, "Error setting IN2 pin low\n");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    float temperature, humidity;
    int rain_detected;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, DHT22_I2C_ADDR, 0); // Bus 1, address 0x22, no flags
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(RAIN_SENSOR_PIN) < 0 ||
        gpio_export(MOTOR_ENA_PIN) < 0 ||
        gpio_export(MOTOR_IN1_PIN) < 0 ||
        gpio_export(MOTOR_IN2_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO pins\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(RAIN_SENSOR_PIN, "in") < 0 ||
        gpio_set_direction(MOTOR_ENA_PIN, "out") < 0 ||
        gpio_set_direction(MOTOR_IN1_PIN, "out") < 0 ||
        gpio_set_direction(MOTOR_IN2_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions\n");
        gpio_unexport(RAIN_SENSOR_PIN);
        gpio_unexport(MOTOR_ENA_PIN);
        gpio_unexport(MOTOR_IN1_PIN);
        gpio_unexport(MOTOR_IN2_PIN);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        // Read rain sensor
        rain_detected = gpio_read(RAIN_SENSOR_PIN);
        if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor\n");
        } else {
            // Read DHT22 sensor
            if (i2c_read_dht22(i2c_fd, &temperature, &humidity) == 0) {
                char log_message[256];
                snprintf(log_message, sizeof(log_message), "Rain detected: %d, Temperature: %.1f°C, Humidity: %.1f%%",
                         rain_detected, temperature, humidity);
                log_event(log_message);

                // Control motor if rain is detected
                if (rain_detected == 0) {
                    log_event("Rain detected, closing window");
                    motor_forward(MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_RUN_TIME);
                    log_event("Window closed");
                }
            } else {
                fprintf(stderr, "Error reading DHT22 sensor\n");
            }
        }

        // Wait 2 seconds
        sleep(2);
    }

    // Cleanup
    log_event("Cleaning up...");
    motor_stop(MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);
    gpio_unexport(RAIN_SENSOR_PIN);
    gpio_unexport(MOTOR_ENA_PIN);
    gpio_unexport(MOTOR_IN1_PIN);
    gpio_unexport(MOTOR_IN2_PIN);
    i2cClose(i2c_fd);
    gpioTerminate();
    log_event("System stopped");

    return 0;
}

