#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load sampling interval (in milliseconds)
#define SAMPLE_INTERVAL_MS 500

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Structure to hold CPU usage statistics
typedef struct {
    unsigned long long user;
    unsigned long long nice;
    unsigned long long system;
    unsigned long long idle;
    unsigned long long iowait;
    unsigned long long irq;
    unsigned long long softirq;
    unsigned long long steal;
    unsigned long long guest;
    unsigned long long guest_nice;
} cpu_stats_t;

// Function prototypes
int initialize_gpio();
void set_led_color(int red, int green, int blue);
float calculate_cpu_load(cpu_stats_t prev_stats, cpu_stats_t current_stats);
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue);
void signal_handler(int signal);
int read_cpu_stats(cpu_stats_t *stats);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    return 0;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Common anode, so invert the PWM values
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(cpu_stats_t *stats) {
    FILE *fp;
    unsigned long long cpu_time[10];
    char line[256];

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Failed to open /proc/stat");
        return 1;
    }

    // Read the first line (CPU statistics)
    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Failed to read /proc/stat");
        fclose(fp);
        return 1;
    }

    // Parse the CPU statistics
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &cpu_time[0], &cpu_time[1], &cpu_time[2], &cpu_time[3],
               &cpu_time[4], &cpu_time[5], &cpu_time[6], &cpu_time[7],
               &cpu_time[8], &cpu_time[9]) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat line\n");
        fclose(fp);
        return 1;
    }

    fclose(fp);

    stats->user = cpu_time[0];
    stats->nice = cpu_time[1];
    stats->system = cpu_time[2];
    stats->idle = cpu_time[3];
    stats->iowait = cpu_time[4];
    stats->irq = cpu_time[5];
    stats->softirq = cpu_time[6];
    stats->steal = cpu_time[7];
    stats->guest = cpu_time[8];
    stats->guest_nice = cpu_time[9];

    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(cpu_stats_t prev_stats, cpu_stats_t current_stats) {
    unsigned long long prev_idle = prev_stats.idle + prev_stats.iowait;
    unsigned long long current_idle = current_stats.idle + current_stats.iowait;

    unsigned long long prev_non_idle = prev_stats.user + prev_stats.nice + prev_stats.system + prev_stats.irq + prev_stats.softirq + prev_stats.steal;
    unsigned long long current_non_idle = current_stats.user + current_stats.nice + current_stats.system + current_stats.irq + current_stats.softirq + current_stats.steal;

    unsigned long long prev_total = prev_idle + prev_non_idle;
    unsigned long long current_total = current_idle + current_non_idle;

    unsigned long long totald = current_total - prev_total;
    unsigned long long idled = current_idle - prev_idle;

    float cpu_usage = (float)(totald - idled) / totald;

    return cpu_usage;
}

// Function to map CPU load to RGB color
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load <= 0.5) {
        // Green to Yellow (0% to 50%)
        *red = 0;
        *green = (int)(255 * (cpu_load / 0.5));
        *blue = 0;
    } else {
        // Yellow to Red (50% to 100%)
        *red = (int)(255 * ((cpu_load - 0.5) / 0.5));
        *green = 255;
        *blue = 0;
    }
}

int main() {
    cpu_stats_t prev_stats, current_stats;
    float cpu_load;
    int red, green, blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read initial CPU statistics
    if (read_cpu_stats(&prev_stats) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current CPU statistics
        if (read_cpu_stats(&current_stats) != 0) {
            fprintf(stderr, "Error reading CPU stats, exiting...\n");
            break;
        }

        // Calculate CPU load
        cpu_load = calculate_cpu_load(prev_stats, current_stats);

        // Map CPU load to color
        map_cpu_load_to_color(cpu_load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous statistics
        prev_stats = current_stats;

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Turn off the LED before exiting
    set_led_color(0, 0, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

