#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Temperature thresholds (°C)
#define TEMP_LOW 25.0
#define TEMP_MED_LOW 40.0
#define TEMP_MED_HIGH 60.0
#define TEMP_HIGH 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_max31855(int *thermocouple_temp, int *internal_temp, int *fault);
float convert_thermocouple_temp(int raw_temp);
int calculate_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from MAX31855
int read_max31855(int *thermocouple_temp, int *internal_temp, int *fault) {
    char tx_buffer[4] = {0};
    char rx_buffer[4];

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract data from the received bytes
    *thermocouple_temp = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 2;
    *internal_temp = ((rx_buffer[2] << 8) | rx_buffer[3]) >> 4;
    *fault = rx_buffer[3] & 0x07;

    return 0;
}

// Function to convert raw thermocouple temperature to Celsius
float convert_thermocouple_temp(int raw_temp) {
    if (raw_temp & 0x2000) {
        // Negative temperature
        return -((~raw_temp & 0x3FFF) + 1) * 0.25;
    } else {
        // Positive temperature
        return raw_temp * 0.25;
    }
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature < TEMP_MED_LOW) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_MED_LOW - TEMP_LOW) * 50.0);
    } else if (temperature < TEMP_MED_HIGH) {
        duty_cycle = 50 + (int)((temperature - TEMP_MED_LOW) / (TEMP_MED_HIGH - TEMP_MED_LOW) * 150.0);
    } else {
        duty_cycle = 200;
    }

    return duty_cycle;
}

// Function to set fan speed using hardware PWM
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(FAN_GPIO, duty_cycle);
    return 0;
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_fan_speed(0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
    print_buffer();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    printf("Temperature monitoring and fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int thermocouple_temp_raw, internal_temp_raw, fault;

        // Read data from MAX31855
        if (read_max31855(&thermocouple_temp_raw, &internal_temp_raw, &fault) == 0) {
            // Convert thermocouple temperature
            float thermocouple_temp = convert_thermocouple_temp(thermocouple_temp_raw);

            // Check for fault conditions
            if (fault != 0) {
                fprintf(stderr, "MAX31855 Fault: ");
                if (fault & 0x01) fprintf(stderr, "OC ");
                if (fault & 0x02) fprintf(stderr, "SCG ");
                if (fault & 0x04) fprintf(stderr, "SCV ");
                fprintf(stderr, "\n");
            } else {
                // Calculate duty cycle
                int duty_cycle = calculate_duty_cycle(thermocouple_temp);

                // Set fan speed
                set_fan_speed(duty_cycle);

                // Log data
                log_data(thermocouple_temp, duty_cycle);

                printf("Temperature: %.2f°C, Duty Cycle: %d\n", thermocouple_temp, duty_cycle);
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

