#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_enabled = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
double calculate_altitude(double pressure);
void log_data(double temperature, double pressure, double altitude);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the I2C bus
uint16_t read_i2c_uword(int handle, uint8_t reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C block data from register 0x%02X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &buf[1], 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    char reg = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, buf[0], &buf[1], 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms (minimum) for OSS=3

    char reg = BMP180_REG_MSB;
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, reg, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    int32_t X4 = ((int32_t)ac2 * B6) / pow(2, 11);
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) / 4;

    uint32_t X1_u = ((uint32_t)ac3 * B6) / pow(2, 13);
    uint32_t X2_u = ((uint32_t)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    uint32_t B4 = ((uint32_t)ac4 * (uint32_t)(X1_u + X2_u + 32768)) / pow(2, 15);

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure;
}

// Function to calculate altitude in meters
double calculate_altitude(double pressure)
{
    double seaLevelPressure = 101325.0; // Standard sea level pressure in Pa
    return 44330.0 * (1.0 - pow(pressure / seaLevelPressure, 0.1903));
}

// Function to log data to a file
void log_data(double temperature, double pressure, double altitude)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, pressure, altitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick)
{
    logging_enabled = !logging_enabled;
    printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge
    gpioSetAlertFunc(INTERRUPT_PIN, interrupt_handler);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Data logging is initially disabled. Press the button connected to GPIO%d to toggle logging.\n", INTERRUPT_PIN);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;
            double temperature, pressure, altitude;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, raw_temperature);
                altitude = calculate_altitude(pressure);

                // Log data
                log_data(temperature, pressure, altitude);

                printf("Temperature: %.2f C, Pressure: %.2f Pa, Altitude: %.2f m\n", temperature, pressure, altitude);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }

        gpioDelay(1000000); // Wait 1 second
    }

    return 0;
}

