#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int cs_pin;
    char log_file[64];
    int sample_interval;
} config_t;

// Function prototypes
int spi_init(int cs_pin);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int max31865_init(int fd);
int read_rtd(int fd, float *temperature);
void log_data(float temperature);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(int cs_pin) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer Function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MAX31865 Initialization
int max31865_init(int fd) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Configure MAX31865 (3-wire, bias voltage enabled, auto conversion)
    tx_buf[0] = MAX31865_CONFIG_REG | 0x80; // Write command
    tx_buf[1] = 0xC2;                           // Configuration value

    if (spi_transfer(fd, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    return 0;
}

// Read RTD Value
int read_rtd(int fd, float *temperature) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int16_t rtd_raw;
    float rtd_resistance;

    // Read RTD MSB and LSB registers
    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x80; // Read command
    tx_buf[1] = 0x00;                           // Dummy byte
    tx_buf[2] = 0x00;                           // Dummy byte

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading RTD registers\n");
        return -1;
    }

    // Combine MSB and LSB to get RTD value
    rtd_raw = ((rx_buf[1] << 8) | rx_buf[2]) >> 1; // Remove fault bit

    // Convert RTD value to resistance (assuming 430 ohms reference resistor)
    rtd_resistance = rtd_raw * 430.0 / 32768.0;

    // Calculate temperature using Callendar-Van Dusen equation
    *temperature = (rtd_resistance - 100.0) / 0.385;

    return 0;
}

// Log Data to File
void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(CS_PIN);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init(spi_fd) < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_rtd(spi_fd, &temperature) == 0) {
            // Log data
            log_data(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

