#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int init_i2c(int bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_calibration_data(int fd, struct bme280_calib_data *calib);
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity);
double compensate_temperature(int32_t raw_temperature, struct bme280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bme280_calib_data calib);
double compensate_humidity(int32_t raw_humidity, int32_t t_fine, struct bme280_calib_data calib);
int log_data(FILE *fp, double temperature, double humidity, double pressure);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C interface
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single byte from a BME280 register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return value;
}

// Write a single byte to a BME280 register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Read calibration data from the BME280
int read_calibration_data(int fd, struct bme280_calib_data *calib) {
    calib->dig_T1 = (read_register(fd, BME280_REG_CALIB_00 + 1) << 8) | read_register(fd, BME280_REG_CALIB_00);
    calib->dig_T2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 3) << 8) | read_register(fd, BME280_REG_CALIB_00 + 2));
    calib->dig_T3 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 5) << 8) | read_register(fd, BME280_REG_CALIB_00 + 4));
    calib->dig_P1 = (read_register(fd, BME280_REG_CALIB_00 + 7) << 8) | read_register(fd, BME280_REG_CALIB_00 + 6);
    calib->dig_P2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 9) << 8) | read_register(fd, BME280_REG_CALIB_00 + 8));
    calib->dig_P3 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 11) << 8) | read_register(fd, BME280_REG_CALIB_00 + 10));
    calib->dig_P4 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 13) << 8) | read_register(fd, BME280_REG_CALIB_00 + 12));
    calib->dig_P5 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 15) << 8) | read_register(fd, BME280_REG_CALIB_00 + 14));
    calib->dig_P6 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 17) << 8) | read_register(fd, BME280_REG_CALIB_00 + 16));
    calib->dig_P7 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 19) << 8) | read_register(fd, BME280_REG_CALIB_00 + 18));
    calib->dig_P8 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 21) << 8) | read_register(fd, BME280_REG_CALIB_00 + 20));
    calib->dig_P9 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 23) << 8) | read_register(fd, BME280_REG_CALIB_00 + 22));
    calib->dig_H1 = read_register(fd, BME280_REG_CALIB_00 + 25);
    calib->dig_H2 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 27) << 8) | read_register(fd, BME280_REG_CALIB_00 + 26));
    calib->dig_H3 = read_register(fd, BME280_REG_CALIB_00 + 28);
    calib->dig_H4 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 29) << 4) | (read_register(fd, BME280_REG_CALIB_00 + 30) & 0x0F));
    calib->dig_H5 = (int16_t)((read_register(fd, BME280_REG_CALIB_00 + 31) << 4) | (read_register(fd, BME280_REG_CALIB_00 + 30) >> 4));
    calib->dig_H6 = (int8_t)read_register(fd, BME280_REG_CALIB_00 + 32);

    return 0;
}

// Read raw temperature, pressure, and humidity data from the BME280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    int32_t raw_temp_msb = read_register(fd, BME280_REG_TEMP_MSB);
    int32_t raw_temp_lsb = read_register(fd, BME280_REG_TEMP_LSB);
    int32_t raw_temp_xlsb = read_register(fd, BME280_REG_TEMP_XLSB);
    int32_t raw_press_msb = read_register(fd, BME280_REG_PRESS_MSB);
    int32_t raw_press_lsb = read_register(fd, BME280_REG_PRESS_LSB);
    int32_t raw_press_xlsb = read_register(fd, BME280_REG_PRESS_XLSB);
    int32_t raw_hum_msb = read_register(fd, BME280_REG_HUM_MSB);
    int32_t raw_hum_lsb = read_register(fd, BME280_REG_HUM_LSB);

    if (raw_temp_msb < 0 || raw_temp_lsb < 0 || raw_temp_xlsb < 0 ||
        raw_press_msb < 0 || raw_press_lsb < 0 || raw_press_xlsb < 0 ||
        raw_hum_msb < 0 || raw_hum_lsb < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *temperature = (raw_temp_msb << 12) | (raw_temp_lsb << 4) | (raw_temp_xlsb >> 4);
    *pressure = (raw_press_msb << 12) | (raw_press_lsb << 4) | (raw_press_xlsb >> 4);
    *humidity = (raw_hum_msb << 8) | raw_hum_lsb;

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temperature, struct bme280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) *
            (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) *
           ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
