// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_START 0xAA

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 10 Hz)
#define BUFFER_SIZE 600

// Pressure deviation threshold (hPa)
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle;
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;
double pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void add_to_buffer(double pressure);
double calculate_rolling_average();
void trigger_alert(double current_pressure, double rolling_average);
void timer_callback();
void signal_handler(int signal);
void log_error(const char *message);
void log_alert(const char *message);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, data, 22) != 22) {
        log_error("Error reading calibration data");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data + 1, 1) != 1) {
        log_error("Error writing temperature conversion command");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        log_error("Error reading raw temperature data");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data + 1, 1) != 1) {
        log_error("Error writing pressure conversion command");
        return -1;
    }

    switch (OSS) {
        case 0: gpioDelay(5000); break;  // Wait 5 ms
        case 1: gpioDelay(8000); break;  // Wait 8 ms
        case 2: gpioDelay(14000); break; // Wait 14 ms
        case 3: gpioDelay(26000); break; // Wait 26 ms
