#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < TEMP_MIN) {
        duty_cycle = 0;
    } else if (temperature > TEMP_MAX) {
        duty_cycle = PWM_RANGE;
    } else {
        duty_cycle = (int)(((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * PWM_RANGE);
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f°C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping fan and exiting...\n", signal);
    running = 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or stopping fan.\n");
            // Optionally, you could set a default temperature or stop the fan here
            // For now, we'll just continue with the previous temperature or stop the fan
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Stop the fan
    set_fan_speed(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control stopped.\n");

    return 0;
}

