#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_RESET_REG 0xE0
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_STATUS_REG 0xF3
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA

// Calibration Data Registers
#define BMP280_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1
#define BMP280_OVERSAMPLING_PRESS 1
#define BMP280_MODE_FORCED 1

// Global variables
int i2c_fd;
int bmp280_address = BMP280_ADDR_1;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c(int address);
int read_register(int reg);
int write_register(int reg, int value);
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int log_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single register
int read_register(int reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        perror("Error reading register");
        return -1;
    }
    return value;
}

// Write a single register
int write_register(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        perror("Error writing register");
        return -1;
    }
    return 0;
}

// Read calibration data
int read_calibration_data() {
    calib.dig_T1 = (read_register(BMP280_CALIB_00 + 1) << 8) | read_register(BMP280_CALIB_00);
    calib.dig_T2 = (read_register(BMP280_CALIB_00 + 3) << 8) | read_register(BMP280_CALIB_00 + 2);
    calib.dig_T3 = (read_register(BMP280_CALIB_00 + 5) << 8) | read_register(BMP280_CALIB_00 + 4);
    calib.dig_P1 = (read_register(BMP280_CALIB_00 + 7) << 8) | read_register(BMP280_CALIB_00 + 6);
    calib.dig_P2 = (read_register(BMP280_CALIB_00 + 9) << 8) | read_register(BMP280_CALIB_00 + 8);
    calib.dig_P3 = (read_register(BMP280_CALIB_00 + 11) << 8) | read_register(BMP280_CALIB_00 + 10);
    calib.dig_P4 = (read_register(BMP280_CALIB_00 + 13) << 8) | read_register(BMP280_CALIB_00 + 12);
    calib.dig_P5 = (read_register(BMP280_CALIB_00 + 15) << 8) | read_register(BMP280_CALIB_00 + 14);
    calib.dig_P6 = (read_register(BMP280_CALIB_00 + 17) << 8) | read_register(BMP280_CALIB_00 + 16);
    calib.dig_P7 = (read_register(BMP280_CALIB_00 + 19) << 8) | read_register(BMP280_CALIB_00 + 18);
    calib.dig_P8 = (read_register(BMP280_CALIB_00 + 21) << 8) | read_register(BMP280_CALIB_00 + 20);
