#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Configuration
#define I2C_BUS_1 "/dev/i2c-1"
#define I2C_BUS_2 "/dev/i2c-2"
#define LM75_ADDR_1 0x48
#define LM75_ADDR_2 0x49
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Data Structures
typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureReading;

typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static volatile sig_atomic_t program_running = 1;
static int i2c_fd_1 = -1;
static int i2c_fd_2 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static CircularBuffer temp_buffer_1;
static CircularBuffer temp_buffer_2;
static pthread_t data_acquisition_thread;

// Function Prototypes
void signal_handler(int sig);
int init_i2c(const char *bus, int addr);
int read_temperature(int fd, float *temperature);
void add_reading(CircularBuffer *buffer, float temperature);
float calculate_average(CircularBuffer *buffer);
void *data_acquisition_thread_func(void *arg);
int init_gpio(const char *chip, int pin);
void set_gpio_value(struct gpiod_line *line, int value);
void cleanup();

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// I2C Initialization
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Temperature Reading
int read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    int16_t raw_temp;

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = (data[0] << 8) | data[1];
    raw_temp >>= 5; // Shift right by 5 bits

    *temperature = (float)raw_temp / 256.0;

    return 0;
}

// Circular Buffer Operations
void add_reading(CircularBuffer *buffer, float temperature) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].temperature = temperature;
    buffer->buffer[buffer->head].timestamp = time(NULL);
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    pthread_mutex_lock(&buffer->mutex);
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i].temperature;
    }
    pthread_mutex_unlock(&buffer->mutex);

    return sum / buffer->count;
}

// Data Acquisition Thread
void *data_acquisition_thread_func(void *arg) {
    while (program_running) {
        float temp1, temp2;

        if (i2c_fd_1 >= 0) {
            if (read_temperature(i2c_fd_1, &temp1) == 0) {
                add_reading(&temp_buffer_1, temp1);
                printf("Sensor 1: Temperature = %.2f°C\n", temp1);
            } else {
                fprintf(stderr, "Error reading from sensor 1, re-initializing...\n");
                close(i2c_fd_1);
                i2c_fd_1 = init_i2c(I2C_BUS_1, LM75_ADDR_1);
            }
        }

        if (i2c_fd_2 >= 0) {
            if (read_temperature(i2c_fd_2, &temp2) == 0) {
                add_reading(&temp_buffer_2, temp2);
                printf("Sensor 2: Temperature = %.2f°C\n", temp2);
            } else {
                fprintf(stderr, "Error reading from sensor 2, re-initializing...\n");
                close(i2c_fd_2);
                i2c_fd_2 = init_i2c(I2C_BUS_2, LM75_ADDR_2);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    pthread_exit(NULL);
}

// GPIO Initialization
int init_gpio(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip, strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "temperature_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Control
void set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
    }
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");

    // Data Acquisition Thread
    if (pthread_join(data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error joining data acquisition thread: %s\n", strerror(errno));
    }

    // I2C
    if (i2c_fd_1 >= 0) {
        close(i2c_fd_1);
    }
