#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>

// Constants
#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define RTD_REF_RESISTANCE 430.0 // 430 ohms
#define MAX_RTD_RESISTANCE 1000.0 // 1000 ohms
#define MAX_TEMPERATURE 80.0 // 80 degrees Celsius
#define CONFIG_FILE "config.json"

// Global variables
int spi_handle;
double target_temperature = 25.0; // Default target temperature
double Kp = 1.0; // Default proportional gain
double Ki = 0.1; // Default integral gain
double Kd = 0.01; // Default derivative gain
double integral = 0.0;
double previous_error = 0.0;
int running = 1;

// Function prototypes
int read_config();
int initialize_spi();
int read_max31865(int *rtd_code, int *fault);
double convert_rtd_to_resistance(int rtd_code);
double convert_resistance_to_temperature(double resistance);
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read configuration from JSON file
int read_config() {
    json_t *root;
    json_error_t error;

    root = json_load_file(CONFIG_FILE, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target = json_object_get(root, "target_temperature");
    json_t *kp = json_object_get(root, "Kp");
    json_t *ki = json_object_get(root, "Ki");
    json_t *kd = json_object_get(root, "Kd");

    if (!json_is_real(target) || !json_is_real(kp) || !json_is_real(ki) || !json_is_real(kd)) {
        fprintf(stderr, "Error: Invalid config file format\n");
        json_decref(root);
        return -1;
    }

    target_temperature = json_real_value(target);
    Kp = json_real_value(kp);
    Ki = json_real_value(ki);
    Kd = json_real_value(kd);

    json_decref(root);
    return 0;
}

// Function to initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 1); // CE0, 500kHz, SPI mode 1
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from MAX31865
int read_max31865(int *rtd_code, int *fault) {
    char tx_buffer[1];
    char rx_buffer[2];

    // Read RTD MSB register (0x01)
    tx_buffer[0] = 0x01;
    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        log_error("SPI read failed");
        return -1;
    }

    *rtd_code = ((rx_buffer[0] << 8) | rx_buffer[1]) >> 1; // Combine MSB and LSB, shift right by 1 to remove fault bit
    *fault = rx_buffer[0] & 0x01; // Extract fault bit

    return 0;
}

// Function to convert RTD code to resistance
double convert_rtd_to_resistance(int rtd_code) {
    return ((double)rtd_code / 32768.0) * RTD_REF_RESISTANCE;
}

// Function to convert resistance to temperature using Callendar-Van Dusen equation
double convert_resistance_to_temperature(double resistance) {
    // Constants for PT100 (0-100°C)
    double R0 = 100.0; // Nominal resistance at 0°C
    double A = 0.0039083;
    double B = -0.0000005775;

    // Check for invalid resistance values
    if (resistance <= 0.0 || resistance > MAX_RTD_RESISTANCE) {
        log_error("Invalid RTD resistance value");
        return -1000.0; // Indicate an error
    }

    // Solve the Callendar-Van Dusen equation for temperature
    double t = (resistance / R0) - 1.0;
    double temperature = (t / A) + (t * t * B) / 2.0;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the PWM range
    if (output < 0.0) output = 0.0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(GPIO_HEATER, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    set_pwm_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to log errors to stderr
void log_error(const char *message) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s.%06ld: ERROR: %s\n", timestamp, tv.tv_usec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);

    // Read configuration from file
    if (read_config() != 0) {
        fprintf(stderr, "Warning: Using default configuration values\n");
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature control started. Target temperature: %.2f°C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n",
           target_temperature, Kp, Ki, Kd);

    // Main loop
    while (running) {
        int rtd_code, fault;
        double resistance, temperature, pid_output;

        // Read RTD data
        if (read_max31865(&rtd_code, &fault) == 0) {
            // Check for faults
            if (fault) {
                log_error("MAX31865 fault detected");
                set_pwm_duty_cycle(0);
                running = 0;
                break;
            }

            // Convert RTD to resistance
            resistance = convert_rtd_to_resistance(rtd_code);

            // Convert resistance to temperature
            temperature = convert_resistance_to_temperature(resistance);

            if (temperature < -999.0) {
                log_error("Temperature conversion failed");
                set_pwm_duty_cycle(0);
                running = 0;
                break;
            }

            // Calculate PID output
            pid_output = calculate_pid(target_temperature, temperature);

            // Set PWM duty cycle
            set_pwm_duty_cycle((int)pid_output);

            // Print temperature and PID output
            printf("Temperature: %.2f°C, PID Output: %.2f\n", temperature, pid_output);

            // Failsafe: Check for over-temperature
            if (temperature > MAX_TEMPERATURE) {
                log_error("Over-temperature detected");
                set_pwm_duty_cycle(0);
                running = 0;
                break;
            }
        } else {
            log_error("Failed to read RTD data");
            set_pwm_duty_cycle(0);
            running = 0;
            break;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    set_pwm_duty_cycle(0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature control stopped.\n");
    return 0;
}

