#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Thresholds
#define TEMP_THRESHOLD_HIGH 30.0
#define PRESSURE_THRESHOLD_LOW 950.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c(int address);
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
int log_breach(double temperature, double pressure);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration data from BMP180
int read_calibration_data() {
    uint8_t buffer[22];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 22) == 22) {
            ac1 = (buffer[0] << 8) | buffer[1];
            ac2 = (buffer[2] << 8) | buffer[3];
            ac3 = (buffer[4] << 8) | buffer[5];
            ac4 = (buffer[6] << 8) | buffer[7];
            ac5 = (buffer[8] << 8) | buffer[9];
            ac6 = (buffer[10] << 8) | buffer[11];
            b1 = (buffer[12] << 8) | buffer[13];
            b2 = (buffer[14] << 8) | buffer[15];
            mb = (buffer[16] << 8) | buffer[17];
            mc = (buffer[18] << 8) | buffer[19];
            md = (buffer[20] << 8) | buffer[21];
            return 0; // Success
        } else {
            perror("Error reading calibration data");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read calibration data after multiple retries.\n");
    return -1; // Failure
}

// Read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temp) {
    uint8_t write_buffer[1] = {BMP180_REG_CONTROL};
    uint8_t read_buffer[2];
    int retries = 3;

    while (retries > 0) {
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing temperature command");
            retries--;
            usleep(10000);
            continue;
        }

        write_buffer[0] = BMP180_CMD_TEMP;
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing temperature command");
            retries--;
            usleep(10000);
            continue;
        }

        usleep(5000); // Wait 4.5ms

        write_buffer[0] = BMP180_REG_MSB;
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing register address for temperature read");
            retries--;
            usleep(10000);
            continue;
        }

        if (read(i2c_fd, read_buffer, 2) == 2) {
            *raw_temp = (read_buffer[0] << 8) | read_buffer[1];
            return 0; // Success
        } else {
            perror("Error reading raw temperature data");
            retries--;
            usleep(10000);
        }
    }

    fprintf(stderr, "Failed to read raw temperature after multiple retries.\n");
    return -1; // Failure
}

// Read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t write_buffer[1] = {BMP180_REG_CONTROL};
    uint8_t read_buffer[3];
    int retries = 3;

    while (retries > 0) {
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing pressure command");
            retries--;
            usleep(10000);
            continue;
        }

        write_buffer[0] = BMP180_CMD_PRESSURE0;
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing pressure command");
            retries--;
            usleep(10000);
            continue;
        }

        usleep(5000); // Wait 4.5ms

        write_buffer[0] = BMP180_REG_MSB;
        if (write(i2c_fd, write_buffer, 1) != 1) {
            perror("Error writing register address for pressure read");
            retries--;
            usleep(10000);
            continue;
        }

        if (read(i2c_fd, read_buffer, 3) == 3) {
            *raw_pressure = ((read_buffer[0] << 16) | (read_buffer[1] << 8) | read_buffer[2]) >> 8;
            return 0; // Success
        } else {
            perror("Error reading raw pressure data");
            retries--;
            usleep(10000);
        }
    }

    fprintf(stderr, "Failed to read raw pressure after multiple retries.\n");
    return -1; // Failure
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << 0) + 2) >> 2;

    uint32_t X1_u = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t B4 = ((uint32_t)ac4 * (X1_u + X2_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> 0);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Log breach to file
int log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BMP180_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor... Press Ctrl+C to exit.\n");

    while (!terminate) {
        int32_t raw_temp, raw_pressure;
        double temperature, pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, raw_temp);

            // Check for breaches
            if (temperature > TEMP_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
                printf("Breach detected: Temperature = %.2f°C, Pressure = %.2f hPa\n", temperature, pressure);
                log_breach(temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Close I2C device and log file
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

