#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define MAX_DUTY_CYCLE 80
#define TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"

// PI Controller Gains
#define KP 1.0
#define KI 0.1

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double integral = 0.0;

// Function Prototypes
int initialize_gpio();
int initialize_spi();
int initialize_logging();
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function Implementations

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(HEATER_GPIO, 100); // PWM range of 0-100
    return 0;
}

int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
    }
    return 0;
}

double read_temperature() {
    unsigned char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1000.0;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;

    // Anti-windup
    if (integral > 100) integral = 100;
    if (integral < -100) integral = -100;

    double derivative = 0.0; // Simple PI controller, no derivative term

    double output = KP * error + KI * integral;

    // Clamp the output to the valid range
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    if (output < 0) output = 0;

    return output;
}

void set_heater_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 100.0 / MAX_DUTY_CYCLE);
    gpioPWM(HEATER_GPIO, pwm_value);
}

void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    double target_temperature = TARGET_TEMPERATURE;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to: %.2f\n", target_temperature);
    }

    // Initialize
    if (initialize_gpio() != 0) return 1;
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heater control started. Press Ctrl+C to exit.\n");

    while (running) {
        double temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            double duty_cycle = calculate_pid(target_temperature, temperature);
            set_heater_duty_cycle(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temperature: %.2f C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0%%\n");
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0); // Log the error
        }

        gpioDelay(1000); // 1 second delay
    }

    cleanup();
    return 0;
}

