// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_THRESHOLD_1 40000
#define TEMP_THRESHOLD_2 60000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temperature() {
    FILE *fp;
    int temperature = -1; // Default to -1 to indicate error
    char buffer[10];

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Convert string to integer
    temperature = atoi(buffer);

    return temperature;
}

// Function to set RGB LED color based on temperature
void set_led_color(int temperature) {
    int red, green, blue;

    if (temperature < TEMP_THRESHOLD_1) {
        // Blue
        red = 255;
        green = 255;
        blue = 0;
    } else if (temperature < TEMP_THRESHOLD_2) {
        // Green
        red = 255;
        green = 0;
        blue = 255;
    } else {
        // Red
        red = 0;
        green = 255;
        blue = 255;
    }

    // Invert the values for common-anode LED
    red = 255 - red;
    green = 255 - green;
    blue = 255 - blue;

    // Set PWM duty cycles
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);

    printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);
}

