#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define MAX_POST_SIZE 256

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int read_dht22(int gpio, DHT22Data *data);
unsigned char calculate_checksum(unsigned char data[], int len);
int post_data(const char *url, const char *data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    unsigned char raw_data[5] = {0};
    unsigned char checksum;

    // Initialize pigpio if not already initialized
    if (!pigpio_initialized) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "pigpio initialisation failed\n");
            return -1;
        }
        pigpio_initialized = 1;
    }

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 20-40us

    gpioSetMode(gpio, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(gpio) == 0) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 200) {
                fprintf(stderr, "Timeout waiting for HIGH signal\n");
                return -1;
            }
        }

        count = 0;
        while (gpioRead(gpio) == 1) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 200) {
                fprintf(stderr, "Timeout waiting for LOW signal\n");
                return -1;
            }
        }

        if (count > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    checksum = calculate_checksum(raw_data, 4);
    if (checksum != raw_data[4]) {
        fprintf(stderr, "Checksum error: calculated 0x%02X, received 0x%02X\n", checksum, raw_data[4]);
        return -1;
    }

    // Convert data
    data->humidity = (float)(((unsigned int)raw_data[0] << 8) | raw_data[1]) / 10.0;
    data->temperature = (float)(((unsigned int)(raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data->temperature *= -1.0;
    }

    return 0;
}

// Function to calculate checksum
unsigned char calculate_checksum(unsigned char data[], int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Function to post data to server using libcurl
int post_data(const char *url, const char *data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(data));

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data posted successfully with response code: %ld\n", response_code);
            } else {
                fprintf(stderr, "HTTP request failed with response code: %ld\n", response_code);
                res = CURLE_HTTP_RETURNED_ERROR; // Indicate HTTP error
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    DHT22Data data;
    char json_data[MAX_POST_SIZE];
    int retries;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT22 sensor data logger started. Press Ctrl+C to exit.\n");

    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_dht22(DHT22_GPIO, &data) == 0) {
                // Get current timestamp
                time(&now);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Format data as JSON
                snprintf(json_data, sizeof(json_data), "{\"timestamp\": \"%s\", \"temperature\": %.1f, \"humidity\": %.1f}",
                         timestamp, data.temperature, data.humidity);

                // Post data to server
                if (post_data(SERVER_URL, json_data) == 0) {
                    printf("Data logged: %s\n", json_data);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Failed to post data, retry %d/%d\n", retries + 1, MAX_RETRIES);
                }
            } else {
                fprintf(stderr, "Failed to read DHT22 data, retry %d/%d\n", retries + 1, MAX_RETRIES);
            }
            retries++;
            gpioDelay(RETRY_DELAY_MS); // Wait before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read DHT22 data after %d retries. Skipping.\n", MAX_RETRIES);
        }

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    // Clean up pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    printf("DHT22 sensor data logger stopped.\n");
    return 0;
}

