    gpioDelay(CONVERSION_DELAY); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
