#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"

// Structure to hold the response data from libcurl
struct MemoryStruct {
  char *memory;
  size_t size;
};

// Global variables
static volatile int running = 1;
static char *server_url = DEFAULT_SERVER_URL;

// Function prototypes
int read_dht22(float *humidity);
int post_humidity(float humidity, const char *url);
void signal_handler(int signal);
void init_syslog();
void cleanup_syslog();
void init_curl();
void cleanup_curl();
void init_pigpio();
void cleanup_pigpio();

// Callback function to write libcurl response data to memory
static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
  size_t realsize = size * nmemb;
  struct MemoryStruct *mem = (struct MemoryStruct *)userp;

  char *ptr = realloc(mem->memory, mem->size + realsize + 1);
  if (ptr == NULL) {
    syslog(LOG_ERR, "realloc() failed");
    return 0;
  }

  mem->memory = ptr;
  memcpy(&(mem->memory[mem->size]), contents, realsize);
  mem->size += realsize;
  mem->memory[mem->size] = 0;

  return realsize;
}

// Function to read humidity from DHT22 sensor
int read_dht22(float *humidity) {
  int data[5] = {0, 0, 0, 0, 0};
  int laststate = PI_HIGH;
  int j = 0;

  gpioSetMode(DHT22_GPIO, PI_OUTPUT);
  gpioWrite(DHT22_GPIO, PI_LOW);
  gpioDelay(1); // > 1ms
  gpioWrite(DHT22_GPIO, PI_HIGH);
  gpioDelay(30); // 20-40us

  gpioSetMode(DHT22_GPIO, PI_INPUT);

  // Read data
  for (int i = 0; i < 85; i++) {
    int counter = 0;
    while (gpioRead(DHT22_GPIO) == laststate) {
      counter++;
      gpioDelay(1); // Delay 1 microsecond
      if (counter == 255) {
        syslog(LOG_ERR, "DHT22 timeout error");
        return -1;
      }
    }
    laststate = gpioRead(DHT22_GPIO);

    if (counter > 3) {
      data[j / 8] <<= 1;
      if (counter > 16) // Increased threshold for 1 bit
        data[j / 8] |= 1;
      j++;
    }
  }

  // Check checksum
  if (j >= 40 && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
    float h = (float)((data[0] << 8) + data[1]) / 10.0;
    if (h > 100) {
      h = data[0]; // for DHT11
    }
    *humidity = h;
    return 0; // Success
  } else {
    syslog(LOG_ERR, "DHT22 checksum failure");
    return -1; // Checksum failure
  }
}

// Function to post humidity data to the server
int post_humidity(float humidity, const char *url) {
  CURL *curl;
  CURLcode res;
  char json_data[50];
  struct curl_slist *headers = NULL;
  struct MemoryStruct chunk;

  chunk.memory = malloc(1);
  chunk.size = 0;

  // Format JSON data
  snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f}", humidity);

  // Initialize libcurl
  curl_global_init(CURL_GLOBAL_DEFAULT);
  curl = curl_easy_init();
  if (curl) {
    // Set URL
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set request type to POST
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    // Set POST data
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

    // Set content type to application/json
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set write callback function
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

    // Perform the request
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
      free(chunk.memory);
      curl_slist_free_all(headers);
      curl_easy_cleanup(curl);
      curl_global_cleanup();
      return -1;
    }

    // Get HTTP response code
    long response_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

    // Check for 2xx response code
    if (response_code >= 200 && response_code < 300) {
      syslog(LOG_INFO, "HTTP POST successful, response code: %ld", response_code);
    } else {
      syslog(LOG_ERR, "HTTP POST failed, response code: %ld", response_code);
      syslog(LOG_ERR, "Response body: %s", chunk.memory);
      free(chunk.memory);
      curl_slist_free_all(headers);
      curl_easy_cleanup(curl);
      curl_global_cleanup();
      return -1;
    }

    // Clean up
    free(chunk.memory);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
  } else {
    syslog(LOG_ERR, "curl_easy_init() failed");
    curl_global_cleanup();
    return -1;
  }

  curl_global_cleanup();
  return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  syslog(LOG_INFO, "Signal received, exiting...");
  running = 0;
}

// Initialize syslog
void init_syslog() {
  openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
}

// Cleanup syslog
void cleanup_syslog() {
  closelog();
