// Constants
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define TEMP_THRESHOLD_1 45000 // 45°C
#define TEMP_THRESHOLD_2 55000 // 55°C
#define TEMP_THRESHOLD_3 65000 // 65°C
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
volatile sig_atomic_t program_running = 1;
int current_fan_state = 0; // Initialize to off

// Function prototypes
int read_cpu_temp();
int set_fan_state(int state);
int get_max_fan_state();
int log_fan_state(int state);
void signal_handler(int signal);
int read_file(const char *path, char *buffer, size_t buffer_size);
int write_file(const char *path, const char *value);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        program_running = 0;
        set_fan_state(0); // Stop the fan
        log_fan_state(0); // Log the shutdown
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    char buffer[10];
    int temp_milli;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_file(CPU_TEMP_FILE, buffer, sizeof(buffer)) == 0) {
            temp_milli = atoi(buffer);
            return temp_milli;
        } else {
            fprintf(stderr, "Error reading CPU temperature, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read CPU temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to set fan state
int set_fan_state(int state) {
    int max_state = get_max_fan_state();
    if (max_state < 0) {
        fprintf(stderr, "Error getting max fan state.\n");
        return -1;
    }

    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state: %d. Max state is %d.\n", state, max_state);
        return -1;
    }

    char state_str[2];
    snprintf(state_str, sizeof(state_str), "%d", state);

    if (write_file(FAN_STATE_FILE, state_str) != 0) {
        fprintf(stderr, "Error setting fan state to %d.\n", state);
        return -1;
    }

    current_fan_state = state;
    return 0;
}

// Function to get maximum fan state
int get_max_fan_state() {
    char buffer[2];
    int max_state;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_file(MAX_STATE_FILE, buffer, sizeof(buffer)) == 0) {
            max_state = atoi(buffer);
            return max_state;
        } else {
            fprintf(stderr, "Error reading max fan state, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read max fan state after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to log fan state
int log_fan_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Fan state: %d\n", timestamp, state);
    fclose(fp);
    return 0;
}

// Function to read from a file
int read_file(const char *path, char *buffer, size_t buffer_size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening file %s: %s\n", path, strerror(errno));
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from file %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    close(fd);
    return 0;
}

// Function to write to a file
int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", path, strerror(errno));
        return -1;
    }

    ssize_t bytes_written = write(fd, value, strlen(value));
    if (bytes_written == -1) {
        fprintf(stderr, "Error writing to file %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Skipping fan control.\n");
        } else {
            int new_fan_state;

            if (temp < TEMP_THRESHOLD_1) {
                new_fan_state = 0;
            } else if (temp < TEMP_THRESHOLD_2) {
                new_fan_state = 1;
            } else if (temp < TEMP_THRESHOLD_3) {
                new_fan_state = 2;
            } else {
                new_fan_state = 3;
            }

            if (new_fan_state != current_fan_state) {
                if (set_fan_state(new_fan_state) == 0) {
                    log_fan_state(new_fan_state);
                    printf("CPU temperature: %d m°C, Fan state: %d\n", temp, new_fan_state);
                } else {
                    fprintf(stderr, "Failed to set fan state.\n");
                }
            }
        }

        sleep(5);
    }

    return 0;
}

