#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define measurement command
#define MEASURE_CMD 0x3608

// Define CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handles
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
unsigned char crc8(const unsigned char *data, int len);
void log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int address;
    int handle;
} sensor_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from a sensor with retries
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char buffer[3];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (bytes_read == 3) {
            // CRC check
            if (crc8(buffer, 2) == buffer[2]) {
                // Convert raw value to flow rate
                int raw_value = (buffer[0] << 8) | buffer[1];
                *flow_rate = raw_value * 0.01;
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed!\n");
            }
        } else {
            fprintf(stderr, "I2C read failed (bytes read: %d), retrying...\n", bytes_read);
        }
        retries--;
        gpioDelay(10000); // 10ms delay
    }

    fprintf(stderr, "Failed to read sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log data to a file
void log_data(float flow_rate1, float flow_rate2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

