#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_adpd144ri(uint16_t *red, uint16_t *ir);
int control_led(int state);
int log_data(uint16_t red, uint16_t ir);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Function to read data from ADPD144RI
int read_adpd144ri(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int result;

    // Read 4 bytes from FIFO data register
    result = read(i2c_fd, buf, 4);
    if (result != 4) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    // Combine bytes to form 16-bit values
    *red = (uint16_t)((buf[0] << 8) | buf[1]);
    *ir = (uint16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_GPIO, state);
    return 0;
}

// Function to log data to file
int log_data(uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri(&sensor_data.red, &sensor_data.ir) == 0) {
            // Log data
            log_data(sensor_data.red, sensor_data.ir);

            // Control LED based on IR threshold
            if (sensor_data.ir > IR_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

