// Define GPIO pins
#define MIC_OUT_PIN 17
#define GAIN_PIN 18

// Define gain level (0 = 60dB, 1 = 90dB)
#define GAIN_LEVEL 0

// Define sampling interval (in milliseconds)
#define SAMPLE_INTERVAL 10

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_gain(int level);
int read_microphone_output();
int log_event(int level);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int mic_out_pin;
    int gain_pin;
} gpio_config_t;

// Structure to hold logging configuration
typedef struct {
    char *log_file_path;
} logging_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_OUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_PIN, PI_OUTPUT);

    return 0;
}

// Function to set the gain level
int set_gain(int level) {
    if (gpioWrite(GAIN_PIN, level) != 0) {
        fprintf(stderr, "Failed to set gain level\n");
        return -1;
    }
    return 0;
}

// Function to read the microphone output
int read_microphone_output() {
    return gpioRead(MIC_OUT_PIN);
}

// Function to log an event to the log file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s LEVEL:%d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

