    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set gain level
    if (set_gain(GAIN_LEVEL) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
