    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int output = read_microphone_output();
        if (output == 1) {
            log_event(1);
        }
        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 10ms
    }

