#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
float calculate_iaq(uint16_t tvoc, uint16_t eco2);
int log_data(float iaq, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-VZ-89TE
int read_sensor_data(sensor_data_t *data) {
    char buffer[7];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 7);

    if (bytes_read != 7) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }

    // Extract TVOC and eCO2 values (big-endian)
    data->tvoc = (buffer[0] << 8) | buffer[1];
    data->eco2 = (buffer[4] << 8) | buffer[5];

    return 0;
}

// Calculate IAQ index
float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0 - (float)tvoc / 10.0 - ((float)eco2 - 400.0) / 50.0;

    // Clamp IAQ index to 0-100 range
    if (iaq < 0.0) {
        iaq = 0.0;
    } else if (iaq > 100.0) {
        iaq = 100.0;
    }

    return iaq;
}

// Log data to CSV file
int log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC (ppb),eCO2 (ppm)\n");
    }

    sensor_data_t sensor_data;
    float iaq;

    printf("Starting air quality monitoring...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ index
            iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

            // Log data
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SLEEP_DURATION);
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

