            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", SLEEP_DURATION);
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

