#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER "ttp223_tamper"
#define TOUCH_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;
static time_t touch_start_time = 0;
static int intrusion_alert_printed = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize the GPIO line
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input_with_consumer(line, CONSUMER) < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to check if the sensor is touched
int is_touched(int sensor_value) {
    return (sensor_value == 1);
}

// Function to handle intrusion detection
void handle_intrusion(void) {
    time_t now = time(NULL);
    if (difftime(now, touch_start_time) >= TOUCH_THRESHOLD_SEC && !intrusion_alert_printed) {
        printf("INTRUSION DETECTED!\n");
        intrusion_alert_printed = 1;
    }
}

// Function to reset the intrusion detection timer
void reset_intrusion_timer(void) {
    touch_start_time = 0;
    intrusion_alert_printed = 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000L}; // 100ms
    int sensor_value;

    printf("Monitoring Tamper Sensor on GPIO %d...\n", GPIO_LINE);

    while (!terminate) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (is_touched(sensor_value)) {
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            }
            handle_intrusion();
        } else {
            reset_intrusion_timer();
        }

        nanosleep(&poll_interval, NULL);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

