#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2s/pcm.h>
#include <pigpio.h>

// Configuration
#define I2S_DEVICE "/dev/snd/pcmC0D0c" // I2S device file
#define GPIO_PIN 17                    // GPIO pin for L/R select
#define SAMPLE_RATE 44100              // Sample rate in Hz
#define NUM_CHANNELS 2                // Number of channels (stereo)
#define BITS_PER_SAMPLE 16             // Bits per sample
#define BUFFER_SIZE 1024               // Buffer size for I2S data
#define FILE_NAME "audio_capture.pcm" // Output file name

// Global variables
static volatile int running = 1; // Flag to control the main loop
static int i2s_fd = -1;           // File descriptor for I2S device
static int gpio_handle = -1;       // pigpio handle
static FILE *output_file = NULL;   // File pointer for output file

// Structure to hold I2S configuration
typedef struct {
    char device[20];
    unsigned int rate;
    unsigned int channels;
    unsigned int format;
} i2s_config_t;

// Function prototypes
int init_i2s(i2s_config_t *config);
int16_t extract_pcm_sample(uint32_t i2s_data);
int write_pcm_data(int16_t *pcm_data, int num_samples);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        running = 0;
    }
}

// Function to initialize the I2S interface
int init_i2s(i2s_config_t *config) {
    int fd;
    struct snd_pcm_hw_params params;

    // Open the I2S device
    fd = open(config->device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2S device");
        return -1;
    }

    // Initialize hardware parameters
    if (snd_pcm_hw_params_any(fd, &params) < 0) {
        perror("Error initializing hardware parameters");
        close(fd);
        return -1;
    }

    // Set access type to interleaved
    if (snd_pcm_hw_params_set_access(fd, &params, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        perror("Error setting access type");
        close(fd);
        return -1;
    }

    // Set format to signed 16-bit little-endian
    if (snd_pcm_hw_params_set_format(fd, &params, SND_PCM_FORMAT_S16_LE) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    // Set sample rate
    unsigned int rate = config->rate;
    if (snd_pcm_hw_params_set_rate_near(fd, &params, &rate, 0) < 0) {
        perror("Error setting sample rate");
        close(fd);
        return -1;
    }
    if (rate != config->rate) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", rate);
    }

    // Set number of channels
    if (snd_pcm_hw_params_set_channels(fd, &params, config->channels) < 0) {
        perror("Error setting number of channels");
        close(fd);
        return -1;
    }

    // Apply hardware parameters
    if (snd_pcm_hw_params(fd, &params) < 0) {
        perror("Error applying hardware parameters");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to extract 16-bit PCM sample from 32-bit I2S data
int16_t extract_pcm_sample(uint32_t i2s_data) {
    // Right-shift to extract the 24-bit data and convert to 16-bit
    return (int16_t)(i2s_data >> 8);
}

// Function to write PCM data to the output file
int write_pcm_data(int16_t *pcm_data, int num_samples) {
    size_t bytes_written = fwrite(pcm_data, sizeof(int16_t), num_samples, output_file);
    if (bytes_written != num_samples) {
        perror("Error writing to output file");
        return -1;
    }
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2S device
    if (i2s_fd != -1) {
        close(i2s_fd);
    }

    // Close output file
    if (output_file != NULL) {
        fclose(output_file);
    }

    // Release GPIO pin
    if (gpio_handle != -1) {
        gpioTerminate();
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    i2s_config_t i2s_config = {
        .device = I2S_DEVICE,
        .rate = SAMPLE_RATE,
        .channels = NUM_CHANNELS,
        .format = SND_PCM_FORMAT_S16_LE
    };
    uint32_t i2s_buffer[BUFFER_SIZE];
    int16_t pcm_buffer[BUFFER_SIZE];
    int bytes_read;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2S
    i2s_fd = init_i2s(&i2s_config);
    if (i2s_fd < 0) {
        cleanup();
        return 1;
    }

    // Open output file in binary write mode
    output_file = fopen(FILE_NAME, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        cleanup();
        return 1;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    // Main loop
    while (running) {
        // Read data from I2S device
        bytes_read = read(i2s_fd, i2s_buffer, sizeof(i2s_buffer));
        if (bytes_read < 0) {
            perror("Error reading from I2S device");
            break;
        }

        // Extract PCM samples and write to file
        for (int i = 0; i < bytes_read / sizeof(uint32_t); i++) {
            pcm_buffer[i] = extract_pcm_sample(i2s_buffer[i]);
        }

        if (write_pcm_data(pcm_buffer, bytes_read / sizeof(uint32_t)) != 0) {
            break;
        }
    }

    // Perform cleanup
    cleanup();

    return 0;
}

