#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_DELAY_MS 50
#define FAN_FREQUENCY 100
#define MAX_FLAME_DURATION_SEC 60
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int duty_cycle);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, FAN_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 0-100

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int sensor_value = gpioRead(FLAME_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the cooling fan
void control_fan(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }
    gpioPWM(FAN_PIN, duty_cycle);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_fan(0); // Turn off the fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    log_event("System started");

    int flame_detected = 0;
    time_t flame_start_time = 0;

    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, continue to the next iteration
            gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        if (sensor_value == 0 && !flame_detected) {
            // Flame detected
            flame_detected = 1;
            flame_start_time = time(NULL);
            log_event("Flame detected");
        } else if (sensor_value == 1 && flame_detected) {
            // Flame ended
            flame_detected = 0;
            time_t flame_duration = time(NULL) - flame_start_time;
            log_event("Flame ended");

            // Calculate duty cycle based on flame duration
            double duty_cycle_double = 0.0;
            if (flame_duration > 0) {
                duty_cycle_double = 80.0 * (1.0 - exp(-(double)flame_duration / MAX_FLAME_DURATION_SEC));
            }

            if (duty_cycle_double > 80.0) {
                duty_cycle_double = 80.0;
            }

            int duty_cycle = (int)duty_cycle_double;

            control_fan(duty_cycle);
        } else if (sensor_value == 1 && !flame_detected) {
            // No flame, turn off the fan
            control_fan(0);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    log_event("System shutdown");
    cleanup();

    return 0;
}

