#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define FRAME_SIZE 32768
#define LOG_FILE "radar_log.bin"

// Configuration structure
typedef struct {
    double start_frequency;
    double end_frequency;
    int num_chirps;
    int num_samples;
    double frame_period;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int configure_gpio();
int write_log_header(FILE *fp, radar_config_t config);
int read_radar_data(FILE *fp, int frame_number);
void trigger_radar();
void data_ready_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure GPIO pins
int configure_gpio() {
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Set up interrupt on DATA_READY_GPIO
    if (gpioSetISRFuncEx(DATA_READY_GPIO, RISING_EDGE, 0, data_ready_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return -1;
    }
    return 0;
}

// Write log header
int write_log_header(FILE *fp, radar_config_t config) {
    uint32_t magic_number = 0x52444144; // "RADA"
    time_t timestamp = time(NULL);
    uint64_t frame_number = 0; // Initial frame number

    if (fwrite(&magic_number, sizeof(uint32_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write magic number\n");
        return -1;
    }
    if (fwrite(&timestamp, sizeof(time_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write timestamp\n");
        return -1;
    }
    if (fwrite(&config, sizeof(radar_config_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write configuration\n");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(uint64_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write frame number\n");
        return -1;
    }

    return 0;
}

// Read radar data
int read_radar_data(FILE *fp, int frame_number) {
    char *buffer = (char *)malloc(FRAME_SIZE);
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for buffer\n");
        return -1;
    }

    // Read data from SPI
    int bytes_read = spiRead(spi_handle, buffer, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "SPI read failed: %d\n", bytes_read);
        free(buffer);
        return -1;
    }

    // Write data to file
    if (fwrite(buffer, 1, FRAME_SIZE, fp) != FRAME_SIZE) {
        fprintf(stderr, "Failed to write data to file\n");
        free(buffer);
        return -1;
    }

    // Update frame number
    time_t timestamp = time(NULL);
    uint64_t frame_number_u64 = (uint64_t)frame_number;

    if (fseek(fp, sizeof(uint32_t) + sizeof(time_t) + sizeof(radar_config_t), SEEK_SET) != 0) {
        fprintf(stderr, "Failed to seek to frame number position\n");
        free(buffer);
        return -1;
    }

    if (fwrite(&frame_number_u64, sizeof(uint64_t), 1, fp) != 1) {
        fprintf(stderr, "Failed to write frame number\n");
        free(buffer);
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek to end of file\n");
        free(buffer);
        return -1;
    }

    free(buffer);
    return 0;
}

// Trigger radar
void trigger_radar() {
    gpioWrite(TRIGGER_GPIO, 1); // Set trigger high
    gpioDelay(10);              // Wait 10 us
    gpioWrite(TRIGGER_GPIO, 0); // Set trigger low
}

// Data ready callback function
void data_ready_callback(int gpio, int level, uint32_t tick) {
    static int frame_number = 0;

    if (level == 1) { // Rising edge detected
        printf("Data ready interrupt received\n");
        trigger_radar(); // Trigger the radar

        if (read_radar_data(log_file, frame_number) == 0) {
            printf("Frame %d logged\n", frame_number);
            frame_number++;
        } else {
            fprintf(stderr, "Failed to log frame %d\n", frame_number);
        }
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        cleanup();
        return 1;
    }

    // Configure GPIO pins
    if (configure_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write log header
    radar_config_t config = {
        .start_frequency = 77.0,
        .end_frequency = 79.0,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period = 0.1
    };
    if (write_log_header(log_file, config) != 0) {
        cleanup();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

