#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO line number
#define GPIO_LINE 17

// Global variable to store the GPIO line
struct gpiod_line *gpio_line = NULL;

// Global variable to store the GPIO chip
struct gpiod_chip *gpio_chip = NULL;

// Global variable to store the GPIO line request
struct gpiod_line_request_config *line_config = NULL;

// Flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame detection status from the GPIO line
int read_flame_detection() {
    int value;

    value = gpiod_line_request_get_value(gpio_line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }

    return value;
}

// Function to log the flame detection status with a timestamp
void log_flame_detection(int flame_detected) {
    char *timestamp = get_timestamp();

    if (flame_detected == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

int main() {
    int ret;

    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line as input with a pull-up resistor
    line_config = gpiod_line_request_config_new(gpio_chip, GPIO_LINE, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!line_config) {
        fprintf(stderr, "Error creating line request config: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_config_set_consumer(line_config, "flame_detect", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting line consumer: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        gpiod_line_request_config_free(line_config);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_request_lines(gpio_chip, line_config);
    if (!gpio_line) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_request_config_free(line_config);
        return EXIT_FAILURE;
    }

    // Main loop to continuously read and log the flame detection status
    while (!terminate) {
        int flame_detected = read_flame_detection();
        if (flame_detected >= 0) {
            log_flame_detection(flame_detected);
        } else {
            fprintf(stderr, "Error reading flame detection, exiting...\n");
            break; // Exit the loop if there's an error reading the sensor
        }

        sleep(1); // Wait for 1 second
    }

    // Clean up resources before exiting
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (line_config) {
        gpiod_line_request_config_free(line_config);
    }

    return EXIT_SUCCESS;
}

