#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[8] = {2, 3, 4, 5, 6, 7, 8, 9};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pins as inputs
    for (int i = 0; i < 8; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    printf("TTP226 sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop to read and log the sensor data
    while (program_running) {
        for (int i = 0; i < 8; i++) {
            int value = gpioRead(gpio_pins[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", gpio_pins[i]);
            } else {
                printf("Channel %d: %d\n", i + 1, value);
            }
        }
        gpioDelay(100); // Wait for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

