#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 channels
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27
#define GPIO_22 22
#define GPIO_10 10
#define GPIO_9 9

// Structure to hold GPIO pin numbers
typedef struct {
    int gpio2;
    int gpio3;
    int gpio4;
    int gpio17;
    int gpio27;
    int gpio22;
    int gpio10;
    int gpio9;
} gpio_pins_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio(gpio_pins_t *pins) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pins->gpio2, PI_INPUT);
    gpioSetMode(pins->gpio3, PI_INPUT);
    gpioSetMode(pins->gpio4, PI_INPUT);
    gpioSetMode(pins->gpio17, PI_INPUT);
    gpioSetMode(pins->gpio27, PI_INPUT);
    gpioSetMode(pins->gpio22, PI_INPUT);
    gpioSetMode(pins->gpio10, PI_INPUT);
    gpioSetMode(pins->gpio9, PI_INPUT);

    gpioSetPullUpDown(pins->gpio2, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio3, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio4, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio17, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio27, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio22, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio10, PI_PUD_DOWN);
    gpioSetPullUpDown(pins->gpio9, PI_PUD_DOWN);

    return 0;
}

// Function to read the state of all GPIO pins
int read_gpio_pins(gpio_pins_t *pins, int *channel_states) {
    channel_states[0] = gpioRead(pins->gpio2);
    channel_states[1] = gpioRead(pins->gpio3);
    channel_states[2] = gpioRead(pins->gpio4);
    channel_states[3] = gpioRead(pins->gpio17);
    channel_states[4] = gpioRead(pins->gpio27);
    channel_states[5] = gpioRead(pins->gpio22);
    channel_states[6] = gpioRead(pins->gpio10);
    channel_states[7] = gpioRead(pins->gpio9);

    return 0;
}

// Function to format the timestamp
int format_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    if (strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

// Function to log the data to the console
int log_data(const char *timestamp, const int *channel_states) {
    printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n", timestamp,
           channel_states[0], channel_states[1], channel_states[2],
           channel_states[3], channel_states[4], channel_states[5],
           channel_states[6], channel_states[7]);
    return 0;
}

int main() {
    gpio_pins_t pins = {GPIO_2, GPIO_3, GPIO_4, GPIO_17, GPIO_27, GPIO_22, GPIO_10, GPIO_9};
    int channel_states[8];
    char timestamp[32];

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(&pins) != 0) {
        return 1;
    }

    printf("TTP226 Touch Sensor Data Logger\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read GPIO pins
        if (read_gpio_pins(&pins, channel_states) != 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break; // Exit loop on error
        }

        // Format timestamp
        if (format_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Error formatting timestamp\n");
            break; // Exit loop on error
        }

        // Log data
        if (log_data(timestamp, channel_states) != 0) {
            fprintf(stderr, "Error logging data\n");
            break; // Exit loop on error
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

