#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int tilt_state;
    int previous_tilt_state = -1; // Initialize to an invalid state
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to poll the tilt sensor
    while (program_running) {
        // Read the current state of the tilt sensor
        tilt_state = gpioRead(TILT_SENSOR_GPIO);

        // Validate the sensor reading
        if (tilt_state != 0 && tilt_state != 1) {
            fprintf(stderr, "Error: Invalid sensor reading: %d\n", tilt_state);
            // Attempt to recover by re-initializing pigpio
            gpioTerminate();
            pigpio_init_result = gpioInitialise();
            if (pigpio_init_result < 0) {
                fprintf(stderr, "pigpio re-initialisation failed: %d\n", pigpio_init_result);
                program_running = 0; // Exit the loop if re-initialization fails
            }
            gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
            gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
            gpioDelay(100); // Small delay before next reading
            continue; // Skip to the next iteration
        }

        // Check if the tilt state has changed
        if (tilt_state != previous_tilt_state) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Log the tilt state to the console
            if (tilt_state == 0) {
                printf("%s Tilted\n", timestamp);
            } else {
                printf("%s Not Tilted\n", timestamp);
            }

            // Update the previous tilt state
            previous_tilt_state = tilt_state;

            // Flush the output buffer to ensure immediate printing
            fflush(stdout);
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Tilt sensor monitoring stopped.\n");

    return 0;
}

