#define REG_CHLIST 0x01
#define REG_ALS_FORCE 0x06
#define REG_UVINDEX_LSB 0x2C
#define REG_ALS_VIS_DATA0 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_sensor_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Check if the sensor is present by reading the PART ID
    status = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Error: Si1145 not found (PART_ID = 0x%02X)\n", status);
        return -1;
    }
    printf("Si1145 sensor found (PART_ID = 0x%02X)\n", status);

    // Write 0x17 to the HW_KEY register
    status = i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Configure the CHLIST register to enable UV and ALS_VIS
    status = i2cWriteByteData(i2c_handle, REG_CHLIST, 0x77); // Enable UV and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CHLIST: %d\n", status);
        return -1;
    }

    return 0;
}

// Read sensor data (UV index and ALS visible)
int read_sensor_data(float *uv_index, int *als_visible) {
    int status;
    uint8_t uv_index_lsb, uv_index_msb;
    uint8_t als_vis_lsb, als_vis_msb;

    // Trigger a measurement by writing 0x01 to the ALS_FORCE register
    status = i2cWriteByteData(i2c_handle, REG_ALS_FORCE, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", status);
        return -1;
    }

    // Read the UV index data
    uv_index_lsb = i2cReadByteData(i2c_handle, REG_UVINDEX_LSB);
    if (uv_index_lsb < 0) {
