    als_vis_lsb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    als_vis_msb = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);

    if (als_vis_lsb < 0 || als_vis_msb < 0) {
        fprintf(stderr, "Error reading ALS visible data: %d, %d\n", als_vis_lsb, als_vis_msb);
        return -1;
    }

    *als_visible = (als_vis_msb << 8) | als_vis_lsb;
    *uv_index = (float)uv_index_lsb / 10.0;

    return 0;
}

