#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37

// I2C bus
#define I2C_BUS 1

// GPIO pin for alarm
#define ALARM_GPIO 17

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, float *flow_rate);
float convert_flow_rate(int16_t raw_flow);
float calculate_average_flow(float flow1, float flow2);
void control_alarm(float average_flow);
void log_flow_rate(float flow1, float flow2, float average_flow);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the sensor
int init_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = 0x36; // MSB of start measurement command
    buf[1] = 0x08; // LSB of start measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(100); // Wait 100 ms
    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_handle, float *flow_rate) {
    char buf[9];
    int16_t raw_flow;
    uint8_t crc;

    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Extract raw flow rate
    raw_flow = (buf[0] << 8) | buf[1];

    // Extract CRC
    crc = buf[2];

    // CRC validation
    if (crc != crc8((uint8_t *)buf, 2)) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert raw flow rate to ml/min
    *flow_rate = convert_flow_rate(raw_flow);

    return 0;
}

// Convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    return (float)raw_flow * 0.036;
}

// Calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Control the alarm based on average flow rate
void control_alarm(float average_flow) {
    if (average_flow < 0.5) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Log the flow rate data to a file
void log_flow_rate(float flow1, float flow2, float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2, average_flow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Release GPIO line
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    gpioSetMode(ALARM_GPIO, PI_INPUT); // Set GPIO to input

    // Close I2C file descriptors
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error initializing sensor 1.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error initializing sensor 2.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2, average_flow;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading sensor 1 data.\n");
            flow_rate1 = 0.0; // Set to 0 to avoid affecting average
        }

        if (read_sensor_data(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 2 data.\n");
            flow_rate2 = 0.0; // Set to 0 to avoid affecting average
        }

        // Calculate average flow rate
        average_flow = calculate_average_flow(flow_rate1, flow_rate2);

        // Control alarm
        control_alarm(average_flow);

        // Log flow rate data
        log_flow_rate(flow_rate1, flow_rate2, average_flow);

        // Wait for 1 second
        gpioDelay(1000);
    }

    return 0;
}

