#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int reading);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Get current timestamp
        time_t current_time = time(NULL);

        // Add data to buffer if obstacle detected (LOW signal)
        if (sensor_value == 0) {
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected at %ld\n", current_time);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Print the buffer before exiting
    print_buffer();

    // Release pigpio resources
    gpioTerminate();

    printf("Obstacle avoidance sensor monitoring stopped.\n");

    return 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, int reading) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].reading = reading;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Reading: %d\n", timestamp_str, buffer[index].reading);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

