#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define SCALE_FACTOR 0.0009765625f
#define ACTIVE_MODE 0x10
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor initialization function
int init_sensor() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, MODE_CONTROL_REG, ACTIVE_MODE) == 0) {
            printf("Sensor initialized successfully.\n");
            return 0;
        } else {
            fprintf(stderr, "Error writing to mode control register (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB_REG, buf, 6) == 6) {
            // Combine LSB and MSB for each axis
            int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

            // Convert to g-force units
            data->x = (float)raw_x * SCALE_FACTOR;
            data->y = (float)raw_y * SCALE_FACTOR;
            data->z = (float)raw_z * SCALE_FACTOR;

            return 0;
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file in append mode
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

