#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170-Q1 Register Addresses
#define TMAG5170_REG_DEVICE_ID 0x00
#define TMAG5170_REG_X_AXIS_LSB 0x01
#define TMAG5170_REG_X_AXIS_MSB 0x02
#define TMAG5170_REG_Y_AXIS_LSB 0x03
#define TMAG5170_REG_Y_AXIS_MSB 0x04
#define TMAG5170_REG_Z_AXIS_LSB 0x05
#define TMAG5170_REG_Z_AXIS_MSB 0x06
#define TMAG5170_REG_CONFIG 0x07

// Configuration values
#define TMAG5170_CONTINUOUS_MODE 0x01 // Continuous conversion mode
#define TMAG5170_ALL_AXES_ENABLED 0x07 // Enable all three axes
#define TMAG5170_50MT_RANGE 0x00 // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void convert_to_mt(sensor_data_t raw_data, float *x_mt, float *y_mt, float *z_mt);
void log_data(float x_mt, float y_mt, float z_mt);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the TMAG5170 sensor
int initialize_sensor() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, TMAG5170_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("Device ID verified: 0x%02X\n", device_id);

    // Configure the sensor
    int config_value = (TMAG5170_CONTINUOUS_MODE << 6) | (TMAG5170_ALL_AXES_ENABLED << 3) | TMAG5170_50MT_RANGE;
    int result = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }
    printf("Sensor configured for continuous mode, all axes enabled, 50 mT range\n");

    return 0;
}

// Function to read raw sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    int result = i2cReadI2CBlockData(i2c_handle, TMAG5170_REG_X_AXIS_LSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to convert raw data to mT
void convert_to_mt(sensor_data_t raw_data, float *x_mt, float *y_mt, float *z_mt) {
    // LSB scale factor for 50 mT range is 0.000122 mT/LSB
    *x_mt = (float)raw_data.x * 0.000122;
    *y_mt = (float)raw_data.y * 0.000122;
    *z_mt = (float)raw_data.z * 0.000122;
}

// Function to log data to a CSV file
void log_data(float x_mt, float y_mt, float z_mt) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_mt, y_mt, z_mt);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
    }
    fflush(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t raw_data = read_sensor_data();

        // Convert to mT
        float x_mt, y_mt, z_mt;
        convert_to_mt(raw_data, &x_mt, &y_mt, &z_mt);

        // Log the data
        log_data(x_mt, y_mt, z_mt);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

