    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to the log file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

// Function to read the water level sensor
int read_water_level() {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Error reading GPIO %d: %d", GPIO_PIN, level);
        log_message(error_message);
        return -1; // Indicate an error
    }
    return level;
}

// Function to handle water detection
void handle_water_detection() {
    log_message("ALERT: Water detected");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int retries = 0;
    int water_level;

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        water_level = read_water_level();

        if (water_level == 1) {
            handle_water_detection();
        } else if (water_level < 0) {
            // Error reading sensor, attempt re-initialization
            retries++;
            if (retries <= MAX_RETRIES) {
                char error_message[100];
                snprintf(error_message, sizeof(error_message), "Retrying pigpio initialization (%d/%d)", retries, MAX_RETRIES);
                log_message(error_message);
                gpioTerminate();
                if (gpioInitialise() < 0) {
                    log_message("pigpio re-initialisation failed");
                    retries++; // Increment retries even if re-initialization fails
                    gpioDelay(60000); // Wait 60 seconds before retrying
                } else {
                    retries = 0; // Reset retries on successful initialization
                }
            } else {
                log_message("Max retries reached. Exiting.");
                running = 0; // Exit loop if max retries reached
            }
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000); // Poll every 2 seconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

