#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the LED state
int control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        log_event("Failed to write to LED pin");
        return -1;
    }
    led_state = state;
    return 0;
}

// Log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
    printf("%s\n", log_message); // Also print to console
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
}

int main() {
    // Open syslog
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    log_event("Touch sensor application started");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            if (led_state == 0) {
                if (control_led(1) == 0) {
