#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to store event data
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} event_t;

// Circular buffer
event_t event_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int control_led(int pin, int state);
void log_event(int sensor_pin, time_t timestamp, int state);
void print_buffer();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Control LEDs based on sensor values
        control_led(LED_1_PIN, sensor1_value);
        control_led(LED_2_PIN, sensor2_value);

        // Log events
        time_t current_time = time(NULL);
        log_event(SENSOR_1_PIN, current_time, sensor1_value);
        log_event(SENSOR_2_PIN, current_time, sensor2_value);

        // Delay for debounce time
        gpioDelay(DEBOUNCE_TIME * 1000); // pigpioDelay takes microseconds
    }

    // Print buffer before exiting
    print_buffer();

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    return gpioRead(pin);
}

// Control LED state
int control_led(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to LED pin %d\n", pin);
        return 1;
    }
    return 0;
}

// Log event to circular buffer
void log_event(int sensor_pin, time_t timestamp, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = timestamp;
    event_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Event Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("Sensor: %d, Timestamp: %ld, State: %d\n",
               event_buffer[index].sensor_pin,
               event_buffer[index].timestamp,
               event_buffer[index].state);
    }
    printf("--- Overflow Count: %d ---\n", overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d). Shutting down...\n", signal);
}

