        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

