    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (rain_detected) {
        fprintf(log_file, "%s: Rain Detected\n", timestamp);
    } else {
        fprintf(log_file, "%s: No Rain\n", timestamp);
    }
    fflush(log_file); // Ensure the log is written immediately
}

