    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected != rain_detected_previously) {
            log_rain_event(rain_detected);
            rain_detected_previously = rain_detected;
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
