#define DEBOUNCE_TIME 5000

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static volatile unsigned long last_tick1 = 0;
static volatile unsigned long last_tick2 = 0;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int gpio;
    unsigned long last_tick;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
void sensor1_callback(int gpio, int level, unsigned int tick);
void sensor2_callback(int gpio, int level, unsigned int tick);
double calculate_rpm(unsigned long pulse_duration);
void log_data(unsigned long timestamp, int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Initialize last tick values
    last_tick1 = gpioTick();
    last_tick2 = gpioTick();

    // Set up callbacks for both sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    return 0;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_tick = gpioTick();
    if (current_tick - last_tick1 > DEBOUNCE_TIME) {
        unsigned long pulse_duration = current_tick - last_tick1;
        double rpm = calculate_rpm(pulse_duration);
        printf("Sensor 1: RPM = %.2f\n", rpm);
        log_data(current_tick, level, gpioRead(SENSOR2_GPIO));
        last_tick1 = current_tick;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_tick = gpioTick();
    if (current_tick - last_tick2 > DEBOUNCE_TIME) {
        unsigned long pulse_duration = current_tick - last_tick2;
        double rpm = calculate_rpm(pulse_duration);
        printf("Sensor 2: RPM = %.2f\n", rpm);
        log_data(current_tick, gpioRead(SENSOR1_GPIO), level);
        last_tick2 = current_tick;
    }
}

// Function to calculate RPM from pulse duration
double calculate_rpm(unsigned long pulse_duration) {
    if (pulse_duration == 0) return 0.0; // Avoid division by zero
    return 60000000.0 / (double)pulse_duration; // 60000000 microseconds in a minute
}

