void log_data(unsigned long timestamp, int sensor1_state, int sensor2_state) {
    if (log_file != NULL) {
        fprintf(log_file, "%lu,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    printf("Monitoring RPM... Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100); // Sleep for 100 milliseconds
    }

    // Clean up and exit
    cleanup();
    return 0;
}

