#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1182_ADDR 0x28

// Define register addresses
#define REG_PART_ID 0x00
#define REG_CONFIG 0x30
#define REG_HR_DATA 0x02
#define REG_SPO2_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int heart_rate;
    int spo2;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    // Verify sensor presence by reading the PART_ID register
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }

    printf("Si1182 Part ID: 0x%02X\n", part_id);

    // Configure the sensor for continuous measurement (example configuration)
    int config_result = i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01); // Example configuration value
    if (config_result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", config_result);
        return -1;
    }

    printf("Sensor configured for continuous measurement.\n");
    return 0;
}

// Function to read heart rate and SpO2 data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int hr_data, spo2_data;

    // Read heart rate data
    hr_data = i2cReadByteData(i2c_handle, REG_HR_DATA);
    if (hr_data < 0) {
        fprintf(stderr, "Error reading heart rate data: %d\n", hr_data);
        data.heart_rate = -1; // Indicate error
    } else {
        data.heart_rate = hr_data;
    }

    // Read SpO2 data
    spo2_data = i2cReadByteData(i2c_handle, REG_SPO2_DATA);
    if (spo2_data < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", spo2_data);
        data.spo2 = -1; // Indicate error
    } else {
        data.spo2 = spo2_data;
    }

    return data;
}

// Function to log the data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Log data to file
    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, data.heart_rate, data.spo2);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    printf("%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, data.heart_rate, data.spo2);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log data if read was successful
        if (data.heart_rate != -1 && data.spo2 != -1) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

