#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define tilt threshold (HIGH for 2 seconds)
#define TILT_THRESHOLD 2 // seconds

// Define polling interval
#define POLLING_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int check_threshold(int sensor1_value, int sensor2_value, int threshold);
int activate_alarm(int alarm_pin);
int deactivate_alarm(int alarm_pin);
int log_event(const char *event_type, int sensor_number);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t sensor1_start_time;
    time_t sensor2_start_time;
} SensorState;

SensorState sensor_state = {0, 0, 0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check if either sensor exceeds the threshold
        if (check_threshold(sensor1_value, sensor2_value, TILT_THRESHOLD)) {
            // Activate alarm
            if (activate_alarm(ALARM_PIN) != 0) {
                fprintf(stderr, "Failed to activate alarm.\n");
            }
        } else {
            // Deactivate alarm
            if (deactivate_alarm(ALARM_PIN) != 0) {
                fprintf(stderr, "Failed to deactivate alarm.\n");
            }
        }

        // Delay for the polling interval
        gpioDelay(POLLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    printf("Exiting gracefully.\n");
    return 0;
}

// Initialize pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Set alarm pin as output and initialize to LOW
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0);

    return 0;
}

// Read the value of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return 0; // Return 0 on error
    }
    return value;
}

// Check if either sensor exceeds the threshold
int check_threshold(int sensor1_value, int sensor2_value, int threshold) {
    time_t current_time = time(NULL);

    if (sensor1_value == 1) {
        if (sensor_state.sensor1_state == 0) {
            sensor_state.sensor1_state = 1;
            sensor_state.sensor1_start_time = current_time;
            log_event("tilt_start", 1);
        } else {
            if (difftime(current_time, sensor_state.sensor1_start_time) >= threshold) {
                log_event("threshold_exceeded", 1);
                return 1;
            }
        }
    } else {
        if (sensor_state.sensor1_state == 1) {
            sensor_state.sensor1_state = 0;
            log_event("tilt_end", 1);
        }
    }

    if (sensor2_value == 1) {
        if (sensor_state.sensor2_state == 0) {
            sensor_state.sensor2_state = 1;
            sensor_state.sensor2_start_time = current_time;
            log_event("tilt_start", 2);
        } else {
            if (difftime(current_time, sensor_state.sensor2_start_time) >= threshold) {
                log_event("threshold_exceeded", 2);
                return 1;
            }
        }
    } else {
        if (sensor_state.sensor2_state == 1) {
            sensor_state.sensor2_state = 0;
            log_event("tilt_end", 2);
        }
    }

    return 0;
}

// Activate the alarm (set GPIO HIGH)
int activate_alarm(int alarm_pin) {
    if (gpioWrite(alarm_pin, 1) != 0) {
        fprintf(stderr, "Error activating alarm on GPIO %d\n", alarm_pin);
        return 1;
    }
    return 0;
}

// Deactivate the alarm (set GPIO LOW)
int deactivate_alarm(int alarm_pin) {
    if (gpioWrite(alarm_pin, 0) != 0) {
        fprintf(stderr, "Error deactivating alarm on GPIO %d\n", alarm_pin);
        return 1;
    }
    return 0;
}

// Log an event to the log file
int log_event(const char *event_type, int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;

    // Deactivate the alarm
    deactivate_alarm(ALARM_PIN);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
