#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_L 0x28
#define ACCEL_X_H 0x29
#define ACCEL_Y_L 0x2A
#define ACCEL_Y_H 0x2B
#define ACCEL_Z_L 0x2C
#define ACCEL_Z_H 0x2D
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_acceleration();
double calculate_magnitude(sensor_data_t data);
void control_led(int on);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Omron D7S-A0011 sensor
int initialize_sensor() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        // Verify sensor presence by reading CTRL1 register
        int ctrl1_value = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (ctrl1_value < 0) {
            fprintf(stderr, "Error reading CTRL1 register: %d. Retrying...\n", ctrl1_value);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        // Check if the sensor is present (CTRL1 should not be 0xFF)
        if (ctrl1_value == 0xFF) {
            fprintf(stderr, "Sensor not found. Check I2C connection. Retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries--;
            continue;
        }

        // Clear power-down bit (CTRL1[0] = 1)
        int result = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x01);
        if (result < 0) {
            fprintf(stderr, "Error writing to CTRL1 register: %d. Retrying...\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries--;
            continue;
        }

        printf("Sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Reads acceleration data from the Omron D7S-A0011 sensor
sensor_data_t read_acceleration() {
    sensor_data_t data;
    char buffer[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_X_L, buffer, 6);
        if (bytes_read == 6) {
            // Combine high and low bytes for each axis
            data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data.z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return data; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data: %d. Retrying...\n", bytes_read);
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", RETRY_COUNT);
    data.x = 0; data.y = 0; data.z = 0; // Return default values
    return data; // Failure
}

// Calculates the Euclidean vibration magnitude
double calculate_magnitude(sensor_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Controls the LED connected to GPIO 17
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Logs the seismic event to a file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        sensor_data_t data = read_acceleration();

        // Calculate vibration magnitude
        double magnitude = calculate_magnitude(data);

        // Check if magnitude exceeds threshold
        if (magnitude > VIBRATION_THRESHOLD) {
            printf("Vibration detected! Magnitude: %.2f\n", magnitude);

            // Turn on LED
            control_led(1);

            // Log event
            log_event(magnitude);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second in microseconds

            // Turn off LED
            control_led(0);
        }

        // Delay for sample rate
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

