#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIO_CHIP_NAME "gpiochip0"

// Define the GPIO pins connected to the TTP226 sensor
const int gpio_pins[8] = {5, 6, 13, 19, 26, 12, 16, 20};

// Structure to hold the GPIO line information
struct gpiod_line *lines[8];

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the GPIO chip and lines
int initialize_gpio() {
    struct gpiod_chip *chip;
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    // Get the number of lines on the chip
    int num_lines = gpiod_chip_get_num_lines(chip);
    if (num_lines < 0) {
        fprintf(stderr, "Error getting number of lines on GPIO chip: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Check if the number of lines is sufficient
    if (num_lines < 8) {
        fprintf(stderr, "Error: Not enough lines on GPIO chip. Expected at least 8, got %d\n", num_lines);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO lines for input
    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_pins[i], strerror(errno));
            // Release previously allocated lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting line %d for input: %s\n", gpio_pins[i], strerror(errno));
            // Release previously allocated lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return -1;
        }
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

// Function to read the touch sensor states
int read_touch_sensor(int *states) {
    int i;

    // Read the state of each line
    for (i = 0; i < 8; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", gpio_pins[i], strerror(errno));
            return -1;
        }
        states[i] = value;
    }

    return 0;
}

// Function to log the touch events
void log_touch_events(int *current_states, int *previous_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int i;

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp in ISO-8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Log the touch events
    for (i = 0; i < 8; i++) {
        if (current_states[i] != previous_states[i]) {
            if (current_states[i] == 1) {
                printf("%s - Sensor %d (BCM %d): Touch detected\n", timestamp, i, gpio_pins[i]);
            } else {
                printf("%s - Sensor %d (BCM %d): Touch released\n", timestamp, i, gpio_pins[i]);
            }
        }
    }
}

// Function to release the GPIO lines
void release_gpio() {
    int i;

    // Release the GPIO lines
    for (i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

int main() {
    int current_states[8] = {0}; // Initialize all states to 0
    int previous_states[8] = {0}; // Initialize previous states to 0
    int i;

    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the touch sensor states
        if (read_touch_sensor(current_states) < 0) {
            fprintf(stderr, "Error reading touch sensor. Continuing...\n");
        } else {
            // Log the touch events
            log_touch_events(current_states, previous_states);

            // Update the previous states
            for (i = 0; i < 8; i++) {
                previous_states[i] = current_states[i];
            }
        }

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO lines before exiting
    release_gpio();

    return 0;
}

