#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100.0
#define LUX_THRESHOLD_2 500.0
#define LUX_THRESHOLD_3 1000.0
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int configure_veml7700();
int read_als_data(uint16_t *als_data);
float convert_to_lux(uint16_t als_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int configure_veml7700() {
    // ALS gain 1/8, ALS integration time 100ms
    uint16_t config_value = 0x0000; // 0x0000 = 0b0000000000000000
    char buf[2];
    buf[0] = config_value & 0xFF; // Low byte
    buf[1] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to VEML7700 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_als_data(uint16_t *als_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from VEML7700 ALS data register: %d\n", result);
        return -1;
    }

    *als_data = (buf[1] << 8) | buf[0]; // Combine high and low bytes
    return 0;
}

// Convert raw ALS data to lux
float convert_to_lux(uint16_t als_data) {
    return als_data * 0.0576;
}

// Set LED brightness using PWM
int set_led_brightness(float lux) {
    int duty_cycle = 0;

    if (lux < LUX_THRESHOLD_1) {
        duty_cycle = PWM_RANGE; // 100%
    } else if (lux < LUX_THRESHOLD_2) {
        duty_cycle = (int)((PWM_RANGE * 3.0) / 4.0); // 75%
    } else if (lux < LUX_THRESHOLD_3) {
        duty_cycle = (int)(PWM_RANGE / 2.0); // 50%
    } else {
        duty_cycle = (int)(PWM_RANGE / 4.0); // 25%
    }

    gpioPWM(LED_GPIO, duty_cycle);
    return duty_cycle;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700 sensor
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t als_data;
    float lux;
    int brightness;
    int error_code = 0;

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Convert to lux
            lux = convert_to_lux(als_data);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, error_code);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            error_code = -1; // I2C read error
            fprintf(stderr, "I2C read error, retrying...\n");
            log_data(0.0, 0, error_code); // Log the error
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Grow light system stopped.\n");
    return 0;
}

