#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors and LED
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int last_touch_states[8] = {0}; // Store the last known state of each touch sensor

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *touch_states);
void log_touch_event(int channel);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int touch_pins[8];
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    gpio_config_t config = {
        {TOUCH_SENSOR_1, TOUCH_SENSOR_2, TOUCH_SENSOR_3, TOUCH_SENSOR_4, TOUCH_SENSOR_5, TOUCH_SENSOR_6, TOUCH_SENSOR_7, TOUCH_SENSOR_8},
        LED_PIN
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(config.touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(config.touch_pins[i], PI_PUD_DOWN);
    }

    // Set LED pin as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    return 0;
}

// Function to read touch sensor states
int read_touch_sensors(int *touch_states) {
    gpio_config_t config = {
        {TOUCH_SENSOR_1, TOUCH_SENSOR_2, TOUCH_SENSOR_3, TOUCH_SENSOR_4, TOUCH_SENSOR_5, TOUCH_SENSOR_6, TOUCH_SENSOR_7, TOUCH_SENSOR_8},
        LED_PIN
    };

    for (int i = 0; i < 8; i++) {
        touch_states[i] = gpioRead(config.touch_pins[i]);
        if (touch_states[i] != 0 && touch_states[i] != 1) {
            fprintf(stderr, "Error reading touch sensor %d\n", i + 1);
            return 1;
        }
    }
    return 0;
}

// Function to log touch event to file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Function to control the LED
void control_led(int on) {
    gpio_config_t config = {
        {TOUCH_SENSOR_1, TOUCH_SENSOR_2, TOUCH_SENSOR_3, TOUCH_SENSOR_4, TOUCH_SENSOR_5, TOUCH_SENSOR_6, TOUCH_SENSOR_7, TOUCH_SENSOR_8},
        LED_PIN
    };

    gpioWrite(config.led_pin, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Security keypad simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_states[8];

        // Read touch sensor states
        if (read_touch_sensors(touch_states) != 0) {
            fprintf(stderr, "Error reading touch sensors, exiting...\n");
            break;
        }

        // Check for changes and log events
        for (int i = 0; i < 8; i++) {
            if (touch_states[i] != last_touch_states[i]) {
                if (touch_states[i] == 1) {
                    log_touch_event(i + 1);
                }
                last_touch_states[i] = touch_states[i];
            }
        }

        // Control LED based on touch sensor states
        int any_touched = 0;
        for (int i = 0; i < 8; i++) {
            if (touch_states[i] == 1) {
                any_touched = 1;
                break;
            }
        }
        control_led(any_touched);

        // Delay for debounce time
        gpioDelay(DEBOUNCE_TIME * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Security keypad simulation stopped.\n");
    return 0;
}

