static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure static allocation to avoid dangling pointer

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a touch event to the log file
int log_touch_event(const char *event) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int current_state = 0; // 0 = released, 1 = pressed
    int last_state = 0;
    int rc;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as an input with a pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Debounce
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state != last_state) {
                if (current_state == 1) {
                    if (log_touch_event("Touch Detected") != 0) {
                        fprintf(stderr, "Error logging touch detected event.\n");
                    }
                } else {
                    if (log_touch_event("Touch Released") != 0) {
                        fprintf(stderr, "Error logging touch released event.\n");
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input
    gpioTerminate(); // Release GPIO resources

    if (log_file != NULL) {
        fclose(log_file); // Close the log file
    }

    printf("Exiting.\n");
    return 0;
}

