#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define FLOW_RATE_SCALE 90.0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define SAMPLE_INTERVAL_SEC 1
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int start_measurement();
int read_sensor_data(sensor_data_t *data);
float convert_to_ml_min(int16_t raw_flow);
int validate_crc(uint8_t crc, int16_t data);
int log_data(float flow_rate, int raw_flags, const char *status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
