#include <gpiod.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables for GPIO lines and chip
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
struct gpiod_chip *chip = NULL;

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_sensor(struct gpiod_line *line);
char* get_iso8601_timestamp(void);
int log_data(const char *timestamp, int left, int middle, int right);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Flush the log file
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines for each sensor
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO lines as input
    if (gpiod_line_request_input(left_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(middle_line, "obstacle_avoidance") < 0 ||
        gpiod_line_request_input(right_line, "obstacle_avoidance") < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the data to the CSV file
int log_data(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        perror("Log file is not open");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp. Continuing.\n");
            sleep(1);
            continue;
        }

        // Log data
        if (log_data(timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Error logging data. Continuing.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 50 milliseconds
        usleep(50000); // 50000 microseconds = 50 milliseconds
    }

    return 0;
}

