#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 24
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750();
int log_event(int led_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int touch_state;
    int led_state;
    float light_level;
} sensor_data_t;

// Function to initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read light level from BH1750
int read_bh1750() {
    unsigned char config[1] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    unsigned char data[2];
    int lux;

    if (write(i2c_fd, config, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    lux = (data[0] << 8) | data[1];
    return lux;
}

// Function to log events to file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    float light_level;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    light_level = (float)read_bh1750() / 1.2; // Convert to lux

    if (log_file != NULL) {
        fprintf(log_file, "%s, LED: %s, Light Level: %.2f lux\n", timestamp, led_state ? "ON" : "OFF", light_level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    int led_state = 0;
    int touch_detected = 0;
    int lux;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read touch sensor
        int current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        if (current_touch_state == 1 && !touch_detected) {
            // Touch detected
            touch_detected = 1;
            led_state = !led_state;
            gpioWrite(LED_GPIO, led_state);
            log_event(led_state);
            printf("Touch detected! LED toggled to %s\n", led_state ? "ON" : "OFF");
        } else if (current_touch_state == 0) {
            touch_detected = 0;
        }

        // Poll for timeout
        gpioDelay(POLL_TIMEOUT_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

