#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int activate_buzzer(int duration_ms);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request flame sensor line as input
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    // Request buzzer line as output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value HIGH: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Log system started event
    if (log_event("System started") < 0) {
        fprintf(stderr, "Failed to log system started event.\n");
    }

    int flame_detected = 0; // Flag to track flame detection state

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Continuing...\n");
            usleep(500000); // Wait 500ms before retrying
            continue;
        }

        // Flame detected (LOW signal)
        if (sensor_value == 0 && !flame_detected) {
            printf("Flame detected!\n");
            if (log_event("Flame detected") < 0) {
                fprintf(stderr, "Failed to log flame detection event.\n");
            }
            if (activate_buzzer(2000) < 0) {
                fprintf(stderr, "Failed to activate buzzer.\n");
            }
            flame_detected = 1; // Set the flag
        } else if (sensor_value == 1 && flame_detected) {
            // Flame disappeared (HIGH signal)
            flame_detected = 0; // Reset the flag
        }

        usleep(500000); // Poll every 500ms
    }

    // Log system stopped event
    if (log_event("System stopped") < 0) {
        fprintf(stderr, "Failed to log system stopped event.\n");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

