        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value HIGH: %s\n", strerror(errno));
        return -1;
    }
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Log system started event
    if (log_event("System started") < 0) {
        fprintf(stderr, "Failed to log system started event.\n");
    }

    int flame_detected = 0; // Flag to track flame detection state

    // Main loop
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Continuing...\n");
            usleep(500000); // Wait 500ms before retrying
            continue;
        }

        // Flame detected (LOW signal)
        if (sensor_value == 0 && !flame_detected) {
            printf("Flame detected!\n");
            if (log_event("Flame detected") < 0) {
                fprintf(stderr, "Failed to log flame detection event.\n");
            }
            if (activate_buzzer(2000) < 0) {
                fprintf(stderr, "Failed to activate buzzer.\n");
            }
            flame_detected = 1; // Set the flag
        } else if (sensor_value == 1 && flame_detected) {
            // Flame disappeared (HIGH signal)
            flame_detected = 0; // Reset the flag
        }

        usleep(500000); // Poll every 500ms
    }

    // Log system stopped event
    if (log_event("System stopped") < 0) {
        fprintf(stderr, "Failed to log system stopped event.\n");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

