// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR3_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR3_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, State: %s\n", timestamp, sensor_id, state == 0 ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Read initial sensor states
    SensorStates initial_states = {
        .sensor1_state = read_sensor(SENSOR1_GPIO),
        .sensor2_state = read_sensor(SENSOR2_GPIO),
        .sensor3_state = read_sensor(SENSOR3_GPIO)
    };

    if (initial_states.sensor1_state == -1 || initial_states.sensor2_state == -1 || initial_states.sensor3_state == -1) {
        fprintf(stderr, "Error reading initial sensor states. Exiting.\n");
        cleanup();
        return 1;
    }

    // Log initial sensor states
    log_event(1, initial_states.sensor1_state);
    log_event(2, initial_states.sensor2_state);
    log_event(3, initial_states.sensor3_state);

    printf("Monitoring magnet sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        } else {
            // Check for state changes and log them
            if (sensor1_state != initial_states.sensor1_state) {
                log_event(1, sensor1_state);
                initial_states.sensor1_state = sensor1_state;
            }
            if (sensor2_state != initial_states.sensor2_state) {
                log_event(2, sensor2_state);
                initial_states.sensor2_state = sensor2_state;
            }
            if (sensor3_state != initial_states.sensor3_state) {
                log_event(3, sensor3_state);
                initial_states.sensor3_state = sensor3_state;
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

