#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30
#define BPM_MAX 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t led_current;
    uint8_t averaging;
    uint8_t enable;
} sensor_config_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle, sensor_config_t config);
int read_heart_rate(int handle);
float calculate_bpm(int raw_value);
float apply_moving_average(float new_value, float *history, int history_size, int *index);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Verify sensor presence and check registers
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, 0x00);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    int hw_rev = i2cReadByteData(handle, 0x01);
    if (hw_rev < 0) {
        fprintf(stderr, "Failed to read HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    printf("Sensor verified successfully\n");
    return 0;
}

