#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for touch sensor inputs
#define TOUCH_PIN_1 5
#define TOUCH_PIN_2 6
#define TOUCH_PIN_3 7
#define TOUCH_PIN_4 8
#define TOUCH_PIN_5 9
#define TOUCH_PIN_6 10
#define TOUCH_PIN_7 11
#define TOUCH_PIN_8 12

// Define GPIO pins for 8-bit binary counter output
#define COUNTER_PIN_0 17
#define COUNTER_PIN_1 18
#define COUNTER_PIN_2 19
#define COUNTER_PIN_3 20
#define COUNTER_PIN_4 21
#define COUNTER_PIN_5 22
#define COUNTER_PIN_6 23
#define COUNTER_PIN_7 24

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_lines[8];
static struct gpiod_line *counter_lines[8];
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(int channel);
void increment_counter(void);
void display_counter(unsigned char value);
void log_touch_event(int channel, unsigned char counter_value);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    int i;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request touch sensor lines as input with pull-down resistors
    for (i = 0; i < 8; i++) {
        int pin;
        switch (i) {
            case 0: pin = TOUCH_PIN_1; break;
            case 1: pin = TOUCH_PIN_2; break;
            case 2: pin = TOUCH_PIN_3; break;
            case 3: pin = TOUCH_PIN_4; break;
            case 4: pin = TOUCH_PIN_5; break;
            case 5: pin = TOUCH_PIN_6; break;
            case 6: pin = TOUCH_PIN_7; break;
            case 7: pin = TOUCH_PIN_8; break;
            default: pin = -1; break; // Should not happen
        }

        touch_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!touch_lines[i]) {
            fprintf(stderr, "Error getting touch line %d: %s\n", pin, strerror(errno));
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
        config.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;

        ret = gpiod_line_request(touch_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting touch line %d: %s\n", pin, strerror(errno));
            goto cleanup;
        }
    }

    // Request counter lines as output
    for (i = 0; i < 8; i++) {
        int pin;
        switch (i) {
            case 0: pin = COUNTER_PIN_0; break;
            case 1: pin = COUNTER_PIN_1; break;
            case 2: pin = COUNTER_PIN_2; break;
            case 3: pin = COUNTER_PIN_3; break;
            case 4: pin = COUNTER_PIN_4; break;
            case 5: pin = COUNTER_PIN_5; break;
            case 6: pin = COUNTER_PIN_6; break;
            case 7: pin = COUNTER_PIN_7; break;
            default: pin = -1; break; // Should not happen
        }

        counter_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!counter_lines[i]) {
            fprintf(stderr, "Error getting counter line %d: %s\n", pin, strerror(errno));
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "counter_output";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(counter_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting counter line %d: %s\n", pin, strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    cleanup();
    return -1;
}

// Function to read the touch sensor
int read_touch_sensor(int channel) {
    int pin;
    struct gpiod_line *line;
    int value;

    switch (channel) {
        case 1: pin = TOUCH_PIN_1; line = touch_lines[0]; break;
        case 2: pin = TOUCH_PIN_2; line = touch_lines[1]; break;
        case 3: pin = TOUCH_PIN_3; line = touch_lines[2]; break;
        case 4: pin = TOUCH_PIN_4; line = touch_lines[3]; break;
        case 5: pin = TOUCH_PIN_5; line = touch_lines[4]; break;
        case 6: pin = TOUCH_PIN_6; line = touch_lines[5]; break;
        case 7: pin = TOUCH_PIN_7; line = touch_lines[6]; break;
        case 8: pin = TOUCH_PIN_8; line = touch_lines[7]; break;
        default: return -1; // Invalid channel
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor on channel %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }

    return value;
}

// Function to increment the counter
void increment_counter(void) {
    static unsigned char counter = 0;
    counter++;
    display_counter(counter);
}

// Function to display the counter on the output pins
void display_counter(unsigned char value) {
    int i;
    int ret;

    for (i = 0; i < 8; i++) {
        ret = gpiod_line_set_value(counter_lines[i], (value >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting counter line %d to %d: %s\n", i, (value >> i) & 1, strerror(errno));
        }
    }
}

// Function to log touch events
void log_touch_event(int channel, unsigned char counter_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Could not open log file for writing.\n");
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
}

// Function to cleanup GPIO resources
void cleanup(void) {
    int i;

