#define TOUCH_PIN_4 8
#define TOUCH_PIN_5 9
#define TOUCH_PIN_6 10
#define TOUCH_PIN_7 11
#define TOUCH_PIN_8 12

// Define GPIO pins for 8-bit binary counter output
#define COUNTER_PIN_0 17
#define COUNTER_PIN_1 18
#define COUNTER_PIN_2 19
#define COUNTER_PIN_3 20
#define COUNTER_PIN_4 21
#define COUNTER_PIN_5 22
#define COUNTER_PIN_6 23
#define COUNTER_PIN_7 24

