// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a CSV file
void log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
    }
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("tracking_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(log_file);
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Infrared tracking started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);
        int sensor4_value = read_sensor(SENSOR4_PIN);

        if (sensor1_value != -1 && sensor2_value != -1 && sensor3_value != -1 && sensor4_value != -1) {
            log_data(log_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value);
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Infrared tracking stopped.\n");

    return 0;
}

