#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *line17, *line18;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(struct gpiod_line *line);
void log_event(int sensor_number);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold sensor state
typedef struct {
    int last_state;
    struct timespec last_change_time;
} sensor_state_t;

sensor_state_t sensor17_state = {1, {0, 0}};
sensor_state_t sensor18_state = {1, {0, 0}};

// Function to initialize GPIO lines
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting GPIO17 line");
        gpiod_chip_close(chip);
        return -1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        perror("Error getting GPIO18 line");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return -1;
    }

    // Request GPIO lines as inputs with pull-up resistors
    if (gpiod_line_request_input_with_flags(line17, "tilt_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Error requesting GPIO17 line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return -1;
    }

    if (gpiod_line_request_input_with_flags(line18, "tilt_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Error requesting GPIO18 line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Function to log event to file
void log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor17_value = read_sensor(line17);
        int sensor18_value = read_sensor(line18);

        if (sensor17_value < 0 || sensor18_value < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Debounce and log sensor 17
        if (sensor17_value == 0 && sensor17_state.last_state == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long time_diff_ms = (now.tv_sec - sensor17_state.last_change_time.tv_sec) * 1000 + (now.tv_nsec - sensor17_state.last_change_time.tv_nsec) / 1000000;

            if (time_diff_ms >= DEBOUNCE_TIME_MS) {
                log_event(1);
                sensor17_state.last_state = 0;
                sensor17_state.last_change_time = now;
            }
        } else if (sensor17_value == 1) {
            sensor17_state.last_state = 1;
        }

        // Debounce and log sensor 18
        if (sensor18_value == 0 && sensor18_state.last_state == 1) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long time_diff_ms = (now.tv_sec - sensor18_state.last_change_time.tv_sec) * 1000 + (now.tv_nsec - sensor18_state.last_change_time.tv_nsec) / 1000000;

            if (time_diff_ms >= DEBOUNCE_TIME_MS) {
                log_event(2);
                sensor18_state.last_state = 0;
                sensor18_state.last_change_time = now;
            }
        } else if (sensor18_value == 1) {
            sensor18_state.last_state = 1;
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Tilt sensor monitoring stopped.\n");
    return 0;
}

