    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
        return -1; // Indicate error
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping this iteration.\n");
            gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for 100ms
            continue;
        }

        // Check if both sensors detect an obstacle
        int obstacle_detected = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        // Control LED
        if (control_led(LED_PIN, obstacle_detected) != 0) {
            fprintf(stderr, "Error controlling LED, skipping this iteration.\n");
        }

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, obstacle_detected) != 0) {
            fprintf(stderr, "Error logging data, skipping this iteration.\n");
        }

        // Delay for 100ms
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Turn off LED
    control_led(LED_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

