#define SAMPLE_PERIOD 125

// Define LED on time (milliseconds)
#define LED_ON_TIME 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the microphone input
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to trigger the LED
void trigger_led() {
    gpioWrite(LED_PIN, 1); // Turn LED ON
    gpioDelay(LED_ON_TIME * 1000); // Wait for LED_ON_TIME milliseconds
    gpioWrite(LED_PIN, 0); // Turn LED OFF
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", &tm_info);
    char milliseconds[5];
    sprintf(milliseconds, ".%03ld", ts.tv_nsec / 1000000);
    strcat(timestamp, milliseconds);
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();
}

