        int mic_value = read_microphone();

        if (mic_value == 1) {
            get_timestamp(timestamp);
            printf("%s: Peak detected\n", timestamp);
            trigger_led();
        }

        gpioDelay(SAMPLE_PERIOD); // Delay for SAMPLE_PERIOD microseconds
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

