#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49

// Define register addresses
#define SI1175_ALS_VIS_DATA0 0x24
#define SI1175_ALS_VIS_DATA1 0x25

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return value;
}

// Function to read the ALS visible data from the Si1175
int read_als_visible(int fd) {
    int lsb = read_i2c_reg(fd, SI1175_ALS_VIS_DATA0);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB\n");
        return -1;
    }

    int msb = read_i2c_reg(fd, SI1175_ALS_VIS_DATA1);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB\n");
        return -1;
    }

    return (msb << 8) | lsb;
}

