    left_value = gpiod_line_get_value(left_line);
    if (left_value < 0) {
        fprintf(stderr, "Error reading left line: %s\n", strerror(-left_value));
        return -1;
    }

    // Read the middle line
    middle_value = gpiod_line_get_value(middle_line);
