#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13
#define GPIO_19 19
#define GPIO_26 26
#define GPIO_12 12
#define GPIO_16 16
#define GPIO_20 20

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single GPIO pin
int read_gpio(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to format the sensor data into a string
int format_data(int channel1, int channel2, int channel3, int channel4, int channel5, int channel6, int channel7, int channel8, char *buffer, size_t buffer_size) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    int result = snprintf(buffer, buffer_size, "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
                         timestamp, channel1, channel2, channel3, channel4, channel5, channel6, channel7, channel8);

    if (result < 0 || result >= buffer_size) {
        fprintf(stderr, "Error formatting data: buffer overflow or encoding error\n");
        return -1; // Indicate an error
    }
    return 0;
}

// Function to log the sensor data to the console
void log_data(const char *data) {
    printf("%s\n", data);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(GPIO_5, PI_INPUT);
    gpioSetMode(GPIO_6, PI_INPUT);
    gpioSetMode(GPIO_13, PI_INPUT);
    gpioSetMode(GPIO_19, PI_INPUT);
    gpioSetMode(GPIO_26, PI_INPUT);
    gpioSetMode(GPIO_12, PI_INPUT);
    gpioSetMode(GPIO_16, PI_INPUT);
    gpioSetMode(GPIO_20, PI_INPUT);

    // Main loop to read and log sensor data
    while (program_running) {
        int channel1 = read_gpio(GPIO_5);
        int channel2 = read_gpio(GPIO_6);
        int channel3 = read_gpio(GPIO_13);
        int channel4 = read_gpio(GPIO_19);
        int channel5 = read_gpio(GPIO_26);
        int channel6 = read_gpio(GPIO_12);
        int channel7 = read_gpio(GPIO_16);
        int channel8 = read_gpio(GPIO_20);

        if (channel1 == -1 || channel2 == -1 || channel3 == -1 || channel4 == -1 ||
            channel5 == -1 || channel6 == -1 || channel7 == -1 || channel8 == -1) {
            fprintf(stderr, "Error reading sensor data, skipping this iteration\n");
            gpioDelay(200); // Wait 200ms before the next iteration
            continue;
        }

        char data_buffer[256];
        if (format_data(channel1, channel2, channel3, channel4, channel5, channel6, channel7, channel8, data_buffer, sizeof(data_buffer)) == 0) {
            log_data(data_buffer);
        } else {
            fprintf(stderr, "Error formatting data, skipping logging\n");
        }

        gpioDelay(200); // Wait 200ms before the next iteration
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

