// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define fade duration (seconds)
#define FADE_DURATION 5

// Define number of steps for linear interpolation
#define NUM_STEPS 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void set_led_color(int red, int green, int blue);
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b);
void fade_to_color(int target_red, int target_green, int target_blue);

// Signal handler function
