#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_CONTROL         0x0F
#define TCS34725_ID              0x12
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// GPIO Pin for LED
#define LED_GPIO_PIN            17

// Calibration Values
#define RED_GAIN                1.0
#define GREEN_GAIN              1.0
#define BLUE_GAIN               1.0
#define CLEAR_OFFSET            0
#define RED_OFFSET              0
#define GREEN_OFFSET            0
#define BLUE_OFFSET             0

// Red Threshold
#define RED_THRESHOLD           200

// I2C Bus
#define I2C_BUS                 "/dev/i2c-1"

// Global Variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue, float *calibrated_clear);
void control_led(struct gpiod_line *line, int state);
void signal_handler(int sig);

// I2C Read Register Function
int i2c_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg | TCS34725_COMMAND_BIT;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

// I2C Write Register Function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg | TCS34725_COMMAND_BIT;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }

    return 0;
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    // Check sensor ID
    int sensor_id = i2c_read_register(fd, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_register(fd, TCS34725_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }
    usleep(3000); // Wait for power-on

    // Enable RGBC
    if (i2c_write_register(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling RGBC\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2c_write_register(fd, TCS34725_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (CONTROL)
    if (i2c_write_register(fd, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 Read Data Function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    uint8_t reg = TCS34725_CDATA | TCS34725_COMMAND_BIT;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for data read");
        return -1;
    }

    if (read(fd, buf, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// Calibrate Data Function
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue, float *calibrated_clear) {
    *calibrated_clear = (float)clear - CLEAR_OFFSET;
    *calibrated_red   = (float)red   * RED_GAIN   - RED_OFFSET;
    *calibrated_green = (float)green * GREEN_GAIN - GREEN_OFFSET;
    *calibrated_blue  = (float)blue  * BLUE_GAIN  - BLUE_OFFSET;
}

// Control LED Function
void control_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Failed to set LED state");
    }
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    float calibrated_red, calibrated_green, calibrated_blue, calibrated_clear;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate data
            calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue, &calibrated_clear);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                control_led(led_line, 1); // Turn LED on
            } else {
                control_led(led_line, 0); // Turn LED off
            }

            // Print calibrated data
            printf("C: %.2f, R: %.2f, G: %.2f, B: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);
        } else {
            fprintf(stderr, "Failed to read sensor data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
        }

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    control_led(led_line, 0); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

