    if (i2c_write_register(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling RGBC\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2c_write_register(fd, TCS34725_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (CONTROL)
    if (i2c_write_register(fd, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 Read Data Function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    uint8_t reg = TCS34725_CDATA | TCS34725_COMMAND_BIT;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for data read");
        return -1;
    }

    if (read(fd, buf, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// Calibrate Data Function
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue, float *calibrated_clear) {
    *calibrated_clear = (float)clear - CLEAR_OFFSET;
    *calibrated_red   = (float)red   * RED_GAIN   - RED_OFFSET;
    *calibrated_green = (float)green * GREEN_GAIN - GREEN_OFFSET;
    *calibrated_blue  = (float)blue  * BLUE_GAIN  - BLUE_OFFSET;
}

// Control LED Function
void control_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Failed to set LED state");
    }
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    float calibrated_red, calibrated_green, calibrated_blue, calibrated_clear;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate data
            calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue, &calibrated_clear);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                control_led(led_line, 1); // Turn LED on
            } else {
                control_led(led_line, 0); // Turn LED off
            }

            // Print calibrated data
            printf("C: %.2f, R: %.2f, G: %.2f, B: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);
        } else {
            fprintf(stderr, "Failed to read sensor data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                terminate = 1; // Exit loop if re-initialization fails
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                close(i2c_fd);
                terminate = 1;
                continue;
            }
        }

        // Wait 200ms
        usleep(200000);
    }

    // Cleanup
    control_led(led_line, 0); // Turn LED off
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

