#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define LED_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
float map_lux_to_brightness(float lux);
void set_led_brightness(float brightness);
void generate_ws2812b_data(uint8_t *data, int num_leds, uint8_t red, uint8_t green, uint8_t blue);
void send_ws2812b_data(uint8_t *data, int num_leds);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 800000); // 800 kHz
    gpioSetPWMrange(LED_GPIO, 255); // 8-bit PWM

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE);
        if (result != 0) {
            fprintf(stderr, "Failed to write to I2C device (mode): %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // Wait 180 ms for measurement

        result = i2cReadWordData(i2c_handle, 0); // Read 2 bytes
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C device (data): %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
            continue;
        }

        uint16_t raw_value = (uint16_t)result;
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries\n");
    return -1; // Failure
}

// Map lux value to brightness (logarithmic mapping)
float map_lux_to_brightness(float lux) {
    if (lux <= 0) {
        return 0.0;
    }

    // Use a logarithmic scale for brightness mapping
    float brightness = log10(lux + 1) / log10(1001) * 255.0; // Map 0-1000 lux to 0-255

    // Clamp the brightness value to the range [0, 255]
    if (brightness < 0) {
        brightness = 0;
    } else if (brightness > 255) {
        brightness = 255;
    }

    return brightness;
}

// Set LED brightness using PWM
void set_led_brightness(float brightness) {
    gpioPWM(LED_GPIO, (int)brightness);
}

// Generate WS2812B data (simplified for all LEDs the same color)
void generate_ws2812b_data(uint8_t *data, int num_leds, uint8_t red, uint8_t green, uint8_t blue) {
    for (int i = 0; i < num_leds; i++) {
        // Green
        for (int j = 7; j >= 0; j--) {
            if ((green >> j) & 1) {
                data[i * 24 + 0] = 0x80; // 1 bit
                data[i * 24 + 1] = 0x00; // 0 bit
            } else {
                data[i * 24 + 0] = 0x40; // 0 bit
                data[i * 24 + 1] = 0x00; // 1 bit
            }
        }

        // Red
        for (int j = 7; j >= 0; j--) {
            if ((red >> j) & 1) {
                data[i * 24 + 2] = 0x80; // 1 bit
                data[i * 24 + 3] = 0x00; // 0 bit
            } else {
                data[i * 24 + 2] = 0x40; // 0 bit
                data[i * 24 + 3] = 0x00; // 1 bit
            }
        }

        // Blue
        for (int j = 7; j >= 0; j--) {
            if ((blue >> j) & 1) {
                data[i * 24 + 4] = 0x80; // 1 bit
                data[i * 24 + 5] = 0x00; // 0 bit
            } else {
                data[i * 24 + 4] = 0x40; // 0 bit
                data[i * 24 + 5] = 0x00; // 1 bit
            }
        }
    }
}

// Send WS2812B data via hardware PWM
void send_ws2812b_data(uint8_t *data, int num_leds) {
    gpioWaveClear();

    gpioPulse_t pulse[NUM_LEDS * 24]; // Each bit requires 2 pulses
    int pulse_count = 0;

    for (int i = 0; i < num_leds; i++) {
        for (int j = 0; j < 24; j++) {
            if (data[i * 24 + j] > 0x80) { // 1 bit
                pulse[pulse_count].gpioOn = (1 << LED_GPIO);
                pulse[pulse_count].gpioOff = 0;
                pulse[pulse_count].usDelay = 0.8; // 0.8 us
                pulse_count++;

                pulse[pulse_count].gpioOn = 0;
                pulse[pulse_count].gpioOff = (1 << LED_GPIO);
                pulse[pulse_count].usDelay = 0.45; // 0.45 us
                pulse_count++;
            } else { // 0 bit
                pulse[pulse_count].gpioOn = (1 << LED_GPIO);
                pulse[pulse_count].gpioOff = 0;
                pulse[pulse_count].usDelay = 0.4; // 0.4 us
                pulse_count++;

                pulse[pulse_count].gpioOn = 0;
                pulse[pulse_count].gpioOff = (1 << LED_GPIO);
                pulse[pulse_count].usDelay = 0.85; // 0.85 us
                pulse_count++;
            }
        }
    }

    gpioWaveAddGeneric(pulse_count, pulse);
    int wave_id = gpioWaveCreate();

    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Send wave in loop mode
        while (gpioWaveTxBusy()) {
            gpioDelay(1000); // Wait for wave to finish
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Failed to create wave: %d\n", wave_id);
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    float brightness;
    uint8_t led_data[NUM_LEDS * 24]; // 24 bits per LED (GRB)

    printf("Ambient Light Sensor and LED Strip Control\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);
            printf("Brightness: %.2f\n", brightness);

            // Set LED brightness
            set_led_brightness(brightness);

            // Generate WS2812B data (all LEDs same color)
            generate_ws2812b_data(led_data, NUM_LEDS, 0, 0, 255); // Blue

            // Send WS2812B data
            send_ws2812b_data(led_data, NUM_LEDS);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

