#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define NUM_LEDS 1
#define START_FRAME 0x00000000
#define END_FRAME 0xFFFFFFFF
#define I2C_RETRY_COUNT 3
#define SPI_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_bh1750(int fd);
float convert_lux(int raw_value);
int map_lux_to_brightness(float lux);
int init_spi(int speed);
int send_apa102_frame(int fd, int brightness, int red, int green, int blue);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    // Turn off LEDs
    if (spi_fd != -1) {
        send_apa102_frame(spi_fd, 0, 0, 0, 0); // Black
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read BH1750 sensor
int read_bh1750(int fd) {
    uint8_t cmd = 0x20; // One-Time High-Resolution Mode
    int raw_value = -1;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // 10 ms delay
            continue;
        }

        usleep(180000); // Wait for measurement (at least 180 ms)

        uint8_t buffer[2];
        if (read(fd, buffer, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // 10 ms delay
            continue;
        }

        raw_value = (buffer[0] << 8) | buffer[1];
        break; // Success, exit retry loop
    }

