#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CONTINUOUS_HIGH_RES_MODE_2 0x21
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 30
#define FADE_DURATION_MS 500
#define SAMPLE_DELAY_MS 100

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
float read_lux(int i2c_handle);
float average_lux(float lux1, float lux2, float lux3);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int spi_handle, int brightness);
void fade_brightness(int spi_handle, int current_brightness, int target_brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE_2);
    if (result != 0) {
        fprintf(stderr, "Error initializing BH1750: %d\n", result);
        return -1;
    }
    gpioDelay(180000); // Wait for measurement (at least 180ms)
    return 0;
}

// Read lux value from BH1750 sensor
float read_lux(int i2c_handle) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading lux value: %d\n", result);
        return -1.0;
    }
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Average lux values
float average_lux(float lux1, float lux2, float lux3) {
    int count = 0;
    float sum = 0.0;

    if (lux1 >= 0) {
        sum += lux1;
        count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        count++;
    }

    if (count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return sum / count;
}

// Map lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Use a logarithmic mapping for better brightness control
    float log_lux = log10(average_lux + 1); // Add 1 to avoid log(0)
    float brightness_float = log_lux / log10(1000) * 31; // Map 0-1000 lux to 0-31

    // Clamp the brightness value to the range 0-31
    int brightness = (int)brightness_float;
    if (brightness < 0) {
        brightness = 0;
    } else if (brightness > 31) {
        brightness = 31;
    }

    return brightness;
}

// Set APA102 strip brightness
void set_apa102_brightness(int spi_handle, int brightness) {
    unsigned char data[4];
    data[0] = 0xE0 | brightness; // Global brightness (0xE0-0xFF)
    data[1] = 0x00; // Blue
    data[2] = 0x00; // Green
    data[3] = 0x00; // Red

    for (int i = 0; i < NUM_LEDS; i++) {
        spiWrite(spi_handle, data, 4);
    }

    // Send end frame (4 null bytes)
    unsigned char end_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, end_frame, 4);
}

// Fade brightness smoothly
void fade_brightness(int spi_handle, int current_brightness, int target_brightness) {
    int steps = 10; // Number of steps in the fade
    float increment = (float)(target_brightness - current_brightness) / steps;
    float brightness = current_brightness;

    for (int i = 0; i < steps; i++) {
        brightness += increment;
        set_apa102_brightness(spi_handle, (int)brightness);
        gpioDelay(FADE_DURATION_MS / steps * 1000); // Delay in microseconds
    }

    set_apa102_brightness(spi_handle, target_brightness);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle_low = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_LOW, i2c_handle_low);
    } else {
        if (init_bh1750(i2c_handle_low) != 0) {
            i2cClose(i2c_handle_low);
            i2c_handle_low = -1;
        }
    }

    i2c_handle_high = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_HIGH, i2c_handle_high);
    } else {
        if (init_bh1750(i2c_handle_high) != 0) {
            i2cClose(i2c_handle_high);
            i2c_handle_high = -1;
        }
    }

    // Open SPI handle
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
        if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int current_brightness = 0;

    // Main loop
    while (!terminate) {
        float lux1 = -1.0, lux2 = -1.0, lux3 = -1.0;

        if (i2c_handle_low >= 0) {
            lux1 = read_lux(i2c_handle_low);
        }
        if (i2c_handle_high >= 0) {
            lux2 = read_lux(i2c_handle_high);
        }

        float average_lux_value = average_lux(lux1, lux2, lux3);
        int target_brightness = map_lux_to_brightness(average_lux_value);

        fade_brightness(spi_handle, current_brightness, target_brightness);
        current_brightness = target_brightness;

        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Clean up
    set_apa102_brightness(spi_handle, 0); // Turn off LED strip
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

