#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define ALS_DATA_REG 0x04
#define CONFIG_REG 0x00
#define CONFIG_VALUE 0x0000 // Integration time 100ms, Gain 1/8
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)
#define MAX_LUX 120000.0
#define MAX_BRIGHTNESS 255.0
#define GAMMA 2.2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_veml7700(int fd);
int read_als_data(int fd, uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize VEML7700
int init_veml7700(int fd) {
    uint8_t config_data[2];
    config_data[0] = CONFIG_VALUE & 0xFF;
    config_data[1] = (CONFIG_VALUE >> 8) & 0xFF;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (write(fd, config_data, 2) == 2) {
            return 0; // Success
        }
        perror("Error writing to VEML7700 config register");
        usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Failed to initialize VEML7700 after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read ALS data from VEML7700
int read_als_data(int fd, uint16_t *als_data) {
    uint8_t reg = ALS_DATA_REG;
    uint8_t data[2];

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, data, 2) == 2) {
                *als_data = (data[1] << 8) | data[0];
                return 0; // Success
            }
            perror("Error reading ALS data");
        } else {
            perror("Error writing ALS data register address");
        }
        usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Failed to read ALS data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate lux value
float calculate_lux(uint16_t als_data) {
    return als_data * 0.0288; // Simplified calculation
}

// Set LED brightness using PWM (bit-banging)
int set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > 255) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    // Calculate duty cycle (on time / period)
    long on_time_ns = (long)((float)brightness / 255.0 * PWM_PERIOD_NS);
    long off_time_ns = PWM_PERIOD_NS - on_time_ns;

    // Bit-banging loop
    struct timespec on_time = {0, on_time_ns};
    struct timespec off_time = {0, off_time_ns};

    if (nanosleep(&on_time, NULL) != 0) {
        perror("nanosleep on");
        return -1;
    }

    if (nanosleep(&off_time, NULL) != 0) {
        perror("nanosleep off");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, VEML7700_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "ws2812b", 0) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t als_data;
    float lux;
    int brightness;

    while (!terminate) {
        // Read ALS data
        if (read_als_data(i2c_fd, &als_data) == 0) {
            // Calculate lux
            lux = calculate_lux(als_data);

            // Map lux to brightness (gamma correction)
            brightness = (int)(MAX_BRIGHTNESS * pow(lux / MAX_LUX, 1.0 / GAMMA));
            if (brightness < 0) brightness = 0;
            if (brightness > 255) brightness = 255;

            // Set LED brightness
            if (set_led_brightness(brightness) != 0) {
                fprintf(stderr, "Error setting LED brightness.\n");
            }

            // Print lux and brightness
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data. Retrying...\n");
        }

        // Delay
        usleep(200000); // 200 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

