#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define SELF_TEST_DURATION 1000 // milliseconds
#define SELF_TEST_READINGS 5
#define SELF_TEST_INTERVAL 100 // milliseconds
#define POLLING_INTERVAL 50 // milliseconds
#define FLAME_DETECTED_DURATION 100 // milliseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int self_test();
void signal_handler(int sig);
void log_event(const char *event);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/export");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/unexport");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Set GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to GPIO direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Read GPIO value
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fgets(value_str, 3, fp) == NULL) {
        perror("Failed to read GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(value_str);
}

// Write GPIO value
int gpio_write(int pin, int value) {
    char path[64];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Self-test function
int self_test() {
    int i, flame_detected = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds

    printf("Starting self-test...\n");

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        if (gpio_write(LED_PIN, 1) != 0) return -1;
        nanosleep(&sleep_time, NULL);
        if (gpio_write(LED_PIN, 0) != 0) return -1;
        nanosleep(&sleep_time, NULL);
    }

    // Read flame sensor
    printf("Reading flame sensor for %d ms...\n", SELF_TEST_DURATION);
    for (i = 0; i < SELF_TEST_READINGS; i++) {
        int value = gpio_read(FLAME_SENSOR_PIN);
        if (value < 0) return -1;
        if (value == 0) {
            flame_detected++;
        }
        nanosleep(&sleep_time, NULL);
    }

    if (flame_detected == SELF_TEST_READINGS) {
        printf("Self-test failed: Flame sensor consistently detected (LOW).\n");
        // Rapid LED blinking
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        for (i = 0; i < 5; i++) {
            if (gpio_write(LED_PIN, 1) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            if (gpio_write(LED_PIN, 0) != 0) return -1;
            nanosleep(&sleep_time, NULL);
        }

        // Buzzer short-short-long-short pattern
        sleep_time.tv_nsec = 200 * 1000 * 1000; // 200 milliseconds
        for (i = 0; i < 3; i++) {
            if (gpio_write(BUZZER_PIN, 1) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            if (gpio_write(BUZZER_PIN, 0) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            if (gpio_write(BUZZER_PIN, 1) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            if (gpio_write(BUZZER_PIN, 0) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            sleep_time.tv_nsec = 600 * 1000 * 1000; // 600 milliseconds
            if (gpio_write(BUZZER_PIN, 1) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            if (gpio_write(BUZZER_PIN, 0) != 0) return -1;
            nanosleep(&sleep_time, NULL);
            sleep_time.tv_nsec = 200 * 1000 * 1000; // 200 milliseconds
        }

        return -1; // Indicate self-test failure
    }

    printf("Self-test passed.\n");
    return 0; // Indicate self-test success
}

// Log events with timestamps
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_sensor_line || !buzzer_line || !led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request flame sensor line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform self-test
    if (self_test() != 0) {
        log_event("Self-test failed, exiting.");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("System started.");

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLLING_INTERVAL * 1000 * 1000; // 50 milliseconds

    int flame_detected = 0;
    int flame_gone = 0;

    while (!terminate) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            perror("Failed to read flame sensor value");
            break;
        }

        if (value == 0) { // Flame detected (LOW)
            if (!flame_detected) {
                log_event("Flame detected!");
                if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                    perror("Failed to set buzzer value");
                    break;
                }
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("Failed to set LED value");
                    break;
                }
                flame_detected = 1;
                flame_gone = 0; // Reset flame_gone flag
            }
        } else { // No flame detected (HIGH)
            if (flame_detected) {
                // Check if flame has been gone for at least FLAME_DETECTED_DURATION
                flame_gone = 1;
                sleep_time.tv_nsec = FLAME_DETECTED_DURATION * 1000 * 1000; // FLAME_DETECTED_DURATION milliseconds
                nanosleep(&sleep_time, NULL);
                value = gpiod_line_get_value(flame_sensor_line);
                if (value < 0) {
                    perror("Failed to read flame sensor value");
                    break;
                }
                if (value == 1) { // Flame is still gone
                    log_event("Flame gone.");
                    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                        perror("Failed to set buzzer value");
                        break;
                    }
                    if (gpiod_line_set_value(led_line, 0) < 0) {
                        perror("Failed to set LED value");
                        break;
                    }
                    flame_detected = 0;
                } else {
                    // Flame re-appeared before FLAME_DETECTED_DURATION, reset flame_gone flag
                    flame_gone = 0;
                }
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    log_event("System shutting down.");
    if (gpiod_line_set_value(buzzer_line, 0) < 0) perror("Failed to set buzzer value");
    if (gpiod_line_set_value(led_line, 0) < 0) perror("Failed to set LED value");
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

