#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_bh1750(int fd);
int read_bh1750(int fd, float *lux);
float convert_to_lux(uint16_t raw_value);
void add_to_buffer(float lux);
float calculate_average_lux();
float calculate_blink_rate(float avg_lux);
int set_gpio_value(int gpio, int value);
int export_gpio(int gpio);
int unexport_gpio(int gpio);
void signal_handler(int signal);

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 initialization function
int init_bh1750(int fd) {
    uint8_t mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// BH1750 reading function
int read_bh1750(int fd, float *lux) {
    uint8_t buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read(fd, buffer, 2) == 2) {
            uint16_t raw_value = (buffer[0] << 8) | buffer[1];
            *lux = convert_to_lux(raw_value);
            return 0; // Success
        } else {
            perror("Error reading from BH1750");
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Conversion function
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Circular buffer functions
void add_to_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

float calculate_average_lux() {
    if (buffer_count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += lux_buffer[i];
    }
    return sum / buffer_count;
}

// Blink rate calculation function
float calculate_blink_rate(float avg_lux) {
    float rate = 0.5 + (avg_lux / 1000.0) * 4.5;
    if (rate < 0.5) {
        rate = 0.5;
    } else if (rate > 5.0) {
        rate = 5.0;
    }
    return rate;
}

// GPIO functions
int set_gpio_value(int gpio, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (write(fd, value ? "1" : "0", 1) != 1) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int export_gpio(int gpio) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO export file");
        return -1;
    }

    char buf[3];
    snprintf(buf, sizeof(buf), "%d", gpio);
    if (write(fd, buf, strlen(buf)) != strlen(buf)) {
        perror("Error writing to GPIO export file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int unexport_gpio(int gpio) {
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO unexport file");
        return -1;
    }

    char buf[3];
    snprintf(buf, sizeof(buf), "%d", gpio);
    if (write(fd, buf, strlen(buf)) != strlen(buf)) {
        perror("Error writing to GPIO unexport file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize BH1750
    if (init_bh1750(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Export GPIO
    if (export_gpio(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set GPIO direction to output
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        unexport_gpio(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }
    if (write(fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        close(fd);
        unexport_gpio(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }
    close(fd);

    struct timespec on_time, off_time;
    float avg_lux, blink_rate;
    float lux;

    while (program_running) {
        // Read light level
        if (read_bh1750(i2c_fd, &lux) == 0) {
            // Add to buffer
            add_to_buffer(lux);

            // Calculate average lux
            avg_lux = calculate_average_lux();

            // Calculate blink rate
            blink_rate = calculate_blink_rate(avg_lux);

            // Blink LED
            on_time.tv_sec = 0;
            on_time.tv_nsec = 500000000; // 500ms
            off_time.tv_sec = 0;
            off_time.tv_nsec = 500000000; // 500ms

            set_gpio_value(GPIO_PIN, 1);
            nanosleep(&on_time, NULL);
            set_gpio_value(GPIO_PIN, 0);
            nanosleep(&off_time, NULL);

            printf("Lux: %.2f, Avg Lux: %.2f, Blink Rate: %.2f Hz\n", lux, avg_lux, blink_rate);
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        sleep(1);
    }

    // Cleanup
    set_gpio_value(GPIO_PIN, 0); // Turn off LED
    unexport_gpio(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

