    // Release GPIO lines
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to shift out data to the 74HC595
int shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, unsigned char data) {
    int i;

    // Send data bits MSB first
    for (i = 7; i >= 0; i--) {
        // Set data line based on the current bit
        int ret = gpiod_line_set_value(data_line, (data >> i) & 0x01);
        if (ret < 0) {
            fprintf(stderr, "Error setting data line value: %s\n", strerror(-ret));
            return -1;
        }

        // Clock the data in
        ret = gpiod_line_set_value(clock_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting clock line value: %s\n", strerror(-ret));
            return -1;
        }
        usleep(1); // Small delay for clock stability

        ret = gpiod_line_set_value(clock_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting clock line value: %s\n", strerror(-ret));
            return -1;
        }
        usleep(1); // Small delay for clock stability
    }

    // Latch the data to the output
    int ret = gpiod_line_set_value(latch_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting latch line value: %s\n", strerror(-ret));
        return -1;
    }
    usleep(1); // Small delay for latch stability

    ret = gpiod_line_set_value(latch_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting latch line value: %s\n", strerror(-ret));
        return -1;
    }
    usleep(1); // Small delay for latch stability

    return 0;
}

