        fprintf(stderr, "Error requesting clock line: %s\n", strerror(errno));
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "seven_segment", 0) < 0) {
        fprintf(stderr, "Error requesting latch line: %s\n", strerror(errno));
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Display the digit '5'
        if (shift_out(data_line, clock_line, latch_line, SEGMENT_PATTERN) < 0) {
            fprintf(stderr, "Error shifting out data\n");
            break; // Exit loop on error
        }
        usleep(500000); // 500 ms

        // Turn off the display
        if (shift_out(data_line, clock_line, latch_line, 0x00) < 0) {
            fprintf(stderr, "Error shifting out data\n");
            break; // Exit loop on error
        }
        usleep(500000); // 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return 0;
}

