#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int setup_gpio(void);
void blink_led(void);
void button_callback(struct gpiod_line *line, unsigned int num, void *data);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Setup GPIO lines and chip
int setup_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request button line as input with pull-up
    if (gpiod_line_request_input(button_line, "blink_button") < 0) {
        perror("Error requesting button line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Request rising edge event for button line
    if (gpiod_line_request_rising_edge_events(button_line, "blink_button") < 0) {
        perror("Error requesting rising edge events for button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Request falling edge event for button line
    if (gpiod_line_request_falling_edge_events(button_line, "blink_button") < 0) {
        perror("Error requesting falling edge events for button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

// Blink LED with 2-second period
void blink_led(void) {
    // Turn LED on
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error setting LED value to 1");
        cleanup_gpio();
        exit(1);
    }
    usleep(1000000); // 1 second

    // Turn LED off
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED value to 0");
        cleanup_gpio();
        exit(1);
    }
    usleep(1000000); // 1 second
}

// Callback function for button events
void button_callback(struct gpiod_line *line, unsigned int num, void *data) {
    // Check if the event is a falling edge
    if (gpiod_line_event_get_type(line) == GPIOD_LINE_EVENT_FALLING_EDGE) {
        printf("Button pressed!\n");

        // Stop blinking
        // Release the LED line
        if (gpiod_line_release(led_line) < 0) {
            perror("Error releasing LED line");
            cleanup_gpio();
            exit(1);
        }
        led_line = NULL; // Set to NULL to prevent double release

        // Turn off the LED
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting LED value to 0");
            cleanup_gpio();
            exit(1);
        }

        // Release the button line
        if (gpiod_line_release(button_line) < 0) {
            perror("Error releasing button line");
            cleanup_gpio();
            exit(1);
        }
        button_line = NULL; // Set to NULL to prevent double release

        // Close the GPIO chip
        if (gpiod_chip_close(chip) < 0) {
            perror("Error closing GPIO chip");
            cleanup_gpio();
            exit(1);
        }
        chip = NULL; // Set to NULL to prevent double close

        exit(0); // Exit the program
    }
}

// Cleanup GPIO lines and chip
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    printf("Blinking LED. Press button to stop.\n");

    // Main loop
    while (1) {
        // Blink the LED
        blink_led();

        // Wait for button event with timeout
        struct timespec timeout;
        timeout.tv_sec = 1; // 1 second timeout
        timeout.tv_nsec = 0;

        int ret = gpiod_line_event_wait(button_line, &timeout);
        if (ret < 0) {
            perror("Error waiting for button event");
            cleanup_gpio();
            return 1;
        } else if (ret == 0) {
            // Timeout occurred, continue blinking
            continue;
        } else {
            // Button event occurred, call the callback function
            button_callback(button_line, 0, NULL);
        }
    }

    return 0;
}

