#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define I2C address for BH1750
#define BH1750_ADDR 0x23

// Define I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int i2c_init(void);
int read_bh1750(float *lux);
int button_pressed(void);
void led_on(void);
void led_off(void);
void led_blink(void);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    terminate = 1;

    // Turn off LED
    if (led_line) {
        led_off();
    }

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

// Initialize GPIO
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    button_line = gpiod_chip_get_line(gpio_chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting button line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Set LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Set button line as input with pull-down
    if (gpiod_line_request_input(button_line, "button") < 0) {
        fprintf(stderr, "Error requesting button line as input: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

// Initialize I2C
int i2c_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
int read_bh1750(float *lux) {
    unsigned char buf[2];
    int ret;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Check if button is pressed
int button_pressed(void) {
    int value = gpiod_line_get_value(button_line);
    if (value < 0) {
        fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
        return 0; // Return 0 on error to avoid unexpected behavior
    }
    return (value == 0); // Button is pressed if value is 0 (active low)
}

// Turn LED on
void led_on(void) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

// Turn LED off
void led_off(void) {
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

// Blink LED
void led_blink(void) {
    led_on();
    usleep(500000); // 500ms
    led_off();
    usleep(500000); // 500ms
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return 1;
    }

    // Initialize I2C
    if (i2c_init() < 0) {
        cleanup(0);
        return 1;
    }

    float lux;
    int button_state = 0; // 0: released, 1: pressed

    printf("Environmental Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        // Check button state
        int current_button_state = button_pressed();

        if (current_button_state && !button_state) {
            // Button pressed
            printf("Button pressed!\n");
            button_state = 1;
            while (button_pressed() && !terminate) {
                led_blink();
            }
            led_off();
        } else if (!current_button_state && button_state) {
            // Button released
            printf("Button released!\n");
            button_state = 0;
        }

        usleep(100000); // 100ms delay
    }

    cleanup(0);
    return 0;
}

