        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double g_force;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
