int initialize_sensor() {
    int result;
    // Set MODE_REG to 0x01 for normal operation
    result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error writing to MODE_REG: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;
    uint8_t als_lsb, als_msb, red_lsb, green_lsb, blue_lsb;

    // Read ALS data
    result = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_LSB_REG: %d\n", result);
        return -1;
    }
    als_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS_MSB_REG: %d\n", result);
        return -1;
    }
    als_msb = (uint8_t)result;

    *als = (als_msb << 8) | als_lsb;

    // Read RGB data
    result = i2cReadByteData(i2c_handle, RED_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading RED_LSB_REG: %d\n", result);
        return -1;
    }
    red_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, GREEN_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading GREEN_LSB_REG: %d\n", result);
        return -1;
    }
    green_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, BLUE_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading BLUE_LSB_REG: %d\n", result);
        return -1;
    }
    blue_lsb = (uint8_t)result;

    *red = (uint16_t)red_lsb;
    *green = (uint16_t)green_lsb;
    *blue = (uint16_t)blue_lsb;

    return 0;
}

// Function to map ALS value to PWM duty cycle
int map_als_to_pwm(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als / 65535.0) * 255.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    return duty_cycle;
}

