    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("color_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&als, &red, &green, &blue) == 0) {
            // Map ALS to PWM duty cycle
            duty_cycle = map_als_to_pwm(als);

            // Set PWM duty cycle
            gpioPWM(LED_GPIO, duty_cycle);

            // Log data
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100 ms delay
            i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_sensor() != 0) {
                    fprintf(stderr, "Sensor re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

