#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Sensitivity (dps/LSB)
#define SENSITIVITY 0.00875

// Zero-rate threshold (dps)
#define ZERO_RATE_THRESHOLD 0.1

// Alert threshold (dps)
#define ALERT_THRESHOLD 50.0

// Calibration samples
#define CALIBRATION_SAMPLES 100

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold calibration offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} gyro_calibration_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gyro(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
gyro_calibration_t calibrate_gyro(int fd);
gyro_data_t apply_calibration(gyro_data_t data, gyro_calibration_t calibration);
int log_data(FILE *fp, gyro_data_t data);
void signal_handler(int sig);
int check_sensor_presence(int fd);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize gyroscope
int init_gyro(int fd) {
    // CTRL_REG1: Normal mode, all axes enabled, 100 Hz ODR
    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Error setting I2C slave address for CTRL_REG1");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, CTRL_REG1, 0x0F) < 0) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // CTRL_REG4: 250 dps full-scale, continuous update
    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Error setting I2C slave address for CTRL_REG4");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, CTRL_REG4, 0x00) < 0) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

// Check sensor presence
int check_sensor_presence(int fd) {
    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Error setting I2C slave address for WHO_AM_I");
        return -1;
    }
    int who_am_i = i2c_smbus_read_byte_data(fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Error reading WHO_AM_I");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: Gyroscope not found (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];

    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Error setting I2C slave address for data read");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    data->x = (float)raw_x * SENSITIVITY;
    data->y = (float)raw_y * SENSITIVITY;
    data->z = (float)raw_z * SENSITIVITY;

    return 0;
}

// Calibrate gyroscope
gyro_calibration_t calibrate_gyro(int fd) {
    gyro_calibration_t calibration = {0.0, 0.0, 0.0};
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;
    uint8_t buffer[6];

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
            perror("Error setting I2C slave address for calibration");
            calibration.x_offset = calibration.y_offset = calibration.z_offset = 0.0; // Set to 0 to avoid using uninitialized values
            return calibration;
        }

        if (read(fd, buffer, 6) != 6) {
            perror("Error reading gyroscope data during calibration");
            calibration.x_offset = calibration.y_offset = calibration.z_offset = 0.0; // Set to 0 to avoid using uninitialized values
            return calibration;
        }

        raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

        calibration.x_offset += (float)raw_x * SENSITIVITY;
        calibration.y_offset += (float)raw_y * SENSITIVITY;
        calibration.z_offset += (float)raw_z * SENSITIVITY;

        usleep(5000); // 5 ms delay
    }

    // Calculate average offsets
    calibration.x_offset /= CALIBRATION_SAMPLES;
    calibration.y_offset /= CALIBRATION_SAMPLES;
    calibration.z_offset /= CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.4f dps, Y=%.4f dps, Z=%.4f dps\n",
           calibration.x_offset, calibration.y_offset, calibration.z_offset);

    return calibration;
}

// Apply calibration
gyro_data_t apply_calibration(gyro_data_t data, gyro_calibration_t calibration) {
    data.x -= calibration.x_offset;
    data.y -= calibration.y_offset;
    data.z -= calibration.z_offset;
    return data;
}

// Log data to file
int log_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, GYRO_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Check sensor presence
    if (check_sensor_presence(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    gyro_calibration_t calibration = calibrate_gyro(i2c_fd);
    if (calibration.x_offset == 0.0 && calibration.y_offset == 0.0 && calibration.z_offset == 0.0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Apply calibration
            gyro_data = apply_calibration(gyro_data, calibration);

            // Log data
            log_data(log_file, gyro_data);

            // Check for zero-rate
            if (fabs(gyro_data.x) < ZERO_RATE_THRESHOLD &&
                fabs(gyro_data.y) < ZERO_RATE_THRESHOLD &&
                fabs(gyro_data.z) < ZERO_RATE_THRESHOLD) {
                fprintf(stderr, "Warning: Zero-rate detected!\n");
                fprintf(log_file, "Alert: Zero-rate detected!\n");
                fflush(log_file);
            }

            // Check for alert
            if (fabs(gyro_data.x) > ALERT_THRESHOLD ||
                fabs(gyro_data.y) > ALERT_THRESHOLD ||
                fabs(gyro_data.z) > ALERT_THRESHOLD) {
                fprintf(stderr, "Warning: Alert threshold exceeded!\n");
                fprintf(log_file, "Alert: Alert threshold exceeded!\n");
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        usleep(50000); // 50 ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

