void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345 sensor
int adxl345_init() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID value: 0x%02X\n", devid);
        return -1;
    }
    printf("ADXL345 DEVID: 0x%02X\n", devid);

    // Set data format: full resolution, ±2g range
    int data_format = i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B);
    if (data_format < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register: %d\n", data_format);
        return -1;
    }

    // Set power control: measurement mode
    int power_ctl = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (power_ctl < 0) {
        fprintf(stderr, "Error writing POWER_CTL register: %d\n", power_ctl);
        return -1;
    }

