// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Scaling factors
#define ACCEL_SCALE 0.001 // +/- 2g range, 1 mg/LSB
#define MAG_SCALE 0.001   // +/- 1.3 gauss range, 0.8 mGauss/LSB

// Global variables
int i2c_handle_accel;
int i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_accel();
int init_mag();
int read_accel_data(float *x, float *y, float *z);
int read_mag_data(float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the accelerometer
int init_accel() {
    int status = i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27); // 50 Hz, all axes enabled
    if (status != 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A: %d\n", status);
        return -1;
    }
    return 0;
}

// Initialize the magnetometer
int init_mag() {
    int status = i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00); // Continuous conversion mode
    if (status != 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M: %d\n", status);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6); // Read auto-incremented
    if (status != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
