#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define register addresses
#define DATA_REG 0x01
#define CTRL_REG 0x00

// Define control register value for continuous measurement
#define CONTINUOUS_MEASUREMENT 0x80

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 10

// Define TDOA calculation parameters
#define SPEED_OF_SOUND 34300 // cm/s
#define MICROPHONE_DISTANCE 10 // cm

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    int16_t tdoa;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int addr);
int read_sensor_data(int i2c_handle, int16_t *data);
int16_t calculate_tdoa(int16_t sensor1, int16_t sensor2);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int addr) {
    int handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }

    // Configure sensor for continuous measurement
    if (i2cWriteByteData(handle, CTRL_REG, CONTINUOUS_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to write to control register at address 0x%02x\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Read sensor data from I2C
int read_sensor_data(int i2c_handle, int16_t *data) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read data from I2C: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Calculate TDOA in milliseconds
int16_t calculate_tdoa(int16_t sensor1, int16_t sensor2) {
    // Simple TDOA calculation based on time difference between samples
    // This is a placeholder and needs to be adjusted based on the actual sensor characteristics
    // and the desired TDOA resolution.
    // Assuming a simple delay between the two sensors.
    return (int16_t)((float)(sensor1 - sensor2) / SPEED_OF_SOUND * 1000.0); // TDOA in ms
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, data.sensor1, data.sensor2, data.tdoa);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (!terminate) {
        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &data.sensor1) != 0) {
            fprintf(stderr, "Error reading sensor 1, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &data.sensor2) != 0) {
            fprintf(stderr, "Error reading sensor 2, retrying...\n");
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        // Calculate TDOA
        data.tdoa = calculate_tdoa(data.sensor1, data.sensor2);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for the specified sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

