// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_CS_GPIO 8

// Scale Factors
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

// Global Variables
int spi_fd;
int cs_gpio;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int16_t read_register(uint8_t reg_addr);
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g);
void log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps, float accel_x_g, float accel_y_g, float accel_z_g);
void signal_handler(int sig);
int initialize();
void cleanup();

// SPI Transfer Function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI Transfer Failed");
        return -1;
    }

    return 0;
}

// Read Register Function
int16_t read_register(uint8_t reg_addr) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg_addr);
        return 0; // Return 0 on error
    }

    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
}

// Process Data Function
void process_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, int16_t accel_x, int16_t accel_y, int16_t accel_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g) {
    *gyro_x_dps = (float)gyro_x * GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y * GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z * GYRO_SCALE;
    *accel_x_g = (float)accel_x * ACCEL_SCALE;
    *accel_y_g = (float)accel_y * ACCEL_SCALE;
    *accel_z_g = (float)accel_z * ACCEL_SCALE;
}

// Log Data Function
void log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps, float accel_x_g, float accel_y_g, float accel_z_g) {
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
           gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization Function
int initialize() {
    // Initialize SPI
    char spi_device_path[20];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device_path, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI Open Failed");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI Mode Set Failed");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI Speed Set Failed");
        close(spi_fd);
        return -1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(spi_fd);
        return -1;
    }

    // Set CS GPIO as output
    cs_gpio = SPI_CS_GPIO;
    gpioSetMode(cs_gpio, PI_OUTPUT);
    gpioWrite(cs_gpio, 1); // Deactivate CS initially

    return 0;
}

// Cleanup Function
void cleanup() {
    // Deactivate CS
    gpioWrite(cs_gpio, 1);

    // Close SPI device
    close(spi_fd);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("ADIS16448 Data Acquisition Started...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int16_t gyro_x = read_register(XGYRO_OUT);
        int16_t gyro_y = read_register(YGYRO_OUT);
        int16_t gyro_z = read_register(ZGYRO_OUT);
        int16_t accel_x = read_register(XACCL_OUT);
        int16_t accel_y = read_register(YACCL_OUT);
        int16_t accel_z = read_register(ZACCL_OUT);

        // Process data
        float gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g;
        process_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps, &accel_x_g, &accel_y_g, &accel_z_g);

        // Log data
        log_data(gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        // Delay
        usleep(100000); // 100 ms
    }

