#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int handle, uint16_t address) {
    char tx_buffer[2];
    char rx_buffer[2];
    int result;

    // Set the MSB of the address to 1 for read operation
    address |= 0x8000;

    // Prepare the transmit buffer
    tx_buffer[0] = (address >> 8) & 0xFF; // MSB
    tx_buffer[1] = address & 0xFF;        // LSB

    // Transfer the data
    result = spiXfer(handle, tx_buffer, rx_buffer, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes to form the 16-bit value
    return (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);
}

// Function to read IMU data
imu_data_t read_imu_data(int handle) {
    imu_data_t data;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read raw gyroscope data
    raw_gyro_x = read_register(handle, X_GYRO_OUT);
    raw_gyro_y = read_register(handle, Y_GYRO_OUT);
    raw_gyro_z = read_register(handle, Z_GYRO_OUT);

    // Read raw accelerometer data
    raw_accel_x = read_register(handle, X_ACCL_OUT);
    raw_accel_y = read_register(handle, Y_ACCL_OUT);
    raw_accel_z = read_register(handle, Z_ACCL_OUT);

    // Check for read errors
    if (raw_gyro_x == -1 || raw_gyro_y == -1 || raw_gyro_z == -1 ||
        raw_accel_x == -1 || raw_accel_y == -1 || raw_accel_z == -1) {
        data.gyro_x = 0.0;
        data.gyro_y = 0.0;
        data.gyro_z = 0.0;
        data.accel_x = 0.0;
        data.accel_y = 0.0;
        data.accel_z = 0.0;
        return data; // Return default values on error
    }

    // Convert raw data to physical units
    data.gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    data.gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    data.gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    data.accel_x = (float)raw_accel_x * ACCL_SCALE;
    data.accel_y = (float)raw_accel_y * ACCL_SCALE;
    data.accel_z = (float)raw_accel_z * ACCL_SCALE;

    return data;
}

