#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register with retries
int read_i2c_register(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }
        if (read(fd, value, 1) == 1) {
            return 0; // Success
        } else {
            perror("Failed to read register value");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// Function to write a single byte to an I2C register with retries
int write_i2c_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("Failed to write register value");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (read_i2c_register(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        return -1;
    }

    printf("MPU-6886 found. WHO_AM_I = 0x%02X\n", who_am_i);

    // Wake up the sensor (clear sleep mode bit)
    if (write_i2c_register(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (write_i2c_register(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG register\n");
        return -1;
    }

    // Set gyroscope range to +-250 dps
    if (write_i2c_register(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer and gyroscope data
int read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, buffer, 14) != 14) {
        perror("Failed to read raw data");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z  = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully\n");

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read raw data
        if (read_raw_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print raw data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read raw data. Retrying...\n");
        }

        // Delay for 50ms
        usleep(50000);
    }

    // Close I2C bus (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

