#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_TAP 0x1D
#define ADXL345_REG_OFSX 0x1E
#define ADXL345_REG_OFSY 0x1F
#define ADXL345_REG_OFSZ 0x20
#define ADXL345_REG_DUR 0x21
#define ADXL345_REG_LATENT 0x22
#define ADXL345_REG_WINDOW 0x23
#define ADXL345_REG_THRESH_ACT 0x24
#define ADXL345_REG_THRESH_INACT 0x25
#define ADXL345_REG_TIME_INACT 0x26
#define ADXL345_REG_ACT_INACT_CTL 0x27
#define ADXL345_REG_THRESH_FF 0x28
#define ADXL345_REG_TIME_FF 0x29
#define ADXL345_REG_TAP_AXES 0x2A
#define ADXL345_REG_ACT_TAP_STATUS 0x2B
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_FIFO_CTL 0x38
#define ADXL345_REG_FIFO_STATUS 0x39

// LED GPIO pin
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Scale factor (LSB/g) for +-2g range
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }
    printf("ADXL345 device ID: 0x%02X\n", devid);

    // Set data format: full resolution, +-2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B); // Full resolution, +-2g range
    if (status < 0) {
        fprintf(stderr, "Error writing to data format register: %d\n", status);
        return -1;
    }

    // Set power control: measurement mode
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08); // Measurement mode
    if (status < 0) {
        fprintf(stderr, "Error writing to power control register: %d\n", status);
        return -1;
    }

    return 0;
}

// Reads the acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SCALE_FACTOR;
    float y_g = (float)y / SCALE_FACTOR;
    float z_g = (float)z / SCALE_FACTOR;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Logs the impact event to a file
void log_impact(float magnitude, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n", timestamp, magnitude, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            float magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);

                // Turn on LED
                gpioWrite(LED_PIN, 1);

                // Log impact
                log_impact(magnitude, x, y, z);

                // Wait for 500 ms
                gpioDelay(500000); // 500 ms = 500000 microseconds

                // Turn off LED
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

