#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define WHO_AM_I     0x75

// Scaling factors
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ICM-20602
int init_imu() {
    // Wake up the device (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU\n");
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer\n");
        return -1;
    }

    // Configure gyroscope range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope\n");
        return -1;
    }

    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x12) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data
int read_sensor_data(sensor_data_t *data) {
    char buf[14];

    // Read accelerometer and gyroscope data in one go
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t accel_x = (buf[0] << 8) | buf[1];
    int16_t accel_y = (buf[2] << 8) | buf[3];
    int16_t accel_z = (buf[4] << 8) | buf[5];

    // Combine high and low bytes for gyroscope data
    int16_t gyro_x = (buf[8] << 8) | buf[9];
    int16_t gyro_y = (buf[10] << 8) | buf[11];
    int16_t gyro_z = (buf[12] << 8) | buf[13];

    // Convert to g and dps
