#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_X_MSB 0x01
#define DATA_X_LSB 0x02
#define DATA_Y_MSB 0x03
#define DATA_Y_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define ACCEL_SCALE 2.0f // +/- 2g range
#define IMPACT_THRESHOLD 2.0f // 2g
#define LED_GPIO 17
#define LED_ON_TIME_MS 500
#define POLL_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(int gpio_pin);
int read_register(int reg);
int write_register(int reg, int value);
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "impact_detector", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read a register from the MMA8451Q
int read_register(int reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        perror("Error reading register");
        return -1;
    }
    return value;
}

// Write a register to the MMA8451Q
int write_register(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        perror("Error writing register");
        return -1;
    }
    return 0;
}

// Read acceleration data from the MMA8451Q
int read_acceleration(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    int x_msb = read_register(DATA_X_MSB);
    int x_lsb = read_register(DATA_X_LSB);
    int y_msb = read_register(DATA_Y_MSB);
    int y_lsb = read_register(DATA_Y_LSB);
    int z_msb = read_register(DATA_Z_MSB);
    int z_lsb = read_register(DATA_Z_LSB);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        return -1;
    }

    raw_x = (int16_t)((x_msb << 8) | x_lsb) >> 4;
    raw_y = (int16_t)((y_msb << 8) | y_lsb) >> 4;
    raw_z = (int16_t)((z_msb << 8) | z_lsb) >> 4;

    *x = (float)raw_x / 4096.0f * ACCEL_SCALE;
    *y = (float)raw_y / 4096.0f * ACCEL_SCALE;
    *z = (float)raw_z / 4096.0f * ACCEL_SCALE;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log an impact event to the file
void log_impact(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Impact detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (led_line) {
        gpiod_line_release(led_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify sensor ID
    int who_am_i = read_register(WHO_AM_I_REG);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        cleanup();
        return 1;
    }
    printf("WHO_AM_I register value: 0x%02X (expected 0x1A)\n", who_am_i);

    // Initialize GPIO
    if (init_gpio(LED_GPIO) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Configure MMA8451Q (Active mode, 100 Hz data rate)
    if (write_register(CTRL_REG1, 0x01 | (0x02 << 3)) < 0) {
        cleanup();
        return 1;
    }

    float x, y, z, magnitude;

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                log_impact(x, y, z);

                // Turn LED on
                gpiod_line_set_value(led_line, 1);
                usleep(LED_ON_TIME_MS * 1000); // 500ms

                // Turn LED off
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        usleep(POLL_INTERVAL_MS * 1000); // 100ms
    }

    cleanup();
    return 0;
}

