#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x35

// Define register addresses for X, Y, and Z data
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12

// Global variables for I2C file descriptor and log file pointer
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_magnetic_field(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read magnetic field data from the sensor
int read_magnetic_field(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read 6 bytes from the sensor (X, Y, Z)
    if (read(fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetic field data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes for each axis (little-endian)
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log the data to a CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write the data to the CSV file
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Close the I2C file descriptor if it's open
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C file descriptor closed.\n");
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, TMAG5273_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }
    printf("I2C bus initialized successfully.\n");

    // Open the log file in append mode
    log_file = fopen("magnetic_field_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if it is
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        printf("CSV header written to log file.\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    sensor_data_t sensor_data;

    // Main loop to read and log data
    while (1) {
        // Read magnetic field data
        if (read_magnetic_field(i2c_fd, &sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Log the data
            log_data(log_file, sensor_data.x, sensor_data.y, sensor_data.z);
            printf("Data logged: X=%d, Y=%d, Z=%d\n", sensor_data.x, sensor_data.y, sensor_data.z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

