#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_SOURCE 0x30
#define DATAX0 0x32
#define DEVID 0x00

// GPIO Pin
#define GPIO_PIN 17

// Scaling factor
#define SCALE_FACTOR 0.0039 // mg/LSB

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int init_adxl345(int fd);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void interrupt_handler(int signum);
void cleanup(void);

// Signal handler
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO
int init_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(gpio_line, "freefall_detector") < 0) {
        perror("Error requesting rising edge events");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize ADXL345
int init_adxl345(int fd) {
    // Verify device ID
    int devid = read_register(fd, DEVID);
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X\n", devid);
        return -1;
    }

    // Put sensor in standby mode
    if (write_register(fd, POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error putting ADXL345 in standby mode\n");
        return -1;
    }

    // Set freefall threshold
    if (write_register(fd, THRESH_FF, 0x14) < 0) {
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Set freefall time
    if (write_register(fd, TIME_FF, 0x0A) < 0) {
        fprintf(stderr, "Error setting freefall time\n");
        return -1;
    }

    // Enable freefall interrupt
    if (write_register(fd, INT_ENABLE, 0x04) < 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (write_register(fd, INT_MAP, 0x00) < 0) {
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    // Put sensor in measurement mode
    if (write_register(fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error putting ADXL345 in measurement mode\n");
        return -1;
    }

    return 0;
}

// Read a single register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return value;
}

// Write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    if (write(fd, DATAX0, 1) != 1) {
        perror("Error writing to DATAX0 register");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    // Combine high and low bytes, and convert to g
    *x = (float)((int16_t)((data[1] << 8) | data[0])) * SCALE_FACTOR;
    *y = (float)((int16_t)((data[3] << 8) | data[2])) * SCALE_FACTOR;
    *z = (float)((int16_t)((data[5] << 8) | data[4])) * SCALE_FACTOR;

    return 0;
}

// Log data to file
int log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);

    return 0;
}

// Interrupt handler
void interrupt_handler(int signum) {
    if (signum == SIGIO) {
        // Read INT_SOURCE register
        int int_source = read_register(i2c_fd, INT_SOURCE);
        if (int_source < 0) {
            fprintf(stderr, "Error reading INT_SOURCE register\n");
            return;
        }

        // Check for freefall
        if (int_source & 0x04) {
            float x, y, z;
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                log_data(log_file, x, y, z);
            } else {
                fprintf(stderr, "Error reading acceleration data during freefall\n");
            }
        }
    }
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Disable interrupts
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(ADXL345_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Set up signal handler for SIGIO
    struct sigaction sa;
    sa.sa_handler = interrupt_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGIO, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        cleanup();
        return 1;
    }

    // Request GPIO line for interrupt
    if (gpiod_line_request_event(gpio_line, "freefall_detector", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error requesting GPIO line for interrupt");
        cleanup();
        return 1;
    }

    // Set up event file descriptor
    int event_fd = gpiod_line_event_get_fd(gpio_line);
    if (event_fd < 0) {
        perror("Error getting event file descriptor");
        cleanup();
        return 1;
    }

    // Enable signal handling for SIGIO
    if (fcntl(event_fd, F_SETOWN, getpid()) == -1) {
        perror("Error setting process owner");
        cleanup();
        return 1;
    }
    if (fcntl(event_fd, F_SETFL, fcntl(event_fd, F_GETFL) | O_ASYNC) == -1) {
        perror("Error setting O_ASYNC flag");
        cleanup();
        return 1;
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Poll for interrupt events
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(event_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 1; // Timeout after 1 second
        timeout.tv_usec = 0;

        int ret = select(event_fd + 1, &readfds, NULL, NULL, &timeout);

        if (ret == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("Error in select");
                break;
            }
        } else if (ret > 0) {
            // Interrupt occurred
            if (FD_ISSET(event_fd, &readfds)) {
                // Consume the event
                struct gpiod_line_event event;
                ssize_t bytes_read = read(event_fd, &event, sizeof(event));
                if (bytes_read < 0) {
                    perror("Error reading event");
                    break;
                }
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

