#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // +/- 2g
#define GYRO_RANGE 250.0f // +/- 250 dps

// ODR (Output Data Rate)
#define ODR 104.0f // 104 Hz

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // 0.2g
#define IMPACT_THRESHOLD 2.5f  // 2.5g
#define IMPACT_WINDOW 1.0f    // 1.0 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float process_accelerometer_data(int16_t raw_data);
float process_gyroscope_data(int16_t raw_data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x69\n", who_am_i);
        return -1;
    }
    printf("LSM6DSR WHO_AM_I: 0x%x\n", who_am_i);

    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read raw sensor data from the LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12) != 12) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Process accelerometer data
    data->accel_x = process_accelerometer_data(raw_accel_x);
    data->accel_y = process_accelerometer_data(raw_accel_y);
    data->accel_z = process_accelerometer_data(raw_accel_z);

    // Process gyroscope data
    data->gyro_x = process_gyroscope_data(raw_gyro_x);
    data->gyro_y = process_gyroscope_data(raw_gyro_y);
    data->gyro_z = process_gyroscope_data(raw_gyro_z);

    return 0;
}

// Process accelerometer data (convert to g)
float process_accelerometer_data(int16_t raw_data) {
    return (float)raw_data / 32768.0f * ACCEL_RANGE;
}

// Process gyroscope data (convert to dps)
float process_gyroscope_data(int16_t raw_data) {
    return (float)raw_data / 32768.0f * GYRO_RANGE;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(sensor_data_t data) {
    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT
    static time_t impact_time = 0;

    float magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    switch (state) {
        case 0: // IDLE
            if (magnitude < FREEFALL_THRESHOLD) {
                state = 1;
                printf("Fall detected!\n");
            }
            break;
        case 1: // FREEFALL
            if (magnitude > IMPACT_THRESHOLD) {
                state = 2;
                impact_time = time(NULL);
                printf("Impact detected!\n");
            } else if (magnitude > FREEFALL_THRESHOLD) {
                // Reset freefall timer if acceleration is above threshold
                state = 1;
            }
            break;
        case 2: // IMPACT
            if (time(NULL) - impact_time >= IMPACT_WINDOW) {
                state = 0;
                printf("Fall recovered!\n");
            }
            break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for approximately 10ms (104 Hz ODR)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

