#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define WHO_AM_I 0x02

// Scaling factor for X_GYRO_OUT (degrees/sec/LSB)
#define GYRO_SCALE 0.0305

// SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adis16266_read_register(int handle, uint8_t reg_addr, int16_t *data);
int adis16266_write_register(int handle, uint8_t reg_addr, uint16_t data);
