#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SENSITIVITY 8.75f // mdps/LSB
#define SAMPLE_RATE_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the gyroscope
int initialize_gyro() {
    int retries = 3;
    int status;

    // Verify sensor presence
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, WHO_AM_I, 0x00); // Dummy write to trigger read
        if (status >= 0) {
            int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
            if (who_am_i >= 0 && who_am_i == 0xD3) {
                printf("Gyroscope found with WHO_AM_I value: 0x%02X\n", who_am_i);
                break; // Sensor found
            } else {
                fprintf(stderr, "Error: Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
                retries--;
                gpioDelay(100000); // Wait 100ms before retrying
            }
        } else {
            fprintf(stderr, "Error: Failed to read WHO_AM_I register (attempt %d): %d\n", 4 - retries, status);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Gyroscope not found after multiple retries.\n");
        return -1; // Sensor not found
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status >= 0) {
            printf("CTRL_REG1 configured successfully.\n");
            break;
        } else {
            fprintf(stderr, "Error: Failed to write to CTRL_REG1 (attempt %d): %d\n", 4 - retries, status);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (+-250 dps full-scale range)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status >= 0) {
            printf("CTRL_REG4 configured successfully.\n");
            break;
        } else {
            fprintf(stderr, "Error: Failed to write to CTRL_REG4 (attempt %d): %d\n", 4 - retries, status);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0; // Initialization successful
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    // Read 6 bytes of data starting from OUT_X_L
    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data: %d\n", status);
        data.x = 0.0f; // Set to 0 to avoid garbage values
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)raw_x / SENSITIVITY;
    data.y = (float)raw_y / SENSITIVITY;
    data.z = (float)raw_z / SENSITIVITY;

    return data;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    char timestamp[30];

    // Get nanosecond-precision timestamp
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    // Format timestamp
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write data to CSV file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

