#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define X_LSB_REG 0x28
#define X_MSB_REG 0x29
#define Y_LSB_REG 0x2A
#define Y_MSB_REG 0x2B
#define Z_LSB_REG 0x2C
#define Z_MSB_REG 0x2D
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_sensor_data(int fd, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting gracefully.\n");
    }
}

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[6];

    // Read X axis data
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading sensor data");
        return -1;
    }

    // Combine LSB and MSB for each axis
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    return 0;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, D7S_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Log data to CSV file
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Error logging data, but continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, but continuing.\n");
        }

        // Delay for 100ms
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

