#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_X_MSB 0x01
#define DATA_X_LSB 0x02
#define DATA_Y_MSB 0x03
#define DATA_Y_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define TILT_THRESHOLD 45.0
#define SAMPLE_INTERVAL_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Structure for sensor configuration
typedef struct {
    int data_rate;
    int active_mode;
} sensor_config_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a single register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return value;
}

// Function to write a single register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing register value");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read all six data registers in one go
    if (write(fd, (uint8_t[]){DATA_X_MSB}, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading block of data");
        return -1;
    }

    // Combine MSB and LSB, right-shift by 4
