#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Calibration constants (example values, adjust as needed)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold (in mG)
#define METAL_THRESHOLD 800.0

// I2C retry settings
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int lis3mdl_init(int fd);
magnetometer_data_t read_magnetometer_data(int fd);
void apply_calibration(magnetometer_data_t *data);
float calculate_magnitude(magnetometer_data_t data);
void log_data(magnetometer_data_t data);
void check_metal_detector(float magnitude);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retry %d/%d\n", reg, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retry %d/%d\n", reg, value, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, value 0x%02X)\n", MAX_RETRIES, reg, value);
    return -1; // Indicate failure
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    // Check WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1: 80 Hz ODR, continuous conversion mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +-4 gauss full scale, high-performance mode
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    // Configure CTRL_REG3: no interrupt
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG3\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw data
    int x_l = i2c_read_reg(fd, OUT_X_L);
    int x_h = i2c_read_reg(fd, OUT_X_H);
    int y_l = i2c_read_reg(fd, OUT_Y_L);
    int y_h = i2c_read_reg(fd, OUT_Y_H);
    int z_l = i2c_read_reg(fd, OUT_Z_L);
    int z_h = i2c_read_reg(fd, OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes (little-endian)
    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    // Convert to milliGauss (0.146 mG/LSB)
    data.x = (float)raw_x * 0.146;
    data.y = (float)raw_y * 0.146;
    data.z = (float)raw_z * 0.146;

    return data;
}

// Function to apply calibration
void apply_calibration(magnetometer_data_t *data) {
    data->x = (data->x - X_OFFSET) * X_SCALE;
    data->y = (data->y - Y_OFFSET) * Y_SCALE;
    data->z = (data->z - Z_OFFSET) * Z_SCALE;
}

// Function to calculate magnitude
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log data to file
void log_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check metal detector threshold
void check_metal_detector(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.3f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize LIS3MDL
    if (lis3mdl_init(i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data(i2c_fd);

        // Apply calibration
        apply_calibration(&data);

        // Calculate magnitude
        float magnitude = calculate_magnitude(data);

        // Log data
        log_data(data);

        // Check metal detector
        check_metal_detector(magnitude);

        // Delay for 100ms (10 Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

