        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1: 80 Hz ODR, continuous conversion mode
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +-4 gauss full scale, high-performance mode
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    // Configure CTRL_REG3: no interrupt
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG3\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw data
    int x_l = i2c_read_reg(fd, OUT_X_L);
    int x_h = i2c_read_reg(fd, OUT_X_H);
    int y_l = i2c_read_reg(fd, OUT_Y_L);
    int y_h = i2c_read_reg(fd, OUT_Y_H);
    int z_l = i2c_read_reg(fd, OUT_Z_L);
    int z_h = i2c_read_reg(fd, OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes (little-endian)
    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    // Convert to milliGauss (0.146 mG/LSB)
    data.x = (float)raw_x * 0.146;
    data.y = (float)raw_y * 0.146;
    data.z = (float)raw_z * 0.146;

    return data;
}

// Function to apply calibration
void apply_calibration(magnetometer_data_t *data) {
    data->x = (data->x - X_OFFSET) * X_SCALE;
    data->y = (data->y - Y_OFFSET) * Y_SCALE;
    data->z = (data->z - Z_OFFSET) * Z_SCALE;
}

// Function to calculate magnitude
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log data to file
void log_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check metal detector threshold
void check_metal_detector(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.3f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize LIS3MDL
    if (lis3mdl_init(i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data(i2c_fd);

        // Apply calibration
        apply_calibration(&data);

        // Calculate magnitude
        float magnitude = calculate_magnitude(data);

        // Log data
        log_data(data);

        // Check metal detector
        check_metal_detector(magnitude);

        // Delay for 100ms (10 Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

