#define ADXL354B_REG_ZDATA_H 0x0E
#define ADXL354B_REG_ZDATA_L 0x0F
#define ADXL354B_REG_ZDATA_XL 0x10
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int adxl354b_init(int handle);
int read_acceleration_data(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];
    int retries = 3;

    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB for read
    memset(tx_buf + 1, 0x00, len);

    while (retries > 0) {
        if (spiXfer(handle, tx_buf, rx_buf, len + 1) == len + 1) {
            memcpy(data, rx_buf + 1, len);
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    return -1; // Failure
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];
    int retries = 3;

    tx_buf[0] = (reg_addr << 1) & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    while (retries > 0) {
        if (spiXfer(handle, tx_buf, rx_buf, 2) == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI write error, retrying...\n");
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI write failed after multiple retries.\n");
    return -1; // Failure
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t part_id;

    // Reset the device
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // Wait for reset to complete

    // Verify device ID
    if (spi_read_register(handle, ADXL354B_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (part_id != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", part_id);
        return -1;
    }

    // Set measurement mode (RUN bit)
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set measurement mode.\n");
        return -1;
    }

    // Wait for stable state
    uint8_t status;
    int timeout = 100; // Timeout after 100 attempts
    while (timeout > 0) {
        if (spi_read_register(handle, ADXL354B_REG_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Failed to read status.\n");
            return -1;
        }
        if (status & 0x04) {
            break; // Stable
        }
        gpioDelay(1000); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for stable state.\n");
        return -1;
    }

    return 0;
}

// Read Acceleration Data Function
int read_acceleration_data(int handle, float *x, float *y, float *z) {
    uint8_t x_data[3], y_data[3], z_data[3];
    int32_t raw_x, raw_y, raw_z;

    if (spi_read_register(handle, ADXL354B_REG_XDATA_H, x_data, 3) != 0) {
        fprintf(stderr, "Failed to read X axis data.\n");
        return -1;
