        return -1;
    }
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_H, z_data, 3) != 0) {
        fprintf(stderr, "Failed to read Z axis data.\n");
        return -1;
    }

    raw_x = ((int32_t)x_data[0] << 12) | ((int32_t)x_data[1] << 4) | ((int32_t)x_data[2] >> 4);
    raw_y = ((int32_t)y_data[0] << 12) | ((int32_t)y_data[1] << 4) | ((int32_t)y_data[2] >> 4);
    raw_z = ((int32_t)z_data[0] << 12) | ((int32_t)z_data[1] << 4) | ((int32_t)z_data[2] >> 4);

    // Sign extend 20-bit data to 32-bit
    if (raw_x & 0x80000) raw_x |= 0xFFF00000;
    if (raw_y & 0x80000) raw_y |= 0xFFF00000;
    if (raw_z & 0x80000) raw_z |= 0xFFF00000;

    // Convert to g-force units
    *x = (float)raw_x * 0.0000039;
    *y = (float)raw_y * 0.0000039;
    *z = (float)raw_z * 0.0000039;

    return 0;
}

// Log Data Function
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %.6f, %.6f, %.6f\n", timestamp, x, y, z);
