        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(spi_handle, &x, &y, &z) == 0) {
