#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCEL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t address, int16_t *data);
imu_data_t read_imu_data(int handle);
void log_data(FILE *fp, struct timespec ts, imu_data_t data);
void signal_handler(int signal);

// Function to read a single register from the ADIS16362
int spi_read_register(int handle, uint8_t address, int16_t *data) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the transmit buffer: address with MSB set, dummy byte
    tx_buffer[0] = address | 0x80; // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer the data
    int result = spiXfer(handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract the data from the receive buffer
    *data = (rx_buffer[1] << 8) | rx_buffer[2];

