void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a specified GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to simulate the self-parking sequence
void simulate_self_parking() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Self-parking sequence started\n", timestamp);
    sleep(5); // Simulate parking for 5 seconds

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Self-parking sequence completed\n", timestamp);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_3_GPIO, PI_INPUT);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the sensors
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        int sensor3_value = read_sensor(SENSOR_3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values. Continuing...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check if any sensor detects an obstacle (LOW signal)
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0) {
            printf("Obstacle detected! Simulating self-parking...\n");
            simulate_self_parking();
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

