#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL  0x24

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8 // CE0

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int adis16266_write_register(uint8_t address, uint16_t data);
int adis16266_read_register(uint8_t address, int16_t *data);
void convert_raw_to_angular_rate(int16_t raw_data, float *angular_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold SPI configuration
typedef struct {
    char device[20];
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Structure to hold GPIO configuration
typedef struct {
    char chip[20];
    int line;
} gpio_config_t;

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure ADIS16266 for data ready mode
    if (adis16266_write_register(ADIS16266_MSC_CTRL, 0x0003) != 0) {
        fprintf(stderr, "Failed to configure ADIS16266. Exiting.\n");
        cleanup();
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (adis16266_read_register(ADIS16266_XGYRO_OUT, &raw_x) != 0 ||
            adis16266_read_register(ADIS16266_YGYRO_OUT, &raw_y) != 0 ||
            adis16266_read_register(ADIS16266_ZGYRO_OUT, &raw_z) != 0) {
            fprintf(stderr, "Failed to read gyroscope data. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw data to angular rates
        convert_raw_to_angular_rate(raw_x, &x_rate);
        convert_raw_to_angular_rate(raw_y, &y_rate);
        convert_raw_to_angular_rate(raw_z, &z_rate);

        // Log the data
        log_data(x_rate, y_rate, z_rate);

        // Wait 100 milliseconds
        usleep(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// SPI Initialization Function
int spi_init(void) {
    spi_config_t config = {
        .device = SPI_DEVICE,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    spi_fd = open(config.device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
