    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    printf("FXOS8700 WHO_AM_I: 0x%02X\n", who_am_i);

    // Configure accelerometer: Active mode, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01 | (0x01 << 3)) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure accelerometer: +/- 2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Configure magnetometer: Hybrid mode, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }

    // Configure magnetometer: +/- 4 gauss range
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x20) < 0) {
