#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_tilt_event(double angle, const char *axis);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize ADXL345
int adxl345_init(int i2c_handle) {
    // Set data rate to 100 Hz and enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 power control register.\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from ADXL345
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate tilt angle
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double angle = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    return angle;
}

// Log tilt event to file
void log_tilt_event(double angle, const char *axis) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Tilt angle: %.2f degrees on axis %s\n", timestamp, angle, axis);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double tilt_x, tilt_y, tilt_z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Calculate tilt angles
            tilt_x = calculate_tilt_angle(x, y, z);
            tilt_y = calculate_tilt_angle(y, x, z);
            tilt_z = calculate_tilt_angle(z, x, y);

            // Log tilt events
            if (fabs(tilt_x) > TILT_THRESHOLD) {
                log_tilt_event(tilt_x, "X");
            }
            if (fabs(tilt_y) > TILT_THRESHOLD) {
                log_tilt_event(tilt_y, "Y");
            }
            if (fabs(tilt_z) > TILT_THRESHOLD) {
                log_tilt_event(tilt_z, "Z");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

