#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_SIZE_SEC 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Validate command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring noise levels... Press Ctrl+C to exit.\n");

    while (program_running) {
        high_count = 0;
        time_t start_time = time(NULL);

        while (time(NULL) - start_time < WINDOW_SIZE_SEC && program_running) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS);
        }

        // Get current timestamp
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Check if threshold is exceeded
        if (high_count > threshold) {
            printf("%s ALERT: Noise level exceeded threshold (%d > %d)\n", timestamp, high_count, threshold);
        } else {
            printf("%s Status: Noise level normal (%d <= %d)\n", timestamp, high_count, threshold);
        }

        gpioDelay(1000); // Wait 1 second before next window
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

