#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;
static int security_code = 0;

// Function prototypes
int generate_security_code();
int read_user_input(char *input_buffer, size_t buffer_size);
int validate_code(int user_input, int security_code);
int unlock_door(struct gpiod_line *line, int gpio_pin);
int lock_door(struct gpiod_line *line, int gpio_pin);
int log_access(int security_code);
void signal_handler(int sig);
int setup_gpio(int gpio_pin, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_line *line);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Generate a random 6-digit security code
int generate_security_code() {
    return (rand() % 900000) + 100000;
}

// Read user input from stdin
int read_user_input(char *input_buffer, size_t buffer_size) {
    if (fgets(input_buffer, buffer_size, stdin) == NULL) {
        return -1; // Error or end of file
    }

    // Remove trailing newline character
    size_t len = strlen(input_buffer);
    if (len > 0 && input_buffer[len - 1] == '\n') {
        input_buffer[len - 1] = '\0';
    }

    return 0;
}

// Validate the user input against the security code
int validate_code(int user_input, int security_code) {
    return (user_input == security_code) ? 1 : 0;
}

// Unlock a door by setting the GPIO pin HIGH
int unlock_door(struct gpiod_line *line, int gpio_pin) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", gpio_pin, gpiod_strerror(ret));
        return -1;
    }
    return 0;
}

// Lock a door by setting the GPIO pin LOW
int lock_door(struct gpiod_line *line, int gpio_pin) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", gpio_pin, gpiod_strerror(ret));
        return -1;
    }
    return 0;
}

// Log access to the log file
int log_access(int security_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, security_code);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Setup GPIO line
int setup_gpio(int gpio_pin, struct gpiod_line **line) {
    struct gpiod_line_request_config config;

    // Request the GPIO line
    memset(&config, 0, sizeof(config));
    config.consumer = "door_access";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", gpio_pin, gpiod_strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d line: %s\n", gpio_pin, gpiod_strerror(ret));
        gpiod_line_release(*line);
        *line = NULL;
        return -1;
    }

    // Set initial value to LOW (locked)
    ret = gpiod_line_set_value(*line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial value for GPIO %d: %s\n", gpio_pin, gpiod_strerror(ret));
        gpiod_line_release(*line);
        *line = NULL;
        return -1;
    }

    return 0;
}

// Cleanup GPIO line
int cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    return 0;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Generate the initial security code
    security_code = generate_security_code();
    printf("Initial security code: %d\n", security_code);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Setup GPIO pins
    if (setup_gpio(DOOR_A_GPIO, &door_a_line) != 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", DOOR_A_GPIO);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (setup_gpio(DOOR_B_GPIO, &door_b_line) != 0) {
        fprintf(stderr, "Failed to setup GPIO %d\n", DOOR_B_GPIO);
        cleanup_gpio(door_a_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char input_buffer[10];
    int user_input;

    // Main loop
    while (!terminate) {
        printf("Enter security code: ");

        // Read user input
        if (read_user_input(input_buffer, sizeof(input_buffer)) != 0) {
            fprintf(stderr, "Error reading input, exiting.\n");
            break;
        }

        // Validate input
        if (sscanf(input_buffer, "%d", &user_input) != 1) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            continue;
        }

        // Validate the code
        if (validate_code(user_input, security_code)) {
            printf("Access granted!\n");

            // Unlock Door A
            if (unlock_door(door_a_line, DOOR_A_GPIO) != 0) {
                fprintf(stderr, "Failed to unlock Door A\n");
            } else {
                sleep(5);

                // Lock Door A
                if (lock_door(door_a_line, DOOR_A_GPIO) != 0) {
                    fprintf(stderr, "Failed to lock Door A\n");
                }
            }

            // Log the access
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Failed to log access\n");
            }

            // Generate a new security code
            security_code = generate_security_code();
            printf("New security code: %d\n", security_code);
        } else {
            printf("Access denied!\n");
        }
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Lock both doors
    lock_door(door_a_line, DOOR_A_GPIO);
    lock_door(door_b_line, DOOR_B_GPIO);

    // Release GPIO lines
    cleanup_gpio(door_a_line);
    cleanup_gpio(door_b_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

