#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define BH1750FVI_ADDR 0x23

// Define the measurement mode command
#define BH1750FVI_MODE_HIGH_RES 0x21

// Define the log file name
#define LOG_FILE "light_log.txt"

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Function prototypes
int init_i2c(const char *bus, int addr);
int write_i2c_byte(int fd, uint8_t data);
int read_i2c_bytes(int fd, uint8_t *data, int len);
float calculate_lux(uint16_t raw_value);
int log_data(const char *filename, float lux_value);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int i2c_fd;
    FILE *log_file;
} ProgramState;

ProgramState state = {-1, NULL};

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to the I2C bus
int write_i2c_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C bus");
        return -1;
    }
    return 0;
}

// Function to read bytes from the I2C bus
int read_i2c_bytes(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C bus");
        return -1;
    }
    return 0;
}

// Function to calculate the illuminance in lux
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log the data to a file
int log_data(const char *filename, float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (state.i2c_fd != -1) {
        close(state.i2c_fd);
    }
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    exit(0);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    state.i2c_fd = init_i2c(I2C_BUS, BH1750FVI_ADDR);
    if (state.i2c_fd < 0) {
        return 1;
    }

    // Write the measurement mode command
    if (write_i2c_byte(state.i2c_fd, BH1750FVI_MODE_HIGH_RES) < 0) {
        close(state.i2c_fd);
        return 1;
    }

    // Wait for the measurement to complete (at least 180 ms)
    usleep(200000); // 200 ms

    // Read the two bytes of data
    uint8_t data[2];
    if (read_i2c_bytes(state.i2c_fd, data, 2) < 0) {
        close(state.i2c_fd);
        return 1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t raw_value = (data[0] << 8) | data[1];

    // Calculate the illuminance in lux
    float lux_value = calculate_lux(raw_value);

    // Log the data
    if (log_data(LOG_FILE, lux_value) < 0) {
        close(state.i2c_fd);
        return 1;
    }

    // Print the illuminance to the console
    printf("Lux: %.2f\n", lux_value);

    // Close the I2C bus
    close(state.i2c_fd);

    return 0;
}

