#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQUENCY 440 // Initial frequency
#define PWM_RANGE 1000
#define SHARED_SECRET "MySecretKey"
#define PORT 12345
#define MAX_TOUCH_VALUE 4095 // Maximum value from MPR121
#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
float map_touch_to_frequency(unsigned short touch_value);
void set_pwm_frequency(float frequency);
void play_tone(float frequency, int duration_ms);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrodes (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Setting electrode config failed\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) { // Set Electrode Enable
        fprintf(stderr, "Error: Setting electrode enable failed\n");
        return -1;
    }

    // Set touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 40) < 0) { // Touch threshold
            fprintf(stderr, "Error: Setting touch threshold failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 20) < 0) { // Release threshold
            fprintf(stderr, "Error: Setting release threshold failed for electrode %d\n", i);
            return -1;
        }
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Map touch value to frequency using logarithmic scale
float map_touch_to_frequency(unsigned short touch_value) {
    float frequency = MIN_FREQUENCY + (float)touch_value / MAX_TOUCH_VALUE * (MAX_FREQUENCY - MIN_FREQUENCY);
    return frequency;
}

// Set PWM frequency
void set_pwm_frequency(float frequency) {
    int duty_cycle = (int)(frequency / 1000.0 * PWM_RANGE); // Calculate duty cycle
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Play tone for a specified duration
void play_tone(float frequency, int duration_ms) {
    set_pwm_frequency(frequency);
    gpioDelay(duration_ms);
    set_pwm_frequency(0); // Stop the tone
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        close(client_socket);
        return;
    }

    printf("Received: %s\n", buffer);

    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        char *secret_start = strstr(buffer, SHARED_SECRET);
        if (secret_start != NULL) {
            printf("Shared secret found!\n");

            unsigned short touch_data;
            float frequency;
            time_t start_time = time(NULL);

            while (time(NULL) - start_time < PLAYBACK_DURATION_S && !terminate) {
                if (read_touch_data(&touch_data) == 0) {
                    frequency = map_touch_to_frequency(touch_data);
                    play_tone(frequency, SAMPLE_INTERVAL_MS);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading touch data, stopping playback.\n");
                    break;
                }
                gpioDelay(SAMPLE_INTERVAL_MS);
            }

            printf("Playback complete.\n");
        } else {
            printf("Shared secret not found!\n");
        }
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        if ((new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len)) < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");
        handle_client(new_socket);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_pwm_frequency(0); // Stop PWM
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

