#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP "gpiochip0"
#define PWM_CHANNEL 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "magnetometer_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line_request_config led_config;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int brightness);
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize magnetometer
int init_magnetometer(int fd) {
    uint8_t config_value = 0x18; // 10 Hz continuous conversion
    if (write(fd, &config_value, 1) != 1) {
        perror("Error writing to magnetometer");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    int duty_cycle = (int)(((float)brightness / 100.0) * PWM_PERIOD);

    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error setting PWM high");
        return -1;
    }

    struct timespec on_time = {0, duty_cycle};
    nanosleep(&on_time, NULL);

    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting PWM low");
        return -1;
    }

    struct timespec off_time = {0, PWM_PERIOD - duty_cycle};
    nanosleep(&off_time, NULL);

    return 0;
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (led_line) {
        gpiod_line_release(led_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, LSM303DLHC_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(PWM_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    memset(&led_config, 0, sizeof(led_config));
    led_config.consumer = "magnetometer_led";
    led_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &led_config, 0) < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return 1;
    }

    // Initialize PWM
    if (gpiod_line_set_period(led_line, PWM_PERIOD) < 0) {
        perror("Error setting PWM period");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Magnetometer program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t x, y, z;
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            int brightness = (int)(((magnitude - 1000) / 1000.0) * 100.0); // Scale magnitude to 0-100
            if (brightness < 0) brightness = 0;
            if (brightness > 100) brightness = 100;

            if (set_led_brightness(brightness) == 0) {
                log_data(x, y, z, magnitude);
            } else {
                fprintf(stderr, "Failed to set LED brightness.\n");
            }
        } else {
            fprintf(stderr, "Failed to read magnetometer data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

