#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron offset window size
#define OFFSET_WINDOW_SIZE 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold hard-iron offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} hard_iron_offsets_t;

// Function prototypes
int initialize_hmc5883l();
magnetometer_data_t read_magnetometer_data();
hard_iron_offsets_t calculate_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets, int window_size);
void apply_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets);
void print_magnetometer_data(magnetometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the HMC5883L magnetometer
int initialize_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Reads raw magnetometer data from the HMC5883L
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Calculates hard-iron offsets by averaging readings over a window
hard_iron_offsets_t calculate_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets, int window_size) {
    static int count = 0;
    static float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    // Subtract the oldest reading from the sum
    if (count == window_size) {
        x_sum -= offsets.x_offset;
        y_sum -= offsets.y_offset;
        z_sum -= offsets.z_offset;
    }

    // Add the new reading to the sum
    x_sum += data.x;
    y_sum += data.y;
    z_sum += data.z;

    // Update the offsets
    offsets.x_offset = x_sum / count;
    offsets.y_offset = y_sum / count;
    offsets.z_offset = z_sum / count;

    // Increment the count, wrapping around if necessary
    count = (count + 1) % window_size;

    return offsets;
}

// Applies hard-iron offsets to the raw magnetometer data
void apply_hard_iron_offsets(magnetometer_data_t data, hard_iron_offsets_t offsets) {
    data.x -= offsets.x_offset;
    data.y -= offsets.y_offset;
    data.z -= offsets.z_offset;
}

// Prints the magnetometer data to stdout
void print_magnetometer_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Hard-iron offsets
    hard_iron_offsets_t offsets = {0.0, 0.0, 0.0};

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t data = read_magnetometer_data();

        // Calculate hard-iron offsets
        offsets = calculate_hard_iron_offsets(data, offsets, OFFSET_WINDOW_SIZE);

        // Apply hard-iron offsets
        apply_hard_iron_offsets(data, offsets);

        // Print magnetometer data
        print_magnetometer_data(data);

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

