#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static accelerometer_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len);
int lsm303d_init(int fd);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
void add_to_buffer(accelerometer_data_t data);
void print_buffer();
void interrupt_handler(struct gpiod_line *line, unsigned int value, void *data);
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    int result = i2c_smbus_read_i2c_block_data(fd, reg | 0x80, (char *)buf, len);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D initialization function
int lsm303d_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(fd, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 50 Hz ODR, all axes enabled, +-2g
    if (i2c_write_byte(fd, CTRL_REG1_A, 0x57) < 0) return -1;
    if (i2c_write_byte(fd, CTRL_REG4_A, 0x00) < 0) return -1;

