#include <gpiod.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *solenoid_1_line = NULL;
struct gpiod_line *solenoid_2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void energize_solenoid(struct gpiod_line *line);
void deenergize_solenoid(struct gpiod_line *line);
void delay_ms(int milliseconds);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get GPIO lines for solenoids
    solenoid_1_line = gpiod_chip_get_line(gpio_chip, SOLENOID_1_PIN);
    if (!solenoid_1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    solenoid_2_line = gpiod_chip_get_line(gpio_chip, SOLENOID_2_PIN);
    if (!solenoid_2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_line_release(solenoid_1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(solenoid_1_line, "solenoid_1", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_line_release(solenoid_2_line);
        gpiod_line_release(solenoid_1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(solenoid_2_line, "solenoid_2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_line_release(solenoid_1_line);
        gpiod_line_release(solenoid_2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Initialize solenoids to LOW (de-energized)
    deenergize_solenoid(solenoid_1_line);
    deenergize_solenoid(solenoid_2_line);

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    // De-energize solenoids
    deenergize_solenoid(solenoid_1_line);
    deenergize_solenoid(solenoid_2_line);

    // Release GPIO lines
    if (solenoid_1_line) {
        gpiod_line_release(solenoid_1_line);
    }
    if (solenoid_2_line) {
        gpiod_line_release(solenoid_2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Function to energize a solenoid
void energize_solenoid(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line value to 1: %s\n", strerror(errno));
    }
}

// Function to de-energize a solenoid
void deenergize_solenoid(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value to 0: %s\n", strerror(errno));
    }
}

// Function to delay execution for a specified number of milliseconds
void delay_ms(int milliseconds) {
    struct timespec ts;
    ts.tv_sec = milliseconds / 1000;
    ts.tv_nsec = (milliseconds % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Energize solenoid 1
        energize_solenoid(solenoid_1_line);
        delay_ms(500);

        // De-energize solenoid 1
        deenergize_solenoid(solenoid_1_line);

        // Energize solenoid 2
        energize_solenoid(solenoid_2_line);
        delay_ms(500);

        // De-energize solenoid 2
        deenergize_solenoid(solenoid_2_line);
    }

    return 0;
}

