#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for the door locks
#define PRIMARY_LOCK_GPIO 17
#define SECONDARY_LOCK_GPIO 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout in seconds
#define TIMEOUT_SECONDS 5

// Global variables for UART file descriptors
int primary_uart_fd = -1;
int secondary_uart_fd = -1;

// Function prototypes
int initialize_uart(const char *port);
int read_code(int fd, char *code, int timeout_seconds);
int validate_code(const char *code, const char *expected_code);
int control_lock(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Ensure both locks are locked
    control_lock(PRIMARY_LOCK_GPIO, 0);
    control_lock(SECONDARY_LOCK_GPIO, 0);

    // Close UART ports
    if (primary_uart_fd != -1) {
        close(primary_uart_fd);
    }
    if (secondary_uart_fd != -1) {
        close(secondary_uart_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a UART port
int initialize_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for UART %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Error setting baud rate for UART %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for UART %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a code from a UART port with timeout
int read_code(int fd, char *code, int timeout_seconds) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;
    char buffer[7]; // Buffer to store the code + null terminator

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_seconds;
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return -1; // Timeout
    } else {
        // Data is available, read it
        while (FD_ISSET(fd, &readfds)) {
            int bytes_available = read(fd, buffer + bytes_read, 1);
            if (bytes_available > 0) {
                bytes_read += bytes_available;
                if (bytes_read >= 7) {
                    fprintf(stderr, "Code too long\n");
                    bytes_read = 0; // Reset the buffer
                    break;
                }
                if (buffer[bytes_read - 1] == '\n') {
                    buffer[bytes_read - 1] = '\0'; // Null-terminate the code
                    strncpy(code, buffer, 6); // Copy the code to the output buffer
                    return 0; // Success
                }
            } else if (bytes_available < 0) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    return 0; // No code received
}

// Function to validate a code against the expected code
int validate_code(const char *code, const char *expected_code) {
    // Constant-time string comparison
    size_t code_len = strlen(code);
    size_t expected_len = strlen(expected_code);

    if (code_len != expected_len) {
        return 0; // Codes are different lengths
    }

    int result = 0;
    for (size_t i = 0; i < code_len; i++) {
        result |= (code[i] ^ expected_code[i]);
    }

    return (result == 0); // Codes are equal
}

// Function to control the state of a door lock
int control_lock(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PRIMARY_LOCK_GPIO, PI_OUTPUT);
    gpioSetMode(SECONDARY_LOCK_GPIO, PI_OUTPUT);

    // Initialize UART ports
    primary_uart_fd = initialize_uart(PRIMARY_UART);
    if (primary_uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    secondary_uart_fd = initialize_uart(SECONDARY_UART);
    if (secondary_uart_fd == -1) {
        close(primary_uart_fd);
        gpioTerminate();
        return 1;
    }

    char primary_code[7] = {0};
    char secondary_code[7] = {0};

    // Main loop
    while (1) {
        // Read codes from both UART ports
        if (read_code(primary_uart_fd, primary_code, TIMEOUT_SECONDS) == 0) {
            printf("Primary code: %s\n", primary_code);
        } else {
            primary_code[0] = '\0'; // Reset code
        }

        if (read_code(secondary_uart_fd, secondary_code, TIMEOUT_SECONDS) == 0) {
            printf("Secondary code: %s\n", secondary_code);
        } else {
            secondary_code[0] = '\0'; // Reset code
        }

        // Validate codes
        if (validate_code(primary_code, EXPECTED_CODE) && validate_code(secondary_code, EXPECTED_CODE)) {
            printf("Codes match, unlocking doors...\n");

            // Unlock both doors
            if (control_lock(PRIMARY_LOCK_GPIO, 1) != 0 || control_lock(SECONDARY_LOCK_GPIO, 1) != 0) {
                fprintf(stderr, "Error unlocking doors\n");
            } else {
                // Wait for 2 seconds
                gpioDelay(2000000); // 2 seconds

                // Re-lock both doors
                if (control_lock(PRIMARY_LOCK_GPIO, 0) != 0 || control_lock(SECONDARY_LOCK_GPIO, 0) != 0) {
                    fprintf(stderr, "Error locking doors\n");
                }
            }
        } else {
            printf("Codes do not match, doors remain locked.\n");
        }

        // Reset codes
        primary_code[0] = '\0';
        secondary_code[0] = '\0';

        // Small delay to prevent busy-waiting
        gpioDelay(100000); // 100ms
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(primary_uart_fd);
    close(secondary_uart_fd);
    gpioTerminate();

    return 0;
}

