#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_DURATION 1 // seconds
#define FAILSAFE_TIMEOUT 10 // seconds
#define POLL_INTERVAL 50 // milliseconds

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void failsafe_check();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    control_relay(0);

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control relay state
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
}

// Failsafe check
void failsafe_check() {
    static time_t last_motion_time = 0;
    time_t current_time = time(NULL);

    if (read_pir_sensor() == 1) {
        last_motion_time = current_time;
    }

    if (difftime(current_time, last_motion_time) > FAILSAFE_TIMEOUT) {
        syslog(LOG_WARNING, "Failsafe triggered: No motion detected for %d seconds", FAILSAFE_TIMEOUT);
        control_relay(0); // De-energize relay
        last_motion_time = current_time; // Reset the timer
    }
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");

    // De-energize relay
    control_relay(0);

    // Release GPIO resources
    if (pigpio_initialized) {
        gpioTerminate();
    }

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Door strike system started");

    // Main loop
    while (running) {
        if (read_pir_sensor() == 1) {
            syslog(LOG_INFO, "Motion detected!");
            control_relay(1); // Energize relay
            gpioDelay(RELAY_ON_DURATION * 1000000); // Delay for relay on duration (microseconds)
            control_relay(0); // De-energize relay
        }

        failsafe_check(); // Check for failsafe condition
        gpioDelay(POLL_INTERVAL * 1000); // Poll interval (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

