#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the timer interval (60 seconds)
#define TIMER_INTERVAL 60

// Define the activation and deactivation times (5 minutes and 1 minute, respectively)
#define ACTIVATION_TIME 300
#define DEACTIVATION_TIME 60

// Define the syslog identifier
#define SYSLOG_IDENTIFIER "irrigation_system"

// Global variables
static volatile int running = 1; // Flag to control the main loop
static int current_relay = 1; // Current relay to activate
static int current_state = 0; // 0: Pause, 1: Activation, 2: Deactivation
static int timer_id = 0; // Timer ID

// Function prototypes
void signal_handler(int signal);
void timer_callback(int timer_id, void *user_data);
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_event(int relay_pin, const char *event);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    if (current_state == 0) { // Pause state
        syslog(LOG_INFO, "Starting relay activation sequence.");
        current_state = 1; // Set state to activation
        activate_relay(RELAY1_PIN);
    } else if (current_state == 1) { // Activation state
        if (current_relay == NUM_RELAYS) {
