#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/timerfd.h>
#include <sys/types.h>
#include <sys/stat.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Accelerometer Range
#define ACCEL_RANGE_2G 0x00

// Circular Buffer Size
#define BUFFER_SIZE 100

// Sysfs Interface Path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel"

// Global Variables
int i2c_fd = -1;
int timer_fd = -1;
volatile sig_atomic_t running = 1;

// Circular Buffer Structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t buffer;

// Function Prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_raw_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void scale_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *scaled_x, float *scaled_y, float *scaled_z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
void get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z);
void signal_handler(int sig);
int create_sysfs_interface(void);
int write_sysfs_data(float x, float y, float z);

// I2C Initialization Function
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 Initialization Function
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_smbus_write_byte_data(fd, ACCEL_CONFIG, ACCEL_RANGE_2G) < 0) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Data Acquisition Function
int read_raw_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Data Scaling Function
void scale_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *scaled_x, float *scaled_y, float *scaled_z) {
    *scaled_x = (float)raw_x / 16384.0;
    *scaled_y = (float)raw_y / 16384.0;
    *scaled_z = (float)raw_z / 16384.0;
}

// Circular Buffer Functions
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

void get_latest_data(circular_buffer_t *buffer, float *x, float *y, float *z) {
    if (buffer->count > 0) {
        int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        *x = buffer->x[index];
        *y = buffer->y[index];
        *z = buffer->z[index];
    } else {
        *x = 0.0;
        *y = 0.0;
        *z = 0.0;
    }
}

// Signal Handler Function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Sysfs Interface Functions
int create_sysfs_interface(void) {
    if (mkdir(SYSFS_PATH, 0777) == -1 && errno != EEXIST) {
        perror("Error creating sysfs directory");
        return -1;
    }

    if (mknod(SYSFS_PATH "/latest", S_IFCHR | 0666, makedev(10, 0)) == -1 && errno != EEXIST) {
        perror("Error creating sysfs node");
        return -1;
    }

    return 0;
}

int write_sysfs_data(float x, float y, float z) {
    int fd = open(SYSFS_PATH "/latest", O_WRONLY);
    if (fd < 0) {
        perror("Error opening sysfs node");
        return -1;
    }

    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%.3f,%.3f,%.3f\n", x, y, z);

    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to sysfs node");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    // Initialize Signal Handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize Circular Buffer
    buffer.head = 0;
    buffer.count = 0;

    // Create Sysfs Interface
    if (create_sysfs_interface() < 0) {
        fprintf(stderr, "Sysfs interface creation failed. Continuing without sysfs.\n");
    }

    // Configure Timer
    struct sigevent sev;
    struct itimerspec its;

    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_fd;

    if (timer_create(CLOCK_REALTIME, &sev, &timer_fd) == -1) {
        perror("Error creating timer");
        close(i2c_fd);
        return 1;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms

    if (timer_settime(timer_fd, 0, &its, NULL) == -1) {
        perror("Error setting timer time");
        timer_delete(timer_fd);
        close(i2c_fd);
        return 1;
    }

    // Main Loop
    int16_t raw_x, raw_y, raw_z;
    float scaled_x, scaled_y, scaled_z;

    while (running) {
        // Read Raw Data
        if (read_raw_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Scale Data
            scale_data(raw_x, raw_y, raw_z, &scaled_x, &scaled_y, &scaled_z);

            // Add to Circular Buffer
            add_to_buffer(&buffer, scaled_x, scaled_y, scaled_z);

            // Write to Sysfs
            if (create_sysfs_interface() == 0) {
                write_sysfs_data(scaled_x, scaled_y, scaled_z);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for the next timer event
        siginfo_t info;
        if (sigwaitinfo(&sev.sigev_notify, &info) == -1) {
            perror("Error waiting for signal");
            break;
        }
    }

    // Cleanup
    timer_delete(timer_fd);
    close(i2c_fd);
    if (create_sysfs_interface() == 0) {
        unlink(SYSFS_PATH "/latest");
        rmdir(SYSFS_PATH);
    }

    return 0;
}

