struct gpiod_line *relay3_line = NULL;
struct gpiod_line *relay4_line = NULL;

// Function prototypes
int initialize_gpio(void);
int set_relay_state(struct gpiod_line *line, int state);
int toggle_relay(struct gpiod_line *line);
int cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO chip and lines
int initialize_gpio(void) {
    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the lines for the relays
    relay1_line = gpiod_chip_get_line(gpio_chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(gpio_chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(gpio_chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(gpio_chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the lines for output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "relay2", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "relay3", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

