    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);

        // Toggle relay 1 every INTERVAL1 seconds
        if (elapsed_time % (INTERVAL1 * 1000000000L) == 0) {
            if (toggle_relay(relay1_line) < 0) {
                fprintf(stderr, "Error toggling relay 1. Continuing.\n");
            }
        }

        // Toggle relay 2 every INTERVAL2 seconds
        if (elapsed_time % (INTERVAL2 * 1000000000L) == 0) {
            if (toggle_relay(relay2_line) < 0) {
                fprintf(stderr, "Error toggling relay 2. Continuing.\n");
            }
        }

        // Toggle relay 3 every INTERVAL3 seconds
        if (elapsed_time % (INTERVAL3 * 1000000000L) == 0) {
            if (toggle_relay(relay3_line) < 0) {
                fprintf(stderr, "Error toggling relay 3. Continuing.\n");
            }
        }

        // Toggle relay 4 every INTERVAL4 seconds
        if (elapsed_time % (INTERVAL4 * 1000000000L) == 0) {
            if (toggle_relay(relay4_line) < 0) {
                fprintf(stderr, "Error toggling relay 4. Continuing.\n");
            }
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

