#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define ALARM_DURATION_MS 3000
#define DEBOUNCE_DELAY_MS 500

// Global variables
static volatile int running = 1;
static volatile int relay_active = 0;
static volatile unsigned long last_trigger_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int deactivate_relay();
int log_alarm();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate relay\n");
        return 1;
    }
    relay_active = 1;
    return 0;
}

// Deactivate the relay
int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay\n");
        return 1;
    }
    relay_active = 0;
    return 0;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open alarm_log.txt\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            unsigned long current_time = gpioTick();

            if (!relay_active && (current_time - last_trigger_time) > DEBOUNCE_DELAY_MS * 1000) {
                printf("Sound detected! Activating relay.\n");
                if (activate_relay() == 0) {
                    if (log_alarm() == 0) {
                        printf("Alarm logged.\n");
                    } else {
                        fprintf(stderr, "Failed to log alarm.\n");
                    }
                    gpioDelay(ALARM_DURATION_MS * 1000); // Delay for alarm duration
                    if (deactivate_relay() != 0) {
                        fprintf(stderr, "Failed to deactivate relay.\n");
                    }
                    last_trigger_time = current_time;
                } else {
                    fprintf(stderr, "Failed to activate relay.\n");
                }
            }
        }

        gpioDelay(100 * 1000); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    deactivate_relay();
    gpioTerminate();

    return 0;
}

