#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Gyroscope sensitivity (LSB/deg/s) for +-250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (deg/s)
#define THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
float calculate_magnitude(gyro_data_t data);
void callback_function(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize MPU-6050 sensor
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Verify WHO_AM_I register
    data[0] = WHO_AM_I;
    if (write(fd, data, 1) != 1) {
        perror("Error writing to WHO_AM_I register");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (data[0] != 0x68) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", data[0]);
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    uint8_t reg = GYRO_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to gyro data register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    // Combine high and low bytes, and convert to degrees/second
    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Callback function to be called when the threshold is exceeded
void callback_function(gyro_data_t data) {
    printf("Threshold exceeded! Angular velocity: X=%.2f, Y=%.2f, Z=%.2f\n", data.x, data.y, data.z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    gyro_data_t gyro_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Calculate the magnitude of the angular velocity vector
            float magnitude = calculate_magnitude(gyro_data);

            // Check if the threshold is exceeded
            if (magnitude > THRESHOLD) {
                callback_function(gyro_data);
            }
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup resources
    cleanup();

    return 0;
}

