#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_READ_LENGTH 9
#define LOG_INTERVAL_SEC 5
#define TIMEOUT_SEC 1

// Global variables
int uart_handle;
FILE *log_file;
FILE *error_file;
volatile sig_atomic_t terminate = 0;

// Structure for CO2 data
typedef struct {
    unsigned int ppm;
    int error;
    long long timestamp_us;
} CO2Data;

// Function prototypes
int initialize_uart();
int read_co2_data(unsigned char *response);
int validate_checksum(const unsigned char *response);
CO2Data process_co2_data(const unsigned char *response);
int log_co2_data(const CO2Data *data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read CO2 data from sensor
int read_co2_data(unsigned char *response) {
    int bytes_read = 0;
    time_t start_time = time(NULL);

    while (bytes_read < CO2_READ_LENGTH && (time(NULL) - start_time) < TIMEOUT_SEC) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int read_result = serRead(uart_handle, response + bytes_read, available);
            if (read_result > 0) {
                bytes_read += read_result;
            } else {
                log_error("Error reading from UART");
                return -1;
            }
        } else {
            gpioDelay(1000); // Sleep for 1 ms
        }
    }

    if (bytes_read != CO2_READ_LENGTH) {
        log_error("Timeout reading CO2 data");
        return -1;
    }

    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = ~checksum + 1;

    if (checksum != response[8]) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Checksum mismatch: calculated 0x%02X, received 0x%02X", checksum, response[8]);
        log_error(error_message);
        return -1;
    }

    return 0;
}

// Process CO2 data
CO2Data process_co2_data(const unsigned char *response) {
    CO2Data data;
    data.ppm = (response[2] << 8) | response[3];
    data.error = 0; // Assume no error initially
    data.timestamp_us = gpioTick();

    if (validate_checksum(response) != 0) {
        data.error = 1; // Set error flag if checksum validation fails
    }

    return data;
}

// Log CO2 data to file
int log_co2_data(const CO2Data *data) {
    char json_string[100];
    snprintf(json_string, sizeof(json_string), "{\"timestamp_us\": %lld, \"ppm\": %u, \"error\": %d}\n",
             data->timestamp_us, data->ppm, data->error);

    if (fputs(json_string, log_file) == EOF) {
        log_error("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk

    printf("%s", json_string); // Simulate sending data to remote server

    return 0;
}

// Log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(error_file);
    perror(message); // Also print to stderr
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
        printf("UART closed\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed\n");
    }
    if (error_file != NULL) {
        fclose(error_file);
        printf("Error log file closed\n");
    }
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen("co2_log.json", "a");
    if (log_file == NULL) {
        perror("Failed to open co2_log.json");
        gpioTerminate();
        return 1;
    }

    error_file = fopen("co2_error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open co2_error.log");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char response[CO2_READ_LENGTH];
    CO2Data co2_data;

    printf("CO2 monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read CO2 data
        if (read_co2_data(response) == 0) {
            // Process CO2 data
            co2_data = process_co2_data(response);

            // Log CO2 data
            if (log_co2_data(&co2_data) != 0) {
                log_error("Failed to log CO2 data");
            }
        } else {
            log_error("Failed to read CO2 data");
        }

        // Wait for the next interval
        sleep(LOG_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

