#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Define lux thresholds
#define LUX_THRESHOLD_RED 50.0
#define LUX_THRESHOLD_GREEN 150.0
#define LUX_THRESHOLD_BLUE 300.0

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_gpio(int pin);
int read_bh1750(int fd);
float calculate_lux(int raw_value);
int control_relay(struct gpiod_line *line, int state);
int log_data(FILE *fp, float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize GPIO line
int init_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "smart_lighting";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int fd) {
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(180000); // Wait for measurement (at least 180ms)

        if (read(fd, buf, 2) == 2) {
            return (buf[0] << 8) | buf[1];
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Indicate failure
}

// Calculate lux value
float calculate_lux(int raw_value) {
    return (float)raw_value / 1.2;
}

// Control relay state
int control_relay(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(FILE *fp, float lux, int red_state, int green_state, int blue_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                lux, red_state, green_state, blue_state) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off all relays
    if (red_line) control_relay(red_line, 0);
    if (green_line) control_relay(green_line, 0);
    if (blue_line) control_relay(blue_line, 0);

    // Release GPIO lines
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);

    // Close I2C device
    if (i2c_fd != -1) close(i2c_fd);

    // Close log file
    if (log_file) fclose(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(RED_RELAY_PIN) < 0 ||
        init_gpio(GREEN_RELAY_PIN) < 0 ||
        init_gpio(BLUE_RELAY_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        int raw_lux = read_bh1750(i2c_fd);
        if (raw_lux < 0) {
            fprintf(stderr, "Failed to read lux value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float lux = calculate_lux(raw_lux);

        // Control relays based on lux value
        int red_state = 0, green_state = 0, blue_state = 0;
        if (lux < LUX_THRESHOLD_RED) {
            red_state = 1;
        } else if (lux < LUX_THRESHOLD_GREEN) {
            green_state = 1;
        } else if (lux < LUX_THRESHOLD_BLUE) {
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        control_relay(red_line, red_state);
        control_relay(green_line, green_state);
        control_relay(blue_line, blue_state);

        // Log data
        if (log_data(log_file, lux, red_state, green_state, blue_state) < 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

