#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Distance threshold (cm)
#define DISTANCE_THRESHOLD 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

// Function to map distance to PWM duty cycle
int map_distance_to_duty_cycle(int distance) {
    if (distance < 10) {
        return 255;
    } else if (distance > 100) {
        return 0;
    } else {
        return (int)(((float)(distance - 10) / 90.0) * 255.0);
    }
}

// Function to control motor A
void control_motor_a(int distance) {
    int duty_cycle = map_distance_to_duty_cycle(distance);

    if (distance < DISTANCE_THRESHOLD) {
        // Forward
        gpioWrite(MOTOR_A_IN1, 1);
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 1);
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    }
}

// Function to control motor B
