#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the stepper motor coils
#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22

// Define GPIO pins for the buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define the number of steps for a quarter turn
#define QUARTER_TURN_STEPS 512

// Define the delay between steps in milliseconds
#define STEP_DELAY 2

// Define the lock state
#define LOCKED 1
#define UNLOCKED 0

// Global variable to store the current lock state
int lock_state = UNLOCKED;

// Function prototypes
void lock_motor();
void unlock_motor();
void stop_motor();
void step_forward();
void step_backward();
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    stop_motor();
    gpioTerminate();
    exit(0);
}

// Function to lock the motor
void lock_motor() {
    if (lock_state == UNLOCKED) {
        printf("Locking door...\n");
        for (int i = 0; i < QUARTER_TURN_STEPS; i++) {
            step_forward();
        }
        lock_state = LOCKED;
    } else {
        printf("Door already locked.\n");
    }
}

// Function to unlock the motor
void unlock_motor() {
    if (lock_state == LOCKED) {
        printf("Unlocking door...\n");
        for (int i = 0; i < QUARTER_TURN_STEPS; i++) {
            step_backward();
        }
        lock_state = UNLOCKED;
    } else {
        printf("Door already unlocked.\n");
    }
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    printf("Motor stopped.\n");
}

// Function to step the motor forward
void step_forward() {
    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000); // Convert ms to microseconds

    gpioWrite(IN1, 0);
    gpioWrite(IN2, 1);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000);

    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 1);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000);

    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY * 1000);
}

// Function to step the motor backward
void step_backward() {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY * 1000);

    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 1);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000);

    gpioWrite(IN1, 0);
    gpioWrite(IN2, 1);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000);

    gpioWrite(IN1, 1);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY * 1000);
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == LOCK_BUTTON) {
        if (level == 0) { // Button pressed (active low)
            lock_motor();
        }
    } else if (gpio == UNLOCK_BUTTON) {
        if (level == 0) { // Button pressed (active low)
            unlock_motor();
        }
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins for motor coils as outputs
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN1 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN2 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN3 as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN4 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins for buttons as inputs with pull-up resistors
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON as input\n");
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Set up callbacks for button presses
    if (gpioSetAlertFunc(LOCK_BUTTON, button_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for LOCK_BUTTON\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(UNLOCK_BUTTON, button_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for UNLOCK_BUTTON\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        sleep(1); // Keep the program running
    }

    return 0;
}

