#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD_NS 20000000 // 20ms period (50Hz)
#define PWM_DUTY_CYCLE_MIN 1000000 // 1ms
#define PWM_DUTY_CYCLE_MAX 2000000 // 2ms
#define PWM_PATH_FORMAT "/sys/class/pwm/pwmchip%d/pwm%d"
#define PWM_EXPORT_PATH "/sys/class/pwm/pwmchip%d/export"
#define PWM_UNEXPORT_PATH "/sys/class/pwm/pwmchip%d/unexport"
#define PWM_ENABLE_PATH_FORMAT "/sys/class/pwm/pwmchip%d/pwm%d/enable"
#define PWM_PERIOD_PATH_FORMAT "/sys/class/pwm/pwmchip%d/pwm%d/period"
#define PWM_DUTY_CYCLE_PATH_FORMAT "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle"
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pitch;
    float roll;
    int servo_position;
} SensorData;

// Function prototypes
int init_i2c(int address);
int init_mpu6050();
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
SensorData process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
int set_servo_position(int position);
int log_data(SensorData data);
void signal_handler(int sig);
int export_pwm(int chip, int num);
int unexport_pwm(int chip, int num);
int enable_pwm(int chip, int num, int enable);
int set_pwm_period(int chip, int num, int period_ns);
int set_pwm_duty_cycle(int chip, int num, int duty_cycle_ns);

// Function to initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2c_smbus_write_byte_data(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    // Configure gyroscope range (+/- 250 degrees/sec)
    if (i2c_smbus_write_byte_data(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        perror("Error writing to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read MPU6050 data
int read_mpu6050_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    if (read(i2c_fd, buffer, 14) != 14) {
        perror("Error reading MPU6050 data");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Function to process sensor data
SensorData process_sensor_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    SensorData data;

    // Calculate pitch and roll (assuming +/- 2g range and 16384 LSB/g)
    data.pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    data.roll = atan2(-accel_y, accel_z) * 180 / M_PI;

    // Simple proportional control for servo position
    data.servo_position = (int)(data.pitch * 50 + 1500); // Map pitch to servo position (1000-2000)
    if (data.servo_position < PWM_DUTY_CYCLE_MIN) data.servo_position = PWM_DUTY_CYCLE_MIN;
    if (data.servo_position > PWM_DUTY_CYCLE_MAX) data.servo_position = PWM_DUTY_CYCLE_MAX;

    return data;
}

// Function to set servo position using PWM
int set_servo_position(int position) {
