// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 1 for ON, 0 for OFF
} ScheduleEntry;

// Global variables
ScheduleEntry schedule[100]; // Assuming a maximum of 100 schedule entries
int schedule_size = 0;
int running = 1; // Flag to control the main loop

// Function prototypes
int read_schedule(const char *filename);
int parse_time(const char *time_str, int *hour, int *minute, int *second);
int parse_relay_state(const char *state_str, int *relay_number, int *state);
