// Function to read the lighting schedule from a file
int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    schedule_size = 0;

    while (fgets(line, sizeof(line), fp) != NULL && schedule_size < 100) {
        // Remove trailing newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char time_str[10];
        char state_str[10];
        if (sscanf(line, "%9[^,],%9s", time_str, state_str) == 2) {
            int hour, minute, second, relay_number, state;

            if (parse_time(time_str, &hour, &minute, &second) == 0 &&
                parse_relay_state(state_str, &relay_number, &state) == 0) {

