#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 30.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
float calculateDistance(long pulseWidth);
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10); // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (timeout).\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not returned (timeout).\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate distance from pulse width
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }

    // Speed of sound in air (approx. 343 m/s)
    // Divide by 2 because the sound travels to the object and back
    float distance = (float)pulseWidth * 343.0 / 20000.0; // Convert us to cm

    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        // Linear mapping
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate PWM duty cycle (50% for square wave)
    int dutyCycle = 128; // 128 out of 255

    gpioPWM(BUZZER_PIN, dutyCycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);

            if (distance > 0) {
                float frequency = mapDistanceToFrequency(distance);
                setBuzzerFrequency(frequency);
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
            } else {
                fprintf(stderr, "Error: Invalid distance measurement\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid pulse width measurement\n");
        }

        gpioDelay(60000); // Delay for 60 ms (approx. 50 Hz)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

