#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a sine wave for proximity simulation
float generate_proximity_value() {
    static float time = 0.0;
    float proximity = 0.5 + 0.5 * sin(time); // Sine wave between 0.0 and 1.0
    time += 0.01; // Increment time for the next cycle
    return proximity;
}

// Function to map proximity value to RGB color values
void map_proximity_to_color(float proximity, int *red, int *green, int *blue) {
    if (proximity < 0.33) {
        // Red to Green transition
        *red = (int)(255 * proximity / 0.33);
        *green = (int)(255 * (1 - proximity / 0.33));
        *blue = 0;
    } else if (proximity < 0.66) {
        // Green to Blue transition
        *red = 0;
        *green = (int)(255 * (1 - (proximity - 0.33) / 0.33));
        *blue = (int)(255 * (proximity - 0.33) / 0.33);
    } else {
        // Blue to Red transition
        *red = (int)(255 * (proximity - 0.66) / 0.33);
        *green = 0;
        *blue = (int)(255 * (1 - (proximity - 0.66) / 0.33));
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
