#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Log file
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_mpu6050(int fd);
gyro_data_t read_gyro_data(int fd);
void log_data(FILE *fp, gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = data.y = data.z = 0.0; // Return 0s on error
        return data;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t gyro_x = (buffer[0] << 8) | buffer[1];
    int16_t gyro_y = (buffer[2] << 8) | buffer[3];
    int16_t gyro_z = (buffer[4] << 8) | buffer[5];

    data.x = (float)gyro_x / GYRO_SCALE;
    data.y = (float)gyro_y / GYRO_SCALE;
    data.z = (float)gyro_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %.2f, %.2f, %.2f\n", timestamp, data.x, data.y, data.z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data(i2c_fd);

        // Log data
        log_data(log_file, gyro_data);

        // Wait 100 milliseconds
        usleep(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

