#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody parameters
#define MELODY_LENGTH 16

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 440

// Define PWM range (0-range)
#define PWM_RANGE 1000

// Define PWM duty cycle (0-range)
#define PWM_DUTY_CYCLE (PWM_RANGE / 2)

// Global variables
volatile int melody_index = 0;
volatile int button_pressed = 0;
volatile unsigned long last_button_press_time = 0;

// Melody notes (frequency in Hz)
const int melody[MELODY_LENGTH] = {
    262, 294, 330, 349, 392, 440, 494, 523,
    587, 659, 698, 784, 880, 988, 1047, 1175
};

// Function prototypes
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt handler for button press
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 0) { // Button pressed (active low)
        unsigned long current_time = gpioTick();
        if (current_time - last_button_press_time > DEBOUNCE_TIME * 1000) {
            button_pressed = 1;
            last_button_press_time = current_time;
        }
    }
}

// Function to play the melody
void play_melody() {
    if (melody_index < MELODY_LENGTH) {
        int frequency = melody[melody_index];
        if (frequency > 0) {
            gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_CYCLE);
        } else {
            gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the buzzer
        }
        melody_index++;
    } else {
        stop_melody();
    }
}

// Function to stop the melody
void stop_melody() {
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the buzzer
    melody_index = 0;
    button_pressed = 0; // Reset button press flag
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(BUZZER_PIN, PWM_RANGE);

    // Set up interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            play_melody();
            gpioDelay(20000); // Delay for 20ms (adjust as needed)
        } else {
            gpioDelay(10000); // Check every 10ms
        }
    }

    return 0;
}

