#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define SLIDING_WINDOW_SIZE 5

// Structure to hold event data
typedef struct {
    struct timespec timestamp;
    int value;
} event_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static event_t event_buffer[SLIDING_WINDOW_SIZE];
static int buffer_index = 0;
static int event_count = 0;

// Function prototypes
int init_gpio(int gpio_pin);
int read_sensor(int gpio_pin);
int log_event(const event_t *event);
void check_earthquake_alert(const event_t *event);
void signal_handler(int sig);
void cleanup();

// Function to initialize the GPIO line
int init_gpio(int gpio_pin) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", gpio_pin);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value\n");
        return -1;
    }
    return value;
}

// Function to log an event to the file
int log_event(const event_t *event) {
    if (!log_file) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    char timestamp_str[30];
    struct tm tm_info;
    localtime_r(&event->timestamp.tv_sec, &tm_info);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), sizeof(timestamp_str) - strlen(timestamp_str), ".%09ldZ", event->timestamp.tv_nsec);

    if (fprintf(log_file, "%s, %d\n", timestamp_str, event->value) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to check for an earthquake alert
void check_earthquake_alert(const event_t *event) {
    event_buffer[buffer_index] = *event;
    buffer_index = (buffer_index + 1) % SLIDING_WINDOW_SIZE;
    if (event_count < SLIDING_WINDOW_SIZE) {
        event_count++;
    }

    int high_count = 0;
    for (int i = 0; i < event_count; i++) {
        if (event_buffer[i].value == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
