#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_i2c(int address);
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float x, float y);
char *map_heading_to_direction(float heading);
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading, char *direction);
void signal_handler(int signal);

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Configure magnetometer (optional: set data rate and continuous conversion)
    // Example: Set data rate to 15 Hz and continuous conversion mode
    uint8_t config_data[2];
    config_data[0] = CRA_REG_M; // Control register A
    config_data[1] = 0x14;      // 15 Hz output data rate
    if (write(fd, config_data, 2) != 2) {
        perror("Error writing to CRA_REG_M");
        close(fd);
        return -1;
    }

    config_data[0] = MR_REG_M; // Mode register
    config_data[1] = 0x00;      // Continuous conversion mode
    if (write(fd, config_data, 2) != 2) {
        perror("Error writing to MR_REG_M");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read 6 bytes of data (X MSB, X LSB, Z MSB, Z LSB, Y MSB, Y LSB)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calibrate magnetometer data
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Function to calculate heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to map heading to compass direction
char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Function to log data to CSV file
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading, char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading, direction);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    stop_flag = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    fflush(log_file);

    magnetometer_data_t mag_data;
    float calibrated_x, calibrated_y, calibrated_z, heading;
    char *direction;

    // Main loop
    while (!stop_flag) {
        // Read magnetometer data
        if (read_magnetometer_data(&mag_data.x, &mag_data.y, &mag_data.z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(mag_data.x, mag_data.y, mag_data.z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to compass direction
            direction = map_heading_to_direction(heading);

            // Log data to CSV file
            log_data(calibrated_x, calibrated_y, calibrated_z, heading, direction);

            // Print heading and direction to console
            printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping logging.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Close I2C file descriptor and CSV file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

