#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile unsigned long last_touch_time = 0;
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_isr(int gpio, int level, unsigned int tick, void *user_data);
int toggle_relay();
int log_relay_state(const char *state);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0;
}

// Interrupt service routine for touch sensor
void touch_isr(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (level == 1) { // Rising edge (touch detected)
        if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Debounce
            if (toggle_relay() == 0) {
                if (relay_state == 1) {
                    log_relay_state("ON");
                } else {
                    log_relay_state("OFF");
                }
            }
            last_touch_time = current_time;
        }
    }
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return 0;
}

// Function to log relay state to file
int log_relay_state(const char *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return 1;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn relay OFF
    gpioWrite(RELAY_PIN, 0);
    log_relay_state("OFF");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt service routine for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

