#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the activation duration (seconds)
#define ACTIVATION_DURATION 5

// Define the deactivation duration (seconds)
#define DEACTIVATION_DURATION 1

// Define the gap between relay activations (seconds)
#define GAP_DURATION 1

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void log_event(int relay_number, int moisture_level);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int relay1;
    int relay2;
    int relay3;
    int relay4;
} gpio_config_t;

gpio_config_t gpio_pins = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read the soil moisture level
        int moisture_level = read_soil_moisture();

        // Check if the moisture level is below the threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d. Activating relays.\n", moisture_level);

            // Activate relays sequentially
            activate_relay(gpio_pins.relay1);
            log_event(1, moisture_level);
            gpioDelay(ACTIVATION_DURATION * 1000000); // Delay for activation duration
            deactivate_relay(gpio_pins.relay1);
            gpioDelay(GAP_DURATION * 1000000); // Delay for gap duration

            activate_relay(gpio_pins.relay2);
            log_event(2, moisture_level);
            gpioDelay(ACTIVATION_DURATION * 1000000); // Delay for activation duration
            deactivate_relay(gpio_pins.relay2);
            gpioDelay(GAP_DURATION * 1000000); // Delay for gap duration

            activate_relay(gpio_pins.relay3);
            log_event(3, moisture_level);
            gpioDelay(ACTIVATION_DURATION * 1000000); // Delay for activation duration
            deactivate_relay(gpio_pins.relay3);
            gpioDelay(GAP_DURATION * 1000000); // Delay for gap duration

            activate_relay(gpio_pins.relay4);
            log_event(4, moisture_level);
            gpioDelay(ACTIVATION_DURATION * 1000000); // Delay for activation duration
            deactivate_relay(gpio_pins.relay4);

            printf("All relays deactivated.\n");
        } else {
            printf("Moisture level: %d. No action required.\n", moisture_level);
        }

        // Wait for 10 seconds
        gpioDelay(10000000); // 10 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(gpio_pins.relay1, PI_OUTPUT);
    gpioSetMode(gpio_pins.relay2, PI_OUTPUT);
    gpioSetMode(gpio_pins.relay3, PI_OUTPUT);
    gpioSetMode(gpio_pins.relay4, PI_OUTPUT);

    // Set initial state to OFF (active-low)
    gpioWrite(gpio_pins.relay1, 1);
    gpioWrite(gpio_pins.relay2, 1);
    gpioWrite(gpio_pins.relay3, 1);
    gpioWrite(gpio_pins.relay4, 1);

    return 0;
}

// Function to read the soil moisture level (simulated)
int read_soil_moisture() {
    // Generate a random number between 0 and 100
    int moisture_level = rand() % 101;
    return moisture_level;
}

// Function to activate a relay
void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        fprintf(stderr, "Error activating relay on pin %d\n", relay_pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        fprintf(stderr, "Error deactivating relay on pin %d\n", relay_pin);
    }
}

// Function to log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Relay %d activated - Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Received signal %d. Shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    // Deactivate all relays
    deactivate_relay(gpio_pins.relay1);
    deactivate_relay(gpio_pins.relay2);
    deactivate_relay(gpio_pins.relay3);
    deactivate_relay(gpio_pins.relay4);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

