#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo angles
#define VALVE_OPEN_ANGLE 90
#define VALVE_CLOSED_ANGLE 0
#define NOZZLE_ANGLES {0, 45, 90, 135, 180}

// Define watering duration
#define WATERING_DURATION 5 // seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_pulse_width(int gpio_pin, int pulse_width);
int open_valve();
int close_valve();
int sweep_nozzle();
int simulate_soil_moisture();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, stopping servos and exiting...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Set servo pulse width using gpioServo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    int result = gpioServo(gpio_pin, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d\n", gpio_pin, result);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Open the water valve
int open_valve() {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)VALVE_OPEN_ANGLE / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    return set_servo_pulse_width(VALVE_SERVO_PIN, pulse_width);
}

// Close the water valve
int close_valve() {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)VALVE_CLOSED_ANGLE / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    return set_servo_pulse_width(VALVE_SERVO_PIN, pulse_width);
}

// Sweep the nozzle through different angles
int sweep_nozzle() {
    int nozzle_angles[] = NOZZLE_ANGLES;
    int num_angles = sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);

    for (int i = 0; i < num_angles; i++) {
        int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)nozzle_angles[i] / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
        if (set_servo_pulse_width(NOZZLE_SERVO_PIN, pulse_width) != 0) {
            fprintf(stderr, "Error setting nozzle angle to %d degrees\n", nozzle_angles[i]);
            return 1; // Indicate failure
        }
        gpioDelay(2000); // 2 seconds per step
    }
    return 0; // Indicate success
}

// Simulate soil moisture reading
int simulate_soil_moisture() {
    static int moisture_level = 20;
    if (moisture_level > 100) {
        moisture_level = 20;
    }
    printf("Simulated soil moisture: %d\n", moisture_level);
    moisture_level += 20;
    return moisture_level;
}

// Cleanup function to stop servos and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    // Stop both servos
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);

