            if (open_valve() != 0) {
                fprintf(stderr, "Critical error: Failed to open valve. Exiting.\n");
                cleanup();
                return 1;
            }

            // Sweep the nozzle
            if (sweep_nozzle() != 0) {
                fprintf(stderr, "Error during nozzle sweep. Continuing.\n");
            }

            // Hold for watering duration
            printf("Watering for %d seconds...\n", WATERING_DURATION);
            gpioDelay(WATERING_DURATION * 1000); // Convert seconds to milliseconds

