#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    char buf[6];
    gyro_data_t data;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Failed to read gyro data: %s\n", strerror(errno));
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    data.x = (float)raw_x / GYRO_SCALE;
    data.y = (float)raw_y / GYRO_SCALE;
    data.z = (float)raw_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(100); // 10 Hz sampling rate (100 ms delay)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

