        for (int j = 0; j < 4; j++) {
            int step_index = (direction == 1) ? j : (3 - j); // Clockwise or counter-clockwise
            gpioWrite(IN1, step_sequence[step_index][0]);
            gpioWrite(IN2, step_sequence[step_index][1]);
            gpioWrite(IN3, step_sequence[step_index][2]);
            gpioWrite(IN4, step_sequence[step_index][3]);
            gpioDelay(STEP_DELAY);
        }
    }
    // De-energize all coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

// Function to lock the door
void lock_door() {
    if (lock_state == UNLOCKED) {
        printf("Locking door...\n");
        step_motor(QUARTER_TURN_STEPS, 1); // Rotate clockwise
        lock_state = LOCKED;
        printf("Door locked.\n");
    } else {
        printf("Door already locked.\n");
    }
}

// Function to unlock the door
void unlock_door() {
    if (lock_state == LOCKED) {
        printf("Unlocking door...\n");
        step_motor(QUARTER_TURN_STEPS, 0); // Rotate counter-clockwise
        lock_state = UNLOCKED;
        printf("Door unlocked.\n");
    } else {
        printf("Door already unlocked.\n");
    }
}

// Callback function for push-button presses
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick < DEBOUNCE_DELAY * 1000) {
        return;
    }
    last_tick = current_tick;

    // Check if the button is pressed (active-low)
    if (level == 0) {
        if (gpio == LOCK_BUTTON) {
            lock_door();
        } else if (gpio == UNLOCK_BUTTON) {
            unlock_door();
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. De-energizing coils and exiting...\n");
    // De-energize all coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

