#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds
#define MIN_MEASUREMENT_INTERVAL_MS 60 // Minimum measurement interval in milliseconds

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_distance(double distance_cm);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Indicate rising edge received
        } else if (level == 0 && echo_received) {
            echo_end_tick = tick;
            echo_received = 0; // Indicate falling edge received
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance_cm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (distance_cm >= 0) {
            fprintf(log_file, "%s, %.2f\n", timestamp, distance_cm);
            fflush(log_file); // Ensure data is written to disk immediately
        } else {
            fprintf(log_file, "%s, -1\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();

        // Wait for echo pulse or timeout
        int timeout_count = 0;
        while (!echo_received && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Check every microsecond
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            log_distance(-1.0);
        } else {
            // Wait for falling edge or timeout
            timeout_count = 0;
            while (echo_received && timeout_count < TIMEOUT_US) {
                gpioDelay(1); // Check every microsecond
                timeout_count++;
            }

            if (echo_received) {
                fprintf(stderr, "Timeout waiting for falling edge\n");
                log_distance(-1.0);
            } else {
                int pulse_width_us = echo_end_tick - echo_start_tick;
                if (pulse_width_us < 0) {
                    pulse_width_us += 0xFFFFFFFF; // Handle tick rollover
                }

                double distance_cm = calculate_distance(pulse_width_us);
                log_distance(distance_cm);
            }
        }

        gpioDelay(MIN_MEASUREMENT_INTERVAL_MS * 1000); // Wait for minimum measurement interval
    }

    cleanup();
    return 0;
}

