#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int write_i2c_reg(int fd, uint8_t reg, uint8_t value);
int read_i2c_reg(int fd, uint8_t reg, uint8_t *value);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void convert_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_dps, float *y_dps, float *z_dps);
void log_data(float x_dps, float y_dps, float z_dps);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Write a byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C register");
        return -1;
    }

    return 0;
}

// Read a byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C register");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (write(fd, (uint8_t[]){GYRO_XOUT_H}, 1) != 1) {
        perror("Error writing register address for gyro data");
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw gyroscope data to degrees per second
void convert_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)raw_x / 131.0;
    *y_dps = (float)raw_y / 131.0;
    *z_dps = (float)raw_z / 131.0;
}

// Log gyroscope data to the console
void log_data(float x_dps, float y_dps, float z_dps) {
    printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", x_dps, y_dps, z_dps);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (write_i2c_reg(i2c_fd, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert gyroscope data
            convert_gyro_data(raw_x, raw_y, raw_z, &x_dps, &y_dps, &z_dps);

            // Log gyroscope data
            log_data(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        usleep(100000);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

