#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800 // 30 minutes

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int pin, int state);
void set_pwm_duty_cycle(int pin, int duty_cycle);
void sunrise_simulation();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency for all relays
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the state of a relay (ON or OFF)
void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
    char message[100];
    snprintf(message, sizeof(message), "Relay on pin %d set to %s", pin, state ? "ON" : "OFF");
    log_event(message);
}

// Function to set the PWM duty cycle for a relay
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    gpioPWM(pin, duty_cycle);
    char message[100];
    snprintf(message, sizeof(message), "PWM duty cycle on pin %d set to %d", pin, duty_cycle);
    log_event(message);
}

// Function to simulate the sunrise effect
void sunrise_simulation() {
    int step_duration = 1000; // 1 second
    int num_steps = SUNRISE_DURATION / step_duration;
    int duty_cycle_increment = 255 / num_steps;

    for (int i = 0; i <= num_steps; i++) {
        int duty_cycle = i * duty_cycle_increment;

        // Set duty cycle for all relays
        set_pwm_duty_cycle(RELAY1_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY2_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY3_PIN, duty_cycle);
        set_pwm_duty_cycle(RELAY4_PIN, duty_cycle);

        gpioDelay(step_duration * 1000); // Delay in microseconds
    }

    // Ensure all relays are fully ON at the end of the sunrise
    set_pwm_duty_cycle(RELAY1_PIN, 255);
    set_pwm_duty_cycle(RELAY2_PIN, 255);
    set_pwm_duty_cycle(RELAY3_PIN, 255);
    set_pwm_duty_cycle(RELAY4_PIN, 255);

    log_event("Sunrise simulation complete");
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Signal received, shutting down...");
}

// Function to clean up resources before exiting
void cleanup() {
    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete, exiting.");
}

int main() {
    // Open the log file
    log_file = fopen("smart_lighting.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    log_event("Starting smart lighting system...");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting.");
        fclose(log_file);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Run the sunrise simulation
    sunrise_simulation();

    // Clean up resources before exiting
    cleanup();

    return 0;
}

