#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47
#define WHO_AM_I     0x75

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    int result;

    while (retries > 0) {
        // Wake up the MPU-6050 (clear sleep mode bit)
        result = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (PWR_MGMT_1). Retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Set sample rate divider (1 kHz)
        result = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
        if (result != 0) {
            fprintf(stderr, "Error: Could not set sample rate divider (SMPLRT_DIV). Retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Set gyroscope full-scale range to ±250 deg/s
        result = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range (GYRO_CONFIG). Retrying... (%d retries left)\n", retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i != 0x68) {
            fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X (expected 0x68). Retrying... (%d retries left)\n", who_am_i, retries);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: MPU-6050 initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data. Returning previous values.\n");
        return -1; // Indicate failure
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second (131 LSB/deg/s)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0; // Indicate success
}

// Function to add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if the threshold is exceeded
void check_threshold(float x, float y, float z) {
    if (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait before re-initializing
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus. Error code: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            if (init_mpu6050() != 0) {
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(50); // 20 Hz (50 ms delay)
    }

    return 0;
}

