#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// MPU-9250 Registers
#define MPU9250_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8 // CE0

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int mpu9250_init(void);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MPU-9250 Initialization
int mpu9250_init(void) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Wake up the MPU-9250 (clear sleep mode bit)
    tx_buf[0] = PWR_MGMT_1 | 0x80; // Write command
    tx_buf[1] = 0x00; // Clear sleep mode bit
    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    usleep(100000); // Wait for the MPU-9250 to wake up

    // Configure gyroscope range to ±250 dps
    tx_buf[0] = GYRO_CONFIG | 0x80; // Write command
    tx_buf[1] = 0x00; // Set full scale range to ±250 dps
    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];

    // Read gyroscope data starting from GYRO_XOUT_H
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read command
    memset(rx_buf, 0, sizeof(rx_buf));

    if (spi_transfer(tx_buf, rx_buf, 7) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    return 0;
}

// Convert Raw Data to Degrees per Second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / 131.0;
}

// Log Data to File
int log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    char timestamp[30];

    // Get current timestamp with nanosecond precision
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting timestamp");
        return -1;
    }

    // Format timestamp in ISO 8601 format
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    // Write data to log file
    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main(void) {
    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;
    int retry_count;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "mpu9250_cs", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize MPU-9250
    if (mpu9250_init() < 0) {
        fprintf(stderr, "MPU-9250 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        retry_count = 0;
        while (retry_count < 3) {
            // Read gyroscope data
            if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
                // Convert raw data to degrees per second
                x_rate = convert_to_dps(raw_x);
                y_rate = convert_to_dps(raw_y);
                z_rate = convert_to_dps(raw_z);

                // Log data
                if (log_data(x_rate, y_rate, z_rate) != 0) {
                    fprintf(stderr, "Error logging data, retrying...\n");
                    retry_count++;
                    usleep(100000); // Wait before retrying
                    continue;
                }

                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "SPI communication failed, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                usleep(100000); // Wait before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "SPI communication failed after multiple retries. Logging to stderr.\n");
            struct timespec ts;
            char timestamp[30];
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);
            fprintf(stderr, "%s,SPI_ERROR,Failed to read gyro data after multiple retries\n", timestamp);
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

