            if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
                // Convert raw data to degrees per second
                x_rate = convert_to_dps(raw_x);
                y_rate = convert_to_dps(raw_y);
                z_rate = convert_to_dps(raw_z);

                // Log data
                if (log_data(x_rate, y_rate, z_rate) != 0) {
                    fprintf(stderr, "Error logging data, retrying...\n");
                    retry_count++;
                    usleep(100000); // Wait before retrying
                    continue;
                }

                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "SPI communication failed, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                usleep(100000); // Wait before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "SPI communication failed after multiple retries. Logging to stderr.\n");
            struct timespec ts;
            char timestamp[30];
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);
            fprintf(stderr, "%s,SPI_ERROR,Failed to read gyro data after multiple retries\n", timestamp);
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

