#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 3900000 // 3.9 MHz
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define GYRO_SENSITIVITY 131.0
#define MAX_GYRO_RATE 200.0

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int spi_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *led_line;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t reg_addr, uint8_t *data, int len);
int read_gyro_data(gyro_data_t *data);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, gyro_data_t data);
void buffer_print(circular_buffer_t *buffer);
void led_on(void);
void led_off(void);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t reg_addr, uint8_t *data, int len) {
    uint8_t tx_buf[len + 1];
    uint8_t rx_buf[len + 1];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    memcpy(tx_buf + 1, data, len);

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len + 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t reg_addr = GYRO_XOUT_H;
    uint8_t raw_data[6];

    if (spi_transfer(reg_addr, raw_data, 6) != 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (raw_data[0] << 8) | raw_data[1];
    int16_t gyro_y = (raw_data[2] << 8) | raw_data[3];
    int16_t gyro_z = (raw_data[4] << 8) | raw_data[5];

    // Convert to degrees per second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    // Get timestamp
    if (clock_gettime(CLOCK_REALTIME, &data->timestamp) == -1) {
        perror("Error getting timestamp");
        return -1;
    }

    return 0;
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer print function
void buffer_print(circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n", buffer->data[index].timestamp.tv_sec, buffer->data[index].timestamp.tv_nsec, buffer->data[index].x, buffer->data[index].y, buffer->data[index].z);
    }
}

// LED on function
void led_on(void) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error setting LED on");
    }
}

// LED off function
void led_off(void) {
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED off");
    }
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (led_line) {
        led_off();
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting LED line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED line as output");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    gyro_data_t gyro_data;

    printf("Starting data acquisition...\n");

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            buffer_add(&gyro_buffer, gyro_data);

            // Check for excessive angular velocity
            if (fabs(gyro_data.x) > MAX_GYRO_RATE || fabs(gyro_data.y) > MAX_GYRO_RATE || fabs(gyro_data.z) > MAX_GYRO_RATE) {
                printf("Excessive angular velocity detected!\n");
                led_on();
                usleep(500000); // 500 ms
                led_off();
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Print circular buffer
    buffer_print(&gyro_buffer);

    // Cleanup and exit
    cleanup();
    return 0;
}

