#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int si1145_init(int fd);
int read_ambient_light(int fd);
int read_proximity(int fd);
void log_data(FILE *fp, int ambient_light, int proximity);
void control_led(int gpio_value);
void signal_handler(int sig);

// I2C read register function with retries
int i2c_read_register(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retry %d/%d\n", reg, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// I2C write register function with retries
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s. Retry %d/%d\n", reg, value, strerror(errno), retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, value 0x%02X)\n", MAX_RETRIES, reg, value);
    return -1; // Indicate failure
}

// Si1145 initialization function
int si1145_init(int fd) {
    // Reset the device
    if (i2c_write_register(fd, 0x07, 0x00) < 0) return -1;
    usleep(10000); // Wait for reset

    // Configure the sensor (example configuration)
    if (i2c_write_register(fd, 0x02, 0x01) < 0) return -1; // Enable force mode
    if (i2c_write_register(fd, 0x03, 0x00) < 0) return -1; // Disable interrupts
    if (i2c_write_register(fd, 0x18, 0x7B) < 0) return -1; // PS1 LED drive strength
    if (i2c_write_register(fd, 0x19, 0x00) < 0) return -1; // PS2 LED drive strength
    if (i2c_write_register(fd, 0x1A, 0x00) < 0) return -1; // PS3 LED drive strength
    if (i2c_write_register(fd, 0x0F, 0x03) < 0) return -1; // PS1 measurement rate
    if (i2c_write_register(fd, 0x10, 0x03) < 0) return -1; // PS2 measurement rate
    if (i2c_write_register(fd, 0x11, 0x03) < 0) return -1; // PS3 measurement rate
    if (i2c_write_register(fd, 0x1E, 0x07) < 0) return -1; // PS1 ADC gain
    if (i2c_write_register(fd, 0x1F, 0x07) < 0) return -1; // PS2 ADC gain
    if (i2c_write_register(fd, 0x20, 0x07) < 0) return -1; // PS3 ADC gain
    if (i2c_write_register(fd, 0x01, 0x77) < 0) return -1; // Enable PS1, PS2, PS3

    return 0;
}

// Read ambient light value
int read_ambient_light(int fd) {
    int low = i2c_read_register(fd, AMBIENT_LIGHT_REG);
    int high = i2c_read_register(fd, AMBIENT_LIGHT_REG + 1);

    if (low < 0 || high < 0) {
        return -1;
    }

    return (high << 8) | low;
}

// Read proximity value
int read_proximity(int fd) {
    int low = i2c_read_register(fd, PROXIMITY_REG);
    int high = i2c_read_register(fd, PROXIMITY_REG + 1);

    if (low < 0 || high < 0) {
        return -1;
    }

    return (high << 8) | low;
}

// Log data to file
void log_data(FILE *fp, int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%04X,Proximity:%04X\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int gpio_value) {
    if (led_line != NULL) {
        int ret = gpiod_line_set_value(led_line, gpio_value);
        if (ret < 0) {
            fprintf(stderr, "Error setting LED value: %s\n", strerror(-ret));
        }
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request LED line for output
    if (gpiod_line_request_output(led_line, "biometric_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int ambient_light = read_ambient_light(i2c_fd);
        int proximity = read_proximity(i2c_fd);

        if (ambient_light >= 0 && proximity >= 0) {
            // Log data
            log_data(log_file, ambient_light, proximity);

            // Control LED
            if (proximity > PROXIMITY_THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 100ms
        usleep(100000);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (led_line) {
        control_led(0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

