#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define seismic event duration (in milliseconds)
#define SEISMIC_EVENT_DURATION 500

// Global variables
FILE *log_file = NULL;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void trigger_alert();
void log_event(const char *message);
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t start_time;
} SensorData;

SensorData sensor_data = {0, 0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set alert pin as output
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure it starts LOW

    // Register callbacks for both sensors
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 1. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 2. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();

    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Trigger the alert (set GPIO HIGH for 2 seconds, then LOW)
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(2000); // 2 seconds
    gpioWrite(ALERT_PIN, 0);
}

// Log an event to the log file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor1_value = read_sensor(SENSOR_1_PIN);
    int sensor2_value = read_sensor(SENSOR_2_PIN);

    if (sensor1_value == 1 && sensor2_value == 1) {
        if (sensor_data.sensor1_state == 0 && sensor_data.sensor2_state == 0) {
            sensor_data.start_time = tick;
        }
        sensor_data.sensor1_state = 1;
        sensor_data.sensor2_state = 1;

        if (tick - sensor_data.start_time >= SEISMIC_EVENT_DURATION) {
            log_event("Seismic event detected!");
            trigger_alert();
            sensor_data.sensor1_state = 0;
            sensor_data.sensor2_state = 0;
        }
    } else {
        sensor_data.sensor1_state = 0;
        sensor_data.sensor2_state = 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    exit(0);
}

