#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define ADXRS290_RATE_XL 0x02
#define ADXRS290_RATE_XH 0x03
#define LED_GPIO 17
#define ANGULAR_RATE_THRESHOLD 20.0
#define BUFFER_CAPACITY 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float angular_rate_x;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_read_register(int handle, uint8_t address, uint8_t *data, int count);
int spi_write_register(int handle, uint8_t address, uint8_t *data, int count);
int16_t combine_bytes(uint8_t msb, uint8_t lsb);
float convert_to_degrees_per_second(int16_t raw_rate);
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, gyro_data_t data);
int buffer_get(circular_buffer_t *buffer, gyro_data_t *data);
void signal_handler(int signal);
void *data_acquisition_thread(void *arg);
void *data_processing_thread(void *arg);

// SPI read function
int spi_read_register(int handle, uint8_t address, uint8_t *data, int count) {
    char tx_buffer[count + 1];
    char rx_buffer[count + 1];

    // Set MSB to 1 for read operation
    tx_buffer[0] = address | 0x80;
    memset(tx_buffer + 1, 0, count); // Fill with dummy data for reading

    if (spiXfer(handle, tx_buffer, rx_buffer, count + 1) != count + 1) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    memcpy(data, rx_buffer + 1, count);
    return 0;
}

// SPI write function
int spi_write_register(int handle, uint8_t address, uint8_t *data, int count) {
    char tx_buffer[count + 1];
    char rx_buffer[count + 1];

    // Set MSB to 0 for write operation
    tx_buffer[0] = address & 0x7F;
    memcpy(tx_buffer + 1, data, count);

    if (spiXfer(handle, tx_buffer, rx_buffer, count + 1) != count + 1) {
        fprintf(stderr, "SPI write failed\n");
        return -1;
    }

    return 0;
}

// Combine two bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Convert raw angular rate to degrees per second
float convert_to_degrees_per_second(int16_t raw_rate) {
    return (float)raw_rate / 200.0;
}

// Circular buffer initialization
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to the circular buffer
int buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Get data from the circular buffer
int buffer_get(circular_buffer_t *buffer, gyro_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Data acquisition thread
void *data_acquisition_thread(void *arg) {
    uint8_t rate_xl, rate_xh;
    int16_t raw_rate;
    float angular_rate;
    struct timespec timestamp;
    gyro_data_t gyro_data;

    while (program_running) {
        // Read X-axis angular rate
        if (spi_read_register(spi_handle, ADXRS290_RATE_XL, &rate_xl, 1) != 0) {
            fprintf(stderr, "Error reading RATE_XL\n");
            continue;
        }
        if (spi_read_register(spi_handle, ADXRS290_RATE_XH, &rate_xh, 1) != 0) {
            fprintf(stderr, "Error reading RATE_XH\n");
            continue;
        }

        // Combine bytes
        raw_rate = combine_bytes(rate_xh, rate_xl);

        // Convert to degrees per second
        angular_rate = convert_to_degrees_per_second(raw_rate);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &timestamp) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Store data in gyro_data struct
        gyro_data.timestamp = timestamp;
        gyro_data.angular_rate_x = angular_rate;

        // Add data to circular buffer
        if (buffer_add(&gyro_buffer, gyro_data) != 0) {
            fprintf(stderr, "Error adding data to buffer\n");
        }

        // Sleep for the specified sample period
        usleep(SAMPLE_PERIOD_US);
    }

    pthread_exit(NULL);
}

// Data processing thread
void *data_processing_thread(void *arg) {
    gyro_data_t gyro_data;
    float angular_rate_x;

    while (program_running) {
        // Get data from circular buffer
        if (buffer_get(&gyro_buffer, &gyro_data) == 0) {
            angular_rate_x = gyro_data.angular_rate_x;

            // Check if angular velocity exceeds threshold
            if (fabs(angular_rate_x) > ANGULAR_RATE_THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
            } else {
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            // Buffer is empty, sleep briefly to avoid busy-waiting
            usleep(1000); // 1 ms
        }
    }

    pthread_exit(NULL);
}

int main() {
    pthread_t acquisition_thread, processing_thread;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create data acquisition thread
    if (pthread_create(&acquisition_thread, NULL, data_acquisition_thread, NULL) != 0) {
        perror("pthread_create (acquisition)");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Create data processing thread
    if (pthread_create(&processing_thread, NULL, data_processing_thread, NULL) != 0) {
        perror("pthread_create (processing)");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for threads to finish (until signal is received)
    pthread_join(acquisition_thread, NULL);
    pthread_join(processing_thread, NULL);

    // Close SPI
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

