#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM range and frequency
#define PWM_RANGE 255
#define PWM_FREQUENCY 100

// Global variable to store the fade duration
int fade_duration = 0;

// Function prototypes
int initialize_gpio();
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the brightness of a lamp using PWM
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off over a specified duration
void fade_lamp(int gpio, int duration) {
    int steps = duration * PWM_FREQUENCY; // Number of steps for the fade
    int delay_us = 1000000 / PWM_FREQUENCY; // Delay between steps in microseconds

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    for (int i = PWM_RANGE; i >= 0; i--) {
        set_lamp_brightness(gpio, i);
        gpioDelay(delay_us);
    }

    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

// Function to turn off all lamps and terminate the pigpio library
void cleanup_gpio() {
    printf("Turning off all lamps...\n");
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main(int argc, char *argv[]) {
    // Check for the correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the command-line argument to an integer
    fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Error: Invalid fade duration. Must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set up signal handling for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, fade_duration);
    fade_lamp(LAMP2_GPIO, fade_duration);
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Sunset simulation complete.\n");

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

