#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

// Define the states of the traffic light
typedef enum {
    RED,
    RED_YELLOW,
    GREEN,
    YELLOW
} TrafficLightState;

// Global variable to track the current state
TrafficLightState currentState = RED;

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Turn off all relays
    gpioWrite(RED_PIN, 1);
    gpioWrite(YELLOW_PIN, 1);
    gpioWrite(GREEN_PIN, 1);
    gpioWrite(BLUE_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    exit(signum);
}

// Function to set the state of the traffic light
void setTrafficLightState(TrafficLightState state) {
    currentState = state;

    switch (state) {
        case RED:
            printf("State: RED\n");
            gpioWrite(RED_PIN, 0);
            gpioWrite(YELLOW_PIN, 1);
            gpioWrite(GREEN_PIN, 1);
            gpioWrite(BLUE_PIN, 1);
            break;
        case RED_YELLOW:
            printf("State: RED+YELLOW\n");
            gpioWrite(RED_PIN, 0);
            gpioWrite(YELLOW_PIN, 0);
            gpioWrite(GREEN_PIN, 1);
            gpioWrite(BLUE_PIN, 1);
            break;
        case GREEN:
            printf("State: GREEN\n");
            gpioWrite(RED_PIN, 1);
            gpioWrite(YELLOW_PIN, 1);
            gpioWrite(GREEN_PIN, 0);
            gpioWrite(BLUE_PIN, 1);
            break;
        case YELLOW:
            printf("State: YELLOW\n");
            gpioWrite(RED_PIN, 1);
            gpioWrite(YELLOW_PIN, 0);
            gpioWrite(GREEN_PIN, 1);
            gpioWrite(BLUE_PIN, 1);
            break;
        default:
            printf("State: Unknown\n");
            gpioWrite(RED_PIN, 1);
            gpioWrite(YELLOW_PIN, 1);
            gpioWrite(GREEN_PIN, 1);
            gpioWrite(BLUE_PIN, 1);
            break;
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // RED state
        setTrafficLightState(RED);
        sleep(10);

        // RED+YELLOW state
        setTrafficLightState(RED_YELLOW);
        sleep(2);

        // GREEN state
        setTrafficLightState(GREEN);
        sleep(10);

        // YELLOW state
        setTrafficLightState(YELLOW);
        sleep(3);
    }

    return 0;
}

