#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 100 // milliseconds
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Structure for MPR121 configuration
typedef struct {
    uint8_t reset_value;
    uint8_t stop_mode_value;
    uint8_t electrode_enable_value;
    uint8_t touch_threshold_value;
    uint8_t release_threshold_value;
    uint8_t debounce_value;
    uint8_t charge_time_value;
    uint8_t run_mode_value;
} mpr121_config_t;

mpr121_config_t mpr121_config = {
    .reset_value = 0x63,
    .stop_mode_value = 0x00,
    .electrode_enable_value = 0x01,
    .touch_threshold_value = TOUCH_THRESHOLD,
    .release_threshold_value = RELEASE_THRESHOLD,
    .debounce_value = 0x21,
    .charge_time_value = 0x0D,
    .run_mode_value = 0x0D
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message("GPIO initialization failed");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        log_message("I2C open failed");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        log_message("MPR121 initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_message("System started");

    uint16_t touch_status = 0;
    int relay_state = 0; // 0 = off, 1 = on
    int last_relay_state = 0;
    int debounce_count = 0;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & 0x01) { // Electrode 0 touched
                debounce_count++;
                if (debounce_count >= (1000 / DEBOUNCE_TIME)) { // Debounce
                    relay_state = !relay_state;
                    control_relay(relay_state);
                    debounce_count = 0;
                }
