// Define dispense duration (milliseconds)
#define DISPENSE_DURATION 1000

// Define log file name
#define LOG_FILE "dispense_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin);
int deactivate_solenoid(int pin);
int dispense_cycle();
int log_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to perform a dispense cycle
int dispense_cycle() {
    if (activate_solenoid(SOLENOID_1_PIN) != 0) {
        return 1;
    }
    gpioDelay(DISPENSE_DURATION * 500); // Half the duration

    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        return 1;
    }

    if (activate_solenoid(SOLENOID_2_PIN) != 0) {
        return 1;
    }
    gpioDelay(DISPENSE_DURATION * 500); // Half the duration

    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        return 1;
    }

    return 0;
}

// Function to log an event to the log file
int log_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Solenoid 1: %d, Solenoid 2: %d, Duration: %d ms\n", timestamp, solenoid1_pin, solenoid2_pin, duration_ms);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file %s\n", LOG_FILE);
        return 1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Dispense cycle failed\n");
        }

        if (log_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Deactivate solenoids before exiting
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    // Terminate pigpio
    gpioTerminate();

    printf("Pneumatic dispensing system stopped.\n");

    return 0;
}

