#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// Ultrasonic sensor GPIO pin
#define ULTRASONIC_TRIGGER 4
#define ULTRASONIC_ECHO 12

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Obstacle avoidance distance (cm)
#define OBSTACLE_DISTANCE 20.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold motor speeds
typedef struct {
    int motor_a_speed;
    int motor_b_speed;
} MotorSpeeds;

// Function prototypes
float generate_tilt_error();
float read_ultrasonic_distance();
MotorSpeeds calculate_motor_speeds(float tilt_error, float distance);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Function to generate a random tilt error between -10.0 and 10.0 degrees
float generate_tilt_error() {
    return (float)(rand() % 2001 - 1000) / 100.0; // Generates a value between -1000 and 1000, then divides by 100 to get a value between -10.0 and 10.0
}

// Function to read the ultrasonic distance sensor
float read_ultrasonic_distance() {
    gpioWrite(ULTRASONIC_TRIGGER, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(ULTRASONIC_TRIGGER, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ULTRASONIC_ECHO) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= 10000) return 1000.0; // Timeout
    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ULTRASONIC_ECHO) == 1 && count < 10000) {
        count++;
        gpioDelay(1);
    }
    if (count >= 10000) return 1000.0; // Timeout
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

// Function to calculate motor speeds using a PID controller
MotorSpeeds calculate_motor_speeds(float tilt_error, float distance) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    float error = tilt_error;
    integral += error;
    float derivative = error - previous_error;

    float output = KP * error + KI * integral + KD * derivative;

    // Obstacle avoidance
    if (distance < OBSTACLE_DISTANCE) {
        output = 0.0; // Stop the robot
        set_motor_speed(-50, -50); // Reverse both motors at 50% speed
        gpioDelay(500); // Reverse for 500ms
        stop_motors();
        return (MotorSpeeds){0, 0}; // Return 0 speeds after obstacle avoidance
    }

    // Clamp the output to the range -255 to 255
    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    // Split the output into motor speeds (assuming symmetric motor control)
    int motor_a_speed = (int)output;
    int motor_b_speed = (int)output;

    // Ensure motor speeds are within the valid range
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    previous_error = error;

    return (MotorSpeeds){motor_a_speed, motor_b_speed};
}

// Function to set the motor speeds
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(MOTOR_A_ENABLE, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_ENABLE, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(MOTOR_B_ENABLE, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_ENABLE, 0);
    }
}

// Function to stop the motors
void stop_motors() {
    set_motor_speed(0, 0);
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    stop_motors();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);
    gpioSetMode(ULTRASONIC_TRIGGER, PI_OUTPUT);
    gpioSetMode(ULTRASONIC_ECHO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_ENABLE, PWM_FREQUENCY);

    // Open the log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate tilt error
        float tilt_error = generate_tilt_error();

        // Read ultrasonic distance
        float distance = read_ultrasonic_distance();

        // Calculate motor speeds
        MotorSpeeds motor_speeds = calculate_motor_speeds(tilt_error, distance);

        // Set motor speeds
        set_motor_speed(motor_speeds.motor_a_speed, motor_speeds.motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_speeds.motor_a_speed, motor_speeds.motor_b_speed);

        // Delay
        gpioDelay(50); // 50 ms
    }

    // Stop motors and close log file before exiting
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    return 0;
}

