#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %d\n", relay_state);
}

// Function to debounce the touch sensor
void debounce() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            debounce();
        }
        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0; // This line will never be reached due to the infinite loop
}

