#define ALSA_AVAILABLE

// Global variables
static volatile int running = 1;
static float sensitivity = 1.0;

// Structure to hold ALSA parameters
typedef struct {
    snd_pcm_t *pcm_handle;
    snd_pcm_hw_params_t *hw_params;
} alsa_params_t;

// Function prototypes
void signal_handler(int signal);
int initialize_pigpio();
void set_led_color(int red, int green, int blue);
float calculate_rms(short *samples, int num_samples);
void map_amplitude_to_color(float rms_amplitude, int *red, int *green, int *blue);
void cleanup();

#ifdef ALSA_AVAILABLE
