#endif

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    return 0;
}

// Set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Calculate the RMS amplitude of the audio samples
float calculate_rms(short *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Map the RMS amplitude to RGB color values using a non-linear transition
void map_amplitude_to_color(float rms_amplitude, int *red, int *green, int *blue) {
    // Normalize the amplitude to a range of 0-1
    float normalized_amplitude = rms_amplitude / 32768.0; // Assuming max amplitude is 32768

    // Apply sensitivity scaling
    normalized_amplitude *= sensitivity;

    // Clamp the amplitude to the range of 0-1
    if (normalized_amplitude < 0.0) normalized_amplitude = 0.0;
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0;

    // Non-linear mapping (example: cool colors for low amplitude, warm colors for high amplitude)
    float hue = normalized_amplitude * 0.5; // Map 0-1 to 0-0.5 (cool colors)
    //hue = (1.0 - normalized_amplitude) * 0.5; // Map 0-1 to 0.5-1 (warm colors)

    // Convert HSV to RGB (simplified, assumes saturation and value are 1.0)
    float r, g, b;
    if (hue < 1.0/6.0) {
        r = 1.0;
        g = hue * 6.0;
        b = 0.0;
    } else if (hue < 2.0/6.0) {
        r = 1.0 - (hue - 1.0/6.0) * 6.0;
        g = 1.0;
        b = 0.0;
    } else if (hue < 3.0/6.0) {
        r = 0.0;
        g = 1.0;
        b = (hue - 2.0/6.0) * 6.0;
    } else if (hue < 4.0/6.0) {
        r = 0.0;
        g = 1.0 - (hue - 3.0/6.0) * 6.0;
        b = 1.0;
    } else if (hue < 5.0/6.0) {
        r = (hue - 4.0/6.0) * 6.0;
        g = 0.0;
        b = 1.0;
    } else {
        r = 1.0;
        g = 0.0;
        b = 1.0 - (hue - 5.0/6.0) * 6.0;
    }

    // Scale RGB values to 0-255
    *red   = (int)(r * 255.0);
    *green = (int)(g * 255.0);
    *blue  = (int)(b * 255.0);
}

// Cleanup resources before exiting
