    printf("Cleaning up...\n");
    set_led_color(0, 0, 0); // Turn off LED

#ifdef ALSA_AVAILABLE
    alsa_params_t alsa_params;
    close_alsa(&alsa_params);
#endif

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

