#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define sunrise/sunset duration (seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime duration (seconds)
#define DAYTIME_DURATION 21600

// Define nighttime duration (seconds)
#define NIGHTTIME_DURATION 518400

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the brightness of a relay using PWM
void set_relay_brightness(int gpio_pin, int brightness) {
    gpioPWM(gpio_pin, brightness);
}

// Function to simulate sunrise
void sunrise() {
    printf("Starting sunrise...\n");
    for (int i = 0; i <= 255 && program_running; ++i) {
        set_relay_brightness(RELAY1_PIN, i);
        set_relay_brightness(RELAY2_PIN, i);
        set_relay_brightness(RELAY3_PIN, i);
        set_relay_brightness(RELAY4_PIN, i);
        gpioDelay(SUNRISE_DURATION * 1000000 / 255); // Delay for each brightness step
    }
    printf("Sunrise complete.\n");
}

// Function to simulate daytime
void daytime() {
    printf("Starting daytime...\n");
    set_relay_brightness(RELAY1_PIN, 255);
    set_relay_brightness(RELAY2_PIN, 255);
    set_relay_brightness(RELAY3_PIN, 255);
    set_relay_brightness(RELAY4_PIN, 255);
    gpioDelay(DAYTIME_DURATION * 1000000); // Delay for daytime duration
    printf("Daytime complete.\n");
}

// Function to simulate sunset
void sunset() {
    printf("Starting sunset...\n");
    for (int i = 255; i >= 0 && program_running; --i) {
        set_relay_brightness(RELAY1_PIN, i);
        set_relay_brightness(RELAY2_PIN, i);
        set_relay_brightness(RELAY3_PIN, i);
        set_relay_brightness(RELAY4_PIN, i);
        gpioDelay(SUNSET_DURATION * 1000000 / 255); // Delay for each brightness step
    }
    printf("Sunset complete.\n");
}

// Function to simulate nighttime
void nighttime() {
    printf("Starting nighttime...\n");
    set_relay_brightness(RELAY1_PIN, 0);
    set_relay_brightness(RELAY2_PIN, 0);
    set_relay_brightness(RELAY3_PIN, 0);
    set_relay_brightness(RELAY4_PIN, 0);
    gpioDelay(NIGHTTIME_DURATION * 1000000); // Delay for nighttime duration
    printf("Nighttime complete.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Turn off all relays before exiting
    set_relay_brightness(RELAY1_PIN, 0);
    set_relay_brightness(RELAY2_PIN, 0);
    set_relay_brightness(RELAY3_PIN, 0);
    set_relay_brightness(RELAY4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

