#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_DELAY 200 // milliseconds
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y%m%dT%H%M%SZ", timeinfo);
    return timestamp;
}

// Function to execute the raspivid command
int execute_raspivid(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    }
    return 0;
}

// Function to log the motion event to a file
int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to generate a filename based on the timestamp
char* generate_filename(const char *timestamp) {
    char *filename = (char*)malloc(128 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }
    snprintf(filename, 128, "%s%s.h264", VIDEO_DIR, timestamp);
    return filename;
}

// Function to handle motion detection
void handle_motion() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp. Skipping motion event.\n");
        return;
    }

    char *filename = generate_filename(timestamp);
    if (filename == NULL) {
        fprintf(stderr, "Failed to generate filename. Skipping motion event.\n");
        free(timestamp);
        return;
    }

    if (log_motion_event(timestamp) != 0) {
        fprintf(stderr, "Failed to log motion event.\n");
    }

    if (execute_raspivid(filename) != 0) {
        fprintf(stderr, "Failed to execute raspivid.\n");
    }

    free(timestamp);
    free(filename);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Create the video directory if it doesn't exist
    struct stat st = {0};
    if (stat(VIDEO_DIR, &st) == -1) {
        if (mkdir(VIDEO_DIR, 0777) == -1) {
            perror("Failed to create video directory");
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Check for motion (LOW signal)
        if (sensor_value == 0) {
            handle_motion();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

