#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_sensor();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPU-6050 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the sensor
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (PWR_MGMT_1). Status: %d. Retrying...\n", status);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Set sample rate divider
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07); // 125 Hz
        if (status != 0) {
            fprintf(stderr, "Error: Could not set sample rate divider (SMPLRT_DIV). Status: %d. Retrying...\n", status);
