int running = 1;

// Function prototypes
int read_moisture_sensor(int zone);
void control_relay(int relay_pin, int state);
void log_data(int zone, int moisture_level, int relay_state);
void signal_handler(int signal);

// Function to read the moisture sensor for a given zone
int read_moisture_sensor(int zone) {
    // Simulate reading the moisture sensor
    int moisture_level = rand() % 101; // Returns a value between 0 and 100
    return moisture_level;
}

// Function to control the relay (activate or deactivate)
void control_relay(int relay_pin, int state) {
    // Set the GPIO pin to the specified state
    gpioWrite(relay_pin, state);
}

// Function to log the data to the file
void log_data(int zone, int moisture_level, int relay_state) {
    // Get the current time
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write the data to the log file
    fprintf(log_file, "%s, Zone: %d, Moisture: %d, Relay: %s\n", timestamp, zone, moisture_level, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Deactivate all relays
    control_relay(RELAY1_PIN, 1);
    control_relay(RELAY2_PIN, 1);
    control_relay(RELAY3_PIN, 1);
    control_relay(RELAY4_PIN, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Greenhouse irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read moisture levels from each zone
        int moisture1 = read_moisture_sensor(1);
        int moisture2 = read_moisture_sensor(2);
        int moisture3 = read_moisture_sensor(3);
        int moisture4 = read_moisture_sensor(4);

        // Control the relays based on the moisture levels
        if (moisture1 < MOISTURE_THRESHOLD) {
            control_relay(RELAY1_PIN, 0); // Activate relay
        } else {
            control_relay(RELAY1_PIN, 1); // Deactivate relay
        }

        if (moisture2 < MOISTURE_THRESHOLD) {
            control_relay(RELAY2_PIN, 0); // Activate relay
        } else {
            control_relay(RELAY2_PIN, 1); // Deactivate relay
        }

        if (moisture3 < MOISTURE_THRESHOLD) {
            control_relay(RELAY3_PIN, 0); // Activate relay
        } else {
            control_relay(RELAY3_PIN, 1); // Deactivate relay
        }

        if (moisture4 < MOISTURE_THRESHOLD) {
            control_relay(RELAY4_PIN, 0); // Activate relay
        } else {
            control_relay(RELAY4_PIN, 1); // Deactivate relay
        }

        // Log the data
        log_data(1, moisture1, gpioRead(RELAY1_PIN));
        log_data(2, moisture2, gpioRead(RELAY2_PIN));
        log_data(3, moisture3, gpioRead(RELAY3_PIN));
        log_data(4, moisture4, gpioRead(RELAY4_PIN));

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

