#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm (4 meters)
#define TIMEOUT_US 100000      // 100 ms
#define TRIG_PULSE_US 10       // 10 us trigger pulse

// Global variables
static volatile uint32_t rising_edge_tick = 0;
static volatile uint32_t falling_edge_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);
void *sensor_thread(void *arg);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0 && echo_received) {
        falling_edge_tick = tick;
        echo_received = 0; // Reset flag
    }
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    double distance = (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    pthread_mutex_lock(&mutex);
    fprintf(log_file, "%ld,%09ld,%.2f\n", ts.tv_sec, ts.tv_nsec, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    pthread_mutex_unlock(&mutex);
}

// Thread function for sensor reading and logging
void *sensor_thread(void *arg) {
    while (running) {
        trigger_sensor();
        gpioDelay(200000); // 200 ms delay

        pthread_mutex_lock(&mutex);
        uint32_t pulse_width = falling_edge_tick - rising_edge_tick;
        if (pulse_width > 23200) {
            timeout_flag = 1; // Set timeout flag if pulse width exceeds maximum
        }
        pthread_mutex_unlock(&mutex);

        if (timeout_flag) {
            printf("Timeout occurred.\n");
            timeout_flag = 0; // Reset timeout flag
        } else {
            pthread_mutex_lock(&mutex);
            double distance = calculate_distance(pulse_width);
            pthread_mutex_unlock(&mutex);

            if (distance <= MAX_DISTANCE) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                printf("Distance out of range: %.2f cm\n", distance);
            }
        }
    }
    pthread_exit(NULL);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Create sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up
    pthread_join(sensor_thread_id, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);

    return 0;
}

