#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define SENSITIVITY 16384.0 // LSB/g for +/- 2g range
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int configure_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int detect_freefall(double magnitude);
int detect_impact(double magnitude);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH configuration failed\n");
        cleanup();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t accel_data;
    double magnitude;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Detect freefall
            if (detect_freefall(magnitude)) {
                printf("Freefall detected!\n");
            }

            // Detect impact
            if (detect_impact(magnitude)) {
                printf("Impact detected!\n");
                activate_buzzer();
                gpioDelay(1000); // Activate buzzer for 1 second
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure LIS3DH accelerometer
int configure_lis3dh() {
    // Enable accelerometer, 100 Hz data rate, and ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }

    // Set ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return 1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) == 6) { // Enable auto-increment
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries\n", RETRY_COUNT);
    return 1; // Failure
}

// Calculate acceleration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / SENSITIVITY;
    double y_g = (double)y / SENSITIVITY;
    double z_g = (double)z / SENSITIVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect freefall
int detect_freefall(double magnitude) {
    return (magnitude < freefall_threshold);
}

// Detect impact
int detect_impact(double magnitude) {
    return (magnitude > impact_threshold);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO high
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    program_running = 0;
}

// Cleanup function
void cleanup() {
    deactivate_buzzer(); // Ensure buzzer is off
    i2cClose(i2c_handle); // Close I2C connection
    gpioTerminate(); // Terminate pigpio
}

