#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to store sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int read_sensor(int gpio_pin);
void add_to_buffer(SensorReadings reading);
SensorReadings get_latest_readings();
int is_line_detected(SensorReadings reading);
void alert_user();
void move_forward();
void turn_left();
void turn_right();
void stop_robot();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(ALERT_PIN, 0); // Turn off alert
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to add reading to circular buffer
void add_to_buffer(SensorReadings reading) {
    buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to get latest readings from circular buffer
SensorReadings get_latest_readings() {
    if (buffer_count == 0) {
        // Return default values if buffer is empty
        return (SensorReadings){0, 0, 0};
    }
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Get the index of the last element
    return buffer[index];
}

// Function to check if a line is detected
int is_line_detected(SensorReadings reading) {
    return (reading.center == 0);
}

// Function to alert user (turn on LED/buzzer)
void alert_user() {
    gpioWrite(ALERT_PIN, 1); // Turn on alert
    gpioDelay(2000); // Wait for 2 seconds
    gpioWrite(ALERT_PIN, 0); // Turn off alert
}

// Placeholder functions for motor control
void move_forward() {
    printf("Moving forward...\n");
}

void turn_left() {
    printf("Turning left...\n");
}

void turn_right() {
    printf("Turning right...\n");
}

void stop_robot() {
    printf("Stopping robot...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, skipping iteration.\n");
            gpioDelay(10); // Small delay to prevent busy-waiting
            continue;
        }

        // Create sensor readings struct
        SensorReadings reading = {left_value, center_value, right_value};

        // Add reading to buffer
        add_to_buffer(reading);

        // Get latest readings
        SensorReadings latest_readings = get_latest_readings();

        // Check if line is detected
        if (is_line_detected(latest_readings)) {
            move_forward();
        } else if (latest_readings.left == 0) {
            turn_left();
        } else if (latest_readings.right == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        // Check for alert condition
        if (latest_readings.center == 1) {
            int consecutive_no_line_count = 0;
            for (int i = 0; i < buffer_count; i++) {
                int index = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
                if (buffer[index].center == 1) {
                    consecutive_no_line_count++;
                } else {
                    break;
                }
            }

            if (consecutive_no_line_count >= 5) {
                alert_user();
            }
        }

        gpioDelay(10); // Delay for 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0); // Turn off alert
    gpioTerminate(); // Terminate pigpio

    return 0;
}

