#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int initialize_gpio();
int create_socket();
int bind_socket(int socket_fd, int port);
int listen_socket(int socket_fd);
int accept_connection(int socket_fd);
int receive_command(int socket_fd, char *buffer, int buffer_size);
int process_command(const char *command);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

int main() {
    char command[10];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Create socket
    if (create_socket() != 0) {
        fprintf(stderr, "Failed to create socket. Exiting.\n");
        cleanup();
        return 1;
    }

    // Bind socket to port
    if (bind_socket(server_fd, PORT) != 0) {
        fprintf(stderr, "Failed to bind socket. Exiting.\n");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen_socket(server_fd) != 0) {
        fprintf(stderr, "Failed to listen for connections. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    // Main loop
    while (1) {
        // Accept connection
        if (accept_connection(server_fd) != 0) {
            fprintf(stderr, "Failed to accept connection. Continuing.\n");
            continue; // Continue listening for new connections
        }

        // Receive command
        if (receive_command(new_socket, command, sizeof(command)) != 0) {
            fprintf(stderr, "Failed to receive command. Closing connection.\n");
            close(new_socket);
            continue; // Continue listening for new connections
        }

        // Process command
        int relay_state = process_command(command);

        // Control relay
        if (relay_state != -1) {
            if (control_relay(relay_state) != 0) {
                fprintf(stderr, "Failed to control relay. Closing connection.\n");
                close(new_socket);
                continue; // Continue listening for new connections
            }
        } else {
            fprintf(stderr, "Invalid command received. Closing connection.\n");
            log_event("Invalid command received");
            close(new_socket);
            continue; // Continue listening for new connections
        }

        // Close connection
        close(new_socket);
    }

    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Create socket
int create_socket() {
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return 1;
    }
    return 0;
}

// Bind socket to port
int bind_socket(int socket_fd, int port) {
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return 1;
    }
    return 0;
}

// Listen for connections
int listen_socket(int socket_fd) {
    if (listen(socket_fd, 3) < 0) {
        perror("listen");
        return 1;
    }
    return 0;
}

// Accept connection
int accept_connection(int socket_fd) {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    if ((new_socket = accept(socket_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        return 1;
    }
    return 0;
}

// Receive command from client
int receive_command(int socket_fd, char *buffer, int buffer_size) {
    memset(buffer, 0, buffer_size);
    ssize_t bytes_received = recv(socket_fd, buffer, buffer_size - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        return 1;
    }
    buffer[bytes_received] = '\0'; // Null-terminate the received data
    return 0;
}

// Process command
int process_command(const char *command) {
    if (strcasecmp(command, "ON") == 0) {
        return 1; // Turn relay ON
    } else if (strcasecmp(command, "OFF") == 0) {
        return 0; // Turn relay OFF
    } else {
        return -1; // Invalid command
    }
}

// Control relay
int control_relay(int state) {
    gpioWrite(GPIO_PIN, state);
    if (state == 1) {
        log_event("Relay ON");
    } else {
        log_event("Relay OFF");
    }
    return 0;
}

// Log event to file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup resources
void cleanup() {
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
}

