#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define POLLING_INTERVAL_MS 100
#define START_MEASUREMENT_CMD_1 0x36
#define START_MEASUREMENT_CMD_2 0x08
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c_device(int handle, uint8_t *data, int count);
int read_i2c_device(int handle, uint8_t *data, int count);
int send_start_measurement_command(int handle);
int read_flow_rate(int handle, float *flow_rate);
float convert_raw_to_ml_min(int16_t raw_value);
int validate_crc8(uint8_t *data, int count);
int control_relay(int gpio, int state);
int log_flow_rates(float flow_rate1, float flow_rate2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Send start measurement command to both sensors
    if (send_start_measurement_command(i2c_handle1) != 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    if (send_start_measurement_command(i2c_handle2) != 0) {
        fprintf(stderr, "Failed to send start measurement command to sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure relay GPIO as output
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output. Exiting.\n", RELAY_GPIO);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float flow_rate1 = -1.0; // Initialize to an invalid value
        float flow_rate2 = -1.0;

        // Read flow rate from sensor 1
        if (read_flow_rate(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Failed to read flow rate from sensor 1.\n");
        }

        // Read flow rate from sensor 2
        if (read_flow_rate(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Failed to read flow rate from sensor 2.\n");
        }

        // Control relay based on flow rates
        if (flow_rate1 >= 0.0 && flow_rate2 >= 0.0) {
            if (flow_rate1 < FLOW_THRESHOLD || flow_rate2 < FLOW_THRESHOLD) {
                if (control_relay(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "Failed to energize relay.\n");
                }
            } else {
                if (control_relay(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Failed to de-energize relay.\n");
                }
            }
        }

        // Log flow rates
        if (flow_rate1 >= 0.0 || flow_rate2 >= 0.0) {
            if (log_flow_rates(flow_rate1, flow_rate2) != 0) {
                fprintf(stderr, "Failed to log flow rates.\n");
            }
        }

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Write data to I2C device
int write_i2c_device(int handle, uint8_t *data, int count) {
    int result = i2cWriteDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c_device(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Send start measurement command to sensor
int send_start_measurement_command(int handle) {
    uint8_t cmd[2] = {START_MEASUREMENT_CMD_1, START_MEASUREMENT_CMD_2};
    return write_i2c_device(handle, cmd, 2);
}

// Read flow rate from sensor
int read_flow_rate(int handle, float *flow_rate) {
    uint8_t data[3];

    if (read_i2c_device(handle, data, 3) != 0) {
        return 1;
    }

    // Combine the two data bytes into a 16-bit signed integer
    int16_t raw_value = (int16_t)((data[0] << 8) | data[1]);

    // Validate CRC-8
    if (validate_crc8(data, 2) != 0) {
        fprintf(stderr, "CRC-8 validation failed.\n");
        return 1;
    }

    // Convert raw value to ml/min
    *flow_rate = convert_raw_to_ml_min(raw_value);

    return 0;
}

// Convert raw value to ml/min
float convert_raw_to_ml_min(int16_t raw_value) {
    return (float)raw_value / 1500.0;
}

// Validate CRC-8 checksum
int validate_crc8(uint8_t *data, int count) {
    return crc8(data, count) != data[2];
}

// Control relay state
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d.\n", gpio);
        return 1;
    }
    return 0;
}

// Log flow rates to file
int log_flow_rates(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open flow_log.txt for writing.\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", timestamp, flow_rate1, flow_rate2);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // De-energize relay
    control_relay(RELAY_GPIO, 0);

    // Close I2C devices
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Terminate pigpio
    gpioTerminate();
}

