#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5
#define DRY_THRESHOLD_MS 600

// Global variables
volatile sig_atomic_t program_running = 1;
int dry_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    stop_motor(); // Ensure motor is stopped on startup

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Close the window
void close_window() {
    log_message(LOG_INFO, "Closing window...");

    if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN HIGH");
        return;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN HIGH");
        gpioWrite(MOTOR_ENA_PIN, 0);
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        return;
    }

    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Run for MOTOR_RUN_TIME_S seconds

    stop_motor();

    log_message(LOG_INFO, "Window closed");
}

// Stop the motor
void stop_motor() {
    log_message(LOG_INFO, "Stopping motor...");

    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN LOW");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN LOW");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
    }

    log_message(LOG_INFO, "Motor stopped");
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);

    syslog(priority, "%s", log_entry);
    printf("%s\n", log_entry); // Also print to console
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain-actuated window controller started");

    int last_rain_state = 1; // Assume initially dry

    while (program_running) {
        int rain_state = read_rain_sensor();

        if (rain_state == 0 && last_rain_state == 1) {
            // Rising edge detected (dry to wet)
            log_message(LOG_INFO, "Rain detected, initiating window close sequence");
            close_window();
            dry_count = 0; // Reset dry count
        } else if (rain_state == 1 && last_rain_state == 0) {
            // Falling edge detected (wet to dry)
            log_message(LOG_INFO, "Rain stopped");
        }

        last_rain_state = rain_state;

        if (rain_state == 1) {
            dry_count++;
            if (dry_count >= 3) {
                // Rain has stopped for at least 3 consecutive polls
                log_message(LOG_INFO, "Rain stopped for sufficient duration, suppressing triggers");
                dry_count = 3; // Prevent further suppression
            }
        } else {
            dry_count = 0; // Reset dry count if rain is detected
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every POLL_INTERVAL_MS milliseconds
    }

    // Stop the motor and terminate pigpio
    stop_motor();
    gpioTerminate();

    log_message(LOG_INFO, "Rain-actuated window controller stopped");
    closelog();

    return 0;
}

