typedef struct {
    int lock_pressed;
    int unlock_pressed;
} ButtonStates;

ButtonStates button_states = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Set up button callbacks with debouncing
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetAlertFuncEx(LOCK_BUTTON_PIN, button_callback, NULL);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetAlertFuncEx(UNLOCK_BUTTON_PIN, button_callback, NULL);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library and set servo pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    return 0;
}

// Set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width to %d\n", pulse_width);
    }
}

// Lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_pulse_width(LOCKED_PULSE_WIDTH);
    gpioDelay(1000); // Keep locked for 1 second
    set_servo_pulse_width(0); // Stop the servo
    printf("Door locked.\n");
}

// Unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_pulse_width(UNLOCKED_PULSE_WIDTH);
    gpioDelay(1000); // Keep unlocked for 1 second
    set_servo_pulse_width(0); // Stop the servo
    printf("Door unlocked.\n");
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (gpio == LOCK_BUTTON_PIN) {
        if (level == 0 && !button_states.lock_pressed) { // Button pressed (low signal)
            lock_door();
            button_states.lock_pressed = 1;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (level == 1) {
            button_states.lock_pressed = 0;
        }
    } else if (gpio == UNLOCK_BUTTON_PIN) {
        if (level == 0 && !button_states.unlock_pressed) { // Button pressed (low signal)
            unlock_door();
            button_states.unlock_pressed = 1;
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (level == 1) {
            button_states.unlock_pressed = 0;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

// Cleanup function to stop the servo and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    set_servo_pulse_width(0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

