#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event_type, double duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int pir_state;
    time_t floodlight_start_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && state.pir_state == 0) {
            // Motion detected
            printf("Motion detected!\n");
            activate_floodlight();
            state.pir_state = 1;
            state.floodlight_start_time = time(NULL);
        } else if (pir_value == 0 && state.pir_state == 1) {
            // Motion stopped
            printf("Motion stopped.\n");
            time_t current_time = time(NULL);
            double duration = difftime(current_time, state.floodlight_start_time);
            deactivate_floodlight();
            log_event("Deactivation", duration);
            state.pir_state = 0;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Security Light System stopped.\n");
    return 0;
}

// Initialize pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    return 0;
}

// Read the PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Activate the floodlight for 60 seconds
void activate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 1); // Turn on the floodlight
    log_event("Activation", 0.0); // Log activation event
    gpioDelay(60000); // Wait for 60 seconds
    gpioWrite(FLOODLIGHT_PIN, 0); // Turn off the floodlight
}

// Deactivate the floodlight
void deactivate_floodlight() {
    gpioWrite(FLOODLIGHT_PIN, 0); // Turn off the floodlight
}

// Log an event to the log file
void log_event(const char *event_type, double duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s", timestamp, event_type);
        if (duration > 0) {
            fprintf(log_file, " - Duration: %.2f seconds\n", duration);
        } else {
            fprintf(log_file, "\n");
        }
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_floodlight(); // Ensure floodlight is off

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio
}

