#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 40
#define RELEASE_THRESHOLD 20
#define DEBOUNCE_TIME 200 // milliseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) return -1; // MHD_R
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) return -1; // NHD_R
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) return -1; // NCL_R
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x00) < 0) return -1; // FDL_R

    if (i2cWriteByteData(i2c_handle, 0x60, 0x01) < 0) return -1; // MHD_T
    if (i2cWriteByteData(i2c_handle, 0x61, 0x01) < 0) return -1; // NHD_T
    if (i2cWriteByteData(i2c_handle, 0x62, 0x00) < 0) return -1; // NCL_T
    if (i2cWriteByteData(i2c_handle, 0x63, 0x00) < 0) return -1; // FDL_T

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x05) < 0) return -1; // Debounce

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) return -1; // FFI
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) return -1; // SFI
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) return -1; // CDT

    // Set auto-config
    if (i2cWriteByteData(i2c_handle, 0x7B, 0x01) < 0) return -1; // USL
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x00) < 0) return -1; // LSL
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x00) < 0) return -1; // Target

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Enable all 12 electrodes

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_level = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_level);
    printf("Relay toggled to %d\n", !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0;
    int relay_state = 0; // 0 = OFF, 1 = ON
    uint32_t last_touch_time = 0;

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched
