#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <gpiod.h>
#include <stdarg.h>

// Configuration
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)
#define SERVO_MIN_PULSE_WIDTH_NS 1000 // 1 ms
#define SERVO_MAX_PULSE_WIDTH_NS 2000 // 2 ms
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define LOG_FILE "security.log"

// Global variables
static int server_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
void *pwm_thread(void *arg);
int set_servo_angle(int angle);
int read_pir_sensor();
void handle_client(int client_fd);
void signal_handler(int sig);
int initialize_gpio();
void cleanup_gpio();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    // Log to syslog
    syslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        fprintf(log_file, "%s: ", buf);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// PWM thread function
void *pwm_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    struct timespec on_time, off_time;
    int angle = 90; // Initial angle
    set_servo_angle(angle);

    while (!terminate) {
        // Calculate pulse width based on angle
        int pulse_width = SERVO_MIN_PULSE_WIDTH_NS + (int)(((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH_NS - SERVO_MIN_PULSE_WIDTH_NS));

        // Calculate on and off times
        on_time.tv_sec = 0;
        on_time.tv_nsec = pulse_width;
        off_time.tv_sec = 0;
        off_time.tv_nsec = PWM_PERIOD_NS - pulse_width;

        // Toggle GPIO line
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_message(LOG_ERR, "Failed to set servo line high: %s", strerror(errno));
            terminate = 1; // Exit thread on error
            break;
        }
        nanosleep(&on_time, NULL);

        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_message(LOG_ERR, "Failed to set servo line low: %s", strerror(errno));
            terminate = 1; // Exit thread on error
            break;
        }
        nanosleep(&off_time, NULL);
    }

    pthread_exit(NULL);
}

// Set servo angle function
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH_NS + (int)(((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH_NS - SERVO_MIN_PULSE_WIDTH_NS));

    // Calculate on and off times
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = pulse_width;
    off_time.tv_sec = 0;
    off_time.tv_nsec = PWM_PERIOD_NS - pulse_width;

    // Toggle GPIO line
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo line high: %s", strerror(errno));
        return -1;
    }
    nanosleep(&on_time, NULL);

    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo line low: %s", strerror(errno));
        return -1;
    }
    nanosleep(&off_time, NULL);

    log_message(LOG_INFO, "Servo angle set to: %d", angle);
    return 0;
}

// Read PIR sensor function
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Handle client function
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);

        char *token = strtok(buffer, " ");
        if (token != NULL) {
            if (strcmp(token, "SERVO") == 0) {
                token = strtok(NULL, " ");
                if (token != NULL) {
                    int angle = atoi(token);
                    if (set_servo_angle(angle) != 0) {
                        send(client_fd, "Error setting servo angle\n", strlen("Error setting servo angle\n"), 0);
                    }
                } else {
                    send(client_fd, "Invalid servo command\n", strlen("Invalid servo command\n"), 0);
                }
            } else if (strcmp(token, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[20];
                    snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                    send(client_fd, response, strlen(response), 0);
                } else {
                    send(client_fd, "Error reading PIR sensor\n", strlen("Error reading PIR sensor\n"), 0);
                }
            } else {
                send(client_fd, "Invalid command\n", strlen("Invalid command\n"), 0);
            }
        }
    }

    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (bytes_received < 0) {
        log_message(LOG_ERR, "Receive failed: %s", strerror(errno));
    }

    close(client_fd);
}

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d", sig);
    terminate = 1;
}

// Initialize GPIO function
int initialize_gpio() {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Get servo line
    servo_line = gpiod_chip_get_line(gpio_chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request servo line for output
    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line for output: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get PIR line
    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request PIR line for input
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line for input: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create PWM thread
    pthread_t pwm_thread_id;
    if (pthread_create(&pwm_thread_id, NULL, pwm_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Server listening on port %d", PORT);

    // Accept connections and handle clients
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_fd;
        int addrlen = sizeof(client_address);

        client_fd = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_fd < 0) {
            if (!terminate) { // Only log if not terminating due to signal
                log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            }
            continue; // Continue listening for other connections
        }

        log_message(LOG_INFO, "Client connected from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_fd);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    pthread_cancel(pwm_thread_id);
    pthread_join(pwm_thread_id, NULL);
    cleanup_gpio();
    close(server_fd);
    fclose(log_file);
    closelog();

    return 0;
}

