                        send(client_fd, "Error setting servo angle\n", strlen("Error setting servo angle\n"), 0);
                    }
                } else {
                    send(client_fd, "Invalid servo command\n", strlen("Invalid servo command\n"), 0);
                }
            } else if (strcmp(token, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[20];
                    snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                    send(client_fd, response, strlen(response), 0);
                } else {
                    send(client_fd, "Error reading PIR sensor\n", strlen("Error reading PIR sensor\n"), 0);
                }
            } else {
                send(client_fd, "Invalid command\n", strlen("Invalid command\n"), 0);
            }
        }
    }

    if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (bytes_received < 0) {
        log_message(LOG_ERR, "Receive failed: %s", strerror(errno));
    }

    close(client_fd);
}

// Signal handler function
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d", sig);
    terminate = 1;
}

// Initialize GPIO function
int initialize_gpio() {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Get servo line
    servo_line = gpiod_chip_get_line(gpio_chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request servo line for output
    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line for output: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get PIR line
    pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request PIR line for input
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line for input: %s", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio() {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create PWM thread
    pthread_t pwm_thread_id;
    if (pthread_create(&pwm_thread_id, NULL, pwm_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        pthread_cancel(pwm_thread_id);
        pthread_join(pwm_thread_id, NULL);
        cleanup_gpio();
        close(server_fd);
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Server listening on port %d", PORT);

    // Accept connections and handle clients
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_fd;
        int addrlen = sizeof(client_address);

        client_fd = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_fd < 0) {
            if (!terminate) { // Only log if not terminating due to signal
                log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            }
            continue; // Continue listening for other connections
        }

        log_message(LOG_INFO, "Client connected from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(client_fd);
    }

    // Cleanup
    log_message(LOG_INFO, "Cleaning up...");
    pthread_cancel(pwm_thread_id);
    pthread_join(pwm_thread_id, NULL);
    cleanup_gpio();
    close(server_fd);
    fclose(log_file);
    closelog();

    return 0;
}

