#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define SLEEP_DURATION_SEC 2
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_gpio();
int init_log();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO pin for relay control
int init_gpio() {
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);
    gpioWrite(GROW_LIGHT_GPIO, 0); // Initially off
    return 0;
}

// Initialize log file
int init_log() {
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE) != 0) {
            fprintf(stderr, "Failed to write to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(180); // Wait for measurement (at least 180ms)

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        uint16_t raw_value = (buf[0] << 8) | buf[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Control the relay (1 = on, 0 = off)
int control_relay(int state) {
    gpioWrite(GROW_LIGHT_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Turn off relay
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_pigpio() != 0) return 1;
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    printf("Grow light ON\n");
                } else {
                    fprintf(stderr, "Failed to turn on relay\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    printf("Grow light OFF\n");
                } else {
                    fprintf(stderr, "Failed to turn off relay\n");
                }
            }

            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(SLEEP_DURATION_SEC * 1000); // Sleep for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

