#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 100.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int chip_id = 0; // Default I2C chip ID

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double tare_offset, double scale);
void control_solenoid(int state);
void signal_handler(int signal);
int tare_load_cell(int num_readings, double *tare_offset);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;
    int timeout = 1000; // Timeout in milliseconds

    // Wait for DOUT to go LOW (data ready)
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT to go LOW");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, double tare_offset, double scale) {
    return (raw_value - tare_offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
    syslog(LOG_INFO, "Solenoid set to %d", state);
}

// Function to tare the load cell
int tare_load_cell(int num_readings, double *tare_offset) {
    int i;
    int sum = 0;
    int raw_value;

    syslog(LOG_INFO, "Taring load cell...");

    for (i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading HX711 during tare");
            return -1; // Indicate tare failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    *tare_offset = (double)sum / num_readings;
    syslog(LOG_INFO, "Tare offset: %f", *tare_offset);
    return 0; // Indicate tare success
}

int main(int argc, char *argv[]) {
    int opt;
    int i;
    int raw_value;
    double weight;
    double tare_offset = 0.0;
    int retry_count;
    int hx711_retries = 3; // Number of retries for HX711 read

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:c:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'c':
                chip_id = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-c chip_id]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    syslog(LOG_INFO, "Starting weight monitoring...");
    syslog(LOG_INFO, "Threshold: %f grams, Scale: %f, Duration: %d ms, Chip ID: %d", threshold, scale, duration, chip_id);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid to LOW initially
    control_solenoid(0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    if (tare_load_cell(10, &tare_offset) != 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        retry_count = 0;
        raw_value = -1; // Initialize to an invalid value

        // Read HX711 with retries
        while (retry_count < hx711_retries) {
            raw_value = read_hx711();
            if (raw_value != -1) {
                break; // Success, exit retry loop
            }
            syslog(LOG_WARNING, "HX711 read failed, retry %d/%d", retry_count + 1, hx711_retries);
            retry_count++;
            gpioDelay(10); // Small delay before retrying
        }

        if (raw_value == -1) {
            syslog(LOG_ERR, "HX711 read failed after multiple retries, skipping this cycle");
            gpioDelay(500); // Wait 500ms before next cycle
            continue;
        }

        // Calculate weight
        weight = calculate_weight(raw_value, tare_offset, scale);

        // Log weight
        syslog(LOG_INFO, "Raw: %d, Weight: %f grams", raw_value, weight);

        // Check if weight exceeds threshold
        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(1); // Activate solenoid
            gpioDelay(duration); // Keep solenoid activated for specified duration
            control_solenoid(0); // Deactivate solenoid
        }

        gpioDelay(500); // Wait 500ms before next cycle
    }

    // Cleanup (should not reach here if signal handler works correctly)
