#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define GPIO_PIN 17
#define GPIO_MODE PI_OUTPUT
#define GPIO_ON 1
#define GPIO_OFF 0
#define RETRY_DELAY 5 // seconds

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signum);
int init_gpio(void);
int init_mqtt(void);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void log_mqtt_event(const char *message);
void log_gpio_event(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO using pigpio
int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, GPIO_MODE);
    gpioWrite(GPIO_PIN, GPIO_OFF); // Initialize relay to OFF
    log_gpio_event("GPIO initialized and relay OFF");
    return 0;
}

// Initialize MQTT client
int init_mqtt(void) {
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    log_mqtt_event("Connected to MQTT broker");
    return 0;
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, GPIO_ON);
            log_gpio_event("Relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, GPIO_OFF);
            log_gpio_event("Relay OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_WARNING, "Empty payload received on topic %s", message->topic);
    }
}

// MQTT connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        } else {
            log_mqtt_event("Subscribed to topic");
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        syslog(LOG_WARNING, "MQTT disconnected unexpectedly with code %d", rc);
    } else {
        log_mqtt_event("Disconnected from MQTT broker");
    }
}

// Log MQTT events to syslog
void log_mqtt_event(const char *message) {
    syslog(LOG_INFO, "MQTT: %s", message);
}

// Log GPIO events to syslog
void log_gpio_event(const char *message) {
    syslog(LOG_INFO, "GPIO: %s", message);
}

int main(void) {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, -1, 1); // -1 for blocking, 1 max messages processed
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s, reconnecting...", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            sleep(RETRY_DELAY);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, GPIO_OFF); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

