#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 17

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define MOTOR_B_PWM 22

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// PI Controller Gains
#define KP 0.5
#define KI 0.05

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Stall Detection Threshold
#define STALL_THRESHOLD 2 // 2 seconds

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int last_encoder_a_count = 0;
volatile int last_encoder_b_count = 0;
volatile unsigned long last_stall_time_a = 0;
volatile unsigned long last_stall_time_b = 0;
volatile int stall_detected_a = 0;
volatile int stall_detected_b = 0;

// Function Prototypes
void encoder_a_isr(int gpio, int level, unsigned int tick, void *user);
void encoder_b_isr(int gpio, int level, unsigned int tick, void *user);
double calculate_rpm(int encoder_count);
double calculate_error(double target_rpm, double actual_rpm);
double calculate_integral(double error, double dt, double *integral);
double calculate_output(double error, double integral, double kp, double ki);
void set_motor_speed(int motor_pwm, int direction_pin, double pwm_duty_cycle);
void stop_motors();
void signal_handler(int signal);

// Encoder ISR for Motor A
void encoder_a_isr(int gpio, int level, unsigned int tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    if (gpioRead(ENCODER_A_A) == gpioRead(ENCODER_A_B)) {
        encoder_a_count++;
    } else {
        encoder_a_count--;
    }
}

// Encoder ISR for Motor B
void encoder_b_isr(int gpio, int level, unsigned int tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    if (gpioRead(ENCODER_B_A) == gpioRead(ENCODER_B_B)) {
        encoder_b_count++;
    } else {
        encoder_b_count--;
    }
}

// Calculate RPM
double calculate_rpm(int encoder_count) {
    // Assuming 64 ticks per revolution and 1:1 encoder-to-output-shaft ratio
    return (double)encoder_count * 60.0 / 64.0;
}

// Calculate Error
double calculate_error(double target_rpm, double actual_rpm) {
    return target_rpm - actual_rpm;
}

// Calculate Integral
double calculate_integral(double error, double dt, double *integral) {
    *integral += error * dt;
    return *integral;
}

// Calculate Output
double calculate_output(double error, double integral, double kp, double ki) {
    return kp * error + ki * integral;
}

// Set Motor Speed
