// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        // Turn off the relay
        gpioWrite(RELAY_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        printf("pigpio terminated. Exiting.\n");
        exit(0);
    }
}

// Initializes the pigpio library and sets GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Reads the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounces the touch sensor input
int debounce_touch() {
    int i;
    for (i = 0; i < 5; i++) {
        if (read_touch_sensor() == 0) {
            return 0; // Not touched
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }
    return 1; // Touched
}

// Toggles the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Logs the relay state with an ISO-8601 timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    int last_touch_state = 0; // 0 = not touched, 1 = touched

    while (1) {
        int current_touch_state = debounce_touch();

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Touch detected (rising edge)
            toggle_relay();
            log_relay_state(relay_state);

            // Wait for touch release
            while (read_touch_sensor() == 1) {
                gpioDelay(10000); // 10ms delay
            }
            last_touch_state = 0;
        } else if (current_touch_state == 0 && last_touch_state == 1) {
            last_touch_state = 0;
        } else if (current_touch_state == 1 && last_touch_state == 1) {
            last_touch_state = 1;
        }

        gpioDelay(10000); // 10ms delay
    }

    return 0;
}

