#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define flow rate thresholds (LPM)
#define FLOW_RATE_THRESHOLD_HIGH 5.0
#define FLOW_RATE_THRESHOLD_LOW 4.5

// Define pulse count per liter
#define PULSES_PER_LITER 450.0

// Define debounce time in microseconds
#define DEBOUNCE_TIME 1000000 // 1 second

// Define log file name
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int solenoid_state = 1; // 1 = open, 0 = closed

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_lpm(int pulses);
void control_solenoid(float lpm);
void log_data(float lpm, int solenoid_state);
void signal_handler(int signal);

// Function to handle flow sensor interrupt
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_TIME) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = current_tick;
    }
}

// Function to calculate LPM from pulse count
float calculate_lpm(int pulses) {
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(float lpm) {
    if (lpm > FLOW_RATE_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0); // Close the solenoid
        solenoid_state = 0;
        log_data(-1.0, solenoid_state); // Log the event
    } else if (lpm < FLOW_RATE_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1); // Open the solenoid
        solenoid_state = 1;
        log_data(-1.0, solenoid_state); // Log the event
    }
}

// Function to log data to file
void log_data(float lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (lpm >= 0) {
            fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "Open" : "Closed");
        } else {
            fprintf(log_file, "%s, Solenoid State Changed: %s\n", timestamp, solenoid_state ? "Open" : "Closed");
        }
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_data(-1.0, solenoid_state); // Log the event

    // Reopen the solenoid to its safe state
    gpioWrite(SOLENOID_PIN, 1);
    solenoid_state = 1;

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", SOLENOID_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", FLOW_SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Main loop
    while (1) {
        // Sample pulse count every 1 second
        gpioDelay(1000000); // 1 second

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        float lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, solenoid_state);
    }

    return 0;
}

