// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// HX711 read function
int read_hx711() {
    int data = 0;
    int attempts = 0;

    // Wait for DATA pin to go low (sensor ready)
    while (gpioRead(hx711_data_pin) == 1 && attempts < 1000) {
        attempts++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (attempts >= 1000) {
        fprintf(stderr, "Error: HX711 not ready after 1000 attempts.\n");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_pin, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(hx711_data_pin)) {
            data++;
        }
        gpioWrite(hx711_sck_pin, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(hx711_sck_pin, 1);
    gpioDelay(1); // Clock pulse width
    gpioWrite(hx711_sck_pin, 0);
    gpioDelay(1); // Clock pulse width

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calibration function
double calibrate_hx711(double known_weight) {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read HX711 during calibration.\n");
        return 0.0; // Return 0.0 as calibration factor
    }
    return (double)raw_value / known_weight;
}

// Dispense ingredient function
int dispense_ingredient(double target_weight) {
    double calibration_factor = config.calibration_factor;
    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read HX711 during dispense.\n");
        return -1;
    }

    double actual_weight = (double)raw_value / calibration_factor;

    // Map target weight to servo pulse width (1000-2000 us)
    int pulse_width = (int)(1000 + (target_weight / actual_weight) * 1000);

    // Clamp pulse width to valid range
    if (pulse_width < 1000) {
        pulse_width = 1000;
    } else if (pulse_width > 2000) {
        pulse_width = 2000;
    }

    // Set servo pulse width
    gpioServo(servo_pin, pulse_width);

    // Wait for servo to reach position (adjust as needed)
    gpioDelay(1000); // 1 second

    return 0;
}

// Send weight to server function
int send_weight_to_server(double weight) {
    struct sockaddr_in server_addr;
    char buffer[256];
    int bytes_sent;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(config.server_port);
    if (inet_pton(AF_INET, config.server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(socket_desc);
        return -1;
    }

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connect failed");
        close(socket_desc);
        return -1;
    }

    // Send weight to server
    snprintf(buffer, sizeof(buffer), "%.2f", weight);
    bytes_sent = send(socket_desc, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        perror("Send failed");
        close(socket_desc);
        return -1;
    }

    close(socket_desc);
    return 0;
}

// Receive weight from server function
int receive_weight_from_server() {
    struct sockaddr_in server_addr, client_addr;
    int client_sock, bytes_received;
    char buffer[256];

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(config.server_port);

    // Bind
    if (bind(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(socket_desc);
        return -1;
    }

    // Listen
    listen(socket_desc, 3);

    // Accept incoming connection
    puts("Waiting for incoming connections...");
    int c = sizeof(struct sockaddr_in);
    client_sock = accept(socket_desc, (struct sockaddr *)&client_addr, (socklen_t*)&c);
    if (client_sock < 0) {
        perror("Accept failed");
        close(socket_desc);
        return -1;
    }

    puts("Connection accepted");

    // Receive a message from client
    bytes_received = recv(client_sock, buffer, 256, 0);
    if (bytes_received < 0) {
        perror("Receive failed");
        close(client_sock);
        close(socket_desc);
        return -1;
    }

    buffer[bytes_received] = '\0';
    printf("Received weight: %s\n", buffer);

    close(client_sock);
    close(socket_desc);

    return atoi(buffer);
}

