#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce delay in milliseconds
#define DEFAULT_DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static int relay_state = 0; // 0 = OFF, 1 = ON
static int debounce_delay = DEFAULT_DEBOUNCE_DELAY;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch(int delay_ms);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch(int delay_ms) {
    int stable_level = read_touch_sensor();
    gpioDelay(delay_ms * 1000); // Convert milliseconds to microseconds
    return (read_touch_sensor() == stable_level) ? stable_level : -1; // Return -1 if unstable
}

// Function to toggle the relay
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1;
    }
    return 0;
}

// Function to log the relay state
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    // Turn the relay OFF
    gpioWrite(RELAY_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        long delay = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || delay <= 0) {
            fprintf(stderr, "Invalid debounce delay. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_DELAY);
            debounce_delay = DEFAULT_DEBOUNCE_DELAY;
        } else {
            debounce_delay = (int)delay;
        }
    }

    printf("Using debounce delay: %d ms\n", debounce_delay);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled desk lamp started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = (read_touch_sensor() == 0); // TTP223 is active low

        if (touch_detected) {
            int stable_level = debounce_touch(debounce_delay);
            if (stable_level == 0) { // Valid touch (LOW after debounce)
                if (toggle_relay() == 0) {
                    log_relay_state(relay_state);
                } else {
                    fprintf(stderr, "Failed to toggle relay\n");
                }
            } else if (stable_level == -1) {
                //printf("Unstable touch detected\n");
            } else {
                //printf("Touch released\n");
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

