#include <pigpio.h>

#define SERVO_GPIO 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_ANGLE 90

volatile sig_atomic_t terminate = 0;
struct termios old_termios;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int angle = DEFAULT_ANGLE;
    int pulse_width;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(SERVO_GPIO, 50);

    // Set PWM range (optional, but good practice)
    gpioSetPWMrange(SERVO_GPIO, 20000); // Range for 20 ms period (50 Hz)

    // Calculate initial pulse width
    pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set initial pulse width
    result = gpioServo(SERVO_GPIO, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Failed to set initial pulse width: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Save terminal settings
    if (tcgetattr(STDIN_FILENO, &old_termios) == -1) {
        perror("tcgetattr");
        gpioTerminate();
        return 1;
    }

    // Configure terminal for non-blocking input
    struct termios new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 0;  // Read non-blocking
    new_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) == -1) {
        perror("tcsetattr");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control.  Angle: %d, Pulse Width: %d\n", angle, pulse_width);
    printf("Use '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    // Main loop
    while (!terminate) {
        int ch = getchar();

        if (ch == '+') {
            angle += 10;
            if (angle > 180) {
                angle = 180;
            }
            pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
            result = gpioServo(SERVO_GPIO, pulse_width);
            if (result != 0) {
                fprintf(stderr, "Failed to set pulse width: %d\n", result);
            }
            printf("Angle: %d, Pulse Width: %d\n", angle, pulse_width);
        } else if (ch == '-') {
            angle -= 10;
            if (angle < 0) {
                angle = 0;
            }
            pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
            result = gpioServo(SERVO_GPIO, pulse_width);
            if (result != 0) {
                fprintf(stderr, "Failed to set pulse width: %d\n", result);
            }
            printf("Angle: %d, Pulse Width: %d\n", angle, pulse_width);
        } else if (ch == 'q') {
            break;
        } else if (ch == 27) {
            // Handle escape sequences (e.g., arrow keys)
            // This is a placeholder, actual handling depends on the terminal
            // and the specific escape sequence.
            // For example, you might need to read more characters to determine
            // the exact key pressed.
            printf("Escape sequence detected.  Ignoring.\n");
        } else if (ch != -1) {
            // Ignore other characters
            printf("Invalid input. Use '+', '-', or 'q'.\n");
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10 ms
    }

    // Stop PWM pulses
    gpioServo(SERVO_GPIO, 0);

    // Restore terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &old_termios) == -1) {
        perror("tcsetattr");
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Servo control terminated.\n");
    return 0;
}

