#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_SEC 5

static volatile int pulseCount = 0;
static FILE *logFile = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulseCounter(int gpio, int level, uint32_t tick, void *user);
void signalHandler(int signal);
char* getISO8601Timestamp();

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Callback function for pulse counting
void pulseCounter(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t lastTick = 0;
    uint32_t diff = tick - lastTick;

    if (diff > DEBOUNCE_MS * 1000) { // Debounce
        pulseCount++;
        lastTick = tick;
    }
}

// Function to get ISO 8601 timestamp
char* getISO8601Timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Enable pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulseCounter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    logFile = fopen("motor_rpm.log", "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Monitoring motor RPM... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sleep(SAMPLE_INTERVAL_SEC);

        // Calculate RPM
        double rpm = (double)pulseCount / SAMPLE_INTERVAL_SEC * 60.0;

        // Get timestamp
        char *timestamp = getISO8601Timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            continue; // Skip logging if timestamp fails
        }

        // Log data to file
        fprintf(logFile, "%s,%.2f\n", timestamp, rpm);
        fflush(logFile); // Flush the buffer to ensure data is written to the file

        // Print RPM to console
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulseCount = 0;

        free(timestamp); // Free the allocated memory
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt handler
    gpioTerminate(); // Terminate pigpio
    if (logFile != NULL) {
        fclose(logFile); // Close log file
    }

    printf("Exiting.\n");
    return 0;
}

