#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define TOUCH_THRESHOLD 10 // seconds
#define POLLING_INTERVAL 50 // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t touch_start_time = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void failsafe_check();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read the touch sensor value
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_PIN);
        return 0; // Return 0 to avoid triggering a toggle on error
    }
    return sensor_value;
}

// Toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

// Failsafe check
void failsafe_check() {
    time_t current_time = time(NULL);
    if (read_touch_sensor() == 1) {
        if (touch_start_time == 0) {
            touch_start_time = current_time;
        }
        if (difftime(current_time, touch_start_time) >= TOUCH_THRESHOLD) {
            printf("Failsafe triggered: Touch sensor continuously HIGH for %d seconds. Turning relay OFF.\n", TOUCH_THRESHOLD);
            gpioWrite(RELAY_PIN, 0); // Turn relay OFF
            relay_state = 0;
            touch_start_time = 0; // Reset touch start time
        }
    } else {
        touch_start_time = 0; // Reset touch start time if sensor is not HIGH
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            gpioDelay(200); // Debounce delay
        }
        failsafe_check();
        gpioDelay(POLLING_INTERVAL); // Polling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

