#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PULSES_PER_LITER 450.0
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define Kp 1.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static double target_flow_rate = 0.0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
double calculate_flow_rate(int pulses);
int set_valve_position(double flow_rate, double target_flow_rate);
void log_data(double flow_rate, int valve_position);
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60000.0 / SAMPLE_INTERVAL_MS; // pulses/L * 60000ms/min / sample_interval_ms
}

// Function to set valve position using PWM
int set_valve_position(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double pwm_duty_cycle = Kp * error;

