#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PID gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Sample time (ms)
#define SAMPLE_TIME 100

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
double last_error1 = 0.0;
double last_error2 = 0.0;
double integral1 = 0.0;
double integral2 = 0.0;
FILE *log_file = NULL;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void encoder1_callback(int gpio, int level, uint32_t tick, void *user);
void encoder2_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pid_control(double target_rpm, double current_rpm, double *last_error, double *integral);
void set_motor_speed(int motor_ena, int motor_in1, int motor_in2, double duty_cycle);
void log_data(double rpm1, double rpm2, double pid_output1, double pid_output2, double p1, double i1, double d1, double p2, double i2, double d2);
void signal_handler(int signal);
void *encoder_thread(void *arg);

// Encoder callback function for Motor 1
void encoder1_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count++;
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder callback function for Motor 2
void encoder2_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder2_mutex);
    encoder2_count++;
    pthread_mutex_unlock(&encoder2_mutex);
}

// Function to calculate RPM
double calculate_rpm(int encoder_count) {
    // Assuming 600 pulses per revolution
    return (double)encoder_count * 60.0 / (600.0 * (SAMPLE_TIME / 1000.0));
}

// PID control function
double pid_control(double target_rpm, double current_rpm, double *last_error, double *integral) {
    double error = target_rpm - current_rpm;
    *integral += error * (SAMPLE_TIME / 1000.0);
    double derivative = (error - *last_error) / (SAMPLE_TIME / 1000.0);
    double output = KP * error + KI * (*integral) + KD * derivative;
    *last_error = error;
    return output;
}

// Function to set motor speed using software PWM
void set_motor_speed(int motor_ena, int motor_in1, int motor_in2, double duty_cycle) {
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    if (duty_cycle < -100.0) duty_cycle = -100.0;

    int pwm_range = 1000; // Adjust as needed
    int pwm_value = (int)((duty_cycle / 100.0) * pwm_range);

    gpioPWM(motor_ena, pwm_value);

    if (duty_cycle > 0) {
        gpioWrite(motor_in1, 1);
        gpioWrite(motor_in2, 0);
    } else if (duty_cycle < 0) {
        gpioWrite(motor_in1, 0);
        gpioWrite(motor_in2, 1);
    } else {
        gpioWrite(motor_in1, 0);
        gpioWrite(motor_in2, 0);
    }
}

