void encoder1_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count++;
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder callback function for Motor 2
void encoder2_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder2_mutex);
    encoder2_count++;
    pthread_mutex_unlock(&encoder2_mutex);
}

// Function to calculate RPM
double calculate_rpm(int encoder_count) {
    // Assuming 600 pulses per revolution
    return (double)encoder_count * 60.0 / (600.0 * (SAMPLE_TIME / 1000.0));
