// PID control function
double pid_control(double target_rpm, double current_rpm, double *last_error, double *integral) {
    double error = target_rpm - current_rpm;
    *integral += error * (SAMPLE_TIME / 1000.0);
    double derivative = (error - *last_error) / (SAMPLE_TIME / 1000.0);
    double output = KP * error + KI * (*integral) + KD * derivative;
    *last_error = error;
    return output;
}

