int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filtering (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // Set MHD_R to 1
        fprintf(stderr, "Error: Failed to set MHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { // Set NHD_R to 1
        fprintf(stderr, "Error: Failed to set NHD_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { // Set NCL_R to 0
        fprintf(stderr, "Error: Failed to set NCL_R\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // Set FDL_R to 0
        fprintf(stderr, "Error: Failed to set FDL_R\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x2F, 0x01) < 0) { // Set MHD_T to 1
        fprintf(stderr, "Error: Failed to set MHD_T\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) { // Set NHD_T to 1
        fprintf(stderr, "Error: Failed to set NHD_T\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x31, 0x00) < 0) { // Set NCL_T to 0
        fprintf(stderr, "Error: Failed to set NCL_T\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x32, 0x00) < 0) { // Set FDL_T to 0
        fprintf(stderr, "Error: Failed to set FDL_T\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Control the relay state
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log the relay state to a file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    int relay_state = 0; // 0 = OFF, 1 = ON
    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                // Any electrode is touched
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_relay_state(relay_state);
                    printf("Relay ON\n");
                }
            } else {
                // No electrode is touched
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_relay_state(relay_state);
                    printf("Relay OFF\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading touch status. Retrying...\n");
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup
    control_relay(0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

