// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int open_valve(int gpio_pin);
int close_valve(int gpio_pin);
int log_event(const char *event_message);
void cleanup(int signal);

// Signal handler function
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close valves
    close_valve(VALVE1_GPIO);
    close_valve(VALVE2_GPIO);

    // Release GPIO lines
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to initialize GPIO
int initialize_gpio(void) {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Error getting GPIO line for Valve 1: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Error getting GPIO line for Valve 2: %s\n", strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO line as output
    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for Valve 1 as output: %s\n", strerror(errno));
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for Valve 2 as output: %s\n", strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to open a valve
int open_valve(int gpio_pin) {
    struct gpiod_line *line = NULL;
    if (gpio_pin == VALVE1_GPIO) {
        line = valve1_line;
    } else if (gpio_pin == VALVE2_GPIO) {
        line = valve2_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO value for Valve %d to 1: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    char event_message[100];
    snprintf(event_message, sizeof(event_message), "Valve %d opened", gpio_pin);
    if (log_event(event_message) != 0) {
        fprintf(stderr, "Error logging event: %s\n", event_message);
    }

    return 0;
}

// Function to close a valve
int close_valve(int gpio_pin) {
    struct gpiod_line *line = NULL;
    if (gpio_pin == VALVE1_GPIO) {
        line = valve1_line;
    } else if (gpio_pin == VALVE2_GPIO) {
        line = valve2_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO value for Valve %d to 0: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    char event_message[100];
    snprintf(event_message, sizeof(event_message), "Valve %d closed", gpio_pin);
    if (log_event(event_message) != 0) {
        fprintf(stderr, "Error logging event: %s\n", event_message);
    }

    return 0;
}

// Function to log an event to a file
int log_event(const char *event_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_message);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Greenhouse water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Valve 1: Open for 500ms, then close
        if (open_valve(VALVE1_GPIO) != 0) {
            fprintf(stderr, "Error opening Valve 1. Continuing.\n");
        }
        usleep(500000); // 500ms
        if (close_valve(VALVE1_GPIO) != 0) {
            fprintf(stderr, "Error closing Valve 1. Continuing.\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Valve 2: Open for 1000ms, then close
        if (open_valve(VALVE2_GPIO) != 0) {
            fprintf(stderr, "Error opening Valve 2. Continuing.\n");
        }
        usleep(1000000); // 1000ms
        if (close_valve(VALVE2_GPIO) != 0) {
            fprintf(stderr, "Error closing Valve 2. Continuing.\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

