#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define PIR_SENSOR_3 23
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define DEBOUNCE_MS 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor(int gpio_pin);
void unlock_door(int gpio_pin);
void log_event(const char *event_type, int gpio_pin);
void rate_limit(int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    unsigned long last_motion_time;
} sensor_data_t;

sensor_data_t sensor_data[3];

int main() {
    // Initialize sensor data
    sensor_data[0].gpio_pin = PIR_SENSOR_1;
    sensor_data[0].last_motion_time = 0;
    sensor_data[1].gpio_pin = PIR_SENSOR_2;
    sensor_data[1].last_motion_time = 0;
    sensor_data[2].gpio_pin = PIR_SENSOR_3;
    sensor_data[2].last_motion_time = 0;

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        for (int i = 0; i < 3; i++) {
            int motion_detected = read_pir_sensor(sensor_data[i].gpio_pin);

            if (motion_detected) {
                unsigned long current_time = gpioTick();

                // Rate limiting
                if (current_time - sensor_data[i].last_motion_time > RATE_LIMIT_MS * 1000) {
                    unlock_door(sensor_data[i].gpio_pin);
                    sensor_data[i].last_motion_time = current_time;
                } else {
                    rate_limit(sensor_data[i].gpio_pin);
                }
            }
        }

        gpioDelay(50); // Check every 50 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Motion detection system stopped.\n");
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value with debouncing
int read_pir_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_MS); // Debounce
    return (gpioRead(gpio_pin) == 1 && value == 0); // Detect rising edge
}

// Unlock the door by activating the relay
void unlock_door(int gpio_pin) {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    log_event("Door Unlocked", gpio_pin);
    gpioDelay(UNLOCK_DURATION_MS);
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    log_event("Door Locked", gpio_pin);
}

// Log an event to the log file
void log_event(const char *event_type, int gpio_pin) {
    if (log_file != NULL) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s.%03d - %s - GPIO: %d\n", timestamp, gpioTick() % 1000, event_type, gpio_pin);
        fflush(log_file); // Ensure immediate write to file
    }
}

// Log rate limiting event
void rate_limit(int gpio_pin) {
    log_event("Rate Limited", gpio_pin);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

