#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define minimum and maximum PWM duty cycle values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Define minimum and maximum step duration (ms)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define minimum and maximum number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, terminating gracefully...\n");
}

// Function to generate a random integer between min and max (inclusive)
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a random PWM duty cycle value
int generate_random_duty_cycle() {
    return generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
}

// Function to generate a random duration value
int generate_random_duration() {
    return generate_random_integer(MIN_DURATION, MAX_DURATION);
}

// Function to generate a random number of steps
int generate_random_steps() {
    return generate_random_integer(MIN_STEPS, MAX_STEPS);
}

// Function to generate a haptic feedback pattern
void generate_haptic_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int *num_steps) {
    *num_steps = generate_random_steps();

    for (int i = 0; i < *num_steps; i++) {
        motor1_duty_cycles[i] = generate_random_duty_cycle();
        motor2_duty_cycles[i] = generate_random_duty_cycle();
        durations[i] = generate_random_duration();
    }
}

// Function to play a haptic feedback pattern
void play_haptic_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_PIN, motor2_duty_cycles[i]);
        gpioDelay(durations[i] * 1000); // Convert ms to microseconds
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set GPIO pins to output mode
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Allocate memory for the haptic pattern
        int *motor1_duty_cycles = (int *)malloc(MAX_STEPS * sizeof(int));
        int *motor2_duty_cycles = (int *)malloc(MAX_STEPS * sizeof(int));
        int *durations = (int *)malloc(MAX_STEPS * sizeof(int));
        int num_steps;

        if (motor1_duty_cycles == NULL || motor2_duty_cycles == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory before exiting
            if (motor1_duty_cycles) free(motor1_duty_cycles);
            if (motor2_duty_cycles) free(motor2_duty_cycles);
            if (durations) free(durations);
            break; // Exit the loop
        }

        // Generate a haptic feedback pattern
        generate_haptic_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, &num_steps);

        // Play the haptic feedback pattern
        play_haptic_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, num_steps);

        // Free allocated memory
        free(motor1_duty_cycles);
        free(motor2_duty_cycles);
        free(durations);
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

