#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Log file name
#define LOG_FILE "weight_log.txt"

// Default calibration values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(int lock);
void log_weight(double weight);
void calibrate_hx711();
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low (HX711 ready)
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // Apply the 25th clock pulse for gain selection (Channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

