#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control constants
#define MOTOR_FREQUENCY 1000 // Hz
#define MOTOR_DUTY_CYCLE 150 // out of 255
#define MOTOR_RUN_TIME 5     // seconds

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY 50 // ms

// Define log file path
#define LOG_FILE "/var/log/window_control.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int debounce_rain_sensor();
int close_window();
int stop_motor();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, shutting down...");
        running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Debounce rain sensor readings
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }
    return (low_count >= (DEBOUNCE_READINGS / 2)); // Rain detected if at least half are LOW
}

// Close the window
int close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, MOTOR_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for MOTOR_RUN_TIME seconds
    return 0;
}

// Stop the motor
int stop_motor() {
    log_event("Stopping motor...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    return 0;
}

// Log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    }
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up...");
    stop_motor();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting...");
        cleanup();
        return 1;
    }

    log_event("Window control system started");

    // Main loop
    while (running) {
        if (debounce_rain_sensor()) {
            log_event("Rain detected!");
            close_window();
            stop_motor();
            gpioDelay(60000000); // Wait 60 seconds before checking again
        } else {
            gpioDelay(60000000); // Check every 60 seconds
        }
    }

    // Cleanup and exit
    cleanup();
    log_event("Window control system stopped");
    return 0;
}

