#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value);
void activate_solenoid();
void log_event(const char *event_description);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;
    int timeout_count = 0;

    // Wait for DT to go low (data ready) with timeout
    while (gpioRead(HX711_DT) == 1 && timeout_count < TIMEOUT_DURATION) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        log_event("HX711 Timeout");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Two's complement conversion if negative
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to grams (calibration needed)
float convert_to_grams(int raw_value) {
    // This is a placeholder.  Calibration is crucial for accurate results.
    // You'll need to determine the relationship between raw_value and grams
    // based on your specific load cell and HX711 setup.
    // Example: 1000 raw units = 100 grams
    return (float)raw_value / 1000.0;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    printf("Activating solenoid lock...\n");
    gpioWrite(SOLENOID_PIN, 1); // Set solenoid pin HIGH
    gpioDelay(SOLENOID_DURATION * 1000); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Set solenoid pin LOW
    printf("Solenoid lock deactivated.\n");
}

