    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return 1;
        }
    }

    fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_solenoid(0); // Unlock solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    long raw_value;
    double weight;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration factor
    if (load_calibration_factor() != 0) {
        // Calibrate if calibration file is not found
        if (calibrate_load_cell() != 0) {
            cleanup();
            return 1;
        }
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read raw value from HX711
        if (read_hx711(&raw_value) == 0) {
