// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_sensor();
int toggle_relay();
int log_event(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

