    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    int result = gpioWrite(RELAY_PIN, relay_state);
    if (result != 0) {
        fprintf(stderr, "Error writing to relay pin: %d\n", result);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to log the event to a file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Relay State: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) { // Obstacle detected (sensor output is LOW)
            if (toggle_relay() == 0) {
                if (log_event(relay_state) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
                fprintf(stderr, "Error toggling relay.\n");
            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            running = 0;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

