        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) { // Obstacle detected (sensor output is LOW)
            if (toggle_relay() == 0) {
                if (log_event(relay_state) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
