            }
        } else if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            running = 0;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

