#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

// Default watering duration (seconds)
#define DEFAULT_DURATION 60

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_duration(const char *filename);
int set_gpio_output(struct gpiod_line *line, int value);
int water_valve(struct gpiod_line *line, int duration);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Function to read the watering duration from the configuration file
int read_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return DEFAULT_DURATION;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return DEFAULT_DURATION;
    }

    fclose(fp);

    // Parse the duration from the line
    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid config file format. Using default duration.\n");
        return DEFAULT_DURATION;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid config file format. Using default duration.\n");
        return DEFAULT_DURATION;
    }

    char *endptr;
    long duration = strtol(token, &endptr, 10);

    // Check for errors during conversion
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid duration value in config file. Using default duration.\n");
        return DEFAULT_DURATION;
    }

    // Validate the duration
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds. Using default duration.\n");
        return DEFAULT_DURATION;
    }

    return (int)duration;
}

// Function to set the GPIO line output value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to control the watering valve
int water_valve(struct gpiod_line *line, int duration) {
    // Turn the valve on
    if (set_gpio_output(line, 1) < 0) {
        return -1;
    }
    printf("Valve ON\n");

    // Wait for the specified duration
    struct timespec req = {0};
    req.tv_sec = duration;
    req.tv_nsec = 0;
    int ret = nanosleep(&req, NULL);

    // Check for termination signal
    if (terminate) {
        fprintf(stderr, "Watering interrupted by signal.\n");
        // Turn the valve off immediately
        if (set_gpio_output(line, 0) < 0) {
            return -1;
        }
        printf("Valve OFF (interrupted)\n");
        return -1; // Indicate interruption
    }

    if (ret < 0) {
        fprintf(stderr, "nanosleep interrupted: %s\n", strerror(errno));
        // Turn the valve off immediately
        if (set_gpio_output(line, 0) < 0) {
            return -1;
        }
        printf("Valve OFF (interrupted)\n");
        return -1; // Indicate interruption
    }

    // Turn the valve off
    if (set_gpio_output(line, 0) < 0) {
        return -1;
    }
    printf("Valve OFF\n");

    return 0;
}

// Cleanup function to release resources
void cleanup(void) {
    if (line) {
        // Ensure valve is off before exiting
        set_gpio_output(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    int duration = read_duration(CONFIG_FILE);
    printf("Watering duration: %d seconds\n", duration);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    // Request the GPIO line as an output
    int ret = gpiod_line_request_output(line, "watering_system", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        cleanup();
        return 1;
    }

    // Main loop: Water the valve for the specified duration
    if (water_valve(line, duration) < 0) {
        fprintf(stderr, "Error watering valve.\n");
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

