#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define LEFT_MOTOR_FORWARD_PIN 22
#define LEFT_MOTOR_BACKWARD_PIN 23
#define RIGHT_MOTOR_FORWARD_PIN 24
#define RIGHT_MOTOR_BACKWARD_PIN 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void set_motor_speed(int left_speed, int right_speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Structure to hold motor pin assignments
typedef struct {
    int left_forward;
    int left_backward;
    int right_forward;
    int right_backward;
} MotorPins;

MotorPins motor_pins = {LEFT_MOTOR_FORWARD_PIN, LEFT_MOTOR_BACKWARD_PIN, RIGHT_MOTOR_FORWARD_PIN, RIGHT_MOTOR_BACKWARD_PIN};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Determine motor speeds based on sensor readings
        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle_sensor == 0) {
            // Straight
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            // Turn right
            left_speed = BASE_SPEED;
            right_speed = TURN_SPEED;
        } else if (right_sensor == 0) {
            // Turn left
            left_speed = TURN_SPEED;
            right_speed = BASE_SPEED;
        } else {
            // Stop
            left_speed = 0;
            right_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(left_speed, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Delay for 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Stop motors
    stop_motors();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

