#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_relay();
int read_lux(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize relay GPIO
int init_relay() {
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off
    return 0;
}

// Read illuminance from BH1750 sensor
int read_lux(float *lux) {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to write config command: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay state
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int i2c_init_attempts = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        i2c_init_attempts++;
        fprintf(stderr, "I2C initialization failed. Retrying in %d seconds...\n", I2C_RETRY_DELAY_MS / 1000);
        gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        if (i2c_init_attempts > I2C_RETRY_COUNT) {
            fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
            cleanup();
            return 1;
        }
        goto main_loop; // Retry the main loop
    }

    // Initialize relay
    if (init_relay() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Grow lamp control system started. Press Ctrl+C to exit.\n");

    // Main loop
    main_loop:
    while (!terminate) {
        // Read lux value
        if (read_lux(&lux) == 0) {
            // Control relay based on lux threshold
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay: ON\n", lux);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay: OFF\n", lux);
            } else {
                log_data(lux, relay_state);
                printf("Lux: %.2f, Relay: %s\n", lux, relay_state ? "ON" : "OFF");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            log_data(-1.0, relay_state); // Log error
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

