#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo lock and unlock positions
#define SERVO_LOCK_POSITION 1000
#define SERVO_UNLOCK_POSITION 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on the button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_pulse_width(SERVO_LOCK_POSITION);
    gpioDelay(1000); // Allow servo to move
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_pulse_width(SERVO_UNLOCK_POSITION);
    gpioDelay(1000); // Allow servo to move
}

// Function to debounce a button press
void debounce_button(int button_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check if the lock button is pressed (active-low)
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            debounce_button(LOCK_BUTTON_PIN);
        }

        // Check if the unlock button is pressed (active-low)
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            debounce_button(UNLOCK_BUTTON_PIN);
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

