// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;
}

// Function to initialize a GPIO pin as an output
int initialize_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to activate a vibration motor for a specified duration
int activate_motor(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error writing HIGH to GPIO %d\n", gpio_pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing LOW to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(MOTOR1_GPIO) != 0 || initialize_gpio(MOTOR2_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate motor 1 for 200 ms
        if (activate_motor(MOTOR1_GPIO, 200) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }

        // Activate motor 2 for 300 ms
        if (activate_motor(MOTOR2_GPIO, 300) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
    }

    // Stop motors and release GPIO lines before exiting
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

