#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoints
#define SOUND_SENSOR_ENDPOINT "tcp://*:5555"
#define ALARM_NODE_ENDPOINT "tcp://localhost:5555"

// Define topic
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"

// Define message format
#define MESSAGE_FORMAT "Timestamp: %ld, Sound Detected: %s"

// Global variables
static volatile int running = 1;
static void *zmq_context = NULL;
static void *zmq_socket = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_zmq();
void cleanup();
int publish_message(const char *message);
int subscribe_message();

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq() {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket\n");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int bind_result = zmq_bind(zmq_socket, SOUND_SENSOR_ENDPOINT);
    if (bind_result != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close ZeroMQ socket and context
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

// Publish message to ZeroMQ
int publish_message(const char *message) {
    zmq_msg_t zmq_message;
    int rc = zmq_msg_init_size(&zmq_message, strlen(message));
    if (rc != 0) {
        fprintf(stderr, "Failed to initialize ZeroMQ message: %s\n", zmq_strerror(errno));
        return -1;
    }
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    rc = zmq_msg_send(&zmq_message, zmq_socket, 0);
    if (rc == -1) {
        fprintf(stderr, "Failed to send ZeroMQ message: %s\n", zmq_strerror(errno));
        zmq_msg_close(&zmq_message);
        return -1;
    }

    zmq_msg_close(&zmq_message);
    return 0;
}

// Subscribe to message from ZeroMQ
int subscribe_message() {
    void *subscriber_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!subscriber_socket) {
        fprintf(stderr, "Failed to create subscriber socket: %s\n", zmq_strerror(errno));
        return -1;
    }

    int connect_result = zmq_connect(subscriber_socket, ALARM_NODE_ENDPOINT);
    if (connect_result != 0) {
        fprintf(stderr, "Failed to connect subscriber socket: %s\n", zmq_strerror(errno));
        zmq_close(subscriber_socket);
        return -1;
    }

    int subscribe_result = zmq_setsockopt(subscriber_socket, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC));
    if (subscribe_result != 0) {
        fprintf(stderr, "Failed to set subscriber options: %s\n", zmq_strerror(errno));
        zmq_close(subscriber_socket);
        return -1;
    }

    while (running) {
        zmq_msg_t zmq_message;
        int rc = zmq_msg_init(&zmq_message);
        if (rc != 0) {
            fprintf(stderr, "Failed to initialize ZeroMQ message: %s\n", zmq_strerror(errno));
            break;
        }

        rc = zmq_msg_recv(&zmq_message, subscriber_socket, 0);
        if (rc == -1) {
            fprintf(stderr, "Failed to receive ZeroMQ message: %s\n", zmq_strerror(errno));
            zmq_msg_close(&zmq_message);
            break;
        }

        char *message_data = (char *)zmq_msg_data(&zmq_message);
        size_t message_size = zmq_msg_size(&zmq_message);
        char message[message_size + 1];
        strncpy(message, message_data, message_size);
        message[message_size] = '\0';

        printf("Received message: %s\n", message);

        gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
        gpioDelay(1000);           // Wait for 1 second
        gpioWrite(ALARM_LED_PIN, 0); // Turn off LED

        zmq_msg_close(&zmq_message);
    }

    zmq_close(subscriber_socket);
    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor or alarm_node\n");
        return 1;
    }

    const char *mode = argv[1];

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started\n");
        while (running) {
            int sound_detected = gpioRead(SOUND_SENSOR_PIN);

            if (sound_detected == 0) {
                // Get current timestamp
                time_t current_time = time(NULL);

                // Format message
                char message[100];
                snprintf(message, sizeof(message), MESSAGE_FORMAT, current_time, "Yes");

                // Publish message
                if (publish_message(message) != 0) {
                    fprintf(stderr, "Failed to publish message\n");
                }

                printf("Sound detected, published message: %s\n", message);
            }

            gpioDelay(10); // Poll every 10 ms
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        printf("Alarm node mode started\n");
        if (subscribe_message() != 0) {
            fprintf(stderr, "Failed to subscribe to messages\n");
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        cleanup();
        return 1;
    }

    // Cleanup resources
    cleanup();

    return 0;
}

