// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100 // Adjust as needed

// NEC timing constants (in microseconds)
#define NEC_HDR_MARK  9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK  560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_times[MAX_PULSES];
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulse_times, int pulse_count, uint32_t *address, uint32_t *command);
int validate_checksum(uint32_t address, uint32_t command);
int publish_mqtt(uint32_t address, uint32_t command);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// IR receiver callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_width;

    if (pulse_count >= MAX_PULSES) {
        syslog(LOG_WARNING, "Pulse buffer overflow");
        pulse_count = 0; // Reset buffer
    }

    if (last_tick != 0) {
        pulse_width = tick - last_tick;
        pulse_times[pulse_count++] = pulse_width;
    }

    last_tick = tick;
}

// Decode NEC IR signal
int decode_nec(uint32_t *pulse_times, int pulse_count, uint32_t *address, uint32_t *command) {
    if (pulse_count < 68) {
        syslog(LOG_WARNING, "Not enough pulses received (%d)", pulse_count);
        return -1;
    }

    // Check for valid header
    if (pulse_times[0] < NEC_HDR_MARK * 0.8 || pulse_times[0] > NEC_HDR_MARK * 1.2 ||
        pulse_times[1] < NEC_HDR_SPACE * 0.8 || pulse_times[1] > NEC_HDR_SPACE * 1.2) {
