#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x23
#define SENSOR2_ADDR 0x24
#define SENSOR3_ADDR 0x25
#define SENSOR4_ADDR 0x26

// Define I2C bus
#define I2C_BUS "/dev/i2c-1"

// Define multicast address and port
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
int i2c_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c(int address);
float read_lux(int fd);
int send_udp_packet(const char *data);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750 sensor
float read_lux(int fd) {
    unsigned char data[2];
    int retries = 3;

    // Send measurement command
    while (retries > 0) {
        if (write(fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C device after multiple retries.\n");
        return NAN;
    }

    // Wait for measurement (at least 180ms)
    usleep(180000);

    retries = 3;
    // Read 2 bytes of data
    while (retries > 0) {
        if (read(fd, data, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        break; // Success, exit retry loop
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C device after multiple retries.\n");
        return NAN;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Send UDP packet
int send_udp_packet(const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(SENSOR1_ADDR); // Initialize with any valid address
    if (i2c_fd < 0) {
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        cleanup();
        return 1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data[4];
        char packet_data[256] = {0};
        int packet_len = 0;

        // Read sensor data
        sensor_data[0].sensor_id = 1;
        sensor_data[0].lux = read_lux(i2c_fd);
        if (isnan(sensor_data[0].lux)) {
            sensor_data[0].lux = NAN;
        }

        sensor_data[1].sensor_id = 2;
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
            perror("Error setting I2C slave address for sensor 2");
            sensor_data[1].lux = NAN;
        } else {
            sensor_data[1].lux = read_lux(i2c_fd);
            if (isnan(sensor_data[1].lux)) {
                sensor_data[1].lux = NAN;
            }
        }

        sensor_data[2].sensor_id = 3;
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR3_ADDR) < 0) {
            perror("Error setting I2C slave address for sensor 3");
            sensor_data[2].lux = NAN;
        } else {
            sensor_data[2].lux = read_lux(i2c_fd);
            if (isnan(sensor_data[2].lux)) {
                sensor_data[2].lux = NAN;
            }
        }

        sensor_data[3].sensor_id = 4;
        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR4_ADDR) < 0) {
            perror("Error setting I2C slave address for sensor 4");
            sensor_data[3].lux = NAN;
        } else {
            sensor_data[3].lux = read_lux(i2c_fd);
            if (isnan(sensor_data[3].lux)) {
                sensor_data[3].lux = NAN;
            }
        }

        // Format data into packet
        for (int i = 0; i < 4; i++) {
            packet_len += snprintf(packet_data + packet_len, sizeof(packet_data) - packet_len, "%d,%.2f;", sensor_data[i].sensor_id, sensor_data[i].lux);
        }
        packet_data[packet_len - 1] = '\0'; // Remove trailing semicolon

        // Send UDP packet
        if (send_udp_packet(packet_data) != 0) {
            fprintf(stderr, "Failed to send UDP packet.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

