#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.1
#define FLOW_OFFSET 3277.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float flow_rate;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int address);
int read_sensor_data(int fd, uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_data(FILE *fp, float flow_rate);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C communication
int init_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data from I2C
int read_sensor_data(int fd, uint16_t *raw_flow) {
    uint8_t buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            *raw_flow = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            perror("Error reading sensor data");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw flow data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    return (float)(raw_flow - FLOW_OFFSET) * FLOW_SCALE_FACTOR;
}

// Log data to file
int log_data(FILE *fp, float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_flow;
        float flow_rate;

        if (read_sensor_data(i2c_fd, &raw_flow) == 0) {
            flow_rate = convert_to_slpm(raw_flow);

            if (log_data(log_file, flow_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

