#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_SP_EN 0x01
#define AS7341_F1_DATA_L 0x60
#define AS7341_F1_DATA_H 0x61
#define AS7341_F2_DATA_L 0x62
#define AS7341_F2_DATA_H 0x63
#define AS7341_F3_DATA_L 0x64
#define AS7341_F3_DATA_H 0x65
#define AS7341_F4_DATA_L 0x66
#define AS7341_F4_DATA_H 0x67
#define AS7341_F5_DATA_L 0x68
#define AS7341_F5_DATA_H 0x69
#define AS7341_F6_DATA_L 0x6A
#define AS7341_F6_DATA_H 0x6B
#define AS7341_F7_DATA_L 0x6C
#define AS7341_F7_DATA_H 0x6D
#define AS7341_F8_DATA_L 0x6E
#define AS7341_F8_DATA_H 0x6F
#define AS7341_CLEAR_DATA_L 0x70
#define AS7341_CLEAR_DATA_H 0x71
#define AS7341_NIR_DATA_L 0x72
#define AS7341_NIR_DATA_H 0x73

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int as7341_init(int fd);
int read_sensor_data(int fd, sensor_data_t *data);
float calculate_lux(sensor_data_t data);
int log_data(FILE *fp, sensor_data_t data, float lux);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// AS7341 initialization function
int as7341_init(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(fd, AS7341_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x19) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I: 0x%02X\n", who_am_i);

    // Power on the sensor
    if (i2c_write_byte(fd, AS7341_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }
    usleep(10000); // Wait for power-on

    // Configure SMUX for spectral readings
    if (i2c_write_byte(fd, AS7341_CFG6, 0x03) < 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_byte(fd, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[20];
    uint8_t reg = AS7341_F1_DATA_L;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, 20) != 20) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->f1 = (buffer[1] << 8) | buffer[0];
    data->f2 = (buffer[3] << 8) | buffer[2];
    data->f3 = (buffer[5] << 8) | buffer[4];
    data->f4 = (buffer[7] << 8) | buffer[6];
    data->f5 = (buffer[9] << 8) | buffer[8];
    data->f6 = (buffer[11] << 8) | buffer[10];
    data->f7 = (buffer[13] << 8) | buffer[12];
    data->f8 = (buffer[15] << 8) | buffer[14];
    data->clear = (buffer[17] << 8) | buffer[16];
    data->nir = (buffer[19] << 8) | buffer[18];

    return 0;
}

// Function to calculate lux
float calculate_lux(sensor_data_t data) {
    // Simplified lux calculation (adjust as needed)
    float lux = (float)(data.clear + data.nir) / 2.0; // Average clear and NIR
    return lux;
}

// Function to log data to file
int log_data(FILE *fp, sensor_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp,
            data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8, data.clear, data.nir, lux);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    sensor_data_t sensor_data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Calculate lux
            lux = calculate_lux(sensor_data);

            // Log data
            log_data(log_file, sensor_data, lux);

            printf("F1: %u, F2: %u, F3: %u, F4: %u, F5: %u, F6: %u, F7: %u, F8: %u, Clear: %u, NIR: %u, Lux: %.2f\n",
                   sensor_data.f1, sensor_data.f2, sensor_data.f3, sensor_data.f4, sensor_data.f5, sensor_data.f6, sensor_data.f7, sensor_data.f8, sensor_data.clear, sensor_data.nir, lux);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated successfully.\n");
    return 0;
}

