        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    sensor_data_t sensor_data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Calculate lux
            lux = calculate_lux(sensor_data);

            // Log data
            log_data(log_file, sensor_data, lux);

