#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1 // seconds
#define DEFAULT_FILENAME "seismic_data.csv"
#define ACCEL_RANGE 8.0 // g
#define ACCEL_SENSITIVITY 0.000244 // g/LSB
#define MAX_RETRIES 3
#define BACKOFF_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_acceleration_data(int fd, sensor_data_t *data);
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, sensor_data_t *data);
void log_data(FILE *fp, sensor_data_t data);
void log_error(FILE *fp, const char *message);
void signal_handler(int sig);
int initialize();
void cleanup();

// I2C read register with retry
int i2c_read_register(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        }

        log_error(error_file, "I2C read failed, retrying...");
        usleep(BACKOFF_MS * 1000); // Backoff in microseconds
        retries++;
    }

    log_error(error_file, "I2C read failed after multiple retries.");
    return -1; // Indicate failure
}

// I2C write register with retry
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }

        log_error(error_file, "I2C write failed, retrying...");
        usleep(BACKOFF_MS * 1000); // Backoff in microseconds
        retries++;
    }

    log_error(error_file, "I2C write failed after multiple retries.");
    return -1; // Indicate failure
}

// Read acceleration data from the sensor
int read_acceleration_data(int fd, sensor_data_t *data) {
    int16_t raw_x, raw_y, raw_z;
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = i2c_read_register(fd, 0x28);
    x_h = i2c_read_register(fd, 0x29);
    y_l = i2c_read_register(fd, 0x2A);
    y_h = i2c_read_register(fd, 0x2B);
    z_l = i2c_read_register(fd, 0x2C);
    z_h = i2c_read_register(fd, 0x2D);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        log_error(error_file, "Failed to read acceleration data.");
        return -1;
    }

    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    convert_to_g(raw_x, raw_y, raw_z, data);

    return 0;
}

// Convert raw data to g
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, sensor_data_t *data) {
    data->x_g = (float)raw_x * ACCEL_SENSITIVITY;
    data->y_g = (float)raw_y * ACCEL_SENSITIVITY;
    data->z_g = (float)raw_z * ACCEL_SENSITIVITY;
}

// Log data to CSV file
void log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.6f,%.6f,%.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.x_g, data.y_g, data.z_g);
    fflush(fp); // Ensure data is written to disk immediately
}

// Log error to error log file
void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s (errno: %d)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            message, errno);
    fflush(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize resources
int initialize() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error(error_file, "Failed to open I2C device.");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error(error_file, "Failed to set I2C slave address.");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        log_error(error_file, "Failed to open data file.");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        log_error(error_file, "Failed to open error log file.");
        fclose(data_file);
        data_file = NULL;
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fflush(data_file);
        fclose(data_file);
    }
    if (error_file != NULL) {
        fflush(error_file);
        fclose(error_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    sensor_data_t sensor_data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Check error log.\n");
        return 1;
    }

    printf("Starting seismic data logging...\n");

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(i2c_fd, &sensor_data) == 0) {
            log_data(data_file, sensor_data);
        } else {
            log_error(error_file, "Failed to read sensor data.");
        }

        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

