#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1
#define RETRY_DELAY_SEC 1

// Global variables
int i2c_fd = -1;
int udp_socket = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_bh1750(int fd);
int read_bh1750(int fd, float *lux);
int send_udp_multicast(int socket, const char *message, const char *addr, int port, int ttl);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize BH1750 sensor
int init_bh1750(int fd) {
    unsigned char config_data[2] = {0x01, CONTINUOUS_HIGH_RES_MODE};
    ssize_t bytes_written = write(fd, config_data, 2);
    if (bytes_written != 2) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// Read BH1750 sensor data
int read_bh1750(int fd, float *lux) {
    unsigned char buffer[2];
    ssize_t bytes_read = read(fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;
    return 0;
}

// Send UDP multicast message
int send_udp_multicast(int socket, const char *message, const char *addr, int port, int ttl) {
    struct sockaddr_in addr_info;
    memset(&addr_info, 0, sizeof(addr_info));
    addr_info.sin_family = AF_INET;
    addr_info.sin_addr.s_addr = inet_addr(addr);
    addr_info.sin_port = htons(port);

    // Set TTL
    if (setsockopt(socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("setsockopt (TTL) failed");
        return -1;
    }

    ssize_t bytes_sent = sendto(socket, message, strlen(message), 0, (struct sockaddr *)&addr_info, sizeof(addr_info));
    if (bytes_sent < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            char message[32];
            snprintf(message, sizeof(message), "%.2f", lux);

            if (send_udp_multicast(udp_socket, message, MULTICAST_ADDR, MULTICAST_PORT, TTL) != 0) {
                fprintf(stderr, "Failed to send UDP multicast. Retrying in %d seconds.\n", RETRY_DELAY_SEC);
            } else {
                printf("Sent: %s\n", message);
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor. Retrying in %d seconds.\n", RETRY_DELAY_SEC);
        }

        sleep(RETRY_DELAY_SEC);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }

    printf("Exiting cleanly.\n");
    return 0;
}

