#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define UART parameters
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define UART_FLAGS 0 // No special flags needed for basic UART

// Define TLV magic word
#define TLV_MAGIC_WORD_1 0x0204
#define TLV_MAGIC_WORD_2 0x0306
#define TLV_MAGIC_WORD_3 0x0805
#define TLV_MAGIC_WORD_4 0x0709

// Define TLV types (example, adjust based on AWR1642 documentation)
#define TLV_TYPE_DETECTED_OBJECTS 1

// Define CSV file name
#define CSV_FILE "radar_data.csv"

// Define buffer size
#define BUFFER_SIZE 2048

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold TLV header
typedef struct {
    uint16_t type;
    uint16_t length;
} tlv_header_t;

// Structure to hold detected object data
typedef struct {
    float range;
    float velocity;
} detected_object_t;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int buffer_size);
int parse_tlv_stream(const char *buffer, int buffer_size);
int validate_tlv_header(const tlv_header_t *header);
int extract_detected_objects(const char *payload, int payload_length, detected_object_t *objects, int max_objects);
int write_to_csv(const detected_object_t *objects, int num_objects);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close UART and CSV file
void cleanup() {
    if (uart_handle >= 0) {
        gpioSerialReadClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

// Initialize UART
int initialize_uart() {
    uart_handle = gpioSerialReadOpen(UART_DEVICE, BAUD_RATE, UART_FLAGS);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(char *buffer, int buffer_size) {
    int bytes_read = gpioSerialRead(uart_handle, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Parse TLV stream
int parse_tlv_stream(const char *buffer, int buffer_size) {
    int offset = 0;
    while (offset < buffer_size - 8) { // Ensure enough data for magic word and header
        uint32_t magic_word = *((uint32_t *)(buffer + offset));
        if (magic_word == (TLV_MAGIC_WORD_1 | (TLV_MAGIC_WORD_2 << 16) | (TLV_MAGIC_WORD_3 << 32) | (TLV_MAGIC_WORD_4 << 48))) {
            // Magic word found, parse TLV header
            tlv_header_t header;
            memcpy(&header, buffer + offset + 8, sizeof(tlv_header_t));

            // Validate TLV header
            if (validate_tlv_header(&header) != 0) {
                fprintf(stderr, "Invalid TLV header at offset %d\n", offset);
                offset++; // Move to the next byte
                continue;
            }

            // Extract payload
            int payload_length = header.length - sizeof(tlv_header_t);
            if (payload_length > 0) {
                char *payload = (char *)malloc(payload_length);
                if (payload == NULL) {
                    fprintf(stderr, "Memory allocation error\n");
                    return -1;
                }
                memcpy(payload, buffer + offset + 8 + sizeof(tlv_header_t), payload_length);

                // Process TLV based on type
                if (header.type == TLV_TYPE_DETECTED_OBJECTS) {
                    detected_object_t objects[10]; // Assuming a maximum of 10 objects
                    int num_objects = extract_detected_objects(payload, payload_length, objects, 10);
                    if (num_objects > 0) {
                        write_to_csv(objects, num_objects);
                    }
                }

                free(payload);
            }

            offset += 8 + sizeof(tlv_header_t) + payload_length; // Move to the next TLV
        } else {
            offset++; // Move to the next byte
        }
    }
    return 0;
}

// Validate TLV header
int validate_tlv_header(const tlv_header_t *header) {
    // Basic validation (example)
    if (header->length < sizeof(tlv_header_t)) {
        fprintf(stderr, "TLV length too short\n");
        return -1;
    }
    return 0;
}

// Extract detected objects from payload
int extract_detected_objects(const char *payload, int payload_length, detected_object_t *objects, int max_objects) {
    int num_objects = 0;
    int offset = 0;

    while (offset < payload_length - 8 && num_objects < max_objects) {
        // Assuming each object is represented by a range and velocity (4 bytes each)
        if (payload_length - offset >= 8) {
            objects[num_objects].range = *((float *)(payload + offset));
            objects[num_objects].velocity = *((float *)(payload + offset + 4));
            num_objects++;
            offset += 8;
        } else {
            fprintf(stderr, "Incomplete object data\n");
            break;
        }
    }

    return num_objects;
}

// Write data to CSV file
int write_to_csv(const detected_object_t *objects, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp, i, objects[i].range, objects[i].velocity);
        fflush(csv_file); // Ensure data is written to file immediately
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    fflush(csv_file);

    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Main loop
    while (!terminate) {
        bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            parse_tlv_stream(buffer, bytes_read);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

