#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define INTER_BYTE_TIMEOUT 0.5 // seconds
#define MAX_LINE_LENGTH 256
#define MAX_RANGE 100.0 // Maximum reasonable range in meters

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = (int)(INTER_BYTE_TIMEOUT * 10); // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 2; // Timeout of 2 seconds
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("select failed");
        return -1;
    } else if (select_result == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("read failed");
            return -1;
        }
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

int parse_range_data(const char *line, double *timestamp, double *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok

    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format: Missing timestamp\n");
        free(line_copy);
        return -1;
    }

    *timestamp = strtod(token, NULL);
    if (errno == ERANGE) {
        fprintf(stderr, "Error: Timestamp conversion error\n");
        free(line_copy);
        return -1;
    }

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format: Missing range\n");
        free(line_copy);
        return -1;
    }

    *range = strtod(token, NULL);
    if (errno == ERANGE) {
        fprintf(stderr, "Error: Range conversion error\n");
        free(line_copy);
        return -1;
    }

    free(line_copy);

    // Data validation
    if (*range < 0.0 || *range > MAX_RANGE) {
        fprintf(stderr, "Error: Invalid range value: %.2f meters\n", *range);
        return -1;
    }

    return 0;
}

int main() {
    char line_buffer[MAX_LINE_LENGTH];
    int bytes_read;
    double timestamp, range;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    // Configure UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured successfully. Reading data...\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, line_buffer, sizeof(line_buffer));

        if (bytes_read > 0) {
            // Attempt to parse the line
            if (parse_range_data(line_buffer, &timestamp, &range) == 0) {
                // Get current time for logging
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

                // Log the data
                printf("Timestamp: %s, Range: %.2f meters\n", buf, range);
            } else {
                fprintf(stderr, "Error: Failed to parse range data: %s\n", line_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

