#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_data(int left, int middle, int right);
void emergency_stop();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close the serial port if it's open
    if (serial_fd != -1) {
        close(serial_fd);
        printf("Serial port closed.\n");
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send an emergency stop message over the serial port
void emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to serial port: %s\n", strerror(errno));
    } else {
        printf("Emergency stop message sent: %s", message);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the serial port
    serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for no flags
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening serial port: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping this iteration.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Log the data
        log_data(left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            emergency_stop();
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Close the serial port and terminate pigpio (should not reach here if signal handler works)
    close(serial_fd);
    gpioTerminate();

    return 0;
}

